#[test]
fn a_failed_wait_is_not_a_recipient_that_blocked() {
    // Producing a poll failure against a live owned socket is not something a
    // control here can arrange, so what is exercised is the reading of it --
    // which is where the conflation would do its damage.
    let failure = X11FrameSendFailure::WaitFailed(std::io::Error::from(
        std::io::ErrorKind::InvalidInput,
    ));
    let error = x11_ordered_frame_error("failed to write an ordered event", failure);

    // Not a client failure. Nothing was established about this recipient: it
    // was never asked and it never declined, so ending its connection on the
    // strength of a broken syscall would blame the wrong party.
    assert!(
        !error.client_failure && !error.client_disconnect,
        "a wait that could not be performed says nothing about the recipient"
    );

    // And it is kept apart from blocking in the type itself, which is what
    // stops a deadline being built out of a failed wait.
    let blocked = x11_ordered_frame_error(
        "failed to write an ordered event",
        X11FrameSendFailure::Blocked {
            written: 8,
            blocked: X_AUTHORITY_ORDERED_BLOCKED_LIMIT,
        },
    );
    assert!(
        blocked.client_failure,
        "a recipient that would not take its bytes is the one that failed"
    );
}

/// The writer fixture uses a real resolved source emission. These controls
/// still prove writer custody, not production producer/consumer completion.
/// A capsule, and the endpoint of the registration that produced it.
///
/// The witness comes from the registration, never from the capsule: a writer
/// whose expectation was read off the capsule would admit anything.
fn capsule_and_endpoint(
    delivery: u64,
) -> (XAuthorityOrderedDelivery, PrivateEndpointIdentity) {
    let (emission, endpoint) =
        private_native_tests::emission_and_endpoint_for_writer_fixture(delivery);
    (
        XAuthorityOrderedDelivery::from_emission(emission).unwrap(),
        endpoint,
    )
}

#[test]
fn a_writer_answers_through_the_one_authority_that_owns_the_answer() {
    // Writing into a completion cell directly recorded an answer the ledger
    // never saw: its ticket stayed unanswered and no ordinary observer was
    // told, so a later disconnect could set a different terminal outcome while
    // the cell still said the first one. Two accounts of one delivery,
    // disagreeing. The finalizer adjudicates in one place, and this control
    // checks every account rather than the cell alone.
    let (capsule, endpoint, recovery, receipts) = answerable_capsule(17301);
    let delivery = capsule.delivery();
    let client = capsule.client();
    let cell = recovery
        .completion_for(delivery)
        .expect("a readable ledger")
        .expect("the admission's own completion");

    let (sender, queue) = sync_channel(4);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let mut in_flight = None;
    let mut refused = None;
    let served = XAuthorityServedConnection::retained(endpoint);
    sender.send(capsule).expect("the queue to accept it");

    assert!(cell.answer().is_none(), "nothing is answered before it is sent");
    for _ in 0..32 {
        match serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => break,
            other => panic!("a healthy recipient took its bytes: {other:?}"),
        }
    }

    // EVERY ACCOUNT AGREES. The cell, the ledger's own ticket, and the
    // ordinary observer.
    let answer = cell.answer().expect("the cell carries the adjudicated answer");
    assert_eq!(answer.outcome, XAuthorityInputDeliveryOutcome::Flushed);
    assert_eq!(answer.delivery, delivery);
    assert_eq!(answer.client, client);
    let notified = receipts
        .try_recv()
        .expect("the ordinary observer was told, through the same adjudication");
    assert_eq!(notified, answer, "and told the same thing");
    assert!(
        recovery.ticket(delivery).is_none() || recovery.completion_for(delivery).is_ok(),
        "the ledger's own account was updated rather than bypassed"
    );
    drop(peer);
}

#[test]
fn a_flushed_delivery_is_retired_once_so_the_next_one_can_be_served() {
    // Reporting a flush without giving the slot up would report that same
    // flush for ever and nothing behind it would ever be served. BOTH capsules
    // carry real origin-bound finalizers and nothing here clears the slot:
    // the retirement this asserts is the one production performs.
    // BOTH FROM ONE REGISTRATION. Two fixtures would be two endpoints whose
    // numbers happen to agree, and this writer serves one endpoint.
    let (first, second, endpoint, _recovery_one, _recovery_two, _receipts_one, _receipts_two) =
        two_answerable_capsules(17201, 17202);
    let (sender, queue) = sync_channel(4);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let mut in_flight = None;
    let mut refused = None;
    let served = XAuthorityServedConnection::retained(endpoint);
    assert_eq!(
        second.recipient(),
        first.recipient(),
        "both are owed to the one connection this writer serves"
    );
    sender.send(first).expect("the queue to accept the first");
    sender.send(second).expect("the queue to accept the second");

    let mut flushes = 0;
    let mut delivered = Vec::new();
    for _ in 0..64 {
        match serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => flushes += 1,
            X11OrderedServeStep::Idle => break,
            other => panic!("every capsule here can be answered: {other:?}"),
        }
        if let Some(held) = in_flight.as_ref() {
            let id = held.delivery().delivery();
            if delivered.last() != Some(&id) {
                delivered.push(id);
            }
        }
    }
    assert_eq!(flushes, 2, "each delivery flushed exactly once");
    assert_eq!(delivered.len(), 2, "and the second was reached after the first");
    assert!(in_flight.is_none(), "nothing is left held");
    drop(peer);
}

/// A capsule whose writer can actually answer: a real admission in a real
/// ledger, and a finalizer built from that admission's own completion.
///
/// Controls that built a completion out of thin air could not see whether the
/// ledger agreed with the writer, because there was no ledger behind it.
/// Two answerable capsules owed to ONE endpoint.
fn two_answerable_capsules(
    first: u64,
    second: u64,
) -> (
    XAuthorityOrderedDelivery,
    XAuthorityOrderedDelivery,
    PrivateEndpointIdentity,
    InputRecovery,
    InputRecovery,
    Receiver<XAuthorityClientInputDelivery>,
    Receiver<XAuthorityClientInputDelivery>,
) {
    let (one, two, endpoint) =
        private_native_tests::emissions_for_one_writer_fixture(first, second);
    let answer = |emission| {
        let mut capsule = XAuthorityOrderedDelivery::from_emission(emission).unwrap();
        let id = capsule.delivery();
        let client = capsule.client();
        let (recovery, receipts) = claim_fixture(id);
        let completion = recovery
            .completion_for(id)
            .expect("a readable ledger")
            .expect("the admission minted its completion");
        capsule.carry_finalizer(Arc::new(finalizer_from_held(
            &recovery, &completion, id, client,
        )));
        (capsule, recovery, receipts)
    };
    let (capsule_one, recovery_one, receipts_one) = answer(one);
    let (capsule_two, recovery_two, receipts_two) = answer(two);
    (
        capsule_one,
        capsule_two,
        endpoint,
        recovery_one,
        recovery_two,
        receipts_one,
        receipts_two,
    )
}

fn answerable_capsule(
    delivery: u64,
) -> (
    XAuthorityOrderedDelivery,
    PrivateEndpointIdentity,
    InputRecovery,
    Receiver<XAuthorityClientInputDelivery>,
) {
    let (mut capsule, endpoint) = capsule_and_endpoint(delivery);
    let id = capsule.delivery();
    let client = capsule.client();
    let (recovery, receipts) = claim_fixture(id);
    let completion = recovery
        .completion_for(id)
        .expect("a readable ledger")
        .expect("the admission minted its completion");
    capsule.carry_finalizer(Arc::new(finalizer_from_held(
        &recovery, &completion, id, client,
    )));
    (capsule, endpoint, recovery, receipts)
}

#[test]
fn an_adjudication_reports_what_the_authority_did_with_it() {
    // A boolean could not say this. Reporting success whenever the authority
    // was called said an answer had been recorded when it had been silently
    // declined; reporting failure for an admission already answered stranded
    // a writer that had done everything asked of it.
    let delivery = XAuthorityInputDeliveryId::from_raw(17401);
    let client = XServerFrontendClientId(17401);
    let other = XServerFrontendClientId(17402);
    let (recovery, _receipts) = claim_fixture(delivery);
    recovery.register(client, None).unwrap();
    assert!(
        recovery.bind(Some(delivery), client).unwrap(),
        "the delivery is bound to the recipient it reached"
    );
    let completion = recovery
        .completion_for(delivery)
        .expect("a readable ledger")
        .expect("the admission's own completion");

    // A finalizer naming somebody else. The authority declines it, and that
    // decline is reported as a refusal rather than as a recorded answer.
    let foreign = finalizer_from_held(&recovery, &completion, delivery, other);
    assert_eq!(
        foreign.finalize(XAuthorityInputDeliveryOutcome::Flushed),
        PrivateAdjudication::Refused,
        "an answer the authority declined is not an answer it recorded"
    );
    assert!(
        completion.answer().is_none(),
        "and nothing was written for the client it named"
    );

    // The right one is recorded.
    let own = finalizer_from_held(&recovery, &completion, delivery, client);
    assert_eq!(
        own.finalize(XAuthorityInputDeliveryOutcome::Flushed),
        PrivateAdjudication::Answered
    );
    assert_eq!(
        completion.answer().map(|receipt| receipt.outcome),
        Some(XAuthorityInputDeliveryOutcome::Flushed)
    );

    // Asked again, it is already answered -- not refused. A writer told
    // otherwise would hold a finished delivery for ever.
    assert_eq!(
        own.finalize(XAuthorityInputDeliveryOutcome::Flushed),
        PrivateAdjudication::AlreadyAnswered,
        "an admission that already has its answer owes nothing further"
    );
}

#[test]
fn a_rejected_offer_stays_refused_even_when_older_work_is_deferred() {
    // Reading the state after the fact could not tell this offer's fate from
    // somebody else's: with an earlier cancellation held under a claim, a
    // wrong-client answer was reported as Deferred and a writer took that as
    // permission to retire a delivery nothing had accepted.
    let delivery = XAuthorityInputDeliveryId::from_raw(17501);
    let client = XServerFrontendClientId(17501);
    let other = XServerFrontendClientId(17502);
    let (recovery, receipts) = claim_fixture(delivery);
    recovery.register(client, None).unwrap();
    assert!(recovery.bind(Some(delivery), client).unwrap());
    assert_eq!(
        recovery.claim_execution(Some(delivery)),
        ExecutionClaim::Claimed
    );
    // An earlier cancellation, held because the claim is out.
    recovery
        .finish(
            client,
            Some(delivery),
            XAuthorityInputDeliveryOutcome::EpochRevoked,
        )
        .expect("the cancellation is offered");
    assert!(
        receipts.try_recv().is_err(),
        "and held rather than published, because the claim is out"
    );

    let completion = recovery
        .completion_for(delivery)
        .expect("a readable ledger")
        .expect("the admission's own completion");
    let foreign = finalizer_from_held(&recovery, &completion, delivery, other);

    // THE OFFER IS REJECTED, and the older held cancellation is not its fate.
    assert_eq!(
        foreign.finalize(XAuthorityInputDeliveryOutcome::Flushed),
        PrivateAdjudication::Refused,
        "a declined offer is refused, whatever else is held for this delivery"
    );
    assert!(
        completion.answer().is_none(),
        "and nothing was recorded for it"
    );

    // The older cancellation is still the one held, untouched by the offer.
    recovery.resolve_claim(Some(delivery), false);
    let published = receipts
        .try_recv()
        .expect("the held cancellation stands once the claim resolves");
    assert_eq!(
        published.outcome,
        XAuthorityInputDeliveryOutcome::EpochRevoked,
        "the rejected Flushed never displaced it"
    );
    assert_eq!(published.client, client);
}

#[test]
fn serving_a_whole_delivery_reports_a_flush_and_nothing_more() {
    // A flush means every frame went and the answer was adjudicated. It does
    // not mean the recipient read them.
    let (capsule, endpoint, _recovery, _receipts) = answerable_capsule(17101);
    let (sender, queue) = sync_channel(4);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let mut in_flight = None;
    let mut refused = None;
    let served = XAuthorityServedConnection::retained(endpoint);
    sender.send(capsule).expect("the queue to accept it");

    let mut flushed = false;
    for _ in 0..16 {
        match serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => {
                flushed = true;
                break;
            }
            other => panic!("a healthy recipient took its bytes: {other:?}"),
        }
    }
    assert!(flushed, "every frame of the delivery went out");
    drop(peer);
}

#[test]
fn a_recipient_that_will_not_take_its_bytes_ends_the_connection_before_returning() {
    // THE OBLIGATION write_one_ordered_frame REFUSES TO DISCHARGE. Every
    // failure leaves a frame owed or its extent unknown, so the socket is
    // closed before this returns. A caller that released output
    // serialization after such a step without the socket being closed would
    // admit another writer into the body of a half-written event.
    let (capsule, endpoint) = capsule_and_endpoint(17102);
    let (sender, queue) = sync_channel(4);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let mut in_flight = None;
    let mut refused = None;
    let served = XAuthorityServedConnection::retained(endpoint);
    sender.send(capsule).expect("the queue to accept it");

    // A recipient that is gone: the send fails rather than blocking, which is
    // the failure this control can reach deterministically.
    drop(peer);

    let mut ended = None;
    for _ in 0..16 {
        match serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ) {
            X11OrderedServeStep::Advanced | X11OrderedServeStep::Flushed => {}
            X11OrderedServeStep::Unanswered => {
                // No finalizer on this capsule, so nothing adjudicates its
                // answer and custody is retained. Released here so the loop
                // can reach the failure it is about.
                in_flight = None;
            }
            step @ X11OrderedServeStep::Ended { .. } => {
                ended = Some(step);
                break;
            }
            X11OrderedServeStep::Idle => break,
            X11OrderedServeStep::AdmissionRefused(_) => {
                panic!("this queue carries only what this connection is owed")
            }
            X11OrderedServeStep::TransportUnavailable
            | X11OrderedServeStep::Unterminated
            | X11OrderedServeStep::Closing
            | X11OrderedServeStep::Stopped
            | X11OrderedServeStep::WireBarred => {
                panic!("this connection is live, serving, unbarred and not stopping")
            }
        }
    }
    let Some(X11OrderedServeStep::Ended { outcome, shutdown }) = ended else {
        // A departed peer may accept the bytes into a closed socket's buffer
        // on some kernels; if it did, this control has nothing to say and
        // says so rather than asserting something it did not observe.
        return;
    };
    assert_eq!(
        outcome,
        XAuthorityInputDeliveryOutcome::WriteFailed,
        "a send that failed is a writer fact, not a recipient settlement"
    );
    assert!(
        shutdown,
        "and the connection was ended before this returned, not left for a \
         caller to remember"
    );
}

#[test]
fn a_taken_delivery_lands_where_it_will_be_answered_for() {
    // Both from one registration: this control is about the slot, and a second
    // registration's capsule would be refused before the slot was consulted.
    let (one, two, endpoint) =
        private_native_tests::emissions_for_one_writer_fixture(17011, 17012);
    let first = XAuthorityOrderedDelivery::from_emission(one).unwrap();
    let second = XAuthorityOrderedDelivery::from_emission(two).unwrap();
    let client = first.client();
    let served = XAuthorityServedConnection::retained(endpoint);
    let (sender, queue) = sync_channel(4);
    let mut in_flight = None;
    let mut refused = None;

    // Nothing waiting is its own answer, and takes nothing.
    assert_eq!(
        take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused),
        Err(X11OrderedTakeRefusal::Empty)
    );
    assert!(in_flight.is_none() && refused.is_none());

    sender
        .send(first)
        .expect("the queue to accept it");
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused).expect("one waiting");
    let held = in_flight.as_ref().expect("taken into storage");
    assert_eq!(held.delivery().client(), client);
    assert_eq!(
        held.delivery().delivery(),
        XAuthorityInputDeliveryId::from_raw(17011),
        "the capsule itself is held, not parts copied out of it"
    );
    assert_eq!(held.frame_index(), 0);
    assert_eq!(held.blocked(), Duration::ZERO);

    // A second is refused rather than queued behind the first. This writer
    // answers for what it holds until that is finished, and taking another
    // would leave the first owed by nobody with its frames half-written.
    sender
        .send(second)
        .expect("the queue to accept it");
    assert_eq!(
        take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused),
        Err(X11OrderedTakeRefusal::InFlight),
        "the slot is answered before anything is received, so this never \
         reaches the endpoint comparison"
    );
    assert_eq!(
        in_flight
            .as_ref()
            .expect("still held")
            .delivery()
            .delivery(),
        XAuthorityInputDeliveryId::from_raw(17011),
        "and the one in hand is untouched"
    );

    // A producer that has gone is not an empty queue: one says to look again,
    // the other says nothing more is coming.
    drop(sender);
    in_flight = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("the queued one is still there");
    in_flight = None;
    assert_eq!(
        take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused),
        Err(X11OrderedTakeRefusal::Closed)
    );
    assert!(refused.is_none(), "nothing here was for another connection");
}

#[test]
fn a_frame_index_does_not_move_past_an_unfinished_frame() {
    let (sender, queue) = sync_channel(1);
    let (capsule, endpoint) = capsule_and_endpoint(1702);
    let served = XAuthorityServedConnection::retained(endpoint);
    sender
        .send(capsule)
        .expect("the queue to accept it");
    let mut in_flight = None;
    let mut refused = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("one waiting");
    let held = in_flight.as_mut().expect("taken");

    // No frame in hand at all is not a finished one.
    assert!(held.advance_frame().is_err());
    assert_eq!(held.frame_index(), 0);

    let (writer, reader) = std::os::unix::net::UnixStream::pair().expect("a socketpair");
    let frame = held
        .delivery()
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 1)
        .expect("the emission's first frame");
    held.send.begin_frame(frame).expect("nothing owed");

    // Begun and not sent is not finished either: the recipient is waiting for
    // bytes this delivery still owes it.
    assert!(held.advance_frame().is_err());
    assert_eq!(held.frame_index(), 0);

    send_pending_frame(&writer, &mut held.send).expect("a healthy send");
    held.advance_frame().expect("the frame in hand went out whole");
    assert_eq!(held.frame_index(), 1, "and only then does the next one begin");
    drop(reader);
}

#[test]
fn one_completed_frame_is_advanced_past_exactly_once() {
    let (sender, queue) = sync_channel(1);
    let (capsule, endpoint) = capsule_and_endpoint(1703);
    let served = XAuthorityServedConnection::retained(endpoint);
    sender
        .send(capsule)
        .expect("the queue to accept it");
    let mut in_flight = None;
    let mut refused = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("one waiting");
    let held = in_flight.as_mut().expect("taken");
    let (writer, reader) = std::os::unix::net::UnixStream::pair().expect("a socketpair");

    let frame = held
        .delivery()
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 1)
        .expect("the emission's first frame");
    held.send.begin_frame(frame).expect("nothing owed");
    send_pending_frame(&writer, &mut held.send).expect("a healthy send");
    held.advance_frame().expect("the frame went out whole");
    assert_eq!(held.frame_index(), 1);

    // The same completed frame cannot be advanced past twice. An index that
    // moved again while nothing had been begun would count a frame that was
    // never started, and the emission frame it skipped would never be sent at
    // all -- an event silently missing from a delivery that reported itself
    // finished.
    let refused = held
        .advance_frame()
        .expect_err("nothing is in hand to advance past");
    assert!(matches!(refused, X11FrameSendFailure::NoFrame));
    assert_eq!(held.frame_index(), 1, "and the index did not move");
    drop(reader);
}

#[test]
fn two_frames_of_one_delivery_reach_the_wire_in_order_and_whole() {
    let (sender, queue) = sync_channel(1);
    let (capsule, endpoint) = capsule_and_endpoint(1704);
    let served = XAuthorityServedConnection::retained(endpoint);
    sender
        .send(capsule)
        .expect("the queue to accept it");
    let mut in_flight = None;
    let mut refused = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("one waiting");
    let held = in_flight.as_mut().expect("taken");
    let (writer, reader) = std::os::unix::net::UnixStream::pair().expect("a socketpair");

    let emission = held.delivery().emission();
    // This fixture's emission has one record, so these are two encodings of
    // the same record with different transport sequences. That makes this a
    // control over frame CUSTODY -- two frames taken, sent, retired and read
    // back in order with nothing of the first carried into the second -- and
    // not evidence that the writer walks distinct emission records. A
    // multi-form emission is what would show that, and this fixture cannot
    // produce one.
    assert_eq!(
        emission.frame_count(),
        1,
        "stated rather than assumed: one record, encoded twice"
    );
    let first = emission
        .encode_frame(0, XByteOrder::LittleEndian, 1)
        .expect("a first frame");
    let second = emission
        .encode_frame(0, XByteOrder::LittleEndian, 2)
        .expect("a second frame");
    let first_bytes = first.as_bytes().to_vec();
    let second_bytes = second.as_bytes().to_vec();
    assert_ne!(
        first_bytes, second_bytes,
        "the sequence is in the bytes, so these are distinguishable on the wire"
    );

    held.send.begin_frame(first).expect("nothing owed");
    send_pending_frame(&writer, &mut held.send).expect("the first frame");
    held.advance_frame().expect("the first went whole");

    held.send.begin_frame(second).expect("the first was retired");
    send_pending_frame(&writer, &mut held.send).expect("the second frame");
    held.advance_frame().expect("the second went whole");
    assert_eq!(held.frame_index(), 2);

    let mut seen = vec![0u8; first_bytes.len() + second_bytes.len()];
    std::io::Read::read_exact(&mut &reader, &mut seen).expect("both frames");
    assert_eq!(
        &seen[..first_bytes.len()],
        first_bytes.as_slice(),
        "the first frame, whole and first"
    );
    assert_eq!(
        &seen[first_bytes.len()..],
        second_bytes.as_slice(),
        "then the second, with nothing of the first carried into it"
    );
    drop(reader);
}

#[test]
fn a_delivery_is_written_one_frame_at_a_time_and_then_is_written() {
    let (writer, reader) = std::os::unix::net::UnixStream::pair().expect("a socketpair");
    let (sender, queue) = sync_channel(1);
    let (capsule, endpoint) = capsule_and_endpoint(1801);
    let served = XAuthorityServedConnection::retained(endpoint);
    sender.send(capsule).expect("accepted");
    let mut in_flight = None;

    // Nothing in flight is its own answer.
    assert_eq!(
        write_one_ordered_frame(&writer, &mut in_flight, XByteOrder::LittleEndian, 1)
            .expect("a step"),
        X11OrderedWriteStep::Idle
    );

    let mut refused = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("one waiting");
    let frames = in_flight
        .as_ref()
        .expect("taken")
        .delivery()
        .emission()
        .frame_count();
    for frame in 0..frames {
        assert_eq!(
            write_one_ordered_frame(&writer, &mut in_flight, XByteOrder::LittleEndian, 1)
                .expect("a step"),
            X11OrderedWriteStep::Advanced { frame },
            "one frame per call, in order"
        );
    }

    // Every frame this delivery owed has gone. That says the bytes went and
    // nothing else: whether the recipient received them is the writer's own
    // outcome to establish, and whether the debt is settled is a question
    // neither this nor a queue can answer.
    assert_eq!(
        write_one_ordered_frame(&writer, &mut in_flight, XByteOrder::LittleEndian, 1)
            .expect("a step"),
        X11OrderedWriteStep::Wrote
    );
    drop(reader);
}

#[test]
fn a_stalled_frame_is_resumed_rather_than_encoded_again() {
    let (writer, reader) = std::os::unix::net::UnixStream::pair().expect("a socketpair");
    let (sender, queue) = sync_channel(1);
    let (capsule, endpoint) = capsule_and_endpoint(1802);
    let served = XAuthorityServedConnection::retained(endpoint);
    sender.send(capsule).expect("accepted");
    let mut in_flight = None;
    let mut refused = None;
    take_ordered_delivery(&queue, &served, &mut in_flight, &mut refused)
        .expect("one waiting");

    // Fill the recipient's buffer so this delivery's frame cannot go out
    // whole, and seed the accumulator so the stall is reached quickly.
    let filler = vec![0u8; 1 << 16];
    // Seeded so the filler gives up as soon as the buffer is full, rather
    // than waiting out its own policy: what is being arranged here is a full
    // recipient, not a measurement.
    let mut filling = X11OrderedSendState {
        blocked: X_AUTHORITY_ORDERED_BLOCKED_LIMIT - Duration::from_millis(60),
        ..X11OrderedSendState::default()
    };
    while {
        if filling.frame_complete() {
            filling.retire_frame().expect("it went");
        }
        if filling.frame.is_none() {
            filling.begin_frame(filler.clone()).expect("nothing owed");
        }
        send_pending_frame(&writer, &mut filling).is_ok()
    } {}

    let held = in_flight.as_mut().expect("taken");
    held.send.blocked = X_AUTHORITY_ORDERED_BLOCKED_LIMIT - Duration::from_millis(60);
    let stalled = write_one_ordered_frame(&writer, &mut in_flight, XByteOrder::LittleEndian, 7)
        .expect_err("the recipient is taking nothing");
    assert!(matches!(
        stalled,
        X11OrderedWriteFailure::Send(X11FrameSendFailure::Blocked { .. })
    ));

    // The frame stays in hand with what the wire took of it. A second call
    // must resume that exact frame: encoding again would produce a second copy
    // of the frame those bytes came from and continue into the middle of it.
    let held = in_flight.as_mut().expect("still in flight");
    assert!(held.send.frame.is_some(), "the frame is still in hand");
    assert_eq!(held.frame_index(), 0, "and it has not been advanced past");

    // The recipient starts reading and this delivery is asked again. The
    // second call has to CONTINUE the frame in hand. A call that encoded again
    // would be asking to begin a frame while one is still owed, and the frame
    // custody refuses exactly that -- so a fresh encoding cannot even reach
    // the socket, and what it would have produced is a second copy of the
    // bytes the wire already holds part of.
    held.send.blocked = Duration::ZERO;
    let mut drained = vec![0u8; 1 << 20];
    let _ = std::io::Read::read(&mut &reader, &mut drained).expect("the recipient reads");
    let resumed = write_one_ordered_frame(&writer, &mut in_flight, XByteOrder::LittleEndian, 7)
        .expect("the frame in hand is continued");
    assert_eq!(
        resumed,
        X11OrderedWriteStep::Advanced { frame: 0 },
        "continuing finished the frame that was already part way out; a call \
         that encoded again would be asking to begin a frame while one is \
         still owed, which the frame custody refuses outright"
    );
    drop(reader);
}

#[test]
fn a_recipient_taking_nothing_leaves_another_recipient_and_the_runner_working() {
    // SCOPE, stated because the obvious reading is wider than what this
    // establishes. It shows that a writer whose recipient takes nothing
    // returns Blocked with its delivery still owned, and that a second
    // recipient's writer and the service runner both complete their work on a
    // run where that is true. It does NOT establish that the first writer was
    // inside its readiness wait while the others ran -- that interval is not
    // observable from here without a fault probe -- and it does not establish
    // that a supervisor can interrupt a writer that is still waiting.
    let (writer_a, reader_a) = std::os::unix::net::UnixStream::pair().expect("a socketpair");
    let (writer_b, reader_b) = std::os::unix::net::UnixStream::pair().expect("a socketpair");
    let (sender_a, queue_a) = sync_channel(1);
    let (sender_b, queue_b) = sync_channel(1);
    let (capsule_a, endpoint_a) = capsule_and_endpoint(1901);
    let (capsule_b, endpoint_b) = capsule_and_endpoint(1902);
    let served_a = XAuthorityServedConnection::retained(endpoint_a);
    let served_b = XAuthorityServedConnection::retained(endpoint_b);
    sender_a.send(capsule_a).expect("accepted");
    sender_b.send(capsule_b).expect("accepted");

    let reached = Arc::new(AtomicBool::new(false));
    let signal = reached.clone();
    let stalled = std::thread::spawn(move || {
        let mut filling = X11OrderedSendState {
            blocked: X_AUTHORITY_ORDERED_BLOCKED_LIMIT - Duration::from_millis(200),
            ..X11OrderedSendState::default()
        };
        let filler = vec![0u8; 1 << 16];
        while {
            if filling.frame_complete() {
                filling.retire_frame().expect("it went");
            }
            if filling.frame.is_none() {
                filling.begin_frame(filler.clone()).expect("nothing owed");
            }
            send_pending_frame(&writer_a, &mut filling).is_ok()
        } {}

        let mut in_flight = None;
        let mut refused = None;
        take_ordered_delivery(&queue_a, &served_a, &mut in_flight, &mut refused)
            .expect("one waiting");
        in_flight.as_mut().expect("taken").send.blocked =
            X_AUTHORITY_ORDERED_BLOCKED_LIMIT - Duration::from_millis(200);
        // Set before the call, and it says only that: this writer is about to
        // attempt a send to a recipient that is taking nothing. It is not a
        // claim about where inside that call the thread is.
        signal.store(true, Ordering::Release);
        let outcome =
            write_one_ordered_frame(&writer_a, &mut in_flight, XByteOrder::LittleEndian, 1);
        (outcome, in_flight, writer_a)
    });

    let limit = std::time::Instant::now() + Duration::from_secs(5);
    while !reached.load(Ordering::Acquire) && std::time::Instant::now() < limit {
        std::thread::yield_now();
    }
    assert!(reached.load(Ordering::Acquire), "A's writer began its attempt");

    // B's recipient reads, so B's delivery goes out whole -- and the bytes are
    // checked off the socket rather than inferred from the step's answer.
    let mut b_flight = None;
    let mut b_refused = None;
    take_ordered_delivery(&queue_b, &served_b, &mut b_flight, &mut b_refused)
        .expect("one waiting");
    let expected = {
        let held = b_flight.as_ref().expect("taken");
        let emission = held.delivery().emission();
        (0..emission.frame_count())
            .map(|index| {
                emission
                    .encode_frame(index, XByteOrder::LittleEndian, 1)
                    .expect("a frame")
                    .as_bytes()
                    .to_vec()
            })
            .collect::<Vec<_>>()
    };
    for _ in 0..expected.len() {
        assert!(matches!(
            write_one_ordered_frame(&writer_b, &mut b_flight, XByteOrder::LittleEndian, 1)
                .expect("B is reading"),
            X11OrderedWriteStep::Advanced { .. }
        ));
    }
    let mut seen = vec![0u8; expected.iter().map(Vec::len).sum()];
    std::io::Read::read_exact(&mut &reader_b, &mut seen).expect("B's bytes");
    assert_eq!(
        seen,
        expected.concat(),
        "B received exactly its delivery's frames, in order"
    );

    // The service runner shares nothing with either socket and completes.
    let client = XServerFrontendClientId(1903);
    let surface = SurfaceId::new(1903, 1);
        let PreparedOrderedFixture {
        keeper,
        mut runner, ingress, channels, registration, durable,
        _acks,
        deliveries: _deliveries,
        selections: _selections,
        client: _client,
        surface: _surface,
        window: _window,
        namespace: _namespace,
    } = prepared_ordered_fixture(client);
    let PrivatePreparedRunner { frontend, keyboards, watch, .. } = &mut runner;
    let private = frontend.as_mut().expect("a live runner");
    let mut inbox = OrderedInbox::default();
    let watch = watch.as_ref().expect("a sealed watch");
    ingress
        .submit(&keeper.lease(), button_to(
            surface,
            XAuthorityInputDeliveryId::from_raw(1903),
            272,
            true,
        ))
        .expect("the order to accept it");
        let press_cell = admitted_cell(private, 1903);
    let turn = private
        .route_pending_ordered(keyboards, watch)
        .expect("a readable order");
    private.deliver_turn(turn);
    let capsule = inbox
        .accepted(private, &channels.ordered, &press_cell, 8)
        .expect("a readable terminal step")
        .expect("the event reached its recipient's ordered queue");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(1903)
    );
    assert_eq!(capsule.client(), client);

    // A's writer reports its own delivery blocked and still owns it. Whether
    // any of the frame reached the wire depends on how full the socket already
    // was, so what is asserted is ownership and position, not partiality.
    let (outcome, in_flight, writer_a) = stalled.join().expect("A's writer returns");
    assert!(matches!(
        outcome,
        Err(X11OrderedWriteFailure::Send(X11FrameSendFailure::Blocked { .. }))
    ));
    let held = in_flight.as_ref().expect("A still owns its delivery");
    assert!(held.send.frame.is_some(), "with its frame still in hand");
    assert_eq!(held.frame_index(), 0, "and not advanced past");

    // Taking the socket down afterwards does not disturb what is owned. This
    // is shutdown of a writer that has already returned, not interruption of
    // one still waiting.
    writer_a
        .shutdown(std::net::Shutdown::Both)
        .expect("the socket can be ended");
    assert!(in_flight.as_ref().expect("still owned").send.frame.is_some());
    drop(reader_a);
    drop(registration);
    drop(channels);
    drop(durable);
}


#[test]
fn a_request_carries_the_capability_it_was_reserved_under() {
    let client = XServerFrontendClientId(2001);
    let surface = SurfaceId::new(2001, 1);
    let window = XResourceId::new(0x202001, 1);
    let (private, _registration, role, _keyboards, _keeper) =
        ordered_fixture(client, surface, window);
    let stamp = private.control_gate().stamp().expect("an open coordinator");
    let reserved = role.reserve(stamp, 1).expect("a reservation");

    // The capability the reservation was issued with, and the one the custody
    // answers with, are the same. A native operation checks that the
    // capability and the permit name one source, and a capability read from
    // the producer at execution time would be whatever it holds then rather
    // than the one this request was accepted against -- which is the whole of
    // what makes that check mean anything.
    let expected = reserved.capability();
    let custody = reserved.accepted();
    assert_eq!(
        custody.capability().source(),
        expected.source(),
        "the custody answers with the capability the request was reserved under"
    );
    let _ = custody.observe();
}

/// One prepared runner with a recipient that has actually selected.
///
/// Built in the order the production path builds it: connection state
/// attached, the source's own window geometry and selections registered,
/// the runner prepared -- which installs the applied registry itself, so
/// nothing here reinstalls it -- and then a real initial focus clear applied
/// through the installed publication. A pointer press resolves against that
/// clear; it admits no key target and is not pretending to.
///
/// Every step unwraps. A setup that cannot reach the prepared state fails the
/// control rather than leaving its body to run against something else.
#[allow(dead_code)]
struct PreparedOrderedFixture {
    runner: PrivatePreparedRunner,
    /// Taken from the runner at construction so a control can borrow the
    /// frontend, the keyboards and the watch disjointly afterwards. The
    /// producer is owned, so holding it costs the runner no borrow.
    ingress: crate::PrivateIngress,
    durable: PrivateSettlementOwner,
    registration: XServerFrontendClientRouteRegistration,
    channels: XServerFrontendClientRouteChannels,
    _acks: Receiver<XAuthorityClientControlAck>,
    deliveries: Receiver<XAuthorityClientInputDelivery>,
    /// The source's own view of this connection's windows, so a control can
    /// change what a fresh resolution would reach.
    selections: Arc<Mutex<XCoreEventSelectionState>>,
    client: XServerFrontendClientId,
    surface: SurfaceId,
    window: XResourceId,
    namespace: NamespaceId,
    /// The owner that keeps this store and this connection's evidence.
    ///
    /// DECLARED LAST SO IT IS DROPPED LAST. Fields go in declaration order, so
    /// the runner and its frontend end before this does -- which is the
    /// ordering the service has in life: a service exits, and its keeper is
    /// destroyed separately and afterwards.
    keeper: crate::PrivateServiceOwner,
}

fn prepared_ordered_fixture(client: XServerFrontendClientId) -> PreparedOrderedFixture {
    let namespace = NamespaceId::from_raw(client.raw());
    let surface = SurfaceId::new(u32::try_from(client.raw()).unwrap(), 1);
    let window = XResourceId::new(0x200000 | client.raw(), 1);
    let durable = PrivateSettlementOwner::default();
    let (ack_sender, acks) = sync_channel(8);
    let (delivery_sender, deliveries) = channel();
    let (authority, issuer, submit) = private_authority();
    let service_keeper = service_owner(&durable, 16);
    let private = PrivateXServerFrontend::new(
        PrivateFrontendParts {
            max_concurrent_clients: NonZeroUsize::new(16).unwrap(),
            input_capacity: NonZeroUsize::new(4).unwrap(),
            control_acknowledgements: ack_sender,
            input_deliveries: delivery_sender,
            authority,
            issuer,
            submit,
        },
        &service_keeper,
    )
    .unwrap_or_else(|(cause, _)| panic!("construction refused: {cause:?}"));
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a fresh client registers");
    // Admitted through the lifecycle rather than beside it: attaching the
    // lifecycle admits too, so a fixture that did both would be refused as
    // already admitted, and one that admits without it leaves anything
    // closing this connection with no gate to close.
    private
        .broker
        .registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the boundary admits and the lifecycle attaches");
    // The selections the resolver actually reads, and the focus projection,
    // both retained here rather than left to defaults.
    let selections = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
    let focused = Arc::new(AtomicU64::new(0));
    private
        .broker
        .registry
        .attach_connection_state(&registration, namespace, selections.clone(), focused.clone())
        .expect("the connection state attaches");
    {
        // The source's own view of this window: where it sits, that it is
        // mapped, and that this recipient selected button press and release.
        // Updating the coarse subscription map instead would leave the
        // resolver reading a selection state nobody had told anything.
        let mut selected = selections.lock().expect("the selections");
        selected.register(
            window,
            XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
            Rect {
                x: 0,
                y: 0,
                width: 200,
                height: 100,
            },
        );
        selected.observe_mapped(window);
        selected.update(window, Some((1 << 2) | (1 << 3)), None);
    }
    private
        .broker
        .registry
        .register_surface(client, namespace, surface, window)
        .expect("the surface registers");

    let mut runner = private
        .prepare_runner(namespace, &service_keeper)
        .unwrap_or_else(|(cause, _)| panic!("runner refused: {cause:?}"));
    let ingress = runner
        .ingress_for(&service_keeper.lease(), client, DeviceId::from_raw(1))
        .expect("the runner exposes a producer");

    // A real initial clear through the publication the runner installed,
    // borrowed rather than installed again. Nothing here sets a published flag
    // or seeds the focus atomic as though that were the same thing.
    {
        let publication = runner
            .frontend
            .as_ref()
            .expect("a live runner")
            .broker
            .registry
            .private_applied
            .get()
            .expect("prepare_runner installed it")
            .publication
            .clone();
        let mut runtime = XAuthorityRuntime::new();
        runtime.prepare_input_focus_namespace(namespace);
        publication
            .lock()
            .expect("the publication")
            .begin_focus_change()
            .expect("a focus change")
            .apply(&mut runtime, &focused, None)
            .expect("the clear applies");
    }

    PreparedOrderedFixture {
        keeper: service_keeper,
        runner,
        ingress,
        durable,
        registration,
        channels,
        _acks: acks,
        deliveries,
        selections,
        client,
        surface,
        window,
        namespace,
    }
}

#[test]
fn a_prepared_runner_presses_through_its_real_producer() {
    let client = XServerFrontendClientId(2101);
    let mut fixture = prepared_ordered_fixture(client);
    let lease = fixture.keeper.lease();
    let ingress = fixture
        .runner
        .ingress_for(&lease, client, DeviceId::from_raw(1))
        .expect("the runner exposes a producer");
    ingress
        .submit(&fixture.keeper.lease(), button_to(
            fixture.surface,
            XAuthorityInputDeliveryId::from_raw(2101),
            272,
            true,
        ))
        .expect("the order accepts it");

    // Driven through the runner's own turn, which is what production drives.
    let progress = fixture
        .runner
        .service_turn(&lease)
        .expect("a readable order");
    assert_eq!(progress.taken, 1, "the runner took the submitted work");
    assert_eq!(progress.refused, 0, "and did not refuse it");
    drop(fixture.registration);
    drop(fixture.channels);
    drop(fixture.durable);
}

// Disposable signed-source review controls. No production source changes.
// Each operation uses the prepared source fixture, its actual reservation,
// native guarded execution and completion observation. Terminal dispatch is
// invoked separately to expose the scheduling state without unrelated work.
fn attempt_run(f: &mut PreparedOrderedFixture, id: u64, button: u32, pressed: bool) {
    f.ingress.submit(&f.keeper.lease(), button_to(f.surface, XAuthorityInputDeliveryId::from_raw(id), button, pressed)).unwrap();
    let PrivatePreparedRunner { frontend, keyboards, watch, .. } = &mut f.runner;
    let p = frontend.as_mut().unwrap();
    assert!(matches!(p.step_once(keyboards, &mut |_, _| Ok(()), watch.as_ref().unwrap()).unwrap(), PrivateOrderedStep::Decided(_)));
    // Observe this decided request without invoking the terminal scheduler,
    // so the control can drive and inspect release dispatch separately.
    let Some(PrivateOrderedItem::Ran { run, custody, .. }) = p.terminal.turn.pop() else { panic!("real accepted input must run"); };
    if !pressed {
        assert!(matches!(run.release, Some(sophia_input_authority::ReleaseOutcome::DeliverTo(_))), "release outcome {:?}", run.release);
    }
    assert!(custody.observe().unwrap().is_some());
}

fn attempt_release(f: &mut PreparedOrderedFixture, id: u64, button: u32) {
    attempt_run(f, id, button, true);
    attempt_run(f, id + 1, button, false);
}


fn order_pass_frames(c: &XAuthorityOrderedDelivery) -> Vec<Vec<u8>> {
    let emission=c.emission();
    (0..emission.frame_count()).map(|index|emission.encode_frame(index,XByteOrder::LittleEndian,7).unwrap().as_bytes().to_vec()).collect()
}


/// The gated sender for this client, captured the way a producer captures it:
/// under the client table, cloned out of the row, table released.
fn capture_gated_sender(
    private: &crate::PrivateXServerFrontend,
    client: XServerFrontendClientId,
) -> PrivateGatedOrderedSender {
    let guard = private
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry");
    let sender = guard
        .get(&client)
        .expect("this client has a row")
        .ordered
        .clone();
    drop(guard);
    sender
}

#[test]
fn a_sender_captured_before_a_close_is_refused_after_it() {
    // THE CAPTURE IS THE PROBLEM THE GATE EXISTS FOR. A producer clones the
    // sender under the client table and releases the table before it hands
    // anything over, so removing the row or reading a flag at lookup time
    // cannot stop a handover that already has its sender. This pins that exact
    // interval: captured before, used after.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8201));
    attempt_run(&mut f, 82010, 272, true);
    let captured = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    assert!(
        captured.admit().is_ok(),
        "before the close the captured sender admits"
    );

    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    assert_eq!(f.registration.ordered_handovers_fenced(), Some(true));

    // The same sender, captured before any of that.
    let refusal = captured
        .admit()
        .err()
        .expect("a captured sender is not permission");
    assert_eq!(refusal, PrivateHandoverRefusal::Fenced);

    // And nothing was lost to find that out: the press is still in custody,
    // its phase untouched, its cell unanswered, and no capsule reached the
    // queue.
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 82010);
    let private = f.runner.frontend.as_ref().unwrap();
    assert_eq!(private.terminal.holds.len(), 1);
    assert!(private.terminal.holds[0].native.is_some());
    assert_eq!(
        handover_phase(private, &cell),
        Some(PrivateDispatchPhase::Untaken),
        "nothing has been offered yet, so nothing moved"
    );
    assert!(cell.answer().is_none());
    assert!(f.channels.ordered.try_recv().is_err());
}

#[test]
fn a_fence_waits_for_a_handover_already_admitted() {
    // THE OTHER SIDE OF THE SAME INTERVAL. A handover that got in before the
    // close finishes, and the close cannot report a fence until it has.
    //
    // WHAT THIS ESTABLISHES, exactly: this thread provably holds the admission
    // for the whole window, and the closer's own message -- sent only after
    // close returns -- does not arrive during it. What it does NOT establish
    // is that the closer reached its lock: the 150ms is a timeout, not a
    // rendezvous, and a closer that had not started yet would look the same
    // from here. The message witnesses completion, not arrival.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8211));
    attempt_run(&mut f, 82110, 272, true);
    let captured = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    // A fixture capsule, not one this recipient's own source built. It is here
    // to be a thing that crosses the gate, so what this control says is about
    // the gate and the channel -- not about which capsules a recipient admits,
    // which is the endpoint check's subject and is covered elsewhere.
    let (capsule, _endpoint) = capsule_and_endpoint(82119);
    let admitted = captured.admit().expect("an open endpoint");

    let gate = f.registration.ordered_gate.clone();
    let (done, fenced) = sync_channel(1);
    let closer = std::thread::spawn(move || {
        let outcome = gate.close();
        done.send(outcome).expect("the control is listening");
    });
    assert_eq!(
        fenced.recv_timeout(std::time::Duration::from_millis(150)),
        Err(std::sync::mpsc::RecvTimeoutError::Timeout),
        "a close cannot report a fence while a handover is admitted"
    );

    // The admitted handover completes, under the admission, as production
    // does it.
    admitted.try_send(capsule).expect("an admitted handover");
    drop(admitted);
    let outcome = fenced
        .recv_timeout(std::time::Duration::from_secs(5))
        .expect("the close completes once the handover is done");
    assert_eq!(outcome, PrivateHandoverFence::Established);
    closer.join().expect("the closing thread");

    // The handover that was already in is on the queue, whole.
    let arrived = f
        .channels
        .ordered
        .try_recv()
        .expect("the admitted handover completed before the fence");
    assert_eq!(
        arrived.delivery(),
        XAuthorityInputDeliveryId::from_raw(82119)
    );
    assert!(f.channels.ordered.try_recv().is_err());
}

#[test]
fn closing_one_endpoint_leaves_a_replacement_registration_untouched() {
    // EXACT. The gate is minted with the queue and bound to the registration
    // that minted it, so a close reaches that registration's handovers and no
    // others. A close that found its gate by client id would fence whoever
    // holds the id now.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8221));
    attempt_run(&mut f, 82210, 272, true);
    let original = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    // ITS GATE IS CAPTURED BEFORE ITS REGISTRATION GOES. The gate is the
    // capability; keeping it is how this control closes the OLD endpoint after
    // that registration has given its number back.
    let original_gate = f.registration.handover_gate();
    let replacement_context = admission_with(f.client, 82219, ROLE_SESSION_GENERATION);
    let spare = spare_registration(&f);
    let original_registration = std::mem::replace(&mut f.registration, spare);
    let (replacement, replacement_channels, _endpoint) = replace_registration(
        f.runner.frontend.as_mut().unwrap(),
        f.client,
        replacement_context,
        namespaced(f.client, f.namespace).client_id,
        original_registration,
        None,
    );

    // The old endpoint closes. The replacement minted its own gate.
    // Closed through the OLD endpoint's own captured gate. Its registration
    // has gone -- which is what freed the number for the replacement -- and
    // the capability it published is what a later closer holds.
    assert_eq!(
        original_gate.close(),
        PrivateHandoverFence::AlreadyEstablished,
        "its own ending closed it; this is that same gate saying so"
    );
    assert_eq!(original_gate.fenced(), Some(true));
    assert_eq!(
        replacement.ordered_handovers_fenced(),
        Some(false),
        "closing an old endpoint must not reach a newer registration"
    );

    let (capsule, _) = capsule_and_endpoint(82219);
    assert_eq!(
        original.admit().err(),
        Some(PrivateHandoverRefusal::Fenced),
        "the closed endpoint's captured sender stays refused"
    );
    let live = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    gated_send(&live, capsule).expect("the replacement's endpoint is open");
    assert_eq!(
        replacement_channels
            .ordered
            .try_recv()
            .expect("onto the replacement's queue")
            .delivery(),
        XAuthorityInputDeliveryId::from_raw(82219)
    );
    assert!(f.channels.ordered.try_recv().is_err());
    drop(replacement);
}

#[test]
fn a_fenced_endpoint_refuses_a_press_handover_and_keeps_everything() {
    // Through the production press path, not a hand-held sender.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8231));
    attempt_run(&mut f, 82310, 272, true);
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 82310);
    let private = f.runner.frontend.as_mut().unwrap();
    let native = private.terminal.holds[0].native.as_ref().unwrap() as *const _ as usize;
    let incarnation = private.terminal.holds[0].incarnation;

    assert_eq!(
        private.dispatch_one_press(),
        Some(false),
        "a fenced endpoint takes no press"
    );

    // NOTHING TAKEN, NOTHING WRITTEN. The capsule was built before the
    // handover was attempted, so Pending is where it belongs -- and NOT
    // Indeterminate, which is the write-ahead mark saying a handover may
    // already have reached the recipient. An endpoint that refused admission
    // never began one, so this capsule is still offerable rather than
    // unrepeatable.
    let phase = handover_phase(private, &cell);
    assert_ne!(
        phase,
        Some(PrivateDispatchPhase::Indeterminate),
        "a refused admission must never mark a handover begun"
    );
    assert_eq!(phase, Some(PrivateDispatchPhase::Pending));
    let owned = matches!(
        private.terminal.holds[0].custody.pending.as_ref(),
        Some(PrivatePendingDelivery::Capsule(capsule))
            if capsule.delivery() == XAuthorityInputDeliveryId::from_raw(82310)
                && Arc::ptr_eq(&cell, &capsule.finalizer().unwrap().completion)
    );
    assert!(owned, "the exact capsule stays inventory-owned");
    assert_eq!(private.terminal.holds[0].incarnation, incarnation);
    assert_eq!(
        private.terminal.holds[0].native.as_ref().unwrap() as *const _ as usize,
        native
    );
    assert!(cell.answer().is_none());
    assert!(f.channels.ordered.try_recv().is_err());
}

#[test]
fn a_fenced_endpoint_refuses_a_release_handover_and_gives_the_attempt_back() {
    // The release path carries an attempt reservation. A refusal before
    // anything is written down leaves it an unused reservation, so it goes
    // back through the confirmed give-back -- and the give-back runs with no
    // gate held, because admission was never obtained.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8241));
    attempt_release(&mut f, 82410, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));
    let press = f.channels.ordered.try_recv().expect("the press went first");
    assert_eq!(press.delivery(), XAuthorityInputDeliveryId::from_raw(82410));

    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 82411);
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(
        private.attempt_one_delivery(),
        Some(false),
        "a fenced endpoint takes no release"
    );
    // The attempt was claimed and given back before anything was written
    // down, so nothing is left holding it: not the record, and not the
    // executor's own attempt custody.
    assert!(
        private.terminal.attempt_custody.is_none(),
        "an attempt that was never begun leaves no custody behind"
    );
    let phase = handover_phase(private, &cell);
    assert_ne!(
        phase,
        Some(PrivateDispatchPhase::Indeterminate),
        "a refused admission must never mark a handover begun"
    );
    assert_eq!(phase, Some(PrivateDispatchPhase::Pending));
    assert!(
        private.terminal.settling[0].custody.attempt.is_none(),
        "the record never named an attempt it did not begin"
    );
    assert!(cell.answer().is_none());
    assert!(f.channels.ordered.try_recv().is_err());
}

#[test]
fn a_gate_that_cannot_be_read_is_retained_failure_and_never_a_fence() {
    // UNREADABLE IS NOT FENCED. A close that reported one as the other would
    // name a fence that was never established, and a caller would go on to end
    // a socket under handovers that may still be running. A producer refuses
    // for the same reason: an unestablished answer is not permission.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8251));
    attempt_run(&mut f, 82510, 272, true);
    let gate = f.registration.ordered_gate.clone();
    let poisoner = std::thread::spawn(move || {
        let _admitted = gate.fenced.lock().expect("an open gate");
        panic!("poison this gate while a handover holds it");
    });
    assert!(poisoner.join().is_err(), "the gate's holder panicked");

    assert_eq!(
        f.registration.ordered_handovers_fenced(),
        None,
        "an unreadable gate is neither open nor closed"
    );
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Unreadable,
        "nothing was established, so no fence may be reported"
    );
    let captured = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    assert_eq!(
        captured.admit().err(),
        Some(PrivateHandoverRefusal::Unreadable)
    );

    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 82510);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(false));
    let phase = handover_phase(private, &cell);
    assert_ne!(
        phase,
        Some(PrivateDispatchPhase::Indeterminate),
        "an unreadable gate is not permission, and refusing on it begins nothing"
    );
    assert_eq!(phase, Some(PrivateDispatchPhase::Pending));
    assert!(cell.answer().is_none());
    assert!(f.channels.ordered.try_recv().is_err());
}


#[test]
fn a_full_refusal_then_a_close_retains_once_and_gives_the_attempt_back_once() {
    // TWO REFUSALS, ONE ACCOUNTING. A queue that was Full gave the capsule
    // back and the attempt with it; a close afterwards refuses admission and
    // must not give the same attempt back a second time, nor take the capsule,
    // nor replay it. Full and fenced are different facts about the same
    // delivery and neither may be read as the other.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8261));
    // One complete pair of this recipient's own deliveries takes two of its
    // four slots, through the ordinary press-then-release flow.
    attempt_release(&mut f, 82610, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));
    assert_eq!(private.attempt_one_delivery(), Some(true));

    // A second pair: its press takes the third slot, and its release is the
    // one this control is about.
    attempt_release(&mut f, 82614, 274);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));
    assert_eq!(
        private.broker.registry.per_client_input_capacity.get(),
        4,
        "four slots"
    );

    // The fourth slot is filled directly, through the same gate production
    // uses, so the release below meets a genuinely full queue rather than a
    // staged refusal. The filler is a fixture capsule: it is here to occupy a
    // slot, and no claim is made that this recipient would admit it.
    let filler = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    let (fill, _) = capsule_and_endpoint(82699);
    gated_send(&filler, fill).expect("the fourth slot");

    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 82615);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(
        private.attempt_one_delivery(),
        Some(false),
        "the fifth delivery meets a genuinely Full queue"
    );
    let after_full = handover_phase(private, &cell);
    assert_eq!(after_full, Some(PrivateDispatchPhase::Pending));
    assert!(private.terminal.attempt_custody.is_none());
    let index = private
        .terminal
        .settling
        .iter()
        .position(|release| release.completion().is_some_and(|held| Arc::ptr_eq(held, &cell)))
        .expect("the refused release is still here");
    assert!(private.terminal.settling[index].custody.attempt.is_none());
    let frames = match private.terminal.settling[index].custody.pending.as_ref() {
        Some(PrivatePendingDelivery::Capsule(capsule)) => order_pass_frames(capsule),
        _ => panic!("the Full refusal gave the exact capsule back"),
    };

    // Now the endpoint closes, and the same delivery is offered again.
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.attempt_one_delivery(), Some(false));
    assert_eq!(
        handover_phase(private, &cell),
        after_full,
        "a fenced refusal leaves the phase the Full refusal left"
    );
    assert!(private.terminal.attempt_custody.is_none());
    assert!(private.terminal.settling[index].custody.attempt.is_none());
    match private.terminal.settling[index].custody.pending.as_ref() {
        Some(PrivatePendingDelivery::Capsule(capsule)) => {
            assert_eq!(
                capsule.delivery(),
                XAuthorityInputDeliveryId::from_raw(82615)
            );
            assert!(Arc::ptr_eq(&cell, &capsule.finalizer().unwrap().completion));
            assert_eq!(
                order_pass_frames(capsule),
                frames,
                "the bytes the release decided, unchanged by either refusal"
            );
        }
        _ => panic!("the fenced refusal took nothing"),
    }
    assert!(cell.answer().is_none());

    // The four that were admitted before the close are still theirs to read.
    let mut seen = Vec::new();
    while let Ok(capsule) = f.channels.ordered.try_recv() {
        seen.push(capsule.delivery());
    }
    assert_eq!(
        seen,
        [82610, 82611, 82614, 82699].map(XAuthorityInputDeliveryId::from_raw),
        "a close takes nothing back that was already handed over"
    );
}


#[test]
fn a_producer_waiting_on_the_ledger_is_not_holding_the_handover_gate() {
    // THE GATE IS NOT HELD ACROSS A LEDGER ACQUISITION. Every producer for
    // this endpoint passes through the gate, and the attempt path takes common
    // twice -- to claim, and to give back. A gate held across either would put
    // every producer for this connection behind the ledger, and would put the
    // gate underneath a lock other work takes for its own reasons.
    //
    // WHAT THIS ESTABLISHES, exactly: common is held for a window in which the
    // producer provably cannot complete, and throughout that window the gate
    // still answers a different thread. It does NOT establish where in the
    // attempt path the producer is waiting -- with common held it stops at the
    // claim, which is the first acquisition -- so it pins the claim side of
    // that rule and not the give-back side. The give-back runs after the
    // admission is dropped by construction; no control here witnesses it.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8271));
    attempt_release(&mut f, 82710, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    let captured = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), f.client);
    let common = Arc::clone(&f.runner.frontend.as_ref().unwrap().authority().common);

    // Held for the whole window: nothing that needs the ledger can finish.
    let ledger = common.lock().expect("a readable authority");
    let mut frontend = f.runner.frontend.take().expect("this fixture's frontend");
    let (refused, produced) = sync_channel(1);
    let producer = std::thread::spawn(move || {
        let outcome = frontend.attempt_one_delivery();
        refused.send(outcome).expect("the control is listening");
        frontend
    });

    // Probed from a third thread, so a gate that is being held shows up as an
    // answer that does not arrive rather than as a control that never returns.
    let (probed, answers) = sync_channel(64);
    let prober = std::thread::spawn(move || {
        for _ in 0..40 {
            let answer = captured.admit().err();
            if probed.send(answer).is_err() {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    });
    for _ in 0..40 {
        assert_eq!(
            answers.recv_timeout(std::time::Duration::from_secs(2)),
            Ok(Some(PrivateHandoverRefusal::Fenced)),
            "the gate must answer while a producer waits on the ledger: a \
             producer holding it across that wait would block every other \
             producer for this endpoint"
        );
    }
    assert_eq!(
        produced.try_recv(),
        Err(std::sync::mpsc::TryRecvError::Empty),
        "and the producer had not completed, so the window was real"
    );
    prober.join().expect("the probing thread");

    drop(ledger);
    assert_eq!(
        produced
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("the producer completes once the ledger is free"),
        Some(false)
    );
    let frontend = producer.join().expect("the producing thread");
    assert!(frontend.terminal.attempt_custody.is_none());
    f.runner.frontend = Some(frontend);
}


/// A retained continuation with an INDEPENDENT HANDLE on its connection.
///
/// A receiver alone can never establish an ending -- it has nothing to end
/// with -- so a control whose subject is what happens after an ending must
/// bind a real transport rather than assert the ending into a record.
fn transport_continuation(
    registration: &XServerFrontendClientRouteRegistration,
    ordered: XAuthorityOrderedReceiver,
) -> PrivateOrderedContinuation {
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let transport = XAuthorityOrderedTransport::bind(
        registration,
        ordered,
        &output,
        &wire,
        &pending,
        None,
    )
    .unwrap_or_else(|_| panic!("this registration's own receiver"));
    PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Transport(Box::new(transport)),
        refusal: X11OrderedServingRefusal::Unserved,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    }
}

/// What a retained continuation is, read from the place a connection held.
fn retained_setup_kind(
    durable: &PrivateSettlementOwner,
    index: usize,
) -> Option<(&'static str, X11OrderedServingRefusal, usize, bool, bool)> {
    durable.with_ordered_continuation(index, |continuation| match continuation {
        PrivateOrderedContinuation::Setup {
            accepted,
            refusal,
            retained,
            drained,
            ended,
            ..
        } => (
            match accepted {
                PrivateOrderedSetupCustody::Receiver(_) => "receiver",
                PrivateOrderedSetupCustody::Transport(_) => "transport",
            },
            *refusal,
            retained.len(),
            *drained,
            *ended,
        ),
        PrivateOrderedContinuation::Serving { .. } => panic!("no owner is built yet"),
    })
}

#[test]
fn a_connections_ordered_output_is_retained_whole_when_its_registration_ends() {
    // UNTIL NOW THIS QUEUE WAS DROPPED. A registration publishes its ordered
    // sender before anything is bound, so a capsule can be accepted into that
    // queue immediately; ending the connection without moving the queue into
    // the place reserved for it discarded accepted work nobody had answered
    // for.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8301);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    assert_eq!(durable.continuations_reserved(), Some(1));

    // Bound where both halves are owned, exactly as connection setup does it.
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        None,
        "this receiver was minted by this registration, so it binds"
    );

    // A capsule is accepted for this connection before it ends.
    let sender = capture_gated_sender(&private, client);
    // A capsule that carries its own completion, so what survives retention
    // can be checked as a payload and not only as a count. It is a fixture
    // capsule: it is here to be work on this queue, and no claim is made that
    // this recipient would have admitted it.
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83010);
    let frames = order_pass_frames(&capsule);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    gated_send(&sender, capsule).expect("an open endpoint");

    drop(registration);
    let (kind, refusal, retained, drained, ended) =
        retained_setup_kind(&durable, 0).expect("the place this connection held");
    assert_eq!(kind, "transport", "the binding is retained, not just the queue");
    assert_eq!(
        refusal,
        X11OrderedServingRefusal::Unserved,
        "no owner was built, and that is the reason recorded"
    );
    assert_eq!(
        (retained, drained, ended),
        (0, false, false),
        "teardown receives nothing, learns nothing about producers, and ends \
         no wire: each of those is a separate act with its own outcome"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the place is still this connection's, because the work in it is not gone"
    );
    assert_eq!(durable.continuations_retained(), Some(1));

    // THE PAYLOAD, not the counters. A kind and a count would be satisfied by
    // a queue that had been emptied and a record that said the right words, so
    // the exact capsule is taken out of the retained receiver here and checked
    // against the one that went in: same delivery, same encoded frames, same
    // completion cell.
    let survived = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup { accepted, .. } = continuation else {
                panic!("no owner is built yet")
            };
            let PrivateOrderedSetupCustody::Transport(transport) = accepted else {
                panic!("this connection bound")
            };
            transport.ordered.receiver.try_recv().ok()
        })
        .expect("the place this connection held")
        .expect("the capsule accepted before the connection ended");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83010)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none(), "and nothing answered for it");
}

#[test]
fn a_connections_own_reservation_keeps_the_store_it_must_dispose_into() {
    // AN EXPOSED CONNECTION CARRIES ITS OWN GUARANTEE. Its registration holds
    // a place in the store and work can already be accepted for it, so the
    // store has to be there when that place is disposed of. Nothing else makes
    // it so: the constructor takes the store by reference, but a reference
    // parameter does not bind the instance -- or the registrations it hands
    // out -- to the caller's binding, and a caller may drop its own holder
    // while a connection is live. A reservation that did not hold it would
    // find, at teardown, that the place it was promised had gone.
    let capability;
    let client = XServerFrontendClientId(8341);
    let (registration, cell, frames, wire_weak) = {
        let durable = PrivateSettlementOwner::default();
        capability = durable.settlement_ref();
        let service_keeper = service_owner(&durable, 2);
        let private = private_over(&service_keeper, 2);
        let (registration, channels) = private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client)))
            .expect("a place and a row");
        let (stream, _peer) = UnixStream::pair().expect("a socket pair");
        let output = Arc::new(Mutex::new(stream));
        let wire = Arc::new(X11WirePermission::open());
        let pending = Arc::new(AtomicUsize::new(0));
        assert_eq!(
            registration
                .bind_ordered_output(channels.ordered, &output, &wire, &pending)
                .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
            None
        );
        // A capsule is accepted for this connection before anything is
        // dropped. It is a fixture capsule carrying its own completion: it is
        // here to be work on this queue, and no claim is made that this
        // recipient would have admitted it.
        let sender = capture_gated_sender(&private, client);
        let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83410);
        let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
        let frames = order_pass_frames(&capsule);
        gated_send(&sender, capsule).expect("an open endpoint");
        let wire_weak = Arc::downgrade(&wire);
        (registration, cell, frames, wire_weak)
    };
    // EVERY HOLDER OUTSIDE THE CONNECTION IS NOW GONE -- the caller's own
    // binding and the instance that cloned it -- and the connection is live.
    assert!(
        capability.owner().is_some(),
        "an exposed connection's reservation is a legitimate owner of its store"
    );

    // Read through an upgraded owner, so what teardown does is observed rather
    // than inferred from the connection having ended quietly.
    let kept = capability.owner().expect("held by the live reservation");
    drop(registration);
    assert_eq!(kept.continuations_retained(), Some(1));
    let survived = kept
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup { accepted, .. } = continuation else {
                panic!("no owner is built yet")
            };
            let PrivateOrderedSetupCustody::Transport(transport) = accepted else {
                panic!("this connection bound")
            };
            transport.ordered.receiver.try_recv().ok()
        })
        .expect("the place this connection held")
        .expect("the capsule accepted before anything was dropped");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83410)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none(), "and nothing answered for it");
    assert!(
        wire_weak.upgrade().is_some(),
        "the binding is retained with the queue, not merely the capsules"
    );

    // AND THIS IS ONE END OF A LIFETIME, NOT A RING. The connection has gone
    // and disposed of its place; when the last reader lets go, so does the
    // store, and the binding it retained goes with it.
    drop((survived, cell, kept));
    assert!(capability.owner().is_none());
    assert!(wire_weak.upgrade().is_none());
}

/// Put a staged continuation in a lease's home and retain its place, which is
/// what a connection's binding and its teardown do between them.
///
/// Both halves are the real ones: the home is the one the reservation made,
/// the binding is the home's own, and the place is accounted for by the
/// lease's own commitment. What is staged is the payload, as it was before.
fn retain_into(
    slot: PrivateOrderedContinuationSlot,
    source: &mut Option<PrivateOrderedContinuation>,
) -> PrivateContinuationCommit {
    let home = slot.home().expect("the place this lease names");
    if let Some(payload) = source.take() {
        assert!(
            matches!(home.bind(payload), PrivateHomeBinding::Bound),
            "a fresh home takes its connection's binding"
        );
    }
    let owed = home.retain();
    slot.commit(owed)
}

/// A registration bound to a real socket, with one capsule accepted for it.
///
/// The connection's own reservation, its published queue and its binding, all
/// through production construction -- the shape every control below starts
/// from. The payload is in the home the reservation made from the moment the
/// binding lands; nothing in these controls puts it there.
/// A converted connection, its instance, and the owner that keeps both.
type ConvertedFixture = (
    crate::PrivateXServerFrontend,
    XServerFrontendClientRouteRegistration,
    Arc<PrivateDeliveryCompletion>,
    Vec<Vec<u8>>,
    std::sync::Weak<X11WirePermission>,
    crate::PrivateServiceOwner,
);

fn converted_fixture(
    durable: &PrivateSettlementOwner,
    client: XServerFrontendClientId,
    delivery: u64,
) -> ConvertedFixture {
    // The owner is handed back rather than kept here: one that died as this
    // returned would leave the caller holding a service with no keeper.
    let service_keeper = service_owner(durable, 2);
    let private = private_over(&service_keeper, 2);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        None
    );
    let sender = capture_gated_sender(&private, client);
    // A fixture capsule carrying its own completion: work on this queue, with
    // no claim that this recipient would have admitted it.
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(delivery);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    gated_send(&sender, capsule).expect("an open endpoint");
    let wire_weak = Arc::downgrade(&wire);
    (private, registration, cell, frames, wire_weak, service_keeper)
}

/// The place a registration reserved, taken without ending the connection.
fn lease_of(
    registration: &XServerFrontendClientRouteRegistration,
) -> PrivateOrderedContinuationSlot {
    registration
        .ordered_continuation
        .lock()
        .expect("a readable registration")
        .take()
        .expect("the place reserved before this connection was exposed")
}

/// Wait for a delivery's completion to be published on its own cell.
///
/// A FINISHED WRITE IS NOT A RECEIPT. The step that puts the last byte of an
/// event on the wire can return Advanced; finalising it is the step after
/// that. A control that read the bytes and then stopped the body would be
/// asking for a receipt nobody had written yet -- and bytes, a stop and a join
/// cannot supply one between them.
///
/// Bounded, because a control that never finishes reports nothing.
fn published(cell: &Arc<PrivateDeliveryCompletion>) -> bool {
    waited_for(|| cell.answer().is_some())
}

/// Poll for an observation, bounded.
///
/// THE BOUND IS NOT THE EVIDENCE. What a caller establishes is whatever it
/// asked about, and this only decides how long to keep asking before giving
/// up; a control that never finished would report nothing at all. Yielding
/// alone is not enough on a machine running the rest of the suite beside it --
/// a spin can exhaust itself while the thread it is waiting on has not been
/// scheduled.
fn waited_for(mut observed: impl FnMut() -> bool) -> bool {
    for _ in 0..3_000 {
        if observed() {
            return true;
        }
        std::thread::sleep(Duration::from_millis(1));
    }
    false
}

/// Whether a body left because this control cancelled it.
///
/// TWO LEGAL ANSWERS, and which one a run gives is the scheduler's. A body
/// told to stop before its own check departs itself; one told between that
/// check and its visit has the OWNER observe the stop, and the trigger is then
/// the owner's step. Both carry the owner's own word, which is the fact worth
/// asserting -- the trigger alone is a race.
fn stopped_by_cancellation(outcome: &PrivateWorkerOutcome) -> bool {
    matches!(
        outcome.trigger,
        PrivateWorkerTrigger::Stopped | PrivateWorkerTrigger::OwnerStep
    ) && outcome.last == Some(PrivateWorkerAsk::Said(X11OrderedServeStep::Stopped))
}

/// Read one capsule out of the place a credit names, through the credit.
fn credit_receives(
    credit: &PrivateInternalCredit,
) -> PrivateCreditReach<Option<XAuthorityOrderedDelivery>> {
    credit.with_place(|continuation| continuation.queue().try_recv().ok())
}

/// Give this connection's place to a holder the store keeps, through the real
/// two-step conversion.
fn hand_place_to_store(
    durable: &PrivateSettlementOwner,
    registration: &XServerFrontendClientRouteRegistration,
) -> PrivateSettlementOwner {
    let lease = lease_of(registration);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("a declared bound leaves a holder place");
    let outer = durable.clone();
    assert!(matches!(
        lease.convert_to_internal(&outer, destination),
        PrivateInternalConversion::Held
    ));
    outer
}

#[test]
fn a_connections_output_lives_in_a_home_its_registration_does_not_own() {
    // THIS IS WHAT THE RELOCATION IS FOR. The payload used to live in the
    // registration, and the only thing that could reach it while the
    // connection ran was the registration itself; teardown then moved it into
    // the place. Anything meaning to borrow it later had to be handed the
    // payload rather than a way to reach it, and the hand-over invalidated
    // whatever it was holding.
    //
    // Here the home is made with the place, before the connection is exposed,
    // and the registration and the place hold the same one. So the exact
    // capsule is readable from the place WHILE the connection runs, and still
    // readable from the same home after the registration is destroyed --
    // without anything having been moved in between.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8381);
    let (private, registration, cell, frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83810);

    // THE SAME HOME, not a copy: the registration's handle and the place's are
    // one object, which is what makes a borrow from either a borrow of the
    // same work.
    let from_place = {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(home) = &held.continuations[0] else {
            panic!("its place holds its home")
        };
        Arc::clone(home)
    };
    assert!(Arc::ptr_eq(&from_place, &registration.ordered_home));
    assert!(from_place.occupied(), "bound, and in its home from binding");
    assert_eq!(from_place.standing(), PrivateHomeStanding::Live);
    assert_eq!(
        durable.continuations_retained(),
        Some(0),
        "a live connection's home is not retained work"
    );

    // AND THE CONNECTION ENDS. Nothing moves; what changes is its standing.
    drop(registration);
    assert_eq!(from_place.standing(), PrivateHomeStanding::Retained);
    assert_eq!(durable.continuations_retained(), Some(1));
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(durable.continuations_abandoned(), Some(0));

    // The exact capsule is in the same home it was accepted into, and the
    // binding is still there.
    let survived = from_place
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("the home its connection bound")
        .expect("the capsule accepted before it ended");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83810)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());
    assert!(wire_weak.upgrade().is_some());

    // Teardown's own evidence is in the home, written where the payload lives.
    assert!(
        from_place
            .borrow(|continuation| matches!(
                continuation,
                PrivateOrderedContinuation::Setup { evidence, .. }
                    if evidence.fence.is_some()
                        && evidence.worker == PrivateOrderedWorkerExit::NeverStarted
            ))
            .expect("the home its connection bound"),
        "the fence it closed and the worker it never started"
    );
    drop((private, survived, cell, from_place));
}

#[test]
fn a_live_connections_home_is_not_driven_by_the_retained_drive() {
    // A DRIVE THAT FINISHES WHAT CONNECTIONS LEFT BEHIND MUST NOT TOUCH ONE
    // THAT HAS NOT LEFT. Now that a connection's output is in its place from
    // binding rather than from teardown, the drive can see it -- and visiting
    // it would receive from a queue a producer may still be using, end a wire
    // the connection is still serving on, and hand the result to whoever is
    // borrowing it. Standing is what separates them.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8382);
    let (private, registration, cell, frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83820);
    assert_eq!(durable.continuations_reserved(), Some(1));

    for _ in 0..8 {
        assert_eq!(
            durable.drive_ordered_continuations(4),
            0,
            "there is nothing retained to drive"
        );
    }

    // UNTOUCHED, AND THE PAYLOAD SAYS SO, not only the flags: the exact
    // capsule is still on the queue with its frames and its unanswered
    // completion. Flags alone would hold equally over a queue the drive had
    // received from and thrown away.
    assert!(
        registration
            .ordered_home
            .borrow(|continuation| matches!(
                continuation,
                PrivateOrderedContinuation::Setup { ended, drained, .. }
                    if !*ended && !*drained
            ))
            .expect("its own home"),
        "the drive neither ended its wire nor drained its queue"
    );
    let survived = registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the capsule the drive did not take");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83820)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());
    assert!(wire_weak.upgrade().is_some());
    assert_eq!(durable.continuations_reserved(), Some(1));

    // AND ONCE IT HAS ENDED, the same drive does take it.
    drop(registration);
    let mut driven = 0;
    for _ in 0..8 {
        driven += durable.drive_ordered_continuations(4);
    }
    assert!(driven > 0, "a retained home is this drive's business");
    drop((private, survived, cell));
}

#[test]
fn the_drive_does_not_hold_the_store_while_it_waits_on_one_connections_home() {
    // TWO LOCKS, ONE ORDER. A home may reach the store while it is held -- a
    // close running under a home's lock can reserve a place, which the helper
    // controls here already do -- so home-then-store is a permitted edge.
    // Asking a home anything while holding the store is that edge reversed,
    // and a scan that did it put every other connection behind whichever home
    // happened to be contended.
    //
    // WHAT THIS ESTABLISHES: that with one connection's home held, the store
    // itself stays acquirable while the drive is waiting on it. It does NOT
    // establish where the driving thread has got to -- nothing here can say
    // that -- and it is not a deadlock observation: the drive waits on that
    // home either way, and what is asked is whether it waits holding the store.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8384);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83840);
    let home = Arc::clone(&registration.ordered_home);
    drop((registration, private));
    assert_eq!(durable.continuations_retained(), Some(1));

    let blocker = home.state.lock().expect("hold this connection's home");
    let driving = durable.clone();
    let (started, wait) = std::sync::mpsc::channel();
    let driver = std::thread::spawn(move || {
        started.send(()).expect("started");
        driving.drive_ordered_continuations(4)
    });
    wait.recv().expect("the driving thread started");
    std::thread::sleep(Duration::from_millis(50));

    // The store is taken and released here many times over while the drive is
    // waiting on a home it cannot have.
    let mut acquired = 0usize;
    for _ in 0..2_000 {
        if durable.inner.try_lock().is_ok() {
            acquired += 1;
            if acquired == 8 {
                break;
            }
        }
        std::thread::yield_now();
    }
    assert_eq!(
        acquired, 8,
        "a contended home must not hold the whole store behind it"
    );

    drop(blocker);
    assert!(
        driver.join().expect("the driving thread finished") > 0,
        "and the drive takes it once the home is free"
    );
}

#[test]
fn a_running_connection_is_not_reported_as_retained_work() {
    // A BINDING POPULATES A LIVE HOME NOW. Before the relocation, anything in
    // a place had been put there by a teardown, so occupancy alone meant
    // retention. A reader that still asked only whether something was there
    // would describe every running connection as work owed to whoever drives
    // retained records -- and a caller acting on that would be acting on a
    // connection that has not ended, through a record its own registration is
    // still using.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8385);
    let (private, registration, cell, frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83850);

    assert!(
        registration.ordered_home.occupied(),
        "bound, and in its home"
    );
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(durable.continuations_retained(), Some(0));
    assert!(
        durable
            .retained_dispositions()
            .expect("a readable store")
            .is_empty(),
        "a live connection is not a retained row"
    );

    // AND THE READING TOUCHED NOTHING. Asking a channel whether it is finished
    // means receiving from it, so a reader that reached into a live queue
    // would answer the question by emptying it.
    let survived = registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("its capsule is still there");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83850)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());

    // ONCE IT HAS ENDED, the same reader has a row for it.
    drop(registration);
    assert_eq!(durable.continuations_retained(), Some(1));
    let readings = durable.retained_dispositions().expect("a readable store");
    assert_eq!(readings.len(), 1);
    assert_eq!(readings[0].0, 0);
    assert!(
        readings[0].1.is_some(),
        "and it is a reading, not an unreadable row"
    );
    drop((private, survived, cell));
}

#[test]
fn a_retained_home_refuses_a_binding_that_arrives_after_its_connection_ended() {
    // NOTHING IS BOUND INTO A CONNECTION THAT HAS GONE. The home outlives the
    // registration now, so a binding arriving late has somewhere to land that
    // it did not have before -- and landing there would give a queue to a
    // connection nobody will serve, behind whoever is already responsible for
    // finishing what is in it. The offer comes back instead.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8383);
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    // A capsule is accepted into this connection's queue before it ends, so
    // what the refused binding carries is real work rather than an empty
    // shape.
    let sender = capture_gated_sender(&private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83830);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    gated_send(&sender, capsule).expect("an open endpoint");
    drop(sender);
    let home = Arc::clone(&registration.ordered_home);
    drop(registration);
    assert_eq!(home.standing(), PrivateHomeStanding::Retained);

    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let late = PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        evidence: PrivateOrderedEvidence::unstarted(),
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    };
    let PrivateHomeBinding::Ended(returned) = home.bind(late) else {
        panic!("a retained home takes no binding")
    };
    // AND IT COMES BACK WHOLE -- the exact capsule, its frames and its
    // unanswered completion, not merely something of the right shape.
    // Reporting a refusal by dropping the offer would answer a question about
    // a queue by destroying the queue.
    assert!(matches!(
        returned,
        PrivateOrderedContinuation::Setup {
            accepted: PrivateOrderedSetupCustody::Receiver(_),
            ..
        }
    ));
    let carried = returned
        .queue()
        .try_recv()
        .expect("the capsule accepted before it ended");
    assert_eq!(
        carried.delivery(),
        XAuthorityInputDeliveryId::from_raw(83830)
    );
    assert_eq!(order_pass_frames(&carried), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &carried.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());
    assert!(!home.occupied(), "and nothing was put in it");
    drop((private, output, wire, pending, returned, carried, cell));
}

#[test]
fn a_conversion_leaves_the_store_holding_the_place_its_connection_held() {
    // THE HOLDER IS THE STORE'S OWN. A place could only be named from outside,
    // by the connection that reserved it; after teardown nothing named it at
    // all. A store that is to finish its own retained work needs an entry of
    // its own for each place, and that entry cannot be an owner of the store
    // it is in.
    let durable = PrivateSettlementOwner::default();
    let capability = durable.settlement_ref();
    let client = XServerFrontendClientId(8351);
    let (private, registration, cell, frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83510);
    let place = registration
        .ordered_continuation
        .lock()
        .expect("a readable registration")
        .as_ref()
        .expect("its own reservation")
        .index;
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(durable.holders_taken(), Some(0));

    let outer = hand_place_to_store(&durable, &registration);
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the same place, neither recharged nor released"
    );
    // AND THE CONNECTION IS STILL RUNNING. Handing the place to the store says
    // who is responsible for it, not that the connection has ended: a
    // conversion that also retired it would give a live connection's home to a
    // drive that closes wires, with the registration still holding it.
    assert_eq!(
        registration.ordered_home.standing(),
        PrivateHomeStanding::Live
    );
    assert_eq!(durable.continuations_retained(), Some(0));
    assert_eq!(
        durable.continuations_abandoned(),
        Some(0),
        "a place that crossed was continuously somebody's"
    );

    // THE CONNECTION THEN ENDS, with its place already the store's. Teardown
    // has no lease left to account for and does not invent one; what it does
    // is say the connection has gone, in the home the holder names.
    drop(registration);
    assert_eq!(durable.continuations_retained(), Some(1));
    assert_eq!(durable.continuations_abandoned(), Some(0));

    let named = durable
        .take_internal_holder(0)
        .expect("the store keeps a holder");
    assert_eq!(named.credit.place(), place);
    assert_eq!(durable.holders_taken(), Some(0));

    // AND THE WORK IS READ THROUGH THE CREDIT, which is the only thing that
    // names the place now -- and which never owned the registration.
    let PrivateCreditReach::Reached(Some(survived)) = credit_receives(&named.credit) else {
        panic!("the capsule accepted before the connection ended")
    };
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83510)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    drop((private, survived, cell, durable, _private_keeper));

    // THE OUTER HOLDER IS THE CONVERSION'S CALLER, and nothing else: the
    // connection, its instance, the service owner and the caller's other
    // binding are gone.
    assert!(capability.owner().is_some());
    assert!(wire_weak.upgrade().is_some(), "with the work still in it");

    // AND WHEN THE LEGITIMATE HOLDERS GO, so does the graph.
    drop(outer);
    assert!(
        capability.owner().is_none(),
        "a store's own holder must not be the reason the store exists"
    );
    assert!(wire_weak.upgrade().is_none());
    drop(named);
}

#[test]
fn a_store_owned_holder_left_in_its_store_does_not_keep_it_alive() {
    // THE RING, BUILT AND LEFT STANDING. The holder above was taken out before
    // the last holder went. This one is not: the credit stays inside the store
    // it names a place in, which is the shape -- store, holder, credit, store
    // -- that an owner in the credit would close.
    let durable = PrivateSettlementOwner::default();
    let capability = durable.settlement_ref();
    let client = XServerFrontendClientId(8352);
    let (private, registration, cell, _frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83520);
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    assert_eq!(durable.holders_taken(), Some(1), "and it is still in there");
    drop((private, cell, durable, _private_keeper));

    assert!(
        capability.owner().is_some(),
        "held by the conversion's caller"
    );
    drop(outer);
    assert!(
        capability.owner().is_none(),
        "the store's own holder is on no ring"
    );
    assert!(
        wire_weak.upgrade().is_none(),
        "and the work it named went with the place"
    );
}

#[test]
fn a_refused_holder_preparation_leaves_the_lease_and_the_work_where_they_were() {
    // PREPARATION IS THE FALLIBLE HALF, so this is where a place that already
    // has a holder has to be felt. A conversion that prepared as it went would
    // have taken the place out of the connection's hands before finding out it
    // had nowhere to put it.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8353);
    let (private, registration, cell, frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83530);
    let lease = lease_of(&registration);
    let place = lease.index;

    let other = XServerFrontendClientId(8363);
    let (other_registration, _other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a place and a row");
    let other_lease = lease_of(&other_registration);
    let held_places = [
        durable
            .prepare_internal_holder(&lease)
            .expect("within the declared bound"),
        durable
            .prepare_internal_holder(&other_lease)
            .expect("within the declared bound"),
    ];
    assert_eq!(durable.holders_taken(), Some(2));
    assert!(
        matches!(
            durable.prepare_internal_holder(&lease),
            Err(PrivateHolderRefusal::AlreadyHeld)
        ),
        "one place, one holder"
    );

    // NOTHING MOVED. The lease is still armed and still names the same place,
    // the work is still in its home, and the counters are untouched.
    assert!(lease.armed);
    assert_eq!(lease.index, place);
    assert!(registration.ordered_home.occupied());
    assert_eq!(durable.continuations_reserved(), Some(2));
    assert_eq!(durable.continuations_abandoned(), Some(0));

    // AND A RELEASED PREPARATION GIVES ITS PLACE BACK.
    drop(held_places);
    assert_eq!(durable.holders_taken(), Some(0));
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("the released places are free again");
    let outer = durable.clone();
    assert!(matches!(
        lease.convert_to_internal(&outer, destination),
        PrivateInternalConversion::Held
    ));
    drop(registration);
    let named = durable.take_internal_holder(0).expect("a holder");
    assert_eq!(named.credit.place(), place, "the same place, after a refusal");
    let PrivateCreditReach::Reached(Some(survived)) = credit_receives(&named.credit) else {
        panic!("the same capsule")
    };
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    drop((other_registration, private, outer, named));
}

#[test]
fn a_conversion_with_a_foreign_destination_is_refused_without_touching_anything() {
    // NOT A DEBUG ASSERTION. A destination prepared against another store
    // names an index in THAT store's holders. Committing it here writes into
    // whatever this store has at that index -- taking over another
    // connection's promise -- and leaves the other store's promise held for
    // ever. A check that only exists in builds with debug assertions makes the
    // provenance of a place a testing-only property.
    let one = PrivateSettlementOwner::default();
    let two = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8360);
    let (private_one, registration_one, cell, frames, _wire, _private_one_keeper) =
        converted_fixture(&one, client, 83600);
    let other = XServerFrontendClientId(8361);
    let (private_two, registration_two, _cell_two, _frames_two, _wire_two, _private_two_keeper) =
        converted_fixture(&two, other, 83610);
    let lease = lease_of(&registration_one);
    let foreign_lease = lease_of(&registration_two);

    // Both are ordinary results of the real API, from their own stores.
    let foreign = two
        .prepare_internal_holder(&foreign_lease)
        .expect("the other store has a holder place");
    let outer = one.clone();
    let PrivateInternalConversion::Foreign(lease) = lease.convert_to_internal(&outer, foreign)
    else {
        panic!("a destination from another store is not this store's to commit")
    };

    // NOTHING TOUCHED, on either side.
    assert!(lease.armed);
    assert!(registration_one.ordered_home.occupied());
    assert_eq!(one.holders_taken(), Some(0));
    assert_eq!(
        two.holders_taken(),
        Some(0),
        "the destination was consumed by the refusal and gave its place back, \
         rather than being left held for ever"
    );
    assert_eq!(one.continuations_abandoned(), Some(0));
    assert_eq!(two.continuations_abandoned(), Some(0));

    // AND A PROMISE MADE FOR ANOTHER PLACE IN THIS STORE IS REFUSED TOO.
    let neighbour = XServerFrontendClientId(8368);
    let (neighbour_registration, _neighbour_channels) = private_one
        .broker
        .registry
        .register_client_with_admission(neighbour, Some(admitted(neighbour)))
        .expect("a place and a row");
    let neighbour_lease = lease_of(&neighbour_registration);
    let neighbours = one
        .prepare_internal_holder(&neighbour_lease)
        .expect("its own place");
    assert_ne!(neighbours.for_place, lease.index);
    let PrivateInternalConversion::Foreign(lease) = lease.convert_to_internal(&outer, neighbours)
    else {
        panic!("a promise made for another place is not this lease's to commit")
    };
    assert!(lease.armed);
    assert_eq!(one.holders_taken(), Some(0));

    // And the lease that came back still converts, over its own store.
    let destination = one
        .prepare_internal_holder(&lease)
        .expect("its own store has a place");
    assert!(matches!(
        lease.convert_to_internal(&outer, destination),
        PrivateInternalConversion::Held
    ));
    drop(registration_one);
    let named = one.take_internal_holder(0).expect("a holder");
    let PrivateCreditReach::Reached(Some(survived)) = credit_receives(&named.credit) else {
        panic!("the work it was refused over")
    };
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    drop((
        registration_two,
        neighbour_registration,
        private_one,
        private_two,
        outer,
        named,
        foreign_lease,
        neighbour_lease,
    ));
}

#[test]
fn a_promise_made_for_one_reservation_is_not_committed_against_its_successor() {
    // THE PROMISE NEEDS AN IDENTITY FOR THE SAME REASON THE CREDIT DOES. A
    // place goes back when its reservation is given up, and the next
    // connection takes the same number. A destination that named only the
    // number would then be committed against that connection's lease -- a
    // holder over a connection nobody prepared one for, made from a promise
    // that was for somebody else.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    // RESERVED WITHOUT BEING PUBLISHED, which is what relinquish_unexposed is
    // for: registering a client publishes its row, and a place given back
    // after that is not an unexposed one.
    let lease = durable
        .reserve_ordered_continuation()
        .expect("a declared bound leaves a place");
    let index = lease.index;
    let stale = durable
        .prepare_internal_holder(&lease)
        .expect("a holder place for this reservation");
    lease.relinquish_unexposed();
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "a reservation that published nothing gives its place back"
    );

    // THE SAME NUMBER, A DIFFERENT CONNECTION.
    let successor_id = XServerFrontendClientId(8372);
    let (successor, successor_registration, cell, frames, wire_weak, _successor_keeper) =
        converted_fixture(&durable, successor_id, 83720);
    let successor_lease = lease_of(&successor_registration);
    assert_eq!(successor_lease.index, index, "the place was handed on");

    let PrivateInternalConversion::Foreign(successor_lease) =
        successor_lease.convert_to_internal(&durable.clone(), stale)
    else {
        panic!("a promise made for another reservation is not this one's to commit")
    };

    // NOTHING TOUCHED: the successor still holds its place and its work.
    assert!(successor_lease.armed);
    assert!(successor_registration.ordered_home.occupied());
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(durable.continuations_abandoned(), Some(0));
    assert_eq!(durable.holders_taken(), Some(0));
    assert!(wire_weak.upgrade().is_some());

    // And its own promise commits, over its own record.
    let destination = durable
        .prepare_internal_holder(&successor_lease)
        .expect("its own reservation");
    let outer = durable.clone();
    assert!(matches!(
        successor_lease.convert_to_internal(&outer, destination),
        PrivateInternalConversion::Held
    ));
    drop(successor_registration);
    let named = durable.take_internal_holder(0).expect("a holder");
    let PrivateCreditReach::Reached(Some(landed)) = credit_receives(&named.credit) else {
        panic!("the successor's own work, in the successor's own record")
    };
    assert_eq!(
        landed.delivery(),
        XAuthorityInputDeliveryId::from_raw(83720)
    );
    assert_eq!(order_pass_frames(&landed), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &landed.finalizer().expect("carried").completion
    ));
    drop((private, successor, named, outer));
}

#[test]
fn a_credit_over_a_place_whose_connection_never_bound_will_not_free_it() {
    // AN EMPTY HOME IS NOT A FINISHED ONE. A place whose home holds nothing is
    // a connection that has not bound -- and one of the moments it has not
    // bound yet is while it is still running. Reading that as "nothing owed"
    // frees the place out from under a binding that is still coming, and the
    // next connection takes it.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8369);
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    assert!(
        !registration.ordered_home.occupied(),
        "exposed, and not bound yet"
    );
    let outer = hand_place_to_store(&durable, &registration);
    let mut named = durable.take_internal_holder(0).expect("a holder");

    assert!(matches!(
        named.credit.with_place(|_| ()),
        PrivateCreditReach::Empty
    ));
    assert!(matches!(
        named.credit.release(),
        PrivateCreditRelease::NotHandedOver
    ));
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the place is kept, so a binding still coming keeps its home"
    );
    assert_eq!(durable.continuations_abandoned(), Some(0));
    drop((registration, private, named, outer));
}

#[test]
fn a_credit_accounts_for_its_place_exactly_once() {
    // ONE PLACE, ONE DISPOSAL. A conversion disarms the lease rather than
    // disposing of it, so the place is not counted abandoned on the way
    // through; the credit takes that duty on, and must not discharge it twice
    // or discharge a duty the lease already discharged.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8354);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83540);
    let outer = hand_place_to_store(&durable, &registration);
    let named = durable.take_internal_holder(0).expect("a holder");

    // THE CONNECTION ENDS WITH ITS PLACE ALREADY THE STORE'S. Teardown has no
    // lease to account for and must not act as though it had one.
    drop(registration);
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(durable.continuations_abandoned(), Some(0));

    // A holder that goes without disposing of its place leaves work nobody
    // accounted for. It is marked once, and the capacity is not handed out
    // again.
    drop(named);
    assert_eq!(durable.continuations_abandoned(), Some(1));
    assert_eq!(durable.continuations_reserved(), Some(1));
    drop((private, outer));
}

#[test]
fn a_credit_refuses_to_free_a_place_that_still_owes_work() {
    // THE PRECONDITION IS CHECKED, NOT ASSUMED. Freeing a place over a queue
    // that still holds capsules destroys them unanswered, which is the loss
    // the precondition existed to prevent.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8355);
    let (private, registration, cell, frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83550);
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    let mut named = durable.take_internal_holder(0).expect("a holder");

    // THE NEGATIVE: a capsule is on that queue and nothing established an
    // ending, so this record is not settled and the release is refused.
    assert!(
        named
            .credit
            .with_place(|continuation| continuation.settled())
            .reached()
            .is_some_and(|settled| !settled),
        "a bound connection with a queued capsule owes work"
    );
    assert!(matches!(
        named.credit.release(),
        PrivateCreditRelease::StillOwed
    ));
    assert_eq!(durable.continuations_reserved(), Some(1), "the place is kept");
    assert_eq!(durable.continuations_abandoned(), Some(0));

    // AND THE PAYLOAD IS STILL THERE.
    let PrivateCreditReach::Reached(Some(survived)) = credit_receives(&named.credit) else {
        panic!("a refused release destroys nothing")
    };
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83550)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());
    assert!(wire_weak.upgrade().is_some());
    drop((private, survived, cell, named, outer));
}

#[test]
fn a_credit_frees_a_place_whose_record_finished_owing_nothing() {
    // THE POSITIVE, over a record that is genuinely settled: its producers are
    // gone, its queue reported Disconnected as it was drained, its wire was
    // ended and its closure established.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8356);
    let (private, registration, _cell, _frames, wire_weak, _private_keeper) =
        converted_fixture(&durable, client, 83560);
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    let mut named = durable.take_internal_holder(0).expect("a holder");

    // DRIVEN THROUGH THE CREDIT, which is what a holder taken out of the store
    // is for. The store's own drive is deliberately not used: it returns the
    // places it settles itself, so a control that let it run would be watching
    // that return rather than this release.
    assert!(matches!(
        credit_receives(&named.credit),
        PrivateCreditReach::Reached(Some(_))
    ));
    drop(private);
    let mut settled = false;
    for _ in 0..8 {
        let Some(finished) = named
            .credit
            .with_place(|continuation| {
                continuation.visit();
                continuation.settled()
            })
            .reached()
        else {
            panic!("the place is this credit's until it releases it")
        };
        settled = finished;
        if settled {
            break;
        }
    }
    assert!(settled, "the real visit finished this record");

    assert!(matches!(
        named.credit.release(),
        PrivateCreditRelease::Released
    ));
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "and the place is free again"
    );
    assert_eq!(durable.continuations_abandoned(), Some(0));
    drop(named);
    assert_eq!(
        durable.continuations_abandoned(),
        Some(0),
        "a released credit is not also an abandoned one"
    );
    // AND THE SERVICE OWNER, which keeps this connection's teardown record and
    // so keeps what that record owns. Its going is a separate event from the
    // registration's, and this control makes it happen before asking.
    drop(_private_keeper);
    assert!(wire_weak.upgrade().is_none());
    drop(outer);
}

#[test]
fn an_old_credit_cannot_reach_or_free_the_place_its_successor_took() {
    // A NUMBER IS NOT AN IDENTITY. A place is returned when the work in it is
    // settled, and the next connection to reserve one takes that same index.
    let durable = PrivateSettlementOwner::default();
    let first = XServerFrontendClientId(8364);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, first, 83640);
    let index = registration
        .ordered_continuation
        .lock()
        .expect("a readable registration")
        .as_ref()
        .expect("its own reservation")
        .index;
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    let mut stale = durable.take_internal_holder(0).expect("a holder");

    // THE REAL DRIVE SETTLES IT AND RETURNS THE PLACE.
    assert!(matches!(
        credit_receives(&stale.credit),
        PrivateCreditReach::Reached(Some(_))
    ));
    drop(private);
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "the drive returned the place it settled"
    );

    // A SUCCESSOR TAKES THE SAME INDEX, through ordinary registration.
    let second = XServerFrontendClientId(8365);
    let (successor, successor_registration, successor_cell, successor_frames, successor_wire, _successor_keeper) =
        converted_fixture(&durable, second, 83650);
    let successor_place = successor_registration
        .ordered_continuation
        .lock()
        .expect("a readable registration")
        .as_ref()
        .expect("its own reservation")
        .index;
    assert_eq!(
        successor_place, index,
        "the same place, a different connection"
    );

    // THE OLD CREDIT REACHES NOTHING.
    assert!(matches!(
        credit_receives(&stale.credit),
        PrivateCreditReach::Moved
    ));
    assert!(matches!(
        stale.credit.release(),
        PrivateCreditRelease::NotOurs
    ));
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the successor still has its place"
    );

    // AND ITS CAPSULE AND BINDING ARE UNTOUCHED.
    let capsule = successor_registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the successor's own capsule");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(83650)
    );
    assert_eq!(order_pass_frames(&capsule), successor_frames);
    assert!(Arc::ptr_eq(
        &successor_cell,
        &capsule.finalizer().expect("carried").completion
    ));
    assert!(successor_cell.answer().is_none());
    assert!(successor_wire.upgrade().is_some());

    // AND DROPPING IT ACCOUNTS FOR NOTHING.
    let before = durable.continuations_abandoned();
    drop(stale);
    assert_eq!(durable.continuations_abandoned(), before);
    drop((successor_registration, successor, capsule, outer));
}

#[test]
fn a_returned_place_leaves_no_holder_behind_naming_it() {
    // THE OTHER HALF OF THE SAME PROBLEM. The credit checking its place keeps
    // a stale holder harmless; this keeps one from being left there at all.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8366);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83660);
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    assert_eq!(durable.holders_taken(), Some(1));

    {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(home) = &held.continuations[0] else {
            panic!("its place holds its home")
        };
        let home = Arc::clone(home);
        drop(held);
        assert!(home
            .borrow(|continuation| continuation.queue().try_recv().is_ok())
            .expect("its own home"));
    }
    drop(private);
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(durable.continuations_reserved(), Some(0));
    assert_eq!(
        durable.holders_taken(),
        Some(0),
        "the holder went with the place it named"
    );
    assert_eq!(
        durable.continuations_abandoned(),
        Some(0),
        "and a holder retired over a settled place accounts for nothing"
    );
    drop(outer);
}

#[test]
fn a_credits_operation_keeps_the_store_it_found_until_the_operation_ends() {
    // THE INTERVAL, DRIVEN RATHER THAN DESCRIBED. A credit holds no owner, so
    // every operation begins by upgrading. A lookup that clones the home
    // handle and lets that upgrade go before acting leaves a window where the
    // last outside holder can drop: the home survives in the clone, so the
    // operation finishes and reports success into storage nobody can reach.
    let durable = PrivateSettlementOwner::default();
    let capability = durable.settlement_ref();
    let client = XServerFrontendClientId(8367);
    let (private, registration, cell, frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 83670);
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    let named = durable.take_internal_holder(0).expect("a holder");
    drop((private, durable, _private_keeper));

    let last = std::cell::Cell::new(Some(outer));
    let watch = capability.clone();
    let PrivateCreditReach::Reached(Some(survived)) = named.credit.with_place(|continuation| {
        drop(last.take());
        // THE ASSERTION THAT SEPARATES THEM. A lookup that let its upgrade go
        // would leave the store gone from here on, and the rest of this
        // callback would run against a home nobody could reach -- which reads
        // exactly like success, because the home itself survives in the handle
        // the lookup cloned. The store is what is asked about, not the home.
        assert!(
            watch.owner().is_some(),
            "the operation holds the store it found for as long as it runs"
        );
        continuation.queue().try_recv().ok()
    }) else {
        panic!("and the work was still readable in it")
    };
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83670)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));

    // AND ONLY UNTIL IT ENDS.
    assert!(capability.owner().is_none());
    assert!(matches!(
        named.credit.with_place(|_| ()),
        PrivateCreditReach::StoreGone
    ));
    drop((survived, cell, named));
}

#[test]
fn a_retained_continuation_outlives_its_instance_and_goes_with_its_store() {
    // AN INSTANCE THAT ENDS DOES NOT TAKE THE STORE WITH IT. The constructor
    // takes it by reference and clones a holder, so a caller that keeps its
    // own holder still has the store -- and the work retained into it -- after
    // the instance is gone. That is what durable means.
    //
    // WHAT THIS DOES NOT ESTABLISH: anything about a ring. The connection here
    // disposes of its place at teardown, so no reservation is live when the
    // last holder goes, and a store that held a place-reference of its own
    // would not be caught by this. That is a separate audit, for a holder that
    // does not exist yet.
    let durable = PrivateSettlementOwner::default();
    let capability = durable.settlement_ref();
    let client = XServerFrontendClientId(8321);
    let (cell, survived, wire_weak, output_weak, pending_weak) = {
        let service_keeper = service_owner(&durable, 2);
        let private = private_over(&service_keeper, 2);
        let (registration, channels) = private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client)))
            .expect("a place and a row");
        let (stream, _peer) = UnixStream::pair().expect("a socket pair");
        let output = Arc::new(Mutex::new(stream));
        let wire = Arc::new(X11WirePermission::open());
        let pending = Arc::new(AtomicUsize::new(0));
        assert_eq!(
            registration
                .bind_ordered_output(channels.ordered, &output, &wire, &pending)
                .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
            None
        );
        let sender = capture_gated_sender(&private, client);
        let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83210);
        let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
        gated_send(&sender, capsule).expect("an open endpoint");
        drop(sender);
        // The binding's own halves are weakly observed from here on, so what
        // the retained record holds can be asked about without holding it.
        let weaks = (
            Arc::downgrade(&wire),
            Arc::downgrade(&output),
            Arc::downgrade(&pending),
        );
        drop((wire, output, pending));

        // Teardown hands the queue into the place reserved for it.
        drop(registration);
        assert_eq!(durable.continuations_retained(), Some(1));

        // AND THEN THE INSTANCE ENDS, with the retained work still owed.
        drop(private);
        (cell, weaks.0.upgrade().is_some(), weaks.0, weaks.1, weaks.2)
    };
    assert!(
        survived,
        "an instance that ends does not take the retained binding with it"
    );
    assert_eq!(
        durable.continuations_retained(),
        Some(1),
        "the place is still this connection's after its instance has gone"
    );
    // THE PAYLOAD, not the counters: the exact capsule accepted before the
    // connection ended is still in the retained queue.
    let capsule = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup { accepted, .. } = continuation else {
                panic!("no owner is built yet")
            };
            let PrivateOrderedSetupCustody::Transport(transport) = accepted else {
                panic!("this connection bound")
            };
            transport.ordered.receiver.try_recv().ok()
        })
        .expect("the place this connection held")
        .expect("the capsule accepted before the connection ended");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(83210)
    );
    assert!(Arc::ptr_eq(
        &cell,
        &capsule.finalizer().expect("carried").completion
    ));
    drop((capsule, cell));

    // AND WHEN THE LAST HOLDER GOES, so does what it was holding. The place
    // was disposed of at teardown, so this is the store's own lifetime ending
    // and the binding being released with it -- not evidence about rings.
    assert!(capability.owner().is_some());
    drop(durable);
    assert!(capability.owner().is_none(), "no holder remains");
    assert!(
        wire_weak.upgrade().is_none()
            && output_weak.upgrade().is_none()
            && pending_weak.upgrade().is_none(),
        "a store that drops releases the binding it retained"
    );
}

#[test]
fn a_registration_that_ends_refuses_handovers_before_it_takes_its_queue_away() {
    // A CONNECTION THAT ENDS IS CLOSED TO HANDOVERS. Removing the row is not
    // what does it: the capture happens under the client table and the send
    // after it is released, so a sender already in a producer's hand outlives
    // the row.
    //
    // WHAT THIS ESTABLISHES is that teardown fences at all, and that what the
    // connection owed is in its place afterwards. It does NOT establish the
    // order of those two inside teardown: nothing is received during teardown,
    // so a capsule accepted between the take and the fence would land on the
    // same retained queue either way, and no outcome here separates them. The
    // order will become observable when a driver receives from that queue, and
    // it is written fence-first for that reason rather than for this one.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8311);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let sender = capture_gated_sender(&private, client);
    assert!(
        sender.admit().is_ok(),
        "before the registration ends, this captured sender admits"
    );
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        None
    );

    drop(registration);
    assert_eq!(
        sender.admit().err(),
        Some(PrivateHandoverRefusal::Fenced),
        "a sender captured before the connection ended is refused after it"
    );
    assert!(
        retained_setup_kind(&durable, 0).is_some(),
        "and what it would have gone to is retained"
    );
}

#[test]
fn a_connection_whose_binding_refused_retains_its_queue_without_a_socket() {
    // RECEIVER ONLY. A transport carries an independent handle on the
    // connection, so retaining one keeps the wire open for whoever drives it.
    // A receiver alone carries no such handle: the accepted socket goes with
    // the connection that owned it, and the queue is retained with no way to
    // deliver what is in it. That is the worse outcome, and it is recorded as
    // what it is.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8321);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");

    // A receiver this registration did not mint: the binding refuses, and
    // refusing hands the receiver back rather than destroying it.
    let other = XServerFrontendClientId(8322);
    let (other_registration, other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a second place and row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(other_channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        Some(X11OrderedServingRefusal::ForeignReceiver),
        "a receiver another registration minted is not this one's, and the \
         refusal does not destroy it"
    );
    drop(channels);

    drop(registration);
    let (kind, refusal, retained, drained, ended) =
        retained_setup_kind(&durable, 0).expect("the place this connection held");
    assert_eq!(kind, "receiver", "there is no transport to retain");
    assert_eq!(
        refusal,
        X11OrderedServingRefusal::ForeignReceiver,
        "THE CAUSE IS THE ONE THAT HAPPENED. Writing 'never served' over a \
         binding that actually refused would send whoever inherits this queue \
         looking for a worker that was never the problem"
    );
    assert_eq!((retained, drained, ended), (0, false, false));
    assert_eq!(
        durable.continuations_reserved(),
        Some(2),
        "both connections still hold their places"
    );
    drop(other_registration);
}

#[test]
fn a_second_binding_is_refused_rather_than_replacing_the_first() {
    // The first custody may already hold accepted capsules. Replacing it would
    // discard them with nothing recording that they existed, so the second is
    // handed back to whoever offered it.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8331);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("the first custody"));

    let second = XServerFrontendClientId(8332);
    let (second_registration, second_channels) = private
        .broker
        .registry
        .register_client_with_admission(second, Some(admitted(second)))
        .expect("a second place and row");
    let Err(returned) = registration.bind_ordered_output(
        second_channels.ordered,
        &output,
        &wire,
        &pending,
    ) else {
        panic!("a second binding is refused")
    };
    assert!(
        returned.minted_by(&second_registration),
        "and the receiver comes back whole, still the one its own \
         registration minted, rather than being dropped"
    );
    drop(returned);
    drop(registration);
    assert_eq!(
        retained_setup_kind(&durable, 0).map(|kind| kind.0),
        Some("transport"),
        "the first custody is what was retained"
    );
    drop(second_registration);
}


#[test]
fn a_receiver_only_connection_never_reports_an_ended_wire() {
    // HAVING NO HANDLE IS NOT HAVING ENDED SOMETHING. A binding that refused
    // leaves a queue and no way to reach the connection: the accepted socket
    // is still open and its peer still waiting. A visit that recorded `ended`
    // because there was nothing to end with let the record read as settled and
    // handed the place back over a live wire with accepted work still on it.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8341);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let other = XServerFrontendClientId(8342);
    let (other_registration, other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a second place and row");

    // A real refusal: a receiver another registration minted.
    let (stream, peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(other_channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        Some(X11OrderedServingRefusal::ForeignReceiver)
    );
    drop(channels);
    drop(registration);

    // Driven as hard as anything drives it. The record can never report an
    // ending, so it never settles and its place never comes back.
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    let (kind, _refusal, _retained, _drained, ended) =
        retained_setup_kind(&durable, 0).expect("the place this connection held");
    assert_eq!(kind, "receiver");
    assert!(
        !ended,
        "nothing here has touched that socket, so nothing may say it was ended"
    );
    assert!(
        !durable
            .with_ordered_continuation(0, |continuation| continuation.settled())
            .expect("the place holds it"),
        "a record that cannot establish an ending is not a settled connection"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(2),
        "and its place is not handed back"
    );

    // The accepted socket is still open, which is the fact the record is
    // refusing to misreport.
    peer.set_nonblocking(true).expect("a readable peer");
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).map_err(|error| error.kind()),
        Err(std::io::ErrorKind::WouldBlock),
        "the peer is still connected and still waiting"
    );
    drop(other_registration);
}

#[test]
fn a_second_binding_hands_back_the_receiver_it_was_offered() {
    // REACHABLE, and it took two steps to reach: offer this registration a
    // receiver it did not mint -- refused, and retained as custody -- then
    // offer it its own. The second binding SUCCEEDS and retention refuses it,
    // which is the arm that hands a bound transport's receiver back out.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let holder = XServerFrontendClientId(8351);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(holder, Some(admitted(holder)))
        .expect("a place and a row");
    let other = XServerFrontendClientId(8352);
    let (other_registration, other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a second place and row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));

    // First: a foreign receiver. Refused, and retained with that cause.
    assert_eq!(
        registration
            .bind_ordered_output(other_channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        Some(X11OrderedServingRefusal::ForeignReceiver)
    );

    // Second: its own receiver. The binding is fine; the custody is not free.
    let Err(returned) =
        registration.bind_ordered_output(channels.ordered, &output, &wire, &pending)
    else {
        panic!("this registration already holds custody")
    };
    assert!(
        returned.minted_by(&registration),
        "the receiver handed back is the one that was offered, whole"
    );

    // The first custody is untouched: it is the foreign receiver, with the
    // cause that stopped it.
    drop(returned);
    drop(registration);
    let (kind, refusal, ..) = retained_setup_kind(&durable, 0).expect("the retained place");
    assert_eq!(kind, "receiver");
    assert_eq!(
        refusal,
        X11OrderedServingRefusal::ForeignReceiver,
        "the first custody stayed, with the reason it was first refused"
    );
    drop(other_registration);
}

#[test]
fn a_bound_connection_keeps_its_queue_through_a_later_setup_refusal() {
    // THE BINDING COMES BEFORE THE FIRST THING THAT CAN REFUSE. Connection
    // setup publishes the row, then attaches lifecycle, connection state and
    // recovery -- each of which can fail. A binding placed after them left
    // every one of those refusals dropping the receiver, and the reserved
    // place survived holding nothing. Here the binding has happened, and the
    // connection then ends the way a refusal ends it.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8361);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));

    // Accepted after the row was published, which is the window that matters.
    let sender = capture_gated_sender(&private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83610);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    gated_send(&sender, capsule).expect("an open endpoint");

    // A refusal after this point unwinds the connection: the registration
    // drops, and so does everything the caller still held.
    drop(registration);
    drop(private);

    let survived = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup { accepted, .. } = continuation else {
                panic!("no owner is built yet")
            };
            let PrivateOrderedSetupCustody::Transport(transport) = accepted else {
                panic!("this connection bound")
            };
            transport.ordered.receiver.try_recv().ok()
        })
        .expect("the place this connection held")
        .expect("the capsule accepted before the refusal");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(83610)
    );
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert!(
        cell.answer().is_none(),
        "nobody answered for it, which is why losing it was losing something"
    );
}


/// The fence a retained record carries, read from the place it went into.
fn retained_fence(
    durable: &PrivateSettlementOwner,
    index: usize,
) -> Option<Option<PrivateHandoverFence>> {
    durable.with_ordered_continuation(index, |continuation| match continuation {
        PrivateOrderedContinuation::Setup { evidence, .. }
        | PrivateOrderedContinuation::Serving { evidence, .. } => evidence.fence,
    })
}

#[test]
fn a_retained_connection_carries_what_closing_it_established() {
    // THE OUTCOME TRAVELS WITH THE WORK. The gate belongs to the registration
    // that minted it and the registration is gone by the time anything drives
    // this record, so the one moment the closure could be established is the
    // moment it was. Asking later is not available; carrying it is.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8391);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));

    drop(registration);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Established)),
        "teardown closed this endpoint, and the record says so"
    );
}

#[test]
fn a_connection_closed_over_a_panicking_handover_never_reads_as_settled() {
    // A FINISHED CHANNEL IS NOT A RESOLVED HANDOVER. Drained is set from
    // Disconnected, so it already establishes that no later send is possible;
    // that is not what the fence is for. The fence carries evidence about the
    // other side: someone panicked inside the gate, so the closure could not
    // be established over resolved custody, and a record carrying that must
    // not read as finished however quiet its queue goes.
    //
    // Exclusion is not what failed. A poisoned lock is acquired and handed
    // back inside the error, so nothing was running beside the close.
    //
    // WHAT THIS CONTROL ESTABLISHES: that such a close is classified as
    // unreadable, carried onto the record, and keeps the place. It does NOT
    // exercise an interrupted capsule transfer -- it holds the gate's own lock
    // and sends nothing -- so it says nothing about recovering a half-made
    // handover, which is open work.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8401);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));

    // A producer panics inside the gate, the way one would if a handover
    // failed mid-flight.
    let gate = registration.ordered_gate.clone();
    let holder = std::thread::spawn(move || {
        let _inside = gate.fenced.lock().expect("an open gate");
        panic!("a handover panicked inside this gate");
    });
    assert!(holder.join().is_err(), "the holder panicked");

    drop(registration);
    drop(private);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Unreadable)),
        "the close could not be established, and the record carries that"
    );

    // Everything else about this record says finished: the producers are gone
    // with the registry, the wire ends on the first visit, and nothing was
    // kept back.
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    let (_kind, _refusal, retained, drained, ended) =
        retained_setup_kind(&durable, 0).expect("the place this connection held");
    assert_eq!(
        (retained, drained, ended),
        (0, true, true),
        "drained, ended, and nothing retained"
    );
    assert!(
        !durable
            .with_ordered_continuation(0, |continuation| continuation.settled())
            .expect("the place holds it"),
        "and still not settled, because the closure was never established"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "so the place stays held"
    );
}

