#[test]
fn a_serving_record_without_an_established_closure_never_settles_either() {
    // THE EVIDENCE MUST SURVIVE THE CONVERSION. A serving owner answers for
    // what it is holding, and its own termination is a different fact from the
    // endpoint's closure: one says this writer finished, the other says
    // nothing was left half-handed-over on the way to it. A conversion that
    // dropped the closure would let the owner's termination speak for both.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8421));
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    // Its producers go, and then it closes: finished by its own account --
    // nothing held, nothing in flight, an established termination over a
    // drained queue.
    drop(f);
    close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert!(
        owner.closing().is_some_and(|closing| {
            closing.termination == X11OrderedTermination::Established && closing.drained
        }),
        "this owner terminated and its queue finished"
    );
    assert!(owner.retained_unanswered().is_empty() && owner.in_flight().is_none());

    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut source = Some(PrivateOrderedContinuation::Serving {
        owner: home_holding(owner),
        // STAGED, NOT OBSERVED. No holder panicked here and no teardown ran:
        // this is the value such a record would arrive carrying, set directly
        // so the guard below is about what a record with it does. What writes
        // this value for real is teardown, and the controls named
        // teardown_records_* are where that is established.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Unreadable),
            ..PrivateOrderedEvidence::unstarted()
        },
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    assert!(
        !durable
            .with_ordered_continuation(0, |continuation| continuation.settled())
            .expect("the place holds it"),
        "an owner that finished is not a connection whose handovers resolved"
    );
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "so the place stays held"
    );
}

#[test]
fn a_closure_someone_else_made_is_carried_as_already_established() {
    // None IS NOT "THE ENDPOINT IS OPEN". Closing is a public act: a caller
    // that closed this endpoint directly leaves the record saying None until
    // teardown writes what ITS close established -- which is then
    // AlreadyEstablished, because the closure was already made.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8431);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));

    // Closed by a caller, through the real API, while the registration lives.
    assert_eq!(
        registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    assert_eq!(
        registration
            .ordered_home
            .borrow(|continuation| match continuation {
                PrivateOrderedContinuation::Setup { evidence, .. } => evidence.fence,
                PrivateOrderedContinuation::Serving { evidence, .. } => evidence.fence,
            }),
        Some(None),
        "the record still says None: no teardown outcome has been recorded here"
    );

    drop(registration);
    drop(private);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::AlreadyEstablished)),
        "teardown's own close found the closure already made, and says so"
    );
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "an already-established closure is a closure, so this place returns"
    );
}


/// A serving owner over this connection's OWN receiver and socket.
///
/// No spare registration is borrowed for a receiver, so the places in the
/// store belong to this connection alone and what a teardown does to them is
/// readable. The conversion that would build one of these in production is not
/// wired; this stands in for its hand-in, and for nothing after it -- the
/// teardown that follows is the real one, and is the subject.
fn serving_custody_for(
    f: PreparedOrderedFixture,
) -> (
    X11OrderedServingOwner,
    XServerFrontendClientRouteRegistration,
    PrivatePreparedRunner,
    PrivateSettlementOwner,
    Arc<Mutex<UnixStream>>,
) {
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let PreparedOrderedFixture {
        registration,
        runner,
        channels,
        durable,
        ..
    } = f;
    let transport = XAuthorityOrderedTransport::bind(
        &registration,
        channels.ordered,
        &output,
        &wire,
        &pending,
        None,
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let owner = X11OrderedServingOwner::for_registration(
        runner.frontend.as_ref().expect("a live runner"),
        &registration,
        transport,
    )
    .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));
    (owner, registration, runner, durable, output)
}

#[test]
fn teardown_records_its_actual_close_on_a_serving_record_too() {
    // A RECORD THAT REACHES A PLACE WITHOUT THIS CARRIES None FOR EVER.
    // Nothing after installation can establish a closure -- the gate goes with
    // the registration -- so a serving record left unwritten could never
    // settle however finished it was, and its place would never come back.
    let f = prepared_ordered_fixture(XServerFrontendClientId(8441));
    let (owner, registration, runner, durable, _output) = serving_custody_for(f);
    registration
        .retain_ordered_setup(PrivateOrderedContinuation::Serving {
            owner: home_holding(owner),
            // A STAGED PRECONDITION, not an observation: no close has happened
            // yet. What this control is about is what teardown writes over it.
            evidence: PrivateOrderedEvidence::unstarted(),
        })
        .unwrap_or_else(|_| panic!("this registration holds no custody yet"));

    // Its producers go, and then the real teardown runs.
    drop(runner);
    drop(registration);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Established)),
        "the actual teardown wrote what its own close established"
    );

    // And because it did, a record with nothing left can finish.
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "a finished serving record with an established closure returns its place"
    );
}

#[test]
fn teardown_records_an_unreadable_close_on_a_serving_record() {
    // The other outcome through the same seam. A holder panicked inside the
    // gate, so teardown's close establishes nothing, and the record says so
    // rather than defaulting to success.
    let f = prepared_ordered_fixture(XServerFrontendClientId(8451));
    let (owner, registration, runner, durable, _output) = serving_custody_for(f);
    registration
        .retain_ordered_setup(PrivateOrderedContinuation::Serving {
            owner: home_holding(owner),
            evidence: PrivateOrderedEvidence::unstarted(),
        })
        .unwrap_or_else(|_| panic!("this registration holds no custody yet"));

    let gate = registration.ordered_gate.clone();
    let holder = std::thread::spawn(move || {
        let _inside = gate.fenced.lock().expect("an open gate");
        panic!("a handover panicked inside this gate");
    });
    assert!(holder.join().is_err(), "the holder panicked");

    drop(runner);
    drop(registration);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Unreadable)),
        "teardown established nothing, and wrote that rather than a success"
    );
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "so this record keeps its place"
    );
}

#[test]
fn teardown_records_an_already_established_close_on_a_serving_record() {
    // The third outcome through the same seam: the endpoint was closed by a
    // caller before teardown reached it, and teardown says what it found.
    let f = prepared_ordered_fixture(XServerFrontendClientId(8461));
    let (owner, registration, runner, durable, _output) = serving_custody_for(f);
    registration
        .retain_ordered_setup(PrivateOrderedContinuation::Serving {
            owner: home_holding(owner),
            evidence: PrivateOrderedEvidence::unstarted(),
        })
        .unwrap_or_else(|_| panic!("this registration holds no custody yet"));
    assert_eq!(
        registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established,
        "closed through the real API, before teardown"
    );

    drop(runner);
    drop(registration);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::AlreadyEstablished))
    );
}


#[test]
fn a_connections_place_coming_back_answers_nothing_for_an_interrupted_handover() {
    // THE TWO ACCOUNTINGS ARE SEPARATE, and this is where that matters most.
    // A handover interrupted between taking the capsule out of custody and
    // handing it over leaves a delivery nobody can resolve from here: the slot
    // is empty, the phase says a handover may have begun, and whether the
    // capsule reached the queue is not knowable from either side. Meanwhile
    // the CONNECTION can finish perfectly well -- its producers go, its wire
    // ends, its closure is established -- and its place comes back.
    //
    // WHAT THIS ESTABLISHES: the delivery is answered by the client going, and
    // answered as that; the place returning neither produces that answer nor
    // revises it; and nothing anywhere rebuilds or re-offers the capsule.
    //
    // WHAT IT DOES NOT ESTABLISH, and the precondition is the reason: the
    // capsule is taken and dropped here OUTSIDE the gate, which leaves the
    // gate healthy, so teardown establishes a closure and the place comes
    // back. A real unwind is not like that -- a producer is INSIDE the gate
    // from before the take until after the owned report, so unwinding there
    // poisons it, teardown then establishes nothing, and the place is kept.
    // The control below carries that state instead. This one is about the
    // separation of accountings under a supplied clean fence, and nothing it
    // says applies to a handover that actually unwound.
    //
    // WHAT IS STAGED IS THE CUSTODY HALF, under a supplied healthy gate. It is
    // not the state an unwind leaves: an unwind is inside the gate and poisons
    // it, and the control below carries that composite. This one sets the
    // custody side directly -- an empty slot under a phase that says a
    // handover may have begun -- and leaves the gate untouched on purpose, so
    // the separation it is about can be read without the closure question
    // mixed into it. What is real is everything after: the producer's own
    // refusal to re-offer, the teardown, the drive, and the answer.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8491));
    attempt_run(&mut f, 84910, 272, true);
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 84910);
    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    {
        let record = &mut private.terminal.holds[0];
        let emission = record
            .native
            .as_mut()
            .unwrap()
            .take_press_emission()
            .expect("its own press emission");
        PrivateXServerFrontend::stow_press_capsule(
            &mut record.custody,
            emission,
            &recovery,
            f.client,
        );
        // The write-ahead, then the take -- and then nothing, which is the
        // interruption.
        record.custody.dispatch = PrivateDispatchPhase::Indeterminate;
        let taken = record.custody.pending.take();
        assert!(
            matches!(taken, Some(PrivatePendingDelivery::Capsule(_))),
            "there was a capsule, and this is where it is lost"
        );
        drop(taken);
    }

    // THE PRODUCER NEVER OFFERS IT AGAIN. The phase authorises, not the slot,
    // and an empty slot under Indeterminate is exactly what an interrupted
    // handover looks like from here.
    for _ in 0..8 {
        f.runner
            .frontend
            .as_mut()
            .unwrap()
            .deliver_one(&mut |_, _| Ok(()))
            .expect("the executor keeps running");
    }
    assert!(
        f.channels.ordered.try_recv().is_err(),
        "nothing is rebuilt and nothing is re-offered"
    );
    let private = f.runner.frontend.as_ref().unwrap();
    assert_eq!(
        handover_phase(private, &cell),
        Some(PrivateDispatchPhase::Indeterminate),
        "and the phase still says a handover may have begun"
    );
    assert!(cell.answer().is_none(), "nobody has answered for it");

    // Now the connection ends and finishes: bound, torn down, closed,
    // producers gone, wire ended.
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let PreparedOrderedFixture {
        registration,
        runner,
        channels,
        durable,
        ..
    } = f;
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a registration that holds no custody yet"));
    drop(runner);
    drop(registration);
    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Established))
    );

    // WHAT ANSWERED IT IS THE DISCONNECT, AND WHAT IT SAYS IS THE DISCONNECT.
    // The client is gone, so this delivery can never be confirmed; recording
    // that is an honest terminal outcome and not a receipt. Nothing claims it
    // was written, flushed or seen.
    let answer = cell
        .answer()
        .expect("the client going is itself an outcome for what it was owed");
    assert_eq!(answer.delivery, XAuthorityInputDeliveryId::from_raw(84910));
    assert_eq!(
        answer.outcome,
        XAuthorityInputDeliveryOutcome::ClientDisconnected,
        "the outcome is that the client went, not that anything reached it"
    );

    // AND THE PLACE COMING BACK CHANGES NOTHING ABOUT IT. A place is about a
    // connection's ordered output; it is not an answer, and it does not revise
    // one. This is the separation: two accountings, each finishing on its own
    // evidence, neither standing in for the other.
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "the connection's own accounting completes: its place comes back"
    );
    let after = cell.answer().expect("still answered, once");
    assert_eq!(after.outcome, answer.outcome, "and answered the same way");
    assert_eq!(after.delivery, answer.delivery);
}


#[test]
fn a_handover_that_unwound_inside_the_gate_keeps_its_place() {
    // WHAT AN ACTUAL UNWIND LEAVES. A producer is inside the gate from before
    // it takes the capsule until after it writes down what came back, so an
    // unwind anywhere in there poisons the gate as it goes. Teardown then
    // establishes no closure, and the place is KEPT -- the opposite of the
    // clean-fence case beside this one, and the reason that case cannot be
    // read as covering this one.
    //
    // BOTH HALVES ARE STAGED HERE, and deliberately together, because that is
    // what makes the state the one an unwind produces: the interrupted custody
    // AND the poisoned gate. This crate cannot unwind a producer mid-call
    // without a hook; what it can do is refuse to pretend that half the state
    // is the whole of it.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8501));
    attempt_run(&mut f, 85010, 272, true);
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 85010);
    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    {
        let record = &mut private.terminal.holds[0];
        let emission = record
            .native
            .as_mut()
            .unwrap()
            .take_press_emission()
            .expect("its own press emission");
        PrivateXServerFrontend::stow_press_capsule(
            &mut record.custody,
            emission,
            &recovery,
            f.client,
        );
        record.custody.dispatch = PrivateDispatchPhase::Indeterminate;
        drop(record.custody.pending.take());
    }
    // The other half: a producer that unwound inside the gate leaves it
    // poisoned.
    let gate = f.registration.ordered_gate.clone();
    let holder = std::thread::spawn(move || {
        let _inside = gate.fenced.lock().expect("an open gate");
        panic!("a handover unwound inside this gate");
    });
    assert!(holder.join().is_err(), "the holder unwound");

    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let PreparedOrderedFixture {
        registration,
        runner,
        channels,
        durable,
        ..
    } = f;
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a registration that holds no custody yet"));
    drop(runner);
    drop(registration);

    assert_eq!(
        retained_fence(&durable, 0),
        Some(Some(PrivateHandoverFence::Unreadable)),
        "teardown established nothing, because the gate had been unwound through"
    );
    let answer = cell.answer().expect("the client going is still an outcome");
    assert_eq!(
        answer.outcome,
        XAuthorityInputDeliveryOutcome::ClientDisconnected,
        "answered as the client going, exactly as in the clean case"
    );
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    let (_kind, _refusal, retained, drained, ended) =
        retained_setup_kind(&durable, 0).expect("the place this connection held");
    assert_eq!(
        (retained, drained, ended),
        (0, true, true),
        "its queue finished and its wire ended, as far as those go"
    );
    assert!(
        !durable
            .with_ordered_continuation(0, |continuation| continuation.settled())
            .expect("the place holds it")
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "AND THE PLACE STAYS HELD. An unwound handover is not a finished one, \
         however quiet everything around it goes"
    );
}


#[test]
fn a_release_meeting_a_gone_receiver_keeps_its_capsule_and_gives_the_attempt_back() {
    // KNOWN NOT ENQUEUED, the other way. A full queue and a gone receiver are
    // both exact answers from the channel: neither took the capsule, so both
    // leave it offerable and both give the attempt back. The existing control
    // for an unplaceable attempt drops the whole registration, so it refuses
    // at the row lookup before the gate; this one keeps the row and the gate
    // and lets the SEND be what refuses.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8511));
    attempt_release(&mut f, 85110, 272);
    {
        let private = f.runner.frontend.as_mut().unwrap();
        assert_eq!(private.dispatch_one_press(), Some(true));
        assert_eq!(private.record_one_native(), Some(true));
    }
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 85111);

    // Its receiver goes while its row stays. A spare registration supplies a
    // receiver to put in its place so the fixture stays whole; the spare's own
    // row goes with it and is nothing to do with this claim.
    let spare = XServerFrontendClientId(f.client.raw() + 900_000);
    let spare_ordered = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .register_client_with_admission(spare, Some(admitted(spare)))
        .expect("a spare registration to borrow a receiver from")
        .1
        .ordered;
    drop(std::mem::replace(&mut f.channels.ordered, spare_ordered));

    let private = f.runner.frontend.as_mut().unwrap();
    let index = private
        .terminal
        .settling
        .iter()
        .position(|release| release.completion().is_some_and(|held| Arc::ptr_eq(held, &cell)))
        .expect("the release this control is about");
    assert_eq!(
        private.attempt_one_delivery(),
        Some(false),
        "the send itself refused: there is no receiver left"
    );

    // EXACTLY WHAT A FULL QUEUE LEAVES. The capsule is the one the release
    // decided -- not rebuilt, not reselected -- the phase says it is offerable
    // again, and the attempt went back rather than being spent on a delivery
    // nobody will make.
    assert_eq!(
        handover_phase(private, &cell),
        Some(PrivateDispatchPhase::Pending),
        "known not enqueued, so it may be offered again"
    );
    match private.terminal.settling[index].custody.pending.as_ref() {
        Some(PrivatePendingDelivery::Capsule(capsule)) => {
            assert_eq!(
                capsule.delivery(),
                XAuthorityInputDeliveryId::from_raw(85111)
            );
            assert!(Arc::ptr_eq(&cell, &capsule.finalizer().unwrap().completion));
        }
        _ => panic!("the refusal handed the exact capsule back"),
    }
    assert!(
        private.terminal.settling[index].custody.attempt.is_none(),
        "the record stops naming an attempt once the ledger confirmed it back"
    );
    assert!(
        private.terminal.attempt_custody.is_none(),
        "and nothing holds the ledger's slot for a delivery nobody will make"
    );
    assert!(
        cell.answer().is_none(),
        "a refused send answers nothing: the debt is exactly as owed as before"
    );
}


/// One real grant from the ledger, taken the way the executor takes one.
///
/// Not a fabricated token: the authority chooses the debt and issues the
/// claim, so what is held afterwards is the ledger's own slot.
fn real_attempt_claim(
    private: &crate::PrivateXServerFrontend,
) -> sophia_input_authority::AttemptClaim {
    let mut cursor = 0;
    private
        .authority()
        .under_common_as_origin(|authority, issuer| {
            authority.claim_next_attempt(issuer, &mut cursor)
        })
        .expect("a readable authority")
        .expect("this issuer answers for it")
        .expect("a debt to attempt")
}

#[test]
fn an_unplaced_attempt_goes_back_and_the_ledger_hands_the_debt_out_again() {
    // UNPLACED IS PROVABLY UNUSED. Nothing was written onto the record and
    // nothing was taken, so this grant reached no recipient and may go back --
    // and going back is what the LEDGER confirms, not what a cleared slot
    // here suggests. The debt being offered again is the ledger saying so.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8521));
    attempt_release(&mut f, 85210, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));

    let claim = real_attempt_claim(private);
    let incarnation = claim.hold;
    assert_eq!(
        private.terminal.settling[0].incarnation(),
        incarnation,
        "the ledger chose this release's own debt"
    );
    private.terminal.attempt_custody = Some(PrivateAttemptCustody {
        token: claim.token,
        phase: PrivateAttemptPhase::Unplaced,
    });

    assert_eq!(
        private.relinquish_one_attempt(),
        Some(true),
        "an unplaced grant goes back, and the ledger confirmed it"
    );
    assert!(
        private.terminal.attempt_custody.is_none(),
        "the executor stops naming it only once that confirmation landed"
    );

    // THE LEDGER'S OWN ACCOUNT, not this executor's. The same debt is granted
    // again, which it could not be while an attempt on it was outstanding.
    let again = real_attempt_claim(private);
    assert_eq!(
        again.hold, incarnation,
        "the debt is outstanding again, so the return really did land"
    );
    assert_ne!(
        again.token, claim.token,
        "and it is a new grant, not the old token handed back"
    );
    assert!(
        private.relinquish_outstanding_attempt(again.token),
        "this control's own cleanup is confirmed too, so it leaves the ledger \
         as it found it"
    );
}

#[test]
fn a_dispatching_attempt_is_never_given_back_as_unused() {
    // DISPATCHING MEANS IT MAY HAVE REACHED THE RECIPIENT. The record names it
    // and the phase says the handover was begun, so no path may hand this
    // grant back as an unused reservation -- that would tell the ledger
    // nothing happened for a delivery that may already be on a queue.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8531));
    attempt_release(&mut f, 85310, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));

    let claim = real_attempt_claim(private);
    let incarnation = claim.hold;
    // The write-ahead state: named on the record, phase says begun. Staged,
    // because an unwind is what leaves it and this crate cannot unwind a
    // producer mid-call; the token and the debt are the ledger's own.
    private.terminal.attempt_custody = Some(PrivateAttemptCustody {
        token: claim.token,
        phase: PrivateAttemptPhase::Dispatching,
    });
    private.terminal.settling[0].custody.attempt = Some(claim.token);
    private.terminal.settling[0].custody.dispatch = PrivateDispatchPhase::Indeterminate;

    assert!(
        private.relinquish_one_attempt().is_none(),
        "a grant that may have been used is not an unused reservation"
    );
    assert_eq!(
        private
            .terminal
            .attempt_custody
            .map(|custody| (custody.token, custody.phase)),
        Some((claim.token, PrivateAttemptPhase::Dispatching)),
        "it stays held, as exactly the token and phase it was"
    );
    assert_eq!(
        private.terminal.settling[0].custody.attempt,
        Some(claim.token),
        "and the record goes on naming that same token"
    );

    // THE LEDGER STILL HAS IT. The debt is not offered again, which is what an
    // outstanding attempt looks like from the other side.
    let mut cursor = 0;
    let next = private
        .authority()
        .under_common_as_origin(|authority, issuer| {
            authority.claim_next_attempt(issuer, &mut cursor)
        })
        .expect("a readable authority")
        .expect("this issuer answers for it");
    // One debt, one attempt: with that attempt outstanding there is nothing
    // left for the ledger to grant at all.
    assert!(
        next.is_none(),
        "a debt with an attempt outstanding is not granted again, and this \
         fixture has no other debt to offer"
    );
    let _ = incarnation;
}


#[test]
fn an_attempt_whose_return_was_not_confirmed_stays_named_here() {
    // THE LEDGER'S CONFIRMATION IS THE EVIDENCE, not the call. A give-back
    // that got no answer has established nothing: the ledger may still hold
    // the slot, and an executor that stopped naming the token on the strength
    // of having asked would have lost the only handle on it.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8541));
    attempt_release(&mut f, 85410, 272);
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(private.record_one_native(), Some(true));
    let claim = real_attempt_claim(private);
    private.terminal.attempt_custody = Some(PrivateAttemptCustody {
        token: claim.token,
        phase: PrivateAttemptPhase::Unplaced,
    });

    // The authority cannot be read: a holder panicked inside it. Asking is
    // still possible; getting an answer is not.
    let common = Arc::clone(&private.authority().common);
    let holder = std::thread::spawn(move || {
        let _inside = common.lock().expect("a readable authority");
        panic!("a holder unwound inside the authority");
    });
    assert!(holder.join().is_err(), "the holder unwound");

    assert_eq!(
        private.relinquish_one_attempt(),
        Some(false),
        "asked, and not answered"
    );
    assert_eq!(
        private
            .terminal
            .attempt_custody
            .map(|custody| custody.token),
        Some(claim.token),
        "so the executor goes on naming exactly that token, unchanged"
    );
    assert_eq!(
        private
            .terminal
            .attempt_custody
            .map(|custody| custody.phase),
        Some(PrivateAttemptPhase::Unplaced),
        "and goes on knowing it was never placed"
    );
}


#[test]
fn a_record_that_cannot_finish_says_which_things_are_stopping_it() {
    // THE REASONS COEXIST AND ARE REPORTED SEPARATELY. A connection can have
    // no way to end its wire AND a closure nobody could establish. They are
    // independent facts of one bounded record: reporting either alone loses
    // the other, and collapsing them into "not finished" sends whoever reads
    // it looking for the wrong thing.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8551);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let other = XServerFrontendClientId(8552);
    let (other_registration, other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a second place and row");

    // A real refusal leaves it holding a receiver and no way to reach the
    // connection at all.
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(other_channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        Some(X11OrderedServingRefusal::ForeignReceiver)
    );
    // And a producer unwinds inside its gate, so the closure establishes
    // nothing either.
    let gate = registration.ordered_gate.clone();
    let holder = std::thread::spawn(move || {
        let _inside = gate.fenced.lock().expect("an open gate");
        panic!("a handover unwound inside this gate");
    });
    assert!(holder.join().is_err(), "the holder unwound");
    drop(channels);
    drop(registration);
    drop(other_registration);
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }

    let readings = durable
        .retained_dispositions()
        .expect("a readable store");
    let stuck = readings
        .iter()
        .find_map(|(index, reading)| (*index == 0).then_some(reading))
        .expect("the connection that could not finish")
        .expect("and it is readable");
    assert_eq!(
        stuck.ending,
        PrivateRetainedEnding::NoCapability,
        "no handle on the connection: not a refused shutdown, and not an ending"
    );
    assert_eq!(
        stuck.closure,
        Some(PrivateHandoverFence::Unreadable),
        "and separately, a closure nobody could establish"
    );
    assert!(!stuck.settled, "so it owes something");
    assert_eq!(
        (stuck.drained, stuck.retained),
        (true, 0),
        "while its queue did finish and it is holding nothing, which is why \
         neither of those can be what a reader is told"
    );
}

#[test]
fn a_reading_reports_an_ending_and_a_closure_that_were_established() {
    // The same reading over a connection that got everything it needed, so
    // the one above is not simply reporting sadness at everything.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8561);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));
    drop(registration);
    drop(private);

    // Read before it is driven: closed, nothing ended yet, nothing held.
    let before = durable.retained_dispositions().expect("a readable store");
    assert_eq!(before.len(), 1);
    let reading = before[0].1.expect("a readable record");
    assert_eq!(reading.closure, Some(PrivateHandoverFence::Established));
    assert_eq!(
        reading.ending,
        PrivateRetainedEnding::Unattempted,
        "it has a handle and has not used it: that is not the same as having none"
    );
    assert!(!reading.settled);

    // Driven, and then gone: a settled record returns its place, so there is
    // nothing left to report.
    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    assert!(
        durable
            .retained_dispositions()
            .expect("a readable store")
            .is_empty(),
        "a place that came back is not a connection, and is not reported as one"
    );

    // NEITHER IS A PLACE THAT WAS PROMISED AND NEVER FILLED. A connection that
    // ended without ever binding keeps its place -- what was accepted for it
    // is unknown, so it is not given back -- but the place holds no record,
    // and there is no connection there to report. A reading that invented one
    // would put a row in front of an operator with nothing behind it.
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let never_bound = XServerFrontendClientId(8562);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(never_bound, Some(admitted(never_bound)))
        .expect("a place and a row");
    drop(channels);
    drop(registration);
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "its place is held, because what was accepted for it is unknown"
    );
    assert!(
        durable
            .retained_dispositions()
            .expect("a readable store")
            .is_empty(),
        "and yet there is no connection there to read"
    );
}


/// A reading of one serving record, installed in a store of its own.
fn serving_reading(
    owner: X11OrderedServingOwner,
) -> (PrivateSettlementOwner, PrivateRetainedDisposition) {
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut source = Some(PrivateOrderedContinuation::Serving {
        owner: home_holding(owner),
        // A staged precondition: what a torn-down record carries.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
    let reading = durable
        .retained_dispositions()
        .expect("a readable store")[0]
        .1
        .expect("a readable record");
    (durable, reading)
}

#[test]
fn a_refused_ending_is_reported_as_refused_and_not_as_untried() {
    // A CLOSE THAT TRIED AND WAS REFUSED IS NOT A CLOSE THAT NEVER TRIED. The
    // refusal is written on the close record itself, and a reading that only
    // consulted the owner's separate cause reported it as unattempted --
    // sending whoever read it looking for a syscall that had already happened
    // and failed.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8571));
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    // Staged: this host gives no honest way to make a shutdown refuse, so the
    // close record is written as begin_close's own failure branch writes it --
    // one attempt made, refused, and no ending established.
    owner.closing = Some(X11OrderedClosing {
        cause: X11OrderedCloseCause::ConnectionEnded,
        termination: X11OrderedTermination::Refused(std::io::ErrorKind::PermissionDenied),
        attempts: 1,
        answered: 0,
        already: 0,
        deferred: 0,
        drained: false,
    });
    assert!(
        !owner.ending_ended(),
        "nothing ended this wire, which is the state being reported"
    );
    assert!(
        owner.unterminated_cause().is_none(),
        "and the owner carries no separate cause, so the close record is the \
         only thing that knows"
    );

    let (_durable, reading) = serving_reading(owner);
    assert_eq!(
        reading.ending,
        PrivateRetainedEnding::Refused(std::io::ErrorKind::PermissionDenied),
        "the close record says it was refused, and that is what is reported"
    );
}

#[test]
fn an_ending_that_was_established_outranks_a_cause_recorded_before_it() {
    // A LATER ESTABLISHED ENDING IS THE ENDING. An earlier attempt that
    // refused leaves its cause standing on the owner; reading that first
    // reported a wire as unterminated after it had actually been ended.
    //
    // The cause is not discharged by being outranked: it still says what
    // happened, and the report saying Ended authorises nothing about it.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8581));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    // Staged history: an earlier attempt refused.
    owner.unterminated = true;
    owner.unterminated_cause = Some(X11OrderedUnterminatedCause::Shutdown(
        std::io::ErrorKind::PermissionDenied,
    ));
    // And then a real close, over a real peer that really goes.
    drop(peer);
    owner
        .begin_close(X11OrderedCloseCause::ConnectionEnded)
        .expect("this socket ends");

    assert!(
        owner.unterminated_cause().is_some(),
        "the earlier cause is still on the owner, undischarged"
    );
    let (_durable, reading) = serving_reading(owner);
    assert_eq!(
        reading.ending,
        PrivateRetainedEnding::Ended,
        "what is reported is the ending that was established"
    );
}

#[test]
fn an_ending_through_a_part_written_frame_is_reported_as_an_ending() {
    // THIS PATH LEAVES NO CLOSE RECORD. Ending a part-written frame ends the
    // wire and writes nothing about having done so, and a reading that looked
    // only at close records called that unattempted.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8591));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    drop(peer);
    owner.end_partial_frame();
    assert!(
        owner.closing().is_none(),
        "no close was begun, which is the whole point of this path"
    );

    let (_durable, reading) = serving_reading(owner);
    assert_eq!(reading.ending, PrivateRetainedEnding::Ended);
}

#[test]
fn a_reading_counts_every_slot_that_is_holding_something() {
    // A CAPSULE HELD IN THE REFUSED SLOT IS CUSTODY. It is unanswered and it
    // is this owner's to answer for, exactly as one in the retained list is,
    // and a count that left it out reported nothing held while an unanswered
    // completion sat in the writer.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8601));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    let sender = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry")
        .get(&f.client)
        .expect("its row")
        .ordered
        .clone();
    let (foreign, _endpoint, _recovery, _receipts) = answerable_capsule(86010);
    let cell = Arc::clone(&foreign.finalizer().expect("carried").completion);
    gated_send(&sender, foreign).expect("this owner's queue accepts it");
    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::AdmissionRefused(_)
    ));
    assert!(
        owner.refused().is_some(),
        "the writer is holding it, unanswered"
    );
    assert!(cell.answer().is_none());

    let (_durable, reading) = serving_reading(owner);
    assert_eq!(
        reading.retained, 1,
        "so the reading says one thing is held, rather than nothing"
    );
    assert!(!reading.settled);
}

#[test]
fn a_record_that_cannot_be_read_is_reported_as_unreadable() {
    // NOT SKIPPED, AND NOT GUESSED AT. A poisoned record may well hold a
    // connection; what it does not hold is a reading. Treating it as a normal
    // row would put an account in front of a reader with nothing behind it,
    // and skipping it would lose a connection from the account entirely.
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8611));
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (owner, _output) = serving_owner_for(&mut f, socket);
    let mut source = Some(PrivateOrderedContinuation::Serving {
        owner: home_holding(owner),
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    // A holder panics inside this record.
    let record = {
        let held = durable.inner.lock().expect("a readable store");
        let PrivateOrderedContinuationPlace::Taken(record) = &held.continuations[0] else {
            panic!("its place holds a record")
        };
        record.clone()
    };
    let holder = std::thread::spawn(move || {
        record.borrow(|_| panic!("a holder unwound inside this record"))
    });
    assert!(holder.join().is_err(), "the holder unwound");

    let readings = durable.retained_dispositions().expect("a readable store");
    assert_eq!(readings.len(), 1, "the connection is still in the account");
    assert!(
        readings[0].1.is_none(),
        "and is reported as unreadable rather than as anything in particular"
    );
}


#[test]
fn an_ordinary_stop_ends_nothing_and_is_not_reported_as_an_ending() {
    // A STOP WITH NOTHING PART-WRITTEN LEAVES THE WIRE ALONE. No shutdown is
    // made, the connection is still usable and still unbarred, and its queue
    // still holds what was accepted.
    //
    // WHICH STOP THIS IS: the early one, where stop is already set when
    // serve_one is entered, so it returns without taking the output at all.
    // The other is a stop that arrives AFTER that check, which reaches the
    // exit under serialization with nothing part-written; "nothing refused" is
    // true there too, and reading an ending from it reported a live connection
    // as ended. Reaching that one needs a rendezvous inside serve_one, which
    // this crate has no way to make, so it is not established here.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8621));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (mut owner, output) = serving_owner_for(&mut f, socket);
    let stop = Arc::new(AtomicBool::new(true));
    owner.stop = Some(stop);
    assert!(!owner.mid_frame(), "nothing is part-written");

    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::Stopped
    ));
    assert!(
        !owner.ending_ended(),
        "nothing attempted an ending, so nothing may record one"
    );
    assert!(
        !owner.wire.barred(),
        "the connection's own permission was never barred"
    );
    let (_durable, reading) = serving_reading(owner);
    assert_eq!(reading.ending, PrivateRetainedEnding::Unattempted);

    // AND THE CONNECTION REALLY IS STILL THERE. Two separate facts: the
    // permission was never barred, and the socket was never shut down. The
    // write below goes through the raw output and so proves only the second;
    // the permission is asked directly, because a writer going through
    // admission would be stopped by a bar this control must rule out itself.
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).map_err(|error| error.kind()),
        Err(std::io::ErrorKind::WouldBlock),
        "nothing was written and nothing was ended"
    );
    std::io::Write::write_all(&mut *output.lock().expect("its output"), b"alive")
        .expect("a wire nobody ended still carries bytes");
    let mut alive = [0u8; 5];
    std::io::Read::read_exact(&mut (&peer), &mut alive).expect("and they arrive");
    assert_eq!(&alive, b"alive");
}

#[test]
fn an_ending_reached_by_an_ordinary_serving_exit_is_reported_as_one() {
    // THE SAME FACT, REACHED THE ORDINARY WAY. A send that finds the peer gone
    // ends the wire on its way out and says so in the step it returns.
    // Recording an ending only on the close paths meant an owner whose wire
    // this had ended read as never having attempted one.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8631));
    attempt_run(&mut f, 86310, 272, true);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    {
        let private = f.runner.frontend.as_mut().unwrap();
        assert_eq!(private.dispatch_one_press(), Some(true));
    }
    // The peer really goes, so the write really fails.
    drop(peer);
    let mut ended = None;
    for _ in 0..8 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            step @ X11OrderedServeStep::Ended { .. } => {
                ended = Some(step);
                break;
            }
            X11OrderedServeStep::Idle => break,
            _ => continue,
        }
    }
    assert!(
        matches!(ended, Some(X11OrderedServeStep::Ended { shutdown: true, .. })),
        "the exit ended this wire and said so: {ended:?}"
    );
    assert!(
        owner.ending_ended(),
        "so the owner knows its wire was ended"
    );

    let (_durable, reading) = serving_reading(owner);
    assert_eq!(reading.ending, PrivateRetainedEnding::Ended);
}


#[test]
fn an_ending_this_owner_made_itself_is_reported_as_one() {
    // THE OWNER'S OWN FALLBACK. When the delivery writer finds the producers
    // gone it reports the end without shutting anything down, and this owner
    // ends the wire itself on the way out. That is a second site, and an
    // ending recorded at only one of them left the other reading as never
    // attempted.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8641));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);

    // Its producers really go: the row and everything holding a sender for it.
    let PreparedOrderedFixture {
        registration,
        runner,
        channels,
        ..
    } = f;
    drop(channels);
    drop(registration);
    drop(runner);

    let step = owner.serve_one(XByteOrder::LittleEndian, 7);
    assert!(
        matches!(
            step,
            X11OrderedServeStep::Ended {
                shutdown: true,
                ..
            }
        ),
        "this owner ended the wire itself: {step:?}"
    );
    assert!(owner.ending_ended(), "so it knows it did");
    let (_durable, reading) = serving_reading(owner);
    assert_eq!(reading.ending, PrivateRetainedEnding::Ended);

    // The peer sees the end, which is the fact being reported.
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).ok(),
        Some(0),
        "the wire really was ended"
    );
}


/// A serving record installed in a store, with its close staged as refused.
///
/// The refusal is staged -- this host gives no honest way to make a shutdown
/// fail -- and written exactly as begin_close's own failure branch writes it,
/// with the attempts already spent. Everything after it is real: the retry is
/// the production visit, and the shutdown it makes is a real one.
fn retained_refused_close(
    owner: X11OrderedServingOwner,
    attempts: u8,
) -> PrivateSettlementOwner {
    let mut owner = owner;
    owner.closing = Some(X11OrderedClosing {
        cause: X11OrderedCloseCause::ConnectionEnded,
        termination: X11OrderedTermination::Refused(std::io::ErrorKind::PermissionDenied),
        attempts,
        answered: 0,
        already: 0,
        deferred: 0,
        drained: false,
    });
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut source = Some(PrivateOrderedContinuation::Serving {
        owner: home_holding(owner),
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
    durable
}

#[test]
fn a_refused_close_is_attempted_again_by_the_next_visit() {
    // NOBODY WAS RETRYING. The visit asked for a close only when none existed,
    // so a close whose shutdown refused was never attempted again: serving
    // excluded, the wire possibly still carrying bytes, and the recipient
    // waiting for an ending that was not coming.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8651));
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (owner, _output) = serving_owner_for(&mut f, socket);
    let durable = retained_refused_close(owner, 1);

    // One visit, and the attempt is made again -- for real, on a real socket,
    // which is why it succeeds this time.
    //
    // WHAT THIS CONTROL DOES NOT COVER: this owner is holding nothing, so what
    // it establishes about publication is that a place is kept, not that
    // custody was withheld. The exhausted control beside it holds a real
    // capsule and an unanswered completion, and is where that is said.
    durable.drive_ordered_continuations(1);
    let held = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Serving { owner, .. } = continuation else {
                panic!("a serving record")
            };
            let closing = owner.closing().expect("its close");
            (closing.cause, closing.termination, closing.attempts)
        })
        .expect("the place holds it");
    assert_eq!(
        held.1,
        X11OrderedTermination::Established,
        "the retry established the termination the first attempt could not"
    );
    assert_eq!(
        held.0,
        X11OrderedCloseCause::ConnectionEnded,
        "THE ORIGINAL CAUSE, not the one the visit would have opened with"
    );
    assert_eq!(
        held.2, 2,
        "and the attempt count carried on rather than starting again"
    );
}

#[test]
fn a_close_with_no_attempts_left_says_so_and_is_not_retried() {
    // EXHAUSTION IS EXPLICIT. A close that refused with attempts left will be
    // tried again by the next visit; one with none left will not, and no
    // amount of driving changes it. Reporting both as refused leaves a reader
    // waiting for a retry that is never coming.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8661));
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);

    // IT IS HOLDING SOMETHING. Without custody this control could only say a
    // place was kept, which is not the same as saying nothing was offered from
    // it. A real capsule goes onto its queue and into its refused slot, with a
    // completion nobody has answered.
    let sender = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry")
        .get(&f.client)
        .expect("its row")
        .ordered
        .clone();
    let (held_capsule, _endpoint, _recovery, _receipts) = answerable_capsule(86610);
    let delivery = held_capsule.delivery();
    let cell = Arc::clone(&held_capsule.finalizer().expect("carried").completion);
    gated_send(&sender, held_capsule).expect("this owner's queue accepts it");
    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::AdmissionRefused(_)
    ));
    assert!(owner.refused().is_some(), "the writer is holding it");

    let durable = retained_refused_close(owner, X11_ORDERED_CLOSE_ATTEMPTS);

    for _ in 0..8 {
        durable.drive_ordered_continuations(4);
    }
    let held = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Serving { owner, .. } = continuation else {
                panic!("a serving record")
            };
            let closing = owner.closing().expect("its close");
            (closing.termination, closing.attempts, owner.ending_ended())
        })
        .expect("the place holds it");
    assert_eq!(
        held.0,
        X11OrderedTermination::Refused(std::io::ErrorKind::PermissionDenied),
        "the original refusal stands, with its original cause"
    );
    assert_eq!(
        held.1, X11_ORDERED_CLOSE_ATTEMPTS,
        "NO ATTEMPT WAS MADE and none was invented: the count did not move"
    );
    assert!(!held.2, "and nothing was ended");

    let reading = durable.retained_dispositions().expect("a readable store")[0]
        .1
        .expect("a readable record");
    assert!(
        reading.retries_exhausted,
        "so the reading says the retries are spent, not merely that it refused"
    );
    assert_eq!(
        reading.ending,
        PrivateRetainedEnding::Refused(std::io::ErrorKind::PermissionDenied)
    );
    assert!(!reading.settled, "and it is not finished");
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "NOTHING IS PUBLISHED BEFORE A CONFIRMED TERMINATION: the place stays"
    );

    // AND NEITHER IS WHAT IT HOLDS. THE EXACT CAPSULE, BY IDENTITY: a delivery
    // number is not an identity -- another real admission can carry the same
    // one -- so what is compared is the completion this capsule was built
    // with, by pointer.
    //
    // WHAT THIS CAPSULE IS: another endpoint's, refused on admission and held
    // unanswered. So what is established here is that a close which could not
    // establish an ending offers nothing derived from one, over FOREIGN
    // custody. It is not independently the publication guard for this
    // endpoint's own admission.
    assert_eq!(reading.retained, 1);
    let still = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Serving { owner, .. } = continuation else {
                panic!("a serving record")
            };
            owner.refused().map(|held| {
                (
                    held.delivery().delivery(),
                    Arc::clone(&held.delivery().finalizer().expect("carried").completion),
                )
            })
        })
        .expect("the place holds it")
        .expect("and the writer still holds the capsule");
    assert_eq!(still.0, delivery);
    assert!(
        Arc::ptr_eq(&still.1, &cell),
        "the exact one, by the completion it was built with"
    );
    assert!(
        cell.answer().is_none(),
        "and nobody answered for it on the strength of a close that failed"
    );
}


/// A home holding an owner a control built directly.
///
/// Production makes one only through `commit`, where the allocation happens
/// before any custody is taken. A control that builds an owner some other way
/// needs somewhere to put it, and this is that -- it is not the promotion
/// path, and a fixture using it is not exercising one.
fn home_holding(owner: X11OrderedServingOwner) -> PrivateServingHome {
    PrivateServingHome(Box::new(Some(owner)))
}

/// A prepared connection whose ordered output is bound, ready to promote.
///
/// Built on the ordered fixture because promotion asks the frontend for this
/// connection's endpoint, and that is answerable only for a connection the
/// instance has actually admitted and published.
fn bound_connection(
    client: XServerFrontendClientId,
) -> (
    XServerFrontendClientRouteRegistration,
    PrivatePreparedRunner,
    PrivateSettlementOwner,
    Arc<Mutex<UnixStream>>,
    UnixStream,
) {
    let f = prepared_ordered_fixture(client);
    let PreparedOrderedFixture {
        registration,
        runner,
        channels,
        durable,
        ..
    } = f;
    let (stream, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));
    (registration, runner, durable, output, peer)
}

/// What this registration's ordered payload is, by shape.
fn payload_shape(
    registration: &XServerFrontendClientRouteRegistration,
) -> Option<&'static str> {
    registration
        .ordered_home
        .borrow(|payload| match payload {
            PrivateOrderedContinuation::Setup {
                accepted: PrivateOrderedSetupCustody::Transport(_),
                ..
            } => "transport",
            PrivateOrderedContinuation::Setup {
                accepted: PrivateOrderedSetupCustody::Receiver(_),
                ..
            } => "receiver",
            PrivateOrderedContinuation::Serving { .. } => "serving",
        })
}

#[test]
fn a_receiver_alone_is_not_something_to_promote() {
    // A binding that refused keeps a receiver and no connection, so there is
    // nothing to make an owner from. This says only that; the control below is
    // where a refusal INSIDE preparation is answered for.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8671);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let other = XServerFrontendClientId(8672);
    let (other_registration, other_channels) = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a second place and row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(other_channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));
    assert_eq!(payload_shape(&registration), Some("receiver"));

    assert_eq!(
        registration.promote_ordered_serving(&private),
        PrivateOrderedPromotion::Unbound
    );
    assert_eq!(
        payload_shape(&registration),
        Some("receiver"),
        "and nothing moved"
    );
    drop(channels);
    drop(registration);
    drop(other_registration);
}

#[test]
fn a_preparation_that_refuses_leaves_the_transport_and_its_queue_untouched() {
    // THE REFUSAL HAPPENS INSIDE PREPARATION, over a connection that really
    // has a bound transport with a real capsule on its queue. That is the only
    // arrangement in which "a refusal consumes nothing" says anything: a
    // refusal reached before preparation runs proves nothing about what
    // preparation does with what it borrows.
    //
    // It refuses because this connection's private lifecycle and connection
    // state were never attached, so the endpoint lookup has nothing to answer
    // with -- a real refusal from the real path, not an injected one.
    //
    // Its ROW is published, by the registration itself, and that is exactly
    // why this control can hold accepted custody: the queue is reachable, so
    // a capsule can be on it. Publication and attachment are different
    // boundaries and only the second is missing here.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8741);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let (stream, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    registration
        .bind_ordered_output(channels.ordered, &output, &wire, &pending)
        .unwrap_or_else(|_| panic!("a fresh registration holds no custody"));
    assert_eq!(payload_shape(&registration), Some("transport"));

    // A real capsule on its queue. Foreign fixture custody: it is here to be
    // work that a refusal could destroy, not an admission to this endpoint.
    let sender = capture_gated_sender(&private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(87410);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let finalizer = Arc::downgrade(capsule.finalizer().expect("carried"));
    let frames = order_pass_frames(&capsule);
    gated_send(&sender, capsule).expect("an open endpoint");

    assert_eq!(
        registration.promote_ordered_serving(&private),
        PrivateOrderedPromotion::Refused(X11OrderedServingRefusal::Unadmitted(
            PrivateAdmissionRefusal::NotAdmitted
        )),
        "refused inside preparation, by the endpoint lookup"
    );

    // NOTHING WAS CONSUMED. The transport is still here, over the same output,
    // and its queue still holds the exact capsule -- by the finalizer it was
    // built with, which is still alive.
    assert_eq!(payload_shape(&registration), Some("transport"));
    assert!(
        finalizer.upgrade().is_some(),
        "the capsule was not dropped on the way out"
    );
    let survived = registration.ordered_home.borrow(|payload| {
        let PrivateOrderedContinuation::Setup {
            accepted: PrivateOrderedSetupCustody::Transport(transport),
            ..
        } = payload
        else {
            panic!("its transport is still here")
        };
        assert!(
            Arc::ptr_eq(&transport.output, &output),
            "over the same output it was bound to"
        );
        assert!(
            transport.ordered.minted_by(&registration),
            "and the same receiver, still this registration's"
        );
        transport.ordered.receiver.try_recv().ok()
    })
    .expect("its own home")
    .expect("its queue still holds the capsule");
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(cell.answer().is_none());

    // AND THE ENDING CAPABILITY IS USED, not inferred from dropping things.
    // Letting go of every descriptor would end the socket whatever handle the
    // transport had kept -- including one for some other connection -- so the
    // retained handle is called while the real output is still open, and the
    // peer this connection belongs to is the one that has to see the end.
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).map_err(|error| error.kind()),
        Err(std::io::ErrorKind::WouldBlock),
        "still connected"
    );
    {
        registration
            .ordered_home
            .borrow(|payload| {
                let PrivateOrderedContinuation::Setup {
                    accepted: PrivateOrderedSetupCustody::Transport(transport),
                    ..
                } = payload
                else {
                    panic!("its transport is still here")
                };
                transport
                    .shutdown
                    .shutdown(Shutdown::Both)
                    .expect("the retained handle ends this connection");
            })
            .expect("its own home");
    }
    assert!(
        Arc::strong_count(&output) >= 2,
        "the real output is still open, so nothing ended by being dropped"
    );
    assert_eq!(
        (&peer).read(&mut byte).ok(),
        Some(0),
        "and THIS connection's peer sees the end, so the handle kept was its own"
    );
    drop(sender);
    drop(registration);
    drop(private);
    drop(durable);
    drop(output);
}

#[test]
fn a_promoted_connection_is_ready_and_serves_nothing() {
    // READY, DRIVEN BY NOBODY. Promotion makes an owner exist. It does not
    // start a worker, receive anything, write anything or answer anything, and
    // this checks each of those rather than the absence of a thread.
    let client = XServerFrontendClientId(8681);
    let (registration, runner, _durable, _output, peer) = bound_connection(client);
    let private = runner.frontend.as_ref().expect("a live runner");

    // A capsule is accepted for it before promotion, so there is something a
    // promotion could wrongly consume. Foreign fixture custody: it is here to
    // be work, not an admission to this endpoint.
    let sender = capture_gated_sender(private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(86810);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let finalizer = Arc::downgrade(capsule.finalizer().expect("carried"));
    let frames = order_pass_frames(&capsule);
    gated_send(&sender, capsule).expect("an open endpoint");

    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::Ready
    );
    assert_eq!(payload_shape(&registration), Some("serving"));

    registration
        .ordered_home
        .borrow(|payload| {
            let PrivateOrderedContinuation::Serving { owner, evidence } = payload else {
                panic!("promoted")
            };
            assert!(
                owner.in_flight().is_none() && owner.refused().is_none(),
                "it received nothing"
            );
            assert!(
                owner.retained_unanswered().is_empty() && owner.retained_foreign().is_empty(),
                "and is holding nothing"
            );
            assert!(owner.closing().is_none() && !owner.ending_ended());
            assert_eq!(
                evidence.worker,
                PrivateOrderedWorkerExit::NeverStarted,
                "nothing was started, and that is what is recorded"
            );
            assert!(evidence.fence.is_none() && !evidence.source_poisoned);
        })
        .expect("its own home");
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).map_err(|error| error.kind()),
        Err(std::io::ErrorKind::WouldBlock),
        "it wrote nothing"
    );
    assert!(cell.answer().is_none(), "and answered nothing");

    // AND IT RECEIVED NOTHING, which empty slots do not establish: they hold
    // equally after a capsule is received and thrown away. The queue still has
    // the exact one, by the finalizer it was built with.
    assert!(
        finalizer.upgrade().is_some(),
        "nothing dropped it on the way through"
    );
    registration
        .ordered_home
        .borrow(|payload| {
            let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                panic!("promoted")
            };
            let survived = owner
                .queue
                .try_recv()
                .expect("its queue still holds the capsule");
            assert!(Arc::ptr_eq(
                &cell,
                &survived.finalizer().expect("carried").completion
            ));
            assert_eq!(order_pass_frames(&survived), frames);
            assert!(
                owner.queue.try_recv().is_err(),
                "and holds nothing else: nothing was added either"
            );
        })
        .expect("its own home");
    assert!(cell.answer().is_none());
    drop(registration);
}

#[test]
fn a_second_promotion_leaves_the_first_owner_exactly_as_it_was() {
    // THE FIRST OWNER STANDS. A second ask does not rebuild it and does not
    // reset what it has been through: identity, close state, attempt budget
    // and held admissions are the ones it had.
    let client = XServerFrontendClientId(8691);
    let (registration, runner, _durable, _output, _peer) = bound_connection(client);
    let private = runner.frontend.as_ref().expect("a live runner");
    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::Ready
    );

    // Give the first owner a history: a close it began, with an attempt spent.
    let first = {
        registration
            .ordered_home
            .borrow(|payload| {
                let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                    panic!("promoted")
                };
                owner.closing = Some(X11OrderedClosing {
                    cause: X11OrderedCloseCause::ConnectionEnded,
                    termination: X11OrderedTermination::Refused(
                        std::io::ErrorKind::PermissionDenied,
                    ),
                    attempts: 2,
                    answered: 0,
                    already: 0,
                    deferred: 0,
                    drained: false,
                });
                (
                    &**owner as *const X11OrderedServingOwner as usize,
                    owner.closing().expect("staged").termination,
                )
            })
            .expect("its own home")
    };

    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::AlreadyServing,
        "the second ask is refused rather than served"
    );
    registration
        .ordered_home
        .borrow(|payload| {
            let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                panic!("still promoted")
            };
            assert_eq!(
                &**owner as *const X11OrderedServingOwner as usize,
                first.0,
                "THE SAME OWNER, not a new one at the same address by luck"
            );
            let closing = owner.closing().expect("its close");
            assert_eq!(closing.attempts, 2, "its attempt budget did not reset");
            assert_eq!(
                closing.termination, first.1,
                "and neither did its close state"
            );
        })
        .expect("its own home");
    drop(registration);
}

#[test]
fn a_closed_endpoint_starts_nothing() {
    // THE LIVE ENDPOINT DECIDES, not what teardown once recorded. Closing this
    // endpoint through the real interface, while the registration lives,
    // leaves the payload's evidence untouched -- that field is teardown's
    // history. An eligibility check reading it admitted an owner onto an
    // endpoint that was already closed.
    let client = XServerFrontendClientId(8701);
    let (registration, runner, _durable, _output, _peer) = bound_connection(client);
    let private = runner.frontend.as_ref().expect("a live runner");

    assert_eq!(
        registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established,
        "closed through the real interface"
    );
    assert_eq!(
        registration.ordered_handovers_fenced(),
        Some(true),
        "and the gate says so"
    );
    assert_eq!(
        registration
            .ordered_home
            .borrow(|payload| match payload {
                PrivateOrderedContinuation::Setup { evidence, .. }
                | PrivateOrderedContinuation::Serving { evidence, .. } => evidence.fence,
            }),
        Some(None),
        "while the payload's evidence is untouched, because no teardown ran"
    );

    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::Closing
    );
    assert_eq!(
        payload_shape(&registration),
        Some("transport"),
        "its transport is untouched"
    );
    drop(registration);
}

#[test]
fn an_endpoint_whose_gate_cannot_be_read_starts_nothing_either() {
    // CLOSED AND UNREADABLE ARE DIFFERENT REFUSALS. One says this endpoint is
    // done; the other says a holder panicked inside its gate, so what the flag
    // says cannot be trusted. Neither is a reason to start an owner, and
    // reporting one as the other would send a reader to the wrong question.
    let client = XServerFrontendClientId(8731);
    let (registration, runner, _durable, _output, _peer) = bound_connection(client);
    let private = runner.frontend.as_ref().expect("a live runner");

    let gate = registration.ordered_gate.clone();
    let holder = std::thread::spawn(move || {
        let _inside = gate.fenced.lock().expect("an open gate");
        panic!("a holder unwound inside this gate");
    });
    assert!(holder.join().is_err(), "the holder unwound");
    assert_eq!(
        registration.ordered_handovers_fenced(),
        None,
        "the gate is neither open nor closed as far as anything can tell"
    );

    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::EndpointUnreadable
    );
    assert_eq!(
        payload_shape(&registration),
        Some("transport"),
        "and nothing was taken to find that out"
    );
    drop(registration);
}

#[test]
fn a_promoted_connection_torn_down_without_a_worker_retains_what_it_is() {
    // NO WORKER, NO JOIN. A connection that was never served reaches retention
    // by its own quiet path: nothing waits for a join nobody can perform, and
    // no successful join is manufactured to make the account look complete.
    let client = XServerFrontendClientId(8711);
    let (registration, runner, durable, _output, _peer) = bound_connection(client);
    assert_eq!(
        registration.promote_ordered_serving(runner.frontend.as_ref().expect("live")),
        PrivateOrderedPromotion::Ready
    );
    let private = runner;

    drop(registration);
    drop(private);
    let reading = durable.retained_dispositions().expect("a readable store")[0]
        .1
        .expect("a readable record");
    assert_eq!(
        reading.closure,
        Some(PrivateHandoverFence::Established),
        "teardown closed the endpoint and carried that"
    );
    assert_eq!(
        reading.worker,
        PrivateOrderedWorkerExit::NeverStarted,
        "and carried that nothing was ever started, rather than a join"
    );
    assert!(!reading.source_poisoned);
}


#[test]
fn a_home_a_holder_panicked_in_stays_unreadable_rather_than_reading_as_ordinary() {
    // THE POISON USED TO HAVE TO TRAVEL. Teardown read the payload out of
    // storage that had panicked and put it in a record with a lock of its own
    // -- a readable one -- so without carrying the fact, the move laundered
    // it: the reading showed an ordinary row for a connection whose storage
    // had been left mid-something.
    //
    // NOTHING MOVES NOW, so nothing launders it. The home a holder panicked in
    // is the home the place holds, and a reader of that place finds it
    // unreadable rather than ordinary. `source_poisoned` is still written --
    // teardown knows the fact and records it where the payload lives -- but it
    // is no longer what carries it, and this control no longer reads it back:
    // the value is inside the storage whose unreadability it describes.
    let client = XServerFrontendClientId(8721);
    let (registration, runner, durable, _output, _peer) = bound_connection(client);

    // A holder panics inside this connection's payload storage.
    let storage = Arc::clone(&registration.ordered_home);
    let panicked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        storage.borrow(|_| panic!("a holder unwound inside this payload's storage"))
    }));
    assert!(panicked.is_err(), "the holder unwound");
    assert!(storage.unreadable(), "so the storage is poisoned");

    // TEARDOWN STILL RUNS THROUGH IT. Refusing to act on a poisoned home would
    // strand accepted work to make a point, so the connection is still said to
    // have ended and the place is still accounted for.
    drop(registration);
    drop(runner);
    assert!(storage.unreadable(), "and it is still the same poisoned home");
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the place is still taken"
    );
    assert_eq!(
        durable.continuations_retained(),
        None,
        "and what is in it is unknown rather than absent"
    );
    let reading = durable.retained_dispositions().expect("a readable store");
    assert_eq!(reading.len(), 1, "the connection is still in the account");
    assert!(
        reading[0].1.is_none(),
        "reported as a row nothing can be read from, not as an ordinary one"
    );
}

/// What a connection's notice currently says.
fn wake_snapshot(wake: &Arc<PrivateOrderedWake>) -> (bool, usize, bool) {
    let state = wake
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    (state.pending, state.senders, state.gone)
}

#[test]
fn a_waiter_asleep_when_the_last_sender_goes_is_woken_by_it() {
    // THE COUNTEREXAMPLE THIS EXISTS FOR. An owner that finds its queue empty
    // and sleeps cannot notice its senders disappearing: the receive that
    // would tell it is the receive it is not making. Nothing in the channel
    // wakes it, so the disappearance has to be published by whoever causes it.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8751);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let wake = Arc::clone(&channels.ordered.wake);
    assert_eq!(wake_snapshot(&wake), (false, 1, false), "one sender: the row's");

    // A waiter asleep on an empty queue, exactly as an owner would be.
    let waiting = Arc::clone(&wake);
    let (woken, wakes) = sync_channel(1);
    let waiter = std::thread::spawn(move || {
        let mut state = waiting.state.lock().expect("a readable notice");
        while !state.pending && !state.gone {
            state = waiting.ready.wait(state).expect("a readable notice");
        }
        woken.send(state.gone).expect("the control is listening");
    });
    // WHAT THIS OBSERVES: no answer has arrived. It does NOT establish that
    // the waiter reached the condvar, or even that it has been scheduled --
    // an answer that has not arrived looks the same from here whatever the
    // waiter is doing. Arrival needs a handshake this control does not have.
    assert_eq!(
        wakes.recv_timeout(std::time::Duration::from_millis(150)),
        Err(std::sync::mpsc::RecvTimeoutError::Timeout),
        "no answer yet"
    );

    // Its senders go. The row's is the last one.
    drop(registration);
    assert_eq!(
        wakes.recv_timeout(std::time::Duration::from_secs(5)),
        Ok(true),
        "and the disappearance woke it"
    );
    waiter.join().expect("the waiting thread");

    // THE NOTICE IS A HINT, NOT A FINDING. What establishes that the producers
    // are finished is a receive, and this one is the parent's, after the
    // waiter joined -- so it says the channel is finished, not that the waiter
    // saw it finished at the moment it woke.
    assert!(matches!(
        channels.ordered.receiver.try_recv(),
        Err(std::sync::mpsc::TryRecvError::Disconnected)
    ));
}

#[test]
fn the_notice_is_published_only_after_the_last_sender_is_actually_gone() {
    // A DROP BODY RUNS BEFORE ITS FIELDS ARE DESTROYED. Publishing from there
    // and letting the sender field fall away afterwards says "all gone" while
    // this one still exists: a waiter woken then receives, finds the queue
    // merely empty rather than finished, and sleeps again -- and the drop that
    // really ends it signals nobody.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8761);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let wake = Arc::clone(&channels.ordered.wake);

    // A waiter that does what an owner does: on waking, it RECEIVES, and
    // reports what the channel told it.
    let waiting = Arc::clone(&wake);
    let (answered, answers) = sync_channel(1);
    let receiver = channels.ordered.receiver;
    let waiter = std::thread::spawn(move || {
        let mut state = waiting.state.lock().expect("a readable notice");
        while !state.pending && !state.gone {
            state = waiting.ready.wait(state).expect("a readable notice");
        }
        drop(state);
        answered
            .send(matches!(
                receiver.try_recv(),
                Err(std::sync::mpsc::TryRecvError::Disconnected)
            ))
            .expect("the control is listening");
    });

    drop(registration);
    assert_eq!(
        answers.recv_timeout(std::time::Duration::from_secs(5)),
        Ok(true),
        "woken by the notice, it finds the channel FINISHED and not merely empty"
    );
    waiter.join().expect("the waiting thread");

    // WHAT THIS DOES NOT ESTABLISH. If the notice were published first and the
    // sender dropped immediately after, this waiter would still almost always
    // find the channel finished: it has to be woken, reacquire the notice and
    // then receive, and the drop it is racing is the next instruction. The
    // window is real but not observable from here without a rendezvous inside
    // that Drop, which this crate has no way to place.
    //
    // So the order is written the way it is because the reasoning says so --
    // a Drop body runs before its fields are destroyed -- and not because this
    // control could tell the difference.
}

#[test]
fn a_clone_going_is_not_the_senders_going() {
    // A NOTICE PER DISAPPEARANCE, NOT PER DROP. Producers clone a connection's
    // sender constantly; saying the senders are gone each time one of those
    // clones is dropped would wake an owner to find a queue that is perfectly
    // alive, over and over.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8771);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let wake = Arc::clone(&channels.ordered.wake);

    // Producers take copies the way the real ones do.
    let first = capture_gated_sender(&private, client);
    let second = capture_gated_sender(&private, client);
    assert_eq!(wake_snapshot(&wake), (false, 3, false));

    drop(first);
    assert_eq!(
        wake_snapshot(&wake),
        (false, 2, false),
        "one producer finished, and the connection is not"
    );
    drop(second);
    assert_eq!(wake_snapshot(&wake), (false, 1, false));

    // The exact capsule on the queue is untouched by any of that.
    let sender = capture_gated_sender(&private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(87710);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    gated_send(&sender, capsule).expect("an open endpoint");
    drop(sender);
    assert_eq!(wake_snapshot(&wake), (false, 1, false));
    // Taken here, BEFORE the last sender goes. So what this shows is that
    // producers finishing does not disturb queued work -- not that work
    // survives the final disappearance, which is a different moment and is
    // not covered by this control.
    let survived = channels
        .ordered
        .receiver
        .try_recv()
        .expect("still queued, and still exactly itself");
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));

    drop(registration);
    assert!(wake_snapshot(&wake).2, "and only the last one says so");
}

#[test]
fn a_refused_publication_does_not_disturb_the_live_connections_notice() {
    // ISOLATION IS WHAT THIS ESTABLISHES. A publication that refuses drops the
    // senders it had built, and those were its own: this connection's notice
    // is not touched by them going.
    //
    // It does NOT observe the refused attempt's own notice. That notice is
    // minted inside the call that refuses and goes with it, so reading it
    // needs a hold on the mint itself, which this control does not have.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8781);
    let (first, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let wake = Arc::clone(&channels.ordered.wake);

    // A duplicate: publication refuses after its senders were made.
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("the client is already registered");
    assert!(matches!(
        refused,
        XServerFrontendRouteError::DuplicateClient { .. }
    ));

    // ISOLATION: the refused attempt's senders were its own. This connection's
    // notice is untouched by them going.
    assert_eq!(
        wake_snapshot(&wake),
        (false, 1, false),
        "the live connection still has its own sender and is not finished"
    );
    drop(first);
    assert!(wake_snapshot(&wake).2);
}


#[test]
fn a_promoted_owner_keeps_the_notice_its_senders_publish_to() {
    // TAKING THE RECEIVER LEAVES ITS WRAPPER BEHIND, and the notice with it.
    // An owner built that way would hold a queue it could be told about and no
    // way to be told: every disappearance would be published to a notice
    // nothing was holding.
    let client = XServerFrontendClientId(8791);
    let (registration, runner, _durable, _output, _peer) = bound_connection(client);
    let private = runner.frontend.as_ref().expect("a live runner");

    // The notice the senders were counted against, taken from the row.
    let minted = {
        let guard = private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable registry");
        Arc::clone(&guard.get(&client).expect("its row").ordered.wake)
    };

    assert_eq!(
        registration.promote_ordered_serving(private),
        PrivateOrderedPromotion::Ready
    );

    let before = registration
        .ordered_home
        .borrow(|payload| {
            let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                panic!("promoted")
            };
            assert!(
                Arc::ptr_eq(&owner.wake, &minted),
                "THE SAME NOTICE, not a fresh one nothing publishes to"
            );
            // And it is live: a disappearance published by the senders reaches
            // it.
            wake_snapshot(&owner.wake)
        })
        .expect("its own home");
    assert!(!before.2 && before.1 > 0);
    drop(runner);
    drop(registration);
    assert!(
        wake_snapshot(&minted).2,
        "the senders going published to the notice the owner is holding"
    );
}


#[test]
fn a_notice_published_before_a_waiter_arrives_is_still_there_to_find() {
    // A SIGNAL IS NOT RETAINED; A LEVEL IS. This is the case a bare signal
    // loses: the handover happens while the owner is between looking at its
    // queue and entering its wait, so the signal reaches nobody. What the
    // owner finds when it does arrive is the level, and that is why the level
    // is published rather than only signalled.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8801));
    attempt_run(&mut f, 88010, 272, true);
    let wake = Arc::clone(&f.channels.ordered.wake);
    {
        let mut state = wake.state.lock().expect("a readable notice");
        state.pending = false;
    }

    // The handover happens with nobody waiting at all.
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.dispatch_one_press(), Some(true));

    // A waiter arriving afterwards finds it set, and does not wait.
    let state = wake.state.lock().expect("a readable notice");
    assert!(
        state.pending,
        "the notice is still there for a waiter that had not arrived yet"
    );
}

#[test]
fn a_handover_interrupted_after_acceptance_still_publishes_its_notice() {
    // ACCEPTED WORK MUST NOT BE LEFT ASLEEP. A handover can be accepted and
    // then unwind before anything is written down; a notification made only on
    // success would be the one not made in exactly that case.
    //
    // THE UNWIND IS STAGED AT THE GUARD, not inside the producer: this crate
    // has no way to panic mid-producer without a hook, so the control arms the
    // real notice, sends through the real admission, and then unwinds.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8811);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let wake = Arc::clone(&channels.ordered.wake);
    {
        let mut state = wake.state.lock().expect("a readable notice");
        state.pending = false;
    }
    let sender = capture_gated_sender(&private, client);
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(88110);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);

    let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let notify = sender.arm_wake();
        let admitted = sender.admit().expect("an open endpoint");
        admitted.try_send(capsule).expect("accepted");
        let _ = &notify;
        panic!("interrupted between acceptance and the owned report");
    }));
    assert!(unwound.is_err(), "it unwound");

    assert!(
        wake.state.lock().expect("a readable notice").pending,
        "and the notice was published on the way out"
    );
    // The accepted capsule is on the queue, exactly itself, unanswered.
    let arrived = channels
        .ordered
        .receiver
        .try_recv()
        .expect("accepted before the unwind");
    assert!(Arc::ptr_eq(
        &cell,
        &arrived.finalizer().expect("carried").completion
    ));
    assert!(cell.answer().is_none());
    drop(registration);
}

#[test]
fn a_refused_handover_publishes_a_recheck_and_keeps_its_capsule() {
    // A REFUSAL IS STILL A REASON TO LOOK, and costs a waiter one look at its
    // own queue. What it is not is evidence: nothing was accepted here, and
    // the capsule is where it was.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(8821));
    attempt_run(&mut f, 88210, 272, true);
    let cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 88210);
    let wake = Arc::clone(&f.channels.ordered.wake);
    assert_eq!(
        f.registration.fence_ordered_handovers(),
        PrivateHandoverFence::Established
    );
    {
        let mut state = wake.state.lock().expect("a readable notice");
        state.pending = false;
    }

    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(
        private.dispatch_one_press(),
        Some(false),
        "the endpoint is closed, so nothing is handed over"
    );
    assert!(
        wake.state.lock().expect("a readable notice").pending,
        "and the notice is published anyway: a recheck request, not evidence"
    );
    assert_eq!(
        handover_phase(private, &cell),
        Some(PrivateDispatchPhase::Pending),
        "with the capsule still offerable"
    );
    assert!(cell.answer().is_none());
    assert!(f.channels.ordered.try_recv().is_err(), "and nothing queued");
}

#[test]
fn publishing_a_notice_needs_nothing_that_a_handover_holds() {
    // THE NOTICE TAKES ITS OWN LOCK AND NO OTHER. If publishing reached for
    // the gate, the payload, the output, common or the client table, it would
    // be doing so on a path where somebody already holds one of them -- and
    // the one it would most obviously reach for is the gate it was armed
    // beside.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8831);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let sender = capture_gated_sender(&private, client);
    let wake = Arc::clone(&channels.ordered.wake);
    {
        let mut state = wake.state.lock().expect("a readable notice");
        state.pending = false;
    }

    // The gate is held by something else entirely, and the client table too.
    let entered = registration
        .ordered_gate
        .entered()
        .unwrap_or_else(|_| panic!("an open endpoint"));
    let clients = private
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry");

    // Publishing completes regardless.
    drop(sender.arm_wake());
    assert!(
        wake.state.lock().expect("a readable notice").pending,
        "published while the gate and the client table are both held elsewhere"
    );
    drop(clients);
    drop(entered);
    drop(registration);
}


/// An attention roll with room for two connections, and both admitted.
fn attention_for_two() -> (
    Arc<PrivateAttention>,
    PrivateAttentionIdentity,
    PrivateAttentionIdentity,
    std::time::Instant,
) {
    let now = std::time::Instant::now();
    let roll = Arc::new(
        PrivateAttention::with_connections(NonZeroUsize::new(2).unwrap(), now)
            .expect("room for two connections"),
    );
    let first = roll.admit(0).expect("a slot");
    let second = roll.admit(1).expect("a slot");
    (roll, first, second, now)
}

#[test]
fn a_release_during_a_failed_attempt_is_not_parked_away() {
    // THE ERASURE THIS EXISTS TO PREVENT. A pass takes a slot, fails to take
    // the record, and parks it -- while the holder released the record during
    // that very attempt. Parking it then buries the one event that says it is
    // worth trying again, and only a timer would ever find it.
    //
    // The interest is armed by the claim itself, before the attempt: the slot
    // is in flight from that moment, so the release lands on something that
    // remembers it.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    assert_eq!(roll.waiting(), Some(1));

    let claim = roll.claim_next().expect("a slot waiting");
    assert_eq!(claim.who(), first);
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::InFlight { dirty: false })
    );

    // The holder releases while the attempt is in flight.
    assert!(roll.released(first));
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::InFlight { dirty: true })
    );

    // And the attempt then fails.
    assert!(claim.could_not());
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::Ready),
        "the release survived the parking that followed it"
    );
    assert_eq!(roll.waiting(), Some(1));
}

#[test]
fn a_notice_arriving_during_a_successful_pass_outlives_its_conclusion() {
    // The same rule on the other outcome: a pass that succeeded concluded
    // about what it saw, and something arrived after it looked.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    let claim = roll.claim_next().expect("a slot waiting");
    assert!(roll.flag(first));
    assert!(claim.took_it());
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::Ready),
        "done with what it saw, and there is something newer"
    );
}

#[test]
fn a_failed_attempt_with_nothing_new_parks_rather_than_spins() {
    // WHAT STOPS THE SPIN. A slot that could not be taken is not counted as
    // waiting, so a supervisor's predicate goes false and it has something to
    // sleep on. A pass that re-marked it ready would take it again at once,
    // for ever.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    let claim = roll.claim_next().expect("a slot waiting");
    assert!(claim.could_not());
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Deferred));
    assert_eq!(roll.waiting(), Some(0), "nothing is waiting to be looked at");
    assert!(
        roll.claim_next().is_none(),
        "and a pass finds nothing to take"
    );
}

#[test]
fn a_pass_that_is_abandoned_parks_its_slot_rather_than_finishing_it() {
    // A claim dropped without an outcome reported nothing. Treating that as
    // done would record a connection as looked at by a pass that did not
    // finish; it is parked instead, and anything that arrived still revives it.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    drop(roll.claim_next().expect("a slot waiting"));
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Deferred));
}

#[test]
fn a_stale_pass_cannot_conclude_about_the_slot_it_no_longer_holds() {
    // A slot can be retired and given to someone else while a pass is in
    // flight. A conclusion written then would be written about a connection
    // that pass never saw.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    let stale = roll.claim_next().expect("a slot waiting");

    // Its occupant goes, and the slot is given to another.
    assert!(roll.retire(first, false));
    let successor = roll.admit(0).expect("the slot again");
    assert_ne!(successor.generation, first.generation);
    assert!(roll.flag(successor));

    // The successor has a pass of its own in flight, which is the state a
    // stale conclusion could actually damage: anything else is refused by the
    // state check before the identity is even consulted.
    let current = roll.claim_next().expect("the successor's own pass");
    assert_eq!(current.who(), successor);
    assert!(roll.flag(successor));
    assert_eq!(
        roll.state_of(successor),
        Some(PrivateAttentionState::InFlight { dirty: true })
    );

    assert!(
        !stale.took_it(),
        "the stale pass is refused rather than applied"
    );
    assert_eq!(
        roll.state_of(successor),
        Some(PrivateAttentionState::InFlight { dirty: true }),
        "and the successor's own pass is exactly where it was"
    );

    // Which its own conclusion then finishes, still carrying what arrived.
    assert!(current.took_it());
    assert_eq!(roll.state_of(successor), Some(PrivateAttentionState::Ready));
    assert_eq!(roll.waiting(), Some(1));
}

#[test]
fn a_slot_whose_generations_are_spent_is_retired_rather_than_wrapped() {
    // A WRAPPED GENERATION IS A STALE NOTICE THAT PASSES THE CHECK. One
    // connection's worth of capacity is a smaller cost than an identity that
    // lies about who it is.
    let now = std::time::Instant::now();
    let roll = Arc::new(
        PrivateAttention::with_connections(NonZeroUsize::new(1).unwrap(), now)
            .expect("room for one"),
    );
    {
        let mut held = roll.roll.lock().expect("readable");
        held.slots[0].next_generation = Some(u32::MAX);
    }
    let last = roll.admit(0).expect("the last generation");
    assert_eq!(last.generation, u32::MAX);

    // ASKED AT THE HANDING-OUT, not only at the giving-up: a slot sitting at
    // the last generation refuses to name another occupant at all, so nothing
    // depends on a retirement having happened first.
    assert!(
        roll.admit(0).is_none(),
        "there is no next name for this slot"
    );

    assert!(roll.retire(last, false));
    assert!(
        roll.admit(0).is_none(),
        "and giving it up does not make one either"
    );
}

#[test]
fn the_sweep_deadline_is_not_pushed_back_by_other_traffic() {
    // A DEADLINE RECOMPUTED ON EVERY WAKE IS NEVER REACHED under load, and
    // load is exactly when work nobody revived has been waiting longest.
    let (roll, first, second, now) = attention_for_two();
    assert!(roll.flag(first));
    let claim = roll.claim_next().expect("a slot waiting");
    assert!(claim.could_not());
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Deferred));

    // Unrelated traffic, repeatedly, at ADVANCING times -- all before the
    // deadline. Asking with one frozen instant would pass equally against a
    // deadline that was being pushed back on every ask, which is the thing
    // this is about.
    for step in 1..=6 {
        assert!(roll.flag(second));
        let other = roll.claim_next().expect("the other slot");
        assert!(other.took_it());
        let later = now + std::time::Duration::from_millis(40 * step);
        assert!(
            !roll.sweep_due(later),
            "not due yet at {}ms, and not rescheduled by any of this",
            40 * step
        );
    }
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::Deferred),
        "still parked, because nothing revived it"
    );

    // The deadline arrives on its own schedule, unmoved by any of that.
    assert!(roll.sweep_due(now + std::time::Duration::from_millis(250)));
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Ready));
    assert_eq!(roll.waiting(), Some(1));
}


#[test]
fn a_second_admission_does_not_move_into_a_live_connections_place() {
    // OCCUPANCY IS NOT A STATE. A slot with nothing to do and a slot with
    // nobody in it look identical from the state alone, and treating them as
    // one let a second admission walk into a live connection's place -- taking
    // its name, its readiness and everything it had been told, while the
    // connection it took them from was still there.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Ready));
    assert_eq!(roll.waiting(), Some(1));

    assert!(
        roll.admit(0).is_none(),
        "somebody lives here, so there is nothing to hand out"
    );
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::Ready),
        "and the occupant keeps its name and its notice"
    );
    assert_eq!(roll.waiting(), Some(1), "and its readiness");

    // The same while a pass is in flight, which is the worse case: a pass with
    // a claim outstanding for an occupant that was replaced under it.
    let claim = roll.claim_next().expect("a slot waiting");
    assert!(roll.admit(0).is_none());
    assert_eq!(claim.who(), first);
    assert!(claim.took_it());
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Idle));
}

#[test]
fn a_retired_occupants_notices_stop_counting_immediately() {
    // GONE AT ONCE, not when a successor arrives. Leaving the name valid in
    // between let a late notice make an empty slot ready, and a pass then took
    // it -- work invented for a connection that had already left, before
    // anybody had moved in.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.retire(first, false));
    assert_eq!(
        roll.state_of(first),
        None,
        "its name means nothing the moment it goes"
    );

    // The interval with nobody in the slot at all.
    assert!(
        !roll.released(first),
        "a release for somebody who has gone is refused"
    );
    assert!(!roll.flag(first), "and so is a notice");
    assert_eq!(roll.waiting(), Some(0));
    assert!(
        roll.claim_next().is_none(),
        "so no pass is manufactured for an empty slot"
    );

    // Retiring again says nothing happened, because nothing did.
    assert!(!roll.retire(first, false), "there is nobody to retire");

    // And a successor is a different connection, not a continuation.
    let successor = roll.admit(0).expect("the slot is free now");
    assert_ne!(successor.generation, first.generation);
    assert!(!roll.flag(first), "the old name still means nothing");
    assert_eq!(roll.waiting(), Some(0));
    assert!(roll.flag(successor));
    assert_eq!(roll.waiting(), Some(1));
}

#[test]
fn a_pass_outstanding_when_its_occupant_goes_concludes_about_nobody() {
    // A claim held across a retirement is a pass for a connection that has
    // left. Whatever it reports -- and whether it reports at all, or is simply
    // dropped -- it must not touch the slot it no longer holds.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.flag(first));
    let outstanding = roll.claim_next().expect("a slot waiting");
    assert!(roll.retire(first, false));

    // Dropped without an outcome: the abandoned-pass path, over a slot with
    // nobody in it.
    drop(outstanding);
    assert_eq!(roll.state_of(first), None);
    assert_eq!(roll.waiting(), Some(0));
    assert!(
        roll.claim_next().is_none(),
        "nothing was parked, because there was nobody to park"
    );

    // And the same for a pass that does report.
    let successor = roll.admit(0).expect("the slot is free");
    assert!(roll.flag(successor));
    let reporting = roll.claim_next().expect("the successor's pass");
    assert!(roll.retire(successor, false));
    assert!(!reporting.could_not(), "refused, not applied");
    assert_eq!(roll.waiting(), Some(0));
}


#[test]
fn no_pass_is_made_for_a_slot_with_nobody_in_it() {
    // DEFENCE IN DEPTH, AND STAGED AS SUCH. Retirement clears the state as
    // well as the occupant, so a slot that is waiting with nobody in it is not
    // reachable through the ordinary operations -- this control sets that
    // state directly to check the guard that would catch it if some later path
    // did produce it. Manufacturing a pass for an empty slot hands a
    // supervisor a connection that is not there.
    let (roll, first, _second, _now) = attention_for_two();
    assert!(roll.retire(first, false));
    {
        let mut held = roll.roll.lock().expect("readable");
        held.slots[0].state = PrivateAttentionState::Ready;
        held.ready = 1;
    }
    assert_eq!(roll.waiting(), Some(1), "the roll believes one is waiting");
    assert!(
        roll.claim_next().is_none(),
        "and no pass is made for it, because nobody lives there"
    );
}


/// The pieces a startup transaction needs, with nothing started.
fn startup_fixture() -> (
    Mutex<PrivateWorkerSlot>,
    Arc<AtomicBool>,
    Arc<PrivateOrderedWake>,
) {
    (
        Mutex::new(PrivateWorkerSlot::empty()),
        Arc::new(AtomicBool::new(false)),
        Arc::new(PrivateOrderedWake::for_first_sender()),
    )
}

/// A worker body that waits for a permit or a stop and reports which it saw.
fn permit_waiter(
    stop: Arc<AtomicBool>,
    wake: Arc<PrivateOrderedWake>,
    saw: std::sync::mpsc::SyncSender<&'static str>,
) -> impl FnOnce() + Send + 'static {
    move || {
        // A POISONED NOTICE IS RECOVERED HERE, NOT UNWRAPPED. A worker that
        // panicked on one would take a cancellation it was meant to observe
        // and turn it into a second failure. What a real worker does with a
        // poisoned notice -- leave and report it -- is policy that belongs
        // with the worker, which is not landed; this fixture only has to stay
        // alive long enough to see its stop.
        let mut state = wake
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        while !state.started && !stop.load(std::sync::atomic::Ordering::Acquire) {
            state = wake
                .ready
                .wait(state)
                .unwrap_or_else(|poisoned| poisoned.into_inner());
        }
        // STOP IS ASKED FIRST AND WINS. A permit says a transaction finished,
        // never that a worker should still be running.
        let outcome = if stop.load(std::sync::atomic::Ordering::Acquire) {
            "stopped"
        } else {
            "permitted"
        };
        drop(state);
        saw.send(outcome).expect("the control is listening");
    }
}

#[test]
fn a_started_worker_is_owned_before_it_is_permitted() {
    // THE PERMIT IS LAST. A worker scheduled the instant it exists cannot
    // serve before its handle is owned, because what it waits for is published
    // after the handle is stored.
    //
    // THAT ORDER IS NOT OBSERVED HERE, and cannot be from outside: the
    // transaction holds the destination throughout, so nothing else can look
    // at the slot while it runs, and by the time a permitted worker reports,
    // the store has happened either way. It rests on the two being adjacent in
    // one function with nothing between them. What this control does observe
    // is the rest: that the notice is free while the thread is made, that the
    // handle is owned afterwards, and that the worker was permitted rather
    // than stopped.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);

    // OBSERVED FROM INSIDE THE SPAWN: the destination is held and the notice
    // is not, so stopping and waking this connection do not queue behind
    // somebody else's thread creation.
    let notice_free = Arc::new(AtomicBool::new(false));
    let seen_free = Arc::clone(&notice_free);
    let spawning = Arc::clone(&wake);
    let outcome = start_connection_worker(&slot, &stop, &wake, move || {
        seen_free.store(spawning.state.try_lock().is_ok(), std::sync::atomic::Ordering::Release);
        std::thread::Builder::new().spawn(body)
    });
    assert_eq!(outcome, PrivateStartupOutcome::Started);
    assert!(
        notice_free.load(std::sync::atomic::Ordering::Acquire),
        "the notice was free while the thread was being made"
    );

    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );
    let handle = slot
        .lock()
        .expect("readable")
        .handle
        .take()
        .expect("its handle is owned here");
    handle.join().expect("the worker");
    assert!(!stop.load(std::sync::atomic::Ordering::Acquire));
}

#[test]
fn a_refused_spawn_leaves_nothing_to_stop_or_join() {
    // Nothing exists, so there is nothing to cancel and nothing to join. The
    // slot is as empty as it was found, and the connection's stop is untouched.
    let (slot, stop, wake) = startup_fixture();
    let outcome = start_connection_worker(&slot, &stop, &wake, || {
        Err(std::io::Error::other("no thread for you"))
    });
    assert_eq!(outcome, PrivateStartupOutcome::SpawnRefused);
    assert!(!slot.lock().expect("readable").running());
    assert!(
        !stop.load(std::sync::atomic::Ordering::Acquire),
        "nothing was running, so nothing was stopped"
    );
    assert!(
        !wake.state.lock().expect("readable").started,
        "and nothing was permitted"
    );
}

#[test]
fn a_transaction_that_fails_after_the_spawn_cancels_rather_than_forgets() {
    // AFTER A SPAWN THERE IS NO GOING BACK TO "NO WORKER". A thread may be
    // running; saying otherwise loses it, and dropping its handle detaches a
    // thread nobody can join.
    //
    // THE UNWIND IS STAGED AT THE GUARD, and the control says so: the
    // transaction has nothing fallible between its store and its commit, so
    // there is no way to make the real one fail there. What is exercised is
    // the guard those paths share.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    let handle = std::thread::Builder::new()
        .spawn(body)
        .expect("a thread for this control");
    {
        let mut held = slot.lock().expect("readable");
        held.handle = Some(handle);
        let _guard = PrivateStartupGuard {
            slot: &mut held,
            stop: &stop,
            wake: &wake,
            committed: false,
        };
        // and it goes out of scope without committing.
    }

    assert!(
        stop.load(std::sync::atomic::Ordering::Acquire),
        "the connection's own stop is set -- the one its serving consults"
    );
    assert!(
        !wake.state.lock().expect("readable").started,
        "and no permit was ever published"
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("stopped"),
        "so the worker leaves rather than waiting for a permission nobody will give"
    );
    let handle = slot
        .lock()
        .expect("readable")
        .handle
        .take()
        .expect("THE HANDLE IS STILL HERE, not detached");
    handle.join().expect("the worker");
}

#[test]
fn a_second_start_is_refused_from_the_handle_that_is_already_owned() {
    // Asked of the handle itself rather than a flag beside it: a flag can be
    // stale in exactly the window that matters, and would then say no worker
    // exists while one does.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );

    let mut spawned_again = false;
    let outcome = start_connection_worker(&slot, &stop, &wake, || {
        spawned_again = true;
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(outcome, PrivateStartupOutcome::AlreadyStarted);
    assert!(!spawned_again, "nothing was even attempted");

    let handle = slot
        .lock()
        .expect("readable")
        .handle
        .take()
        .expect("the first worker's handle, untouched");
    handle.join().expect("the worker");
}

#[test]
fn a_stop_after_a_permit_still_takes_the_worker_out() {
    // A PERMIT IS NOT A RIGHT TO CONTINUE. It says a transaction finished; the
    // connection's stop says whether it should still be running, and it is
    // asked every time the worker wakes rather than once at the start.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let waiting_stop = Arc::clone(&stop);
    let waiting_wake = Arc::clone(&wake);
    // A body that is permitted, then waits again -- the shape a serving loop
    // has, without any serving in it.
    let body = move || {
        {
            let mut state = waiting_wake.state.lock().expect("a readable notice");
            while !state.started {
                state = waiting_wake.ready.wait(state).expect("a readable notice");
            }
        }
        saw.send("permitted").expect("listening");
        let mut state = waiting_wake.state.lock().expect("a readable notice");
        while !waiting_stop.load(std::sync::atomic::Ordering::Acquire) {
            state = waiting_wake.ready.wait(state).expect("a readable notice");
        }
        saw.send("stopped").expect("listening");
    };
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );

    // Through the real cancellation: the connection's own stop, and a wake so
    // it looks. A cancellation that only cleared the permit would leave this
    // worker exactly where it is.
    cancel_connection_worker(&stop, &wake);
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("stopped"),
        "the permit did not keep it running"
    );
    let handle = slot.lock().expect("readable").handle.take().expect("owned");
    handle.join().expect("the worker");
}


#[test]
fn a_worker_that_cannot_be_permitted_is_cancelled_rather_than_declared_started() {
    // A PERMIT TAKEN FROM A POISONED NOTICE IS NOT A PERMIT. Recovering that
    // guard and writing into it grants a worker permission on the strength of
    // a lock whose contents nobody stands behind -- and reports Started, with
    // the connection's stop never set, over a thread that is actually running.
    //
    // The poisoning is real and happens inside the spawner, which then returns
    // a real worker: exactly the window between the store and the commit that
    // I had claimed nothing could refuse in.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    let poisoning = Arc::clone(&wake);
    let outcome = start_connection_worker(&slot, &stop, &wake, move || {
        let holder = std::thread::spawn(move || {
            let _inside = poisoning.state.lock().expect("a readable notice");
            panic!("a holder unwound inside this notice");
        });
        assert!(holder.join().is_err(), "the holder unwound");
        std::thread::Builder::new().spawn(body)
    });

    assert_eq!(
        outcome,
        PrivateStartupOutcome::PermitRefused,
        "its own answer: a worker exists and could not be permitted"
    );
    assert!(
        stop.load(std::sync::atomic::Ordering::Acquire),
        "the connection's own stop is set"
    );
    let state = wake
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    assert!(!state.started, "and nothing was permitted");
    drop(state);
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("stopped"),
        "so the worker leaves"
    );
    let handle = slot
        .lock()
        .expect("readable")
        .handle
        .take()
        .expect("and its handle is here to be joined");
    handle.join().expect("the worker");
}

#[test]
fn a_worker_handed_on_to_be_joined_does_not_leave_its_slot_free() {
    // AN EMPTY SLOT IS NOT AN UNUSED ONE. Handing a handle to whoever joins it
    // empties the slot while the thread is still running, and a slot that read
    // that as "nobody was ever started" would start a second worker for a
    // connection whose first is alive.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(2);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );

    // The handle goes to a joiner, and nothing is joined yet.
    let handed = hand_worker_to_joiner(&slot);
    assert!(!handed.source_poisoned);
    let handed = handed.handle.expect("its handle");
    assert!(
        !slot.lock().expect("readable").running(),
        "the slot holds no handle now"
    );
    assert!(
        wake.state.lock().expect("readable").started,
        "AND THE GRANT IS UNTOUCHED. Moving a handle is not a decision about \
         whether the worker should still be running"
    );

    let mut spawned_again = false;
    let outcome = start_connection_worker(&slot, &stop, &wake, || {
        spawned_again = true;
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(
        outcome,
        PrivateStartupOutcome::NoLongerStartable,
        "the slot remembers that it had one"
    );
    assert!(!spawned_again, "and nothing was attempted");

    // Both threads are accounted for before anything is concluded, and
    // stopping is its own deliberate act rather than a side effect of the
    // handoff.
    cancel_connection_worker(&stop, &wake);
    handed.join().expect("the first worker");
}

#[test]
fn a_worker_not_yet_at_its_first_look_is_not_stranded_by_the_handoff() {
    // THE GRANT SURVIVES THE MOVE. A worker held before it has reached its
    // first look has not seen its permit yet; a handoff that revoked the
    // permit left it waiting for a permission taken back, with nothing telling
    // it otherwise and its handle already somewhere else.
    //
    // A real predicate-lock handshake holds the worker there: the control owns
    // the notice until it chooses to let go, so this does not depend on
    // timing.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);

    // Held here, so the worker cannot reach its predicate.
    let held_notice = wake.state.lock().expect("a readable notice");
    let started = std::thread::Builder::new()
        .spawn(body)
        .expect("a thread for this control");
    {
        let mut slotted = slot.lock().expect("readable");
        slotted.handle = Some(started);
        slotted.life = PrivateWorkerLife::Running;
    }
    // Permit it, and KEEP HOLDING THE NOTICE. Releasing here would let the
    // worker reach its predicate before the handoff, which is exactly the
    // ordering this control is about -- and a release followed by a handoff
    // establishes nothing about a worker that has not looked, because it may
    // well have.
    let mut state = held_notice;
    state.started = true;

    // The handle goes while the notice is still held, so the worker provably
    // has not observed anything. Handing on does not take this notice, which
    // is why holding it across the call is possible at all.
    let handed = hand_worker_to_joiner(&slot).handle.expect("its handle");

    // Only now may it look. It is not stranded: the grant it was given is
    // still there.
    drop(state);
    wake.ready.notify_all();
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted"),
        "the worker got the permission it was granted"
    );
    handed.join().expect("the first worker");
    assert!(
        !stop.load(std::sync::atomic::Ordering::Acquire),
        "and nothing stopped it, because nothing asked it to"
    );
}

#[test]
fn a_poisoned_slot_still_hands_over_the_worker_it_owns() {
    // ACCEPTED CUSTODY IS NOT ABSENCE. A slot somebody panicked inside still
    // owns whatever it owns, and answering "nothing here" would leave a
    // running thread with no route to a join at all -- while reporting that
    // there was nothing to join.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );

    // A holder panics inside the slot.
    let holder = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _inside = slot.lock().expect("readable");
        panic!("a holder unwound inside this slot");
    }));
    assert!(holder.is_err(), "the holder unwound");
    assert!(slot.lock().is_err(), "so the slot is poisoned");

    let handed = hand_worker_to_joiner(&slot);
    assert!(
        handed.source_poisoned,
        "and that is reported, beside the handle rather than instead of it"
    );
    let handle = handed
        .handle
        .expect("THE WORKER IS STILL HANDED OVER, because it is still owned");
    cancel_connection_worker(&stop, &wake);
    handle.join().expect("the worker");
}


#[test]
fn a_release_is_news_only_where_somebody_is_waiting_on_it() {
    // EVERY STATE, because the narrowing is about which of them a release
    // means anything in. Announcing into a slot an actor's own pass just
    // finished with would make it ready, be claimed again, find nothing again,
    // and announce again -- a loop with no progress in it.
    let (roll, first, second, _now) = attention_for_two();

    // Idle: an actor's own concluded pass leaves this. Nothing to tell.
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Idle));
    assert!(roll.released(first), "the identity is live");
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::Idle),
        "and stays idle: no new readiness from a release nobody awaited"
    );
    assert_eq!(roll.waiting(), Some(0));

    // Ready: already has a reason to be looked at, and does not need two.
    assert!(roll.flag(first));
    assert_eq!(roll.waiting(), Some(1));
    assert!(roll.released(first));
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Ready));
    assert_eq!(roll.waiting(), Some(1), "counted once, not twice");

    // InFlight: a pass is running and may be failing to take the record, so a
    // release is exactly what it needs to know.
    let claim = roll.claim_next().expect("a slot waiting");
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::InFlight { dirty: false })
    );
    assert!(roll.released(first));
    assert_eq!(
        roll.state_of(first),
        Some(PrivateAttentionState::InFlight { dirty: true })
    );
    assert!(claim.could_not());
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Ready));

    // Deferred: a pass gave up, and the release is what revives it.
    let parked = roll.claim_next().expect("a slot waiting");
    assert!(parked.could_not());
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Deferred));
    assert_eq!(roll.waiting(), Some(0));
    assert!(roll.released(first));
    assert_eq!(roll.state_of(first), Some(PrivateAttentionState::Ready));
    assert_eq!(roll.waiting(), Some(1));

    // A stale identity is refused outright, whatever the slot is doing now.
    let claim = roll.claim_next().expect("a slot waiting");
    assert!(claim.could_not());
    assert!(roll.retire(first, false));
    let successor = roll.admit(0).expect("the slot is free");
    assert!(roll.flag(successor));
    let current = roll.claim_next().expect("the successor's pass");
    assert!(
        !roll.released(first),
        "a release for somebody who has gone is not a release"
    );
    assert_eq!(
        roll.state_of(successor),
        Some(PrivateAttentionState::InFlight { dirty: false }),
        "and the occupant's own pass is untouched by it"
    );
    assert!(current.took_it());
    let _ = second;
}


#[test]
fn a_departure_stops_a_connection_without_waiting_for_a_spawn_in_flight() {
    // THE SLOT IS HELD ACROSS A SPAWN. Creating a thread is somebody else's
    // latency, and a departure that took that lock before telling the
    // connection anything would wait behind it -- stopping a connection
    // queueing behind starting one.
    //
    // The spawner here is held by the control, so the lock is provably held
    // while the departure runs: this does not depend on timing.
    let (slot, stop, wake) = startup_fixture();
    let slot = Arc::new(slot);
    let (inside, entered) = sync_channel(1);
    let (go, wait_here) = sync_channel(1);
    let starting = Arc::clone(&slot);
    let start_stop = Arc::clone(&stop);
    let start_wake = Arc::clone(&wake);
    let starter = std::thread::spawn(move || {
        start_connection_worker(&starting, &start_stop, &start_wake, || {
            inside.send(()).expect("the control is listening");
            wait_here.recv().expect("the control lets go");
            std::thread::Builder::new().spawn(|| {})
        })
    });
    entered.recv().expect("the spawn is in flight, holding the slot");
    assert!(
        slot.try_lock().is_err(),
        "and the slot really is held while it is"
    );

    // The departure runs now, with that lock held by the spawn.
    let departing_slot = Arc::clone(&slot);
    let departing_stop = Arc::clone(&stop);
    let departing_wake = Arc::clone(&wake);
    let departure = std::thread::spawn(move || {
        depart_connection(&departing_slot, &departing_stop, &departing_wake)
    });

    // THE STOP ARRIVES WHILE THE SPAWN IS STILL PAUSED. Nothing has released
    // the slot, and the control has not let the spawner go.
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
    while !stop.load(std::sync::atomic::Ordering::Acquire) {
        assert!(
            std::time::Instant::now() < deadline,
            "the stop must not wait for the spawn"
        );
        std::thread::yield_now();
    }
    assert!(
        slot.try_lock().is_err(),
        "and it arrived with the spawn still holding the slot"
    );

    // Only now does the spawn finish, and the departure's decision follows it.
    go.send(()).expect("the spawner is waiting");
    let started = starter.join().expect("the starting thread");
    assert_eq!(started, PrivateStartupOutcome::Started);
    assert_eq!(
        departure.join().expect("the departing thread"),
        PrivateDeparture::WorkerRunning,
        "and it found the worker that had just been started"
    );

    let handle = slot
        .lock()
        .expect("readable")
        .handle
        .take()
        .expect("its handle");
    handle.join().expect("the worker");
}

#[test]
fn a_departure_says_which_of_the_three_histories_it_found() {
    // AN EMPTY SLOT CAN BE ANY OF THREE THINGS, and they need different things
    // done for them: nothing to join, a handle to take, or a handle already
    // taken. A departure that collapsed them into one state would leave
    // whoever acts next guessing.
    let (slot, stop, wake) = startup_fixture();
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::NothingStarted
    );
    assert!(stop.load(std::sync::atomic::Ordering::Acquire));
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::AlreadyDeparting,
        "the first departure stands"
    );

    // A connection whose worker is here.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::WorkerRunning
    );
    let handed = hand_worker_to_joiner(&slot).handle.expect("its handle");

    // A repeated departure says what it is: the first one stands. It does not
    // re-read the history, which is why the third case below is a connection
    // of its own rather than this one with a field put back.
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::AlreadyDeparting
    );
    handed.join().expect("the worker");

    // The third history, through a fresh connection: started, handed on, and
    // only then departed for the first time.
    let (slot, stop, wake) = startup_fixture();
    let (saw, seen) = sync_channel(1);
    let body = permit_waiter(Arc::clone(&stop), Arc::clone(&wake), saw);
    assert_eq!(
        start_connection_worker(&slot, &stop, &wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        seen.recv_timeout(std::time::Duration::from_secs(5)),
        Ok("permitted")
    );
    let handed = hand_worker_to_joiner(&slot).handle.expect("its handle");
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::WorkerHandedOn,
        "its handle is with a joiner, and the departure says so"
    );
    handed.join().expect("the worker");

    // WHAT THESE ARE: facts about a handle and a history. Neither says the
    // thread is executing now, and neither says it has been joined.
}

#[test]
fn a_departing_connection_starts_nothing_whatever_its_history() {
    // The serialized transition is the slot's own lock: a start takes it and
    // refuses a departing slot, a departure takes it and marks one. Neither
    // can interleave with the other, and this is the refusal.
    let (slot, stop, wake) = startup_fixture();
    assert_eq!(
        depart_connection(&slot, &stop, &wake),
        PrivateDeparture::NothingStarted
    );
    let mut spawned = false;
    let outcome = start_connection_worker(&slot, &stop, &wake, || {
        spawned = true;
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(
        outcome,
        PrivateStartupOutcome::NoLongerStartable,
        "departing, however little ever happened here"
    );
    assert!(!spawned, "and nothing was attempted");
}

#[test]
fn a_full_recipient_does_not_consume_a_live_recipients_turn() {
    let mut f=prepared_ordered_fixture(XServerFrontendClientId(7601));
    // Four ORIGINAL events fill A: each pair is actually reserved, executed,
    // observed at the common boundary, built and enqueued by production code.
    // Each release's actual sealed native proof is recorded once. No receipt
    // or settlement is invented, and the A receiver stays live and undrained.
    for (id,button) in [(76010,272),(76012,273)] {
        attempt_release(&mut f,id,button);
        let p=f.runner.frontend.as_mut().unwrap();
        assert!(p.terminal.settling.last().unwrap().native().unwrap().proof().is_some());
        assert_eq!(p.dispatch_one_press(),Some(true));
        assert_eq!(p.record_one_native(),Some(true));
        assert_eq!(p.attempt_one_delivery(),Some(true));
    }
    attempt_run(&mut f,76014,274,true);
    let (original,frames,order)={
        let p=f.runner.frontend.as_mut().unwrap();
        assert_eq!(p.broker.registry.per_client_input_capacity.get(),4);
        assert_eq!(p.terminal.holds.len(),1);
        assert_eq!(p.terminal.settling.len(),2);
        assert!(p.terminal.settling.iter().all(|r|r.native_recorded() && r.dispatch()==PrivateDispatchPhase::Enqueued && r.attempt().is_some()));
        let recovery=p.broker.registry.input_recovery.clone();
        let record=&mut p.terminal.holds[0];
        let original=record.custody.completion.as_ref().unwrap().clone();
        let emission=record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody,emission,&recovery,f.client);
        let Some(PrivatePendingDelivery::Capsule(capsule))=record.custody.pending.take() else{panic!("the actual fifth event built a capsule")};
        let frames=order_pass_frames(&capsule);
        let sender=p.broker.registry.clients.lock().unwrap().get(&f.client).unwrap().ordered.clone();
        // Classify the actual send refusal. Return the exact original capsule
        // to custody; this is neither synthetic filler nor a fake Full result.
        let capsule=match gated_send(&sender,capsule) {
            Err(std::sync::mpsc::TrySendError::Full(c))=>c,
            Err(std::sync::mpsc::TrySendError::Disconnected(_))=>panic!("A receiver remains live"),
            Ok(())=>panic!("four original capsules must fill A's four slots"),
        };
        assert!(Arc::ptr_eq(&original,&capsule.finalizer().unwrap().completion));
        record.custody.pending=Some(PrivatePendingDelivery::Capsule(capsule));
        assert_eq!(record.custody.dispatch,PrivateDispatchPhase::Pending);
        (original,frames,record.custody.order)
    };

    // B is a genuine second recipient in the same namespace, admitted with
    // its own selection/connection. Real A-ungrab/B-grab changes subsequent
    // source resolution; no foreign custody or fabricated native hold is used.
    let other=XServerFrontendClientId(7602);
    let other_window=XResourceId::new(0x307602,1);
    let (other_registration,other_channels)={
        let p=f.runner.frontend.as_mut().unwrap();let registry=&p.broker.registry;
        let context=namespaced(other,f.namespace);
        let (registration,channels)=registry.register_client_with_admission(other,Some(context)).unwrap();
        registry.attach_private_lifecycle(&registration,context).unwrap();
        let selected=Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry.attach_connection_state(&registration,f.namespace,selected.clone(),Arc::new(AtomicU64::new(0))).unwrap();
        {
            let mut s=selected.lock().unwrap();
            s.register(other_window,XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT),1),Rect{x:0,y:0,width:200,height:100});
            s.observe_mapped(other_window);s.update(other_window,Some((1<<2)|(1<<3)),None);
        }
        let mut grabs=registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace,f.client.raw());
        grabs.grab_pointer(f.namespace,crate::XActiveInputGrab{owner:other.raw(),window:other_window,owner_events:false,pointer_mode:1,keyboard_mode:1,event_mask:u16::MAX,xi_event_mask:[0;8],xi_event_mask_words:0,route_lease:None}).unwrap();
        (registration,channels)
    };
    attempt_run(&mut f,76015,275,true);
    let p=f.runner.frontend.as_mut().unwrap();
    assert_eq!(p.terminal.holds.len(),2);
    assert_eq!(p.terminal.holds[0].reached.client(),f.client);
    assert_eq!(p.terminal.holds[1].reached.client(),other);
    let original_native=p.terminal.holds[0].native.as_ref().unwrap() as *const _ as usize;
    let incarnation=p.terminal.holds[0].incarnation;
    assert_eq!(p.terminal.holds[0].custody.order,order);
    assert!(order<p.terminal.holds[1].custody.order);
    let later=p.terminal.holds[1].custody.completion.as_ref().unwrap().clone();
    let recovery=p.broker.registry.input_recovery.clone();
    let queue_cells=[76010,76011,76012,76013].map(|id|recovery.completion_for(XAuthorityInputDeliveryId::from_raw(id)).unwrap().unwrap());
    let mut seen_b=Vec::new();let mut refused=0;let mut idle=0;
    for _ in 0..32 {
        match p.deliver_one(&mut |_,_|Ok(())).unwrap() {
            PrivateDeliveryStep::Dispatched{enqueued:false,..}=>refused+=1,
            PrivateDeliveryStep::Idle=>idle+=1,
            _=>{},
        }
        // Only B is drainable during measurement. A's original four remain
        // untouched until after every actual terminal visit has completed.
        while let Ok(c)=other_channels.ordered.try_recv() {
            assert_eq!(c.delivery(),XAuthorityInputDeliveryId::from_raw(76015));
            assert_eq!(c.client(),other);
            assert!(Arc::ptr_eq(&later,&c.finalizer().unwrap().completion));
            seen_b.push(c.delivery());
        }
    }
    let old=&p.terminal.holds[0];
    assert_eq!(old.incarnation,incarnation);
    assert_eq!(old.native.as_ref().unwrap() as *const _ as usize,original_native);
    assert_eq!(old.custody.dispatch,PrivateDispatchPhase::Pending);
    assert_eq!(old.custody.order,order);
    let Some(PrivatePendingDelivery::Capsule(c))=old.custody.pending.as_ref() else{panic!("the original blocked capsule remains inventory-owned")};
    assert_eq!(c.delivery(),XAuthorityInputDeliveryId::from_raw(76014));
    assert_eq!(c.client(),f.client);
    assert!(Arc::ptr_eq(&original,&c.finalizer().unwrap().completion));
    assert_eq!(order_pass_frames(c),frames);
    assert!(original.answer().is_none() && later.answer().is_none());
    assert!(queue_cells.iter().all(|c|c.answer().is_none()));
    assert!(p.terminal.settling.iter().all(|r|r.dispatch()==PrivateDispatchPhase::Enqueued && r.attempt().is_some()));
    let mut seen_a=Vec::new();
    while let Ok(c)=f.channels.ordered.try_recv() {
        let index=seen_a.len();assert!(index<queue_cells.len());
        assert_eq!(c.client(),f.client);
        assert!(Arc::ptr_eq(&queue_cells[index],&c.finalizer().unwrap().completion));
        seen_a.push(c.delivery());
    }
    assert_eq!(seen_a,[76010,76011,76012,76013].map(XAuthorityInputDeliveryId::from_raw));
    assert!(
        refused + idle > 0,
        "the visits were real: {refused} refused dispatches, {idle} idle"
    );
    assert_eq!(seen_b,[XAuthorityInputDeliveryId::from_raw(76015)],"a genuinely Full older recipient must not consume every later live recipient's turn");

    // AND THE RETAINED CAPSULE GOES ONCE, NOW THAT THERE IS ROOM. Draining A's
    // four freed its slots; what was refused is offered again unchanged. The
    // capsule is the one that was built before the refusal -- same completion,
    // same recipient, same bytes -- because a refused queue is a handover that
    // did not happen, not one to redo.
    let mut inbox = OrderedInbox::default();
    let retried = inbox
        .accepted(p, &f.channels.ordered, &original, 8)
        .expect("a readable terminal step")
        .expect("the retained capsule is accepted once its recipient has room");
    assert_eq!(
        retried.delivery(),
        XAuthorityInputDeliveryId::from_raw(76014)
    );
    assert_eq!(retried.client(), f.client);
    assert!(Arc::ptr_eq(
        &original,
        &retried.finalizer().unwrap().completion
    ));
    assert_eq!(
        order_pass_frames(&retried),
        frames,
        "the same encoded event, not one built again"
    );
    assert_eq!(
        retried.emission().incarnation(),
        incarnation,
        "still named by the hold it came from"
    );
    assert!(
        inbox.taken.is_empty(),
        "and nothing else of A's was taken while finding it"
    );

    // Once. Further visits produce no duplicate for either recipient.
    for _ in 0..8 {
        let _ = p.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    assert!(
        f.channels.ordered.try_recv().is_err(),
        "an accepted handover is not repeated after capacity opens"
    );
    assert!(other_channels.ordered.try_recv().is_err());
    assert!(original.answer().is_none() && later.answer().is_none());
    drop(other_registration);
}

#[test]
fn an_unrecorded_release_at_the_head_spends_its_connections_turn() {
    // A release whose native half is not in yet cannot be given a ledger
    // attempt, so its handover is unfinished and it is its connection's head.
    // The press path must recognise that and leave it alone: the release
    // belongs to the attempt path, and reaching into it from here would act on
    // a debt the ledger has not authorised.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(7611));
    attempt_release(&mut f, 76110, 272);
    // The press it ends comes first and is handed over, which is what leaves
    // the release alone at the head of that connection.
    {
        let p = f.runner.frontend.as_mut().unwrap();
        assert_eq!(p.dispatch_one_press(), Some(true));
    }
    assert_eq!(
        f.channels.ordered.try_iter().count(),
        1,
        "the carried press, and only it"
    );

    // A second connection with its own press, behind the release in stamp
    // order, so a release head that stopped everything would show here.
    let other = XServerFrontendClientId(7612);
    let other_window = XResourceId::new(0x307612, 1);
    let (other_registration, other_channels) = {
        let p = f.runner.frontend.as_mut().unwrap();
        let registry = &p.broker.registry;
        let context = namespaced(other, f.namespace);
        let (registration, channels) = registry
            .register_client_with_admission(other, Some(context))
            .unwrap();
        registry.attach_private_lifecycle(&registration, context).unwrap();
        let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry
            .attach_connection_state(
                &registration,
                f.namespace,
                selected.clone(),
                Arc::new(AtomicU64::new(0)),
            )
            .unwrap();
        {
            let mut state = selected.lock().unwrap();
            state.register(
                other_window,
                XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
                Rect { x: 0, y: 0, width: 200, height: 100 },
            );
            state.observe_mapped(other_window);
            state.update(other_window, Some((1 << 2) | (1 << 3)), None);
        }
        let mut grabs = registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace, f.client.raw());
        grabs
            .grab_pointer(
                f.namespace,
                crate::XActiveInputGrab {
                    owner: other.raw(),
                    window: other_window,
                    owner_events: false,
                    pointer_mode: 1,
                    keyboard_mode: 1,
                    event_mask: u16::MAX,
                    xi_event_mask: [0; 8],
                    xi_event_mask_words: 0,
                    route_lease: None,
                },
            )
            .unwrap();
        (registration, channels)
    };
    attempt_run(&mut f, 76112, 273, true);

    let p = f.runner.frontend.as_mut().unwrap();
    // The state this control exists for: one settling release, native not yet
    // recorded, so the ledger will refuse it an attempt and its own handover
    // has not been taken.
    assert_eq!(p.terminal.settling.len(), 1);
    assert!(!p.terminal.settling[0].native_recorded());
    assert_eq!(
        p.terminal.settling[0].dispatch(),
        PrivateDispatchPhase::Untaken,
        "the release owes a handover, so it is its connection's head"
    );
    assert!(p.terminal.settling[0].attempt().is_none());
    assert_eq!(p.terminal.holds.len(), 1);
    assert_eq!(p.terminal.holds[0].reached.client(), other);

    let recovery = p.broker.registry.input_recovery.clone();
    let press_cell = recovery
        .completion_for(XAuthorityInputDeliveryId::from_raw(76110))
        .unwrap()
        .unwrap();
    let release_cell = recovery
        .completion_for(XAuthorityInputDeliveryId::from_raw(76111))
        .unwrap()
        .unwrap();
    let other_cell = p.terminal.holds[0].custody.completion.as_ref().unwrap().clone();

    // The other connection's own press goes first: the turn moved on from A
    // when A was last offered, which is what keeps a stuck connection from
    // consuming every visit.
    assert_eq!(p.dispatch_one_press(), Some(true));
    let handed: Vec<_> = other_channels.ordered.try_iter().collect();
    assert_eq!(handed.len(), 1, "the connection behind it is not blocked by it");

    // Now only the release is left unfinished, so it is what the next visit is
    // offered. The press path must recognise it and leave it alone: reaching
    // into it would act on a debt the ledger never authorised.
    assert_eq!(
        p.dispatch_one_press(),
        None,
        "a release head is left to the attempt path, and costs the visit"
    );
    assert_eq!(
        p.terminal.settling[0].dispatch(),
        PrivateDispatchPhase::Untaken,
        "nothing was taken from it"
    );
    assert_eq!(
        handed[0].delivery(),
        XAuthorityInputDeliveryId::from_raw(76112)
    );
    assert_eq!(handed[0].client(), other);
    assert!(Arc::ptr_eq(
        &other_cell,
        &handed[0].finalizer().expect("carried").completion
    ));
    assert!(f.channels.ordered.try_recv().is_err(), "and nothing of A's moved");
    assert!(
        press_cell.answer().is_none()
            && release_cell.answer().is_none()
            && other_cell.answer().is_none()
    );
    drop(other_registration);
}

#[test]
fn a_recipients_complete_event_order_is_preserved_across_press_and_release() {
    let mut f=prepared_ordered_fixture(XServerFrontendClientId(7551));
    attempt_release(&mut f,75510,272);
    attempt_run(&mut f,75512,273,true);
    let p=f.runner.frontend.as_mut().unwrap();
    let recovery=p.broker.registry.input_recovery.clone();
    let cells=[75510,75511,75512].map(|id|recovery.completion_for(XAuthorityInputDeliveryId::from_raw(id)).unwrap().unwrap());
    let mut seen=Vec::new();
    // Drive the actual terminal arbiter, including native recording/release
    // dispatch. Drain ALL queue entries after every visit, not merely presses.
    for _ in 0..16 {
        let _=p.deliver_one(&mut |_,_|Ok(())).unwrap();
        while let Ok(capsule)=f.channels.ordered.try_recv() {
            let id=capsule.delivery();
            let expected=[75510,75511,75512].iter().position(|n|id==XAuthorityInputDeliveryId::from_raw(*n)).expect("only these actual events exist");
            assert!(Arc::ptr_eq(&cells[expected],&capsule.finalizer().unwrap().completion));
            seen.push(id);
        }
    }
    assert!(cells.iter().all(|c|c.answer().is_none()));
    assert_eq!(seen,[75510,75511,75512].map(XAuthorityInputDeliveryId::from_raw),"sorting only presses cannot preserve the recipient's complete event order");
}

#[test]
fn an_indeterminate_head_keeps_its_custody_while_another_recipient_progresses() {
    let mut f=prepared_ordered_fixture(XServerFrontendClientId(7561));
    attempt_run(&mut f,75610,272,true);attempt_run(&mut f,75611,273,true);
    let other=XServerFrontendClientId(7562);let other_window=XResourceId::new(0x307562,1);
    let (other_registration,other_channels)={
        let p=f.runner.frontend.as_mut().unwrap();let registry=&p.broker.registry;
        let context=namespaced(other,f.namespace);
        let (registration,channels)=registry.register_client_with_admission(other,Some(context)).unwrap();
        registry.attach_private_lifecycle(&registration,context).unwrap();
        let selected=Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry.attach_connection_state(&registration,f.namespace,selected.clone(),Arc::new(AtomicU64::new(0))).unwrap();
        {
            let mut s=selected.lock().unwrap();
            s.register(other_window,XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT),1),Rect{x:0,y:0,width:200,height:100});
            s.observe_mapped(other_window);s.update(other_window,Some((1<<2)|(1<<3)),None);
        }
        // Genuine owner operations change subsequent source resolution. Native
        // A holds remain retained; no foreign inventory or fake recipient is
        // inserted into this executor. We make no cleanup/lifecycle claim.
        let mut grabs=registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace,f.client.raw());
        grabs.grab_pointer(f.namespace,crate::XActiveInputGrab{owner:other.raw(),window:other_window,owner_events:false,pointer_mode:1,keyboard_mode:1,event_mask:u16::MAX,xi_event_mask:[0;8],xi_event_mask_words:0,route_lease:None}).unwrap();
        (registration,channels)
    };
    attempt_run(&mut f,75612,274,true);
    let p=f.runner.frontend.as_mut().unwrap();assert_eq!(p.terminal.holds.len(),3);
    assert_eq!(p.terminal.holds[0].reached.client(),f.client);assert_eq!(p.terminal.holds[1].reached.client(),f.client);assert_eq!(p.terminal.holds[2].reached.client(),other);
    let recovery=p.broker.registry.input_recovery.clone();
    let cells=[75610,75611,75612].map(|id|recovery.completion_for(XAuthorityInputDeliveryId::from_raw(id)).unwrap().unwrap());
    let record=&mut p.terminal.holds[0];let emission=record.native.as_mut().unwrap().take_press_emission().unwrap();
    PrivateXServerFrontend::stow_press_capsule(&mut record.custody,emission,&recovery,f.client);
    // Explicitly staged at the state between the dispatch phase write and
    // capsule take. No actual interrupted send or already-sent byte is claimed.
    record.custody.dispatch=PrivateDispatchPhase::Indeterminate;
    let mut seen_a=Vec::new();let mut seen_b=Vec::new();
    for _ in 0..8 {
        let _=p.deliver_one(&mut |_,_|Ok(())).unwrap();
        while let Ok(c)=f.channels.ordered.try_recv(){
            let index=if c.delivery()==XAuthorityInputDeliveryId::from_raw(75610){0}else{assert_eq!(c.delivery(),XAuthorityInputDeliveryId::from_raw(75611));1};
            assert!(Arc::ptr_eq(&cells[index],&c.finalizer().unwrap().completion));seen_a.push(c.delivery());
        }
        while let Ok(c)=other_channels.ordered.try_recv(){
            assert_eq!(c.delivery(),XAuthorityInputDeliveryId::from_raw(75612));assert_eq!(c.client(),other);
            assert!(Arc::ptr_eq(&cells[2],&c.finalizer().unwrap().completion));seen_b.push(c.delivery());
        }
    }
    let old_phase=p.terminal.holds[0].custody.dispatch;
    let old_owned=matches!(p.terminal.holds[0].custody.pending.as_ref(),Some(PrivatePendingDelivery::Capsule(c)) if c.delivery()==XAuthorityInputDeliveryId::from_raw(75610) && Arc::ptr_eq(&cells[0],&c.finalizer().unwrap().completion));
    assert!(cells.iter().all(|c|c.answer().is_none()));
    assert_eq!(seen_b,[XAuthorityInputDeliveryId::from_raw(75612)],"a distinct exact recipient must progress under retained arbitration");
    assert!(seen_a.is_empty(),"neither the indeterminate head nor any later event may enqueue for its recipient");
    assert_eq!(old_phase,PrivateDispatchPhase::Indeterminate);assert!(old_owned,"the exact unknown-handover capsule stays inventory-owned");
    drop(other_registration);
}

fn output_refused(f:&mut PreparedOrderedFixture,route:XAuthorityRoutedInput)->PrivateExecutionRefusal {
    f.ingress.submit(&f.keeper.lease(), route).unwrap();
    let PrivatePreparedRunner{frontend,keyboards,watch,..}=&mut f.runner;let p=frontend.as_mut().unwrap();
    assert!(matches!(p.step_once(keyboards,&mut |_,_|Ok(()),watch.as_ref().unwrap()).unwrap(),PrivateOrderedStep::Decided(_)));
    let Some(PrivateOrderedItem::Refused{refusal,custody,..})=p.terminal.turn.pop() else{panic!("typed pre-effect refusal required")};
    assert!(custody.observe().unwrap().is_some());refusal
}

#[test]
fn an_exhausted_event_order_refuses_before_any_effect() {
    for release in [false,true] {
        let mut f=prepared_ordered_fixture(XServerFrontendClientId(if release{7572}else{7571}));
        if release{attempt_run(&mut f,75720,272,true);}
        let p=f.runner.frontend.as_mut().unwrap();
        let held=if release{Some((p.terminal.holds[0].incarnation,p.terminal.holds[0].native.as_ref().unwrap() as *const _ as usize,p.terminal.holds[0].custody.completion.as_ref().unwrap().clone()))}else{None};
        // Counter exhaustion only is staged. The reservation, completion cell,
        // native source call boundary and typed refusal are real.
        p.terminal.next_event_order=u64::MAX;
        let id=XAuthorityInputDeliveryId::from_raw(if release{75721}else{75710});
        let route=button_to(f.surface,id,272,!release);
        assert!(matches!(output_refused(&mut f,route),PrivateExecutionRefusal::OrderExhausted));
        let p=f.runner.frontend.as_ref().unwrap();
        assert_eq!(p.terminal.next_event_order,u64::MAX);
        assert!(p.terminal.pending_custody.is_none() && p.terminal.native_pending.is_none() && p.terminal.settling.is_empty());
        assert_eq!(p.terminal.holds.len(),usize::from(release));
        let mask=p.broker.registry.pointer_state.lock().unwrap().get(&(f.namespace,SeatId::from_raw(1))).expect("existing mapper").state();
        assert_eq!(mask,if release{256}else{0});
        if let Some((incarnation,native,cell))=held {
            assert_eq!(p.terminal.holds[0].incarnation,incarnation);assert_eq!(p.terminal.holds[0].native.as_ref().unwrap() as *const _ as usize,native);
            assert!(Arc::ptr_eq(&cell,p.terminal.holds[0].custody.completion.as_ref().unwrap()));assert_eq!(Arc::strong_count(&cell),3);assert!(cell.answer().is_none());
        }
        let recovery=&p.broker.registry.input_recovery;let cell=recovery.completion_for(id).unwrap().unwrap();
        assert!(cell.answer().is_none());assert_eq!(Arc::strong_count(&cell),2);
        let (claimed,applied)={let s=recovery.state.lock().unwrap();let e=s.tickets.get(&id).unwrap();(e.claimed,e.may_have_applied)};
        assert!(!claimed && !applied);assert!(f.channels.ordered.try_recv().is_err());
    }
}

#[test]
fn an_instrument_recognises_its_admission_after_the_ticket_is_pruned() {
    // The helper used to ask the recovery for the cell when it was called, so
    // an admission whose ticket had been answered and pruned read as one that
    // was never handed over. The identity has to be fixed where the admission
    // mints it, and a lookup that returns nothing is not evidence.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(7621));
    attempt_run(&mut f, 76210, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    let id = XAuthorityInputDeliveryId::from_raw(76210);
    let original = admitted_cell(private, 76210);
    let mut inbox = OrderedInbox::default();

    let capsule = inbox
        .accepted(private, &f.channels.ordered, &original, 8)
        .expect("a readable terminal step")
        .expect("the actual recipient accepted the original capsule");
    assert_eq!(capsule.delivery(), id);
    assert_eq!(capsule.client(), f.client);
    assert!(Arc::ptr_eq(
        &original,
        &capsule.finalizer().unwrap().completion
    ));
    assert_eq!(
        handover_phase(private, &original),
        Some(PrivateDispatchPhase::Enqueued)
    );

    // A real finish and an ordinary observation prune the ticket. Nothing
    // about the handover changes: the capsule and the custody still carry the
    // cell this admission minted.
    recovery
        .finish(f.client, Some(id), XAuthorityInputDeliveryOutcome::WriteFailed)
        .unwrap();
    let answer = original
        .answer()
        .expect("the original admission owns the established answer");
    assert_eq!(answer.delivery, id);
    assert_eq!(answer.outcome, XAuthorityInputDeliveryOutcome::WriteFailed);
    assert!(
        recovery.observe(answer),
        "an ordinary observer consumes and prunes the exact answered ticket"
    );
    assert!(
        recovery.completion_for(id).unwrap().is_none(),
        "the lookup this instrument must not depend on is gone"
    );

    assert_eq!(
        handover_phase(private, &original),
        Some(PrivateDispatchPhase::Enqueued)
    );
    assert!(Arc::ptr_eq(
        &original,
        private.terminal.holds[0].custody.completion.as_ref().unwrap()
    ));
    assert!(Arc::ptr_eq(
        &original,
        &capsule.finalizer().unwrap().completion
    ));

    // And the retained capsule is still recognised as this admission's, with
    // nothing replayed to find it again.
    inbox.taken.push(capsule);
    let found = inbox
        .accepted(private, &f.channels.ordered, &original, 8)
        .expect("a readable terminal step")
        .expect("an instrument holding the admission's own cell still knows it");
    assert_eq!(found.delivery(), id);
    assert!(
        f.channels.ordered.try_recv().is_err(),
        "the actual accepted event is never replayed"
    );
}

#[test]
fn an_instrument_takes_the_admission_asked_for_and_keeps_the_others() {
    // Three events owed to one recipient, asked for out of order. An
    // instrument that returned whatever capsule it found first would answer
    // every one of these with the press, and a control built on it would be
    // asserting about an event it never named.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(7631));
    let cells: Vec<_> = {
        let mut cells = Vec::new();
        for (id, button, pressed) in [(76310u64, 272u32, true), (76311, 272, false), (76312, 273, true)] {
            f.ingress
                .submit(&f.keeper.lease(), button_to(
                    f.surface,
                    XAuthorityInputDeliveryId::from_raw(id),
                    button,
                    pressed,
                ))
                .unwrap();
            let PrivatePreparedRunner { frontend, keyboards, watch, .. } = &mut f.runner;
            let private = frontend.as_mut().unwrap();
            assert!(matches!(
                private
                    .step_once(keyboards, &mut |_, _| Ok(()), watch.as_ref().unwrap())
                    .unwrap(),
                PrivateOrderedStep::Decided(_)
            ));
            cells.push(admitted_cell(private, id));
            let Some(PrivateOrderedItem::Ran { custody, .. }) = private.terminal.turn.pop() else {
                panic!("an accepted request runs")
            };
            assert!(custody.observe().unwrap().is_some());
        }
        cells
    };
    let private = f.runner.frontend.as_mut().unwrap();

    // THE BUDGET STOPS AT THE ANSWER. Nothing is queued yet, so visits have to
    // be driven -- but only until this admission's capsule appears. Spending
    // the rest would hand over events this question never mentioned, which a
    // control asking about the first one has no business causing.
    let mut inbox = OrderedInbox::default();
    assert!(
        f.channels.ordered.try_recv().is_err(),
        "nothing has been handed over before this"
    );
    let first = inbox
        .accepted(private, &f.channels.ordered, &cells[0], 8)
        .expect("a readable terminal step")
        .expect("the press is handed over and recognised");
    assert_eq!(
        first.delivery(),
        XAuthorityInputDeliveryId::from_raw(76310)
    );
    assert_ne!(
        handover_phase(private, &cells[2]),
        Some(PrivateDispatchPhase::Enqueued),
        "and the events nobody asked about are still owed"
    );
    assert!(
        inbox.taken.is_empty(),
        "nothing else was taken off that queue"
    );

    // Now let the rest go, so the whole stream is in hand.
    for _ in 0..12 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    inbox.collect(&f.channels.ordered);
    assert_eq!(
        inbox
            .taken
            .iter()
            .map(XAuthorityOrderedDelivery::delivery)
            .collect::<Vec<_>>(),
        [76311, 76312].map(XAuthorityInputDeliveryId::from_raw),
        "in their own order, with the one already taken out"
    );

    // ASKED FOR THE LAST ONE, out of order and with no budget at all.
    let third = inbox
        .accepted(private, &f.channels.ordered, &cells[2], 0)
        .expect("a readable terminal step")
        .expect("what is already queued counts without driving anything");
    assert_eq!(
        third.delivery(),
        XAuthorityInputDeliveryId::from_raw(76312),
        "the admission asked for, not the first capsule to hand"
    );
    assert!(Arc::ptr_eq(&cells[2], &third.finalizer().unwrap().completion));

    // The one it was not asked about is kept.
    assert_eq!(
        inbox
            .taken
            .iter()
            .map(XAuthorityOrderedDelivery::delivery)
            .collect::<Vec<_>>(),
        [76311].map(XAuthorityInputDeliveryId::from_raw),
        "unrelated capsules are retained, not consumed by someone else's question"
    );
    assert!(cells.iter().all(|cell| cell.answer().is_none()));
}

#[test]
fn a_capsule_for_another_connection_is_refused_before_any_byte_of_it_is_written() {
    // STAGED, AND SAID SO. Nothing in the routing path puts one connection's
    // capsule on another's queue today: dispatch looks the queue up by the
    // recipient the capsule names. This is the check that has to exist before
    // a per-connection loop is attached to that queue, because by the time a
    // frame for the wrong connection is on a wire the recipient has read it.
    //
    // Both capsules are real: two genuinely admitted connections, each
    // pressing through the source and building its own emission.
    let mut f = prepared_ordered_fixture(XServerFrontendClientId(7641));
    attempt_run(&mut f, 76410, 272, true);

    let other = XServerFrontendClientId(7642);
    let other_window = XResourceId::new(0x307642, 1);
    let (other_registration, _other_channels) = {
        let p = f.runner.frontend.as_mut().unwrap();
        let registry = &p.broker.registry;
        let context = namespaced(other, f.namespace);
        let (registration, channels) = registry
            .register_client_with_admission(other, Some(context))
            .unwrap();
        registry.attach_private_lifecycle(&registration, context).unwrap();
        let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry
            .attach_connection_state(
                &registration,
                f.namespace,
                selected.clone(),
                Arc::new(AtomicU64::new(0)),
            )
            .unwrap();
        {
            let mut state = selected.lock().unwrap();
            state.register(
                other_window,
                XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
                Rect { x: 0, y: 0, width: 200, height: 100 },
            );
            state.observe_mapped(other_window);
            state.update(other_window, Some((1 << 2) | (1 << 3)), None);
        }
        let mut grabs = registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace, f.client.raw());
        grabs
            .grab_pointer(
                f.namespace,
                crate::XActiveInputGrab {
                    owner: other.raw(),
                    window: other_window,
                    owner_events: false,
                    pointer_mode: 1,
                    keyboard_mode: 1,
                    event_mask: u16::MAX,
                    xi_event_mask: [0; 8],
                    xi_event_mask_words: 0,
                    route_lease: None,
                },
            )
            .unwrap();
        (registration, channels)
    };
    attempt_run(&mut f, 76412, 273, true);

    // Each connection's own capsule, taken out of the record that owns it.
    let p = f.runner.frontend.as_mut().unwrap();
    assert_eq!(p.terminal.holds.len(), 2);
    assert_eq!(p.terminal.holds[0].reached.client(), f.client);
    assert_eq!(p.terminal.holds[1].reached.client(), other);
    let recovery = p.broker.registry.input_recovery.clone();
    let mine = {
        let record = &mut p.terminal.holds[0];
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, f.client);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("the press built its own capsule")
        };
        capsule
    };
    let theirs = {
        let record = &mut p.terminal.holds[1];
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, other);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("the other press built its own capsule")
        };
        capsule
    };
    assert_ne!(
        mine.recipient(),
        theirs.recipient(),
        "two connections, two identities"
    );
    let their_cell = theirs.finalizer().expect("carried").completion.clone();
    let my_delivery = mine.delivery();

    // A writer serving the first connection, and the other's capsule on its
    // queue ahead of its own.
    // The writer's expectation comes from the registration it serves, not from
    // anything it is about to be asked to write.
    let served = XAuthorityServedConnection::retained(
        p.endpoint_for(&f.registration)
            .expect("this connection's own endpoint"),
    );
    let (sender, queue) = sync_channel(4);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let mut in_flight = None;
    let mut refused = None;
    sender.send(theirs).expect("the queue to accept it");
    sender.send(mine).expect("the queue to accept it");

    assert!(matches!(
        serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ),
        X11OrderedServeStep::AdmissionRefused(_)
    ));

    // NOTHING WENT ON THE WIRE. That is the whole point of checking at
    // admission: a frame is read by the time anyone could regret it.
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "no byte of another connection's event reached this one"
    );
    assert!(in_flight.is_none(), "and it was never taken as work");

    // It is retained rather than dropped -- the queue has already given it up
    // -- and it is not answered here.
    let held = refused.as_ref().expect("the capsule is owned by this writer");
    assert_eq!(
        held.cause(),
        Some(X11OrderedAdmissionRefusal::ForeignEndpoint),
        "and it says exactly what was wrong: not a flush, not a failure to write"
    );
    assert_eq!(
        held.delivery().delivery(),
        XAuthorityInputDeliveryId::from_raw(76412)
    );
    assert_eq!(held.client(), other);
    assert!(Arc::ptr_eq(
        &their_cell,
        &held.delivery().finalizer().expect("carried").completion
    ));
    assert!(
        their_cell.answer().is_none(),
        "a writer that was never entitled to it does not answer for it"
    );

    // And nothing behind it is served while it is held: taking another would
    // overwrite the one thing that still owns this capsule.
    assert!(matches!(
        serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ),
        X11OrderedServeStep::AdmissionRefused(_)
    ));
    assert_eq!(
        refused
            .as_ref()
            .expect("still held")
            .delivery()
            .delivery(),
        XAuthorityInputDeliveryId::from_raw(76412),
        "the first is still the one held"
    );
    assert!(in_flight.is_none());

    // Disposed of, and this connection's own capsule is admitted normally.
    let _disposed = refused.take().expect("held");
    assert!(matches!(
        serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ),
        X11OrderedServeStep::Advanced | X11OrderedServeStep::Flushed
    ));
    assert!(
        refused.is_none(),
        "its own capsule is not refused"
    );
    assert!(
        in_flight
            .as_ref()
            .is_none_or(|held| held.delivery().delivery() == my_delivery),
        "the connection's own event is what it serves"
    );
    drop(peer);
    drop(other_registration);
}

/// An admission for this client with a chosen admission id and generation.
fn admission_with(
    client: XServerFrontendClientId,
    admission: u64,
    generation: u64,
) -> sophia_protocol::ClientAdmissionContext {
    sophia_protocol::ClientAdmissionContext::new(
        sophia_protocol::ClientAdmissionId::from_raw(admission),
        sophia_protocol::NamespaceContext::new(
            NamespaceId::from_raw(client.raw()),
            sophia_protocol::NamespaceProfile::Confined,
            sophia_protocol::NamespaceCapabilities::NONE,
        )
        .unwrap(),
        sophia_protocol::ClientAuthProvenance::new(
            sophia_protocol::ClientAuthenticationMethod::PeerCredentials,
            generation,
        )
        .unwrap(),
    )
    .unwrap()
}

/// Replace this client's registration and admission, and say what the
/// replacement's exact endpoint is.
///
/// THE REGISTRATION/API SEAM, NOT AN ORDINARY RECONNECT. Nothing a client can
/// drive replaces a live registration: register_client_with_admission refuses a
/// duplicate, and admit refuses an already-bound client. This goes through the
/// registry's and the participant's own replacement path -- revoke, drop the
/// row, admit and register again -- because that is the seam an endpoint
/// identity has to survive. It is not evidence that a reconnect misdelivers.
fn replace_registration(
    private: &mut crate::PrivateXServerFrontend,
    client: XServerFrontendClientId,
    replacement: sophia_protocol::ClientAdmissionContext,
    previous: sophia_protocol::ClientAdmissionId,
    // TAKEN, NOT BORROWED. A client number belongs to one exact registration
    // until that registration's ending has finished with it, so a replacement
    // at the same number is only reachable once the original has gone. What a
    // control still wants afterwards -- its gate, its sender, its endpoint --
    // it captures before calling this.
    original: XServerFrontendClientRouteRegistration,
    surface: Option<(SurfaceId, XResourceId)>,
) -> (
    XServerFrontendClientRouteRegistration,
    XServerFrontendClientRouteChannels,
    PrivateEndpointIdentity,
) {
    private
        .participant
        .revoke_admission(client, previous)
        .expect("the admission this fixture made is the one it revokes");
    // The first registration's row goes before the second exists. Its
    // channels are the caller's to dispose of, because a caller may still be
    // holding one on purpose.
    //
    // THE REGISTRATION ITSELF GOES HERE, and it has to. A client number
    // belongs to one exact registration until that registration's ending has
    // finished with it, so a replacement at the same number is reachable only
    // afterwards. What a control still wants -- its gate, its senders, its
    // endpoint identity -- it captured before calling this.
    drop(original);
    private
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry")
        .remove(&client);
    // The lifecycle owner still holds a record for the closed admission. It is
    // released by the owner's own drive, not by dropping anything, so the
    // replacement is admitted only after the first one has actually finished.
    let lifecycle = private.terminal.lifecycle.clone();
    for _ in 0..16 {
        lifecycle
            .drive(NonZeroUsize::new(1).unwrap())
            .expect("a readable lifecycle owner");
    }
    private
        .admission_participant()
        .admit(client, replacement)
        .expect("the boundary admits the replacement");
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(replacement))
        .expect("a replacement registration");
    // No attach_private_lifecycle here: with the owner already installed, the
    // admit above registered the replacement's gate itself, and attaching a
    // second one for the same client is refused as a duplicate.
    let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
    if let Some((surface, window)) = surface {
        // The original registration's surface route went with it, so the
        // replacement registers its own.
        private
            .broker
            .registry
            .register_surface(client, replacement.namespace.id, surface, window)
            .expect("the replacement's surface");
        // The replacement selects the same window, so its own presses resolve.
        let mut state = selected.lock().expect("a readable selection state");
        state.register(
            window,
            XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
            Rect { x: 0, y: 0, width: 200, height: 100 },
        );
        state.observe_mapped(window);
        state.update(window, Some((1 << 2) | (1 << 3)), None);
    }
    private
        .broker
        .registry
        .attach_connection_state(
            &registration,
            replacement.namespace.id,
            selected,
            Arc::new(AtomicU64::new(0)),
        )
        .expect("the replacement's connection state");
    let endpoint = private
        .endpoint_for(&registration)
        .expect("the replacement's own endpoint, from its own registration");
    (registration, channels, endpoint)
}

/// One real source-built capsule, and a replacement registration for the same
/// client that did not exist when it was built.
fn capsule_then_replacement(
    client: XServerFrontendClientId,
    delivery: u64,
    replacement: sophia_protocol::ClientAdmissionContext,
) -> (
    PrivatePreparedRunner,
    PrivateSettlementOwner,
    XAuthorityOrderedDelivery,
    Arc<PrivateDeliveryCompletion>,
    XServerFrontendClientRouteRegistration,
    XServerFrontendClientRouteChannels,
    PrivateEndpointIdentity,
) {
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, delivery, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    let cell = admitted_cell(private, delivery);
    let original = {
        let record = &mut private.terminal.holds[0];
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, client);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("the press built its own capsule")
        };
        capsule
    };
    assert!(Arc::ptr_eq(
        &cell,
        &original.finalizer().expect("carried").completion
    ));
    let PreparedOrderedFixture {
        mut runner,
        durable,
        registration: original_registration,
        channels: _original_channels,
        ..
    } = f;
    let private = runner.frontend.as_mut().unwrap();
    let (registration, channels, endpoint) = replace_registration(
        private,
        client,
        replacement,
        admitted(client).client_id,
        original_registration,
        None,
    );
    (
        runner,
        durable,
        original,
        cell,
        registration,
        channels,
        endpoint,
    )
}

#[test]
fn a_capsule_from_a_replaced_admission_is_refused_though_every_number_agrees() {
    // Same client, same session generation, a different admission. The tuple
    // the ledger knows this connection by is identical on both sides, which is
    // exactly why it cannot be what admission is decided on: the boundary
    // itself treats a replacement admission inside one session as a different
    // admission, and a delayed revoke naming the old one must not close the
    // new one.
    let client = XServerFrontendClientId(7651);
    let replacement = admission_with(client, 76519, ROLE_SESSION_GENERATION);
    let (runner, durable, original, cell, registration, channels, endpoint) =
        capsule_then_replacement(client, 76510, replacement);
    assert_eq!(
        original.recipient(),
        sophia_input_authority::ConnectionIdentity {
            recipient: client.raw(),
            connection_generation: ROLE_SESSION_GENERATION,
        },
        "the capsule's ledger identity"
    );

    // WHAT THE TEARDOWN ALREADY DID is recorded before the writer is asked,
    // so what follows is attributed to the refusal and not to the revocation.
    // Replacing an admission ends its outstanding deliveries -- that is the
    // recovery answering for a connection that has gone -- and this control is
    // about the writer, which must add nothing to it either way.
    let answered_by_teardown = cell.answer();

    // The replacement writer's expectation comes from its own registration.
    let served = XAuthorityServedConnection::retained(endpoint);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (sender, queue) = sync_channel(4);
    let mut in_flight = None;
    let mut refused = None;
    sender.send(original).expect("the queue to accept it");

    assert!(matches!(
        serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ),
        X11OrderedServeStep::AdmissionRefused(X11OrderedAdmissionRefusal::ForeignEndpoint)
    ));
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "not one byte of a replaced admission's event reached the replacement"
    );
    let held = refused.as_ref().expect("owned by this writer");
    assert_eq!(
        held.delivery().delivery(),
        XAuthorityInputDeliveryId::from_raw(76510)
    );
    assert!(Arc::ptr_eq(
        &cell,
        &held.delivery().finalizer().expect("carried").completion
    ));
    assert_eq!(
        cell.answer(),
        answered_by_teardown,
        "and the writer that never wrote for it changed nothing about its answer"
    );
    assert!(in_flight.is_none());
    drop(peer);
    drop(channels);
    drop(registration);
    drop(runner);
    drop(durable);
}

#[test]
fn a_capsule_from_a_replaced_registration_is_refused_though_the_admission_agrees_too() {
    // The sharpest case: the replacement is admitted with THE SAME admission
    // context -- same client, same admission id, same namespace, same session
    // generation. Every number on both sides is equal. What differs is the
    // registration, and that is the whole of what distinguishes them.
    let client = XServerFrontendClientId(7661);
    let (runner, durable, original, cell, registration, channels, endpoint) =
        capsule_then_replacement(client, 76610, admitted(client));
    assert_eq!(
        original.recipient(),
        sophia_input_authority::ConnectionIdentity {
            recipient: client.raw(),
            connection_generation: ROLE_SESSION_GENERATION,
        }
    );

    let answered_by_teardown = cell.answer();
    let served = XAuthorityServedConnection::retained(endpoint);
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let (sender, queue) = sync_channel(4);
    let mut in_flight = None;
    let mut refused = None;
    sender.send(original).expect("the queue to accept it");

    assert!(matches!(
        serve_one_ordered_delivery(
            &socket,
            &served,
            &mut in_flight,
            &mut refused,
            &queue,
            XByteOrder::LittleEndian,
            7,
        ),
        X11OrderedServeStep::AdmissionRefused(X11OrderedAdmissionRefusal::ForeignEndpoint)
    ));
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "identical numbers are not an entitlement to these bytes"
    );
    assert!(
        refused.is_some() && in_flight.is_none(),
        "it is owned as refused work, not taken as work to do"
    );
    assert_eq!(
        cell.answer(),
        answered_by_teardown,
        "and the refusal is not an answer"
    );
    drop(peer);
    drop(channels);
    drop(registration);
    drop(runner);
    drop(durable);
}

#[test]
fn a_producer_does_not_send_an_old_capsule_through_a_replacement_entry() {
    // THE OTHER HALF OF THE SEAM. The writer's check catches a capsule that
    // reached the wrong queue; this catches one being put there. The row the
    // endpoint is compared against is the row the sender is cloned from, under
    // one guard, so there is no gap between deciding a row is right and taking
    // its channel.
    //
    // Registration/API seam, as above: nothing a client drives replaces a live
    // registration.
    let client = XServerFrontendClientId(7681);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 76810, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 76810);

    // The press has an event owed and a capsule built for it, still owned by
    // the custody that made it.
    let recovery = private.broker.registry.input_recovery.clone();
    {
        let record = &mut private.terminal.holds[0];
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, client);
    }
    assert_eq!(
        private.terminal.holds[0].custody.dispatch,
        PrivateDispatchPhase::Pending
    );

    let PreparedOrderedFixture {
        mut runner,
        durable,
        registration: original_registration,
        channels: _original_channels,
        ..
    } = f;
    let private = runner.frontend.as_mut().unwrap();
    let (registration, channels, _endpoint) = replace_registration(
        private,
        client,
        admitted(client),
        admitted(client).client_id,
        original_registration,
        None,
    );
    let answered_by_teardown = cell.answer();

    // The replacement's row holds a different channel. Offering the old
    // capsule must not put it there.
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    assert!(
        channels.ordered.try_recv().is_err(),
        "a replacement registration is not handed the work of the one it replaced"
    );

    // And the capsule stays exactly where it was, unsent and unanswered by
    // this refusal.
    let custody = &private.terminal.holds[0].custody;
    assert_eq!(
        custody.dispatch,
        PrivateDispatchPhase::Pending,
        "no handover was begun for it"
    );
    let Some(PrivatePendingDelivery::Capsule(held)) = custody.pending.as_ref() else {
        panic!("the original capsule is still owned by the custody that built it")
    };
    assert_eq!(
        held.delivery(),
        XAuthorityInputDeliveryId::from_raw(76810)
    );
    assert!(Arc::ptr_eq(
        &cell,
        &held.finalizer().expect("carried").completion
    ));
    assert_eq!(
        cell.answer(),
        answered_by_teardown,
        "and offering it to a row that is not its own answers nothing"
    );
    drop(channels);
    drop(registration);
    drop(runner);
    drop(durable);
}

#[test]
fn a_producer_does_not_send_an_old_release_through_a_replacement_entry() {
    // The press control could not see this: the release reaches its queue by
    // the ledger-selected attempt path, which acquires its own sender. Both
    // paths have to check the row they send through.
    //
    // Registration/API seam, as elsewhere in this file.
    let client = XServerFrontendClientId(7691);
    let mut f = prepared_ordered_fixture(client);
    attempt_release(&mut f, 76910, 272);
    let private = f.runner.frontend.as_mut().unwrap();

    // The press goes first and normally, so what is left owed is the release.
    assert_eq!(private.dispatch_one_press(), Some(true));
    assert_eq!(
        f.channels.ordered.try_iter().count(),
        1,
        "the press this release ends"
    );
    let private = f.runner.frontend.as_mut().unwrap();
    assert_eq!(private.record_one_native(), Some(true));
    let release_cell = admitted_cell(private, 76911);
    assert_eq!(private.terminal.settling.len(), 1);
    assert!(private.terminal.settling[0].native_recorded());

    let PreparedOrderedFixture {
        mut runner,
        durable,
        registration: original_registration,
        channels: _original_channels,
        ..
    } = f;
    let private = runner.frontend.as_mut().unwrap();
    let (registration, channels, _endpoint) = replace_registration(
        private,
        client,
        admitted(client),
        admitted(client).client_id,
        original_registration,
        None,
    );
    let answered_by_teardown = release_cell.answer();

    // The ledger may hand out an attempt; the row it would be served through
    // is not this release's, so nothing is written down and nothing is taken.
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    assert!(
        channels.ordered.try_recv().is_err(),
        "a replacement registration is not handed the release of the one it replaced"
    );
    let release = &private.terminal.settling[0];
    assert!(
        matches!(
            release.dispatch(),
            PrivateDispatchPhase::Untaken | PrivateDispatchPhase::Pending
        ),
        "no handover was begun for it: building its capsule may move Untaken to \
         Pending, but nothing past that, got {:?}",
        release.dispatch()
    );
    assert!(
        matches!(
            release.custody.pending.as_ref(),
            Some(PrivatePendingDelivery::Capsule(_))
        ),
        "and its own capsule is still there, unsent"
    );
    assert!(
        release.attempt().is_none(),
        "any attempt claimed for it was given back rather than held against an \
         unusable row"
    );
    assert_eq!(
        release_cell.answer(),
        answered_by_teardown,
        "and offering it to a row that is not its own answers nothing"
    );
    drop(channels);
    drop(registration);
    drop(runner);
    drop(durable);
}

#[test]
fn a_serving_owner_keeps_its_own_endpoint_when_its_registration_is_replaced() {
    // The comparison controls prove two deliberately different identities
    // compare unequal. This proves what matters for attachment: an owner built
    // for one registration, holding that registration's receiver and socket,
    // goes on expecting THAT registration after a replacement exists -- and
    // refuses bytes for anything else through its own serving call rather than
    // through a free function a caller could hand three unrelated things.
    //
    // Registration/API seam, as elsewhere in this file.
    let client = XServerFrontendClientId(7701);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77010, 272, true);

    // A genuinely different connection, admitted and grabbed the ordinary way,
    // with its own source-built press. Nothing about this capsule is
    // fabricated: it is what its own endpoint is owed.
    let other = XServerFrontendClientId(7702);
    let other_window = XResourceId::new(0x307702, 1);
    let (other_registration, _other_channels) = {
        let p = f.runner.frontend.as_mut().unwrap();
        let registry = &p.broker.registry;
        let context = namespaced(other, f.namespace);
        let (registration, channels) = registry
            .register_client_with_admission(other, Some(context))
            .unwrap();
        registry.attach_private_lifecycle(&registration, context).unwrap();
        let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry
            .attach_connection_state(
                &registration,
                f.namespace,
                selected.clone(),
                Arc::new(AtomicU64::new(0)),
            )
            .unwrap();
        {
            let mut state = selected.lock().unwrap();
            state.register(
                other_window,
                XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
                Rect { x: 0, y: 0, width: 200, height: 100 },
            );
            state.observe_mapped(other_window);
            state.update(other_window, Some((1 << 2) | (1 << 3)), None);
        }
        let mut grabs = registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace, f.client.raw());
        grabs
            .grab_pointer(
                f.namespace,
                crate::XActiveInputGrab {
                    owner: other.raw(),
                    window: other_window,
                    owner_events: false,
                    pointer_mode: 1,
                    keyboard_mode: 1,
                    event_mask: u16::MAX,
                    xi_event_mask: [0; 8],
                    xi_event_mask_words: 0,
                    route_lease: None,
                },
            )
            .unwrap();
        (registration, channels)
    };
    attempt_run(&mut f, 77012, 273, true);

    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    let foreign_cell = admitted_cell(private, 77012);
    let foreign = {
        let record = private
            .terminal
            .holds
            .iter_mut()
            .find(|record| record.reached.client() == other)
            .expect("the other connection's own press");
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, other);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("it built its own capsule")
        };
        capsule
    };

    // Kept before the replacement removes the row that holds it, so this
    // owner's queue can still be handed something afterwards. That is the
    // point: an incorrectly supplied capsule has to be caught at the serving
    // boundary, not only prevented at the producer.
    let original_sender = private
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("the original row")
        .ordered
        .clone();

    let PreparedOrderedFixture {
        mut runner,
        durable,
        registration: original_registration,
        channels: original_channels,
        ..
    } = f;
    let private = runner.frontend.as_mut().unwrap();

    // The owner is built from the registration and receiver that exist now,
    // and owns them from here on.
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let transport =
        XAuthorityOrderedTransport::bind(&original_registration, original_channels.ordered, &output, &wire, &pending, None)
            .unwrap_or_else(|(refusal, _)| {
                panic!("this connection's own receiver and output bind: {refusal:?}")
            });
    let mut owner =
        X11OrderedServingOwner::for_registration(private, &original_registration, transport)
            .unwrap_or_else(|(refusal, _)| {
                panic!("an owner for the registration that made this receiver: {refusal:?}")
            });

    // Its own connection's event is served normally, once.
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    let mut flushed = 0;
    for _ in 0..16 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => flushed += 1,
            X11OrderedServeStep::Idle => break,
            other => panic!("its own endpoint's event is served: {other:?}"),
        }
    }
    assert_eq!(flushed, 1, "the endpoint it was built for writes once");
    assert!(owner.refused().is_none() && owner.in_flight().is_none());
    // Its own event's bytes are taken off the wire, so what is read later can
    // only be something written after this point.
    let mut drained = [0u8; 4096];
    assert!(
        (&peer).read(&mut drained).is_ok_and(|read| read > 0),
        "its own event really did reach the wire"
    );
    while (&peer).read(&mut drained).is_ok_and(|read| read > 0) {}

    // THE FOREIGN CAPSULE GOES ON THIS OWNER'S QUEUE FIRST, while this
    // connection's own gate is still open. Its ending closes that gate, and a
    // capsule offered afterwards would be refused by the gate rather than by
    // the owner -- which is a different refusal and not this control's
    // subject.
    gated_send(&original_sender, foreign).expect("this owner's queue accepts it");

    // FIRST, ITS ROW GOES AND ITS REGISTRATION DOES NOT. This is where the
    // stale capability is asked, because it is the only arrangement in which a
    // stale registration and a would-be replacement both exist: the number is
    // still this registration's, so the replacement is refused outright.
    private
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry")
        .remove(&client);
    assert!(
        private.endpoint_for(&original_registration).is_err(),
        "a registration that is no longer the current row names no endpoint"
    );
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("its number is still this registration's");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "a number whose registration still holds it is not available: {refused:?}"
    );

    // NOW the registration goes, which is what frees the number, and the
    // replacement is made. The owner is not rebuilt and is not told: it still
    // holds what it was given.
    let (replacement_registration, replacement_channels, replacement_endpoint) =
        replace_registration(
            private,
            client,
            admitted(client),
            admitted(client).client_id,
            original_registration,
            None,
        );

    // IT CANNOT ADOPT THE REPLACEMENT'S IDENTITY. The replacement can name its
    // own endpoint, and it is not the one this owner serves.
    assert!(
        !owner.served.endpoint().matches(&replacement_endpoint),
        "the owner serves the registration it was built for, not the current one"
    );
    assert!(
        private.endpoint_for(&replacement_registration).is_ok(),
        "and the replacement can name its own"
    );
    // THE STALE CAPABILITY WAS ALREADY ASKED, above, while it still existed.
    // It cannot be asked here: a registration holds its number until its own
    // ending has finished with it, so there is no moment at which a stale
    // registration and the replacement that took its number are both in a
    // caller's hands.

    // AND IT CANNOT BE HANDED ANOTHER ENDPOINT'S BYTES. The capsule queued
    // above is owed to a different connection, and the owner's own serving
    // call refuses it before any of it is written.
    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::AdmissionRefused(X11OrderedAdmissionRefusal::ForeignEndpoint)
    ));
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "not one byte of another endpoint's event reached the socket this owner holds"
    );
    let held = owner.refused().expect("owned by this owner");
    assert_eq!(
        held.delivery().delivery(),
        XAuthorityInputDeliveryId::from_raw(77012)
    );
    assert_eq!(held.cause(), Some(X11OrderedAdmissionRefusal::ForeignEndpoint));
    assert!(Arc::ptr_eq(
        &foreign_cell,
        &held.delivery().finalizer().expect("carried").completion
    ));
    assert!(owner.in_flight().is_none());
    assert!(
        foreign_cell.answer().is_none(),
        "and its admission is not answered by an owner that was never entitled to it"
    );

    // A second arrival while one is held is reported as itself and does not
    // overwrite the one thing that still owns the first.
    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::AdmissionRefused(X11OrderedAdmissionRefusal::AlreadyHolding)
    ));
    assert_eq!(
        owner
            .refused()
            .expect("still held")
            .delivery()
            .delivery(),
        XAuthorityInputDeliveryId::from_raw(77012)
    );
    drop(peer);
    drop(other_registration);
    drop(replacement_channels);
    drop(replacement_registration);
    drop(runner);
    drop(durable);
}

#[test]
fn a_serving_constructor_rejects_another_registrations_receiver() {
    // Two real prepared registrations and their actual registry-created
    // receivers. Independent origins make the mismatch unambiguous; no
    // capsule, outcome, socket traffic or production-loop scenario is staged.
    let a=prepared_ordered_fixture(XServerFrontendClientId(7711));
    let b=prepared_ordered_fixture(XServerFrontendClientId(7712));
    let private=a.runner.frontend.as_ref().unwrap();
    let endpoint_a=private.endpoint_for(&a.registration).unwrap();
    let endpoint_b=b.runner.frontend.as_ref().unwrap().endpoint_for(&b.registration).unwrap();
    assert!(!endpoint_a.matches(&endpoint_b));
    let (socket,_peer)=UnixStream::pair().unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    // The association is established where the transport is bound, so that is
    // where crossing two real connections is caught.
    let bound = XAuthorityOrderedTransport::bind(&a.registration, b.channels.ordered, &output, &wire, &pending, None);
    assert!(
        bound.is_err(),
        "binding must reject B's original receiver when given registration A"
    );
    let (refusal, returned) = bound.err().expect("refused");
    assert_eq!(refusal, X11OrderedServingRefusal::ForeignReceiver);
    assert!(
        returned.minted_by(&b.registration),
        "and the receiver handed back is B's own, whole"
    );
    // And the same refusal stands at the serving owner, for a transport that
    // was bound for a different registration.
    let transport = XAuthorityOrderedTransport::bind(&b.registration, returned, &output, &wire, &pending, None)
        .unwrap_or_else(|_| panic!("B's own registration and B's own receiver bind"));
    let owner = X11OrderedServingOwner::for_registration(private, &a.registration, transport);
    assert!(
        owner.is_err(),
        "a transport bound for another registration prepares no writer here"
    );
}

#[test]
fn a_failed_serving_constructor_preserves_its_original_queued_capsule() {
    let client=XServerFrontendClientId(7721);
    let mut f=prepared_ordered_fixture(client);
    // Real admitted native press and actual original ordered queue handover.
    attempt_run(&mut f,77210,272,true);
    let private=f.runner.frontend.as_mut().unwrap();
    let original=admitted_cell(private,77210);
    assert_eq!(private.dispatch_one_press(),Some(true));
    let sender=private.broker.registry.clients.lock().unwrap().get(&client).unwrap().ordered.clone();
    let capsule=f.channels.ordered.try_recv().expect("original queue accepted the actual press");
    assert_eq!(capsule.delivery(),XAuthorityInputDeliveryId::from_raw(77210));
    assert_eq!(capsule.client(),client);
    assert!(Arc::ptr_eq(&original,&capsule.finalizer().unwrap().completion));
    assert!(capsule.endpoint().matches(&private.endpoint_for(&f.registration).unwrap()));
    assert_eq!(Arc::strong_count(capsule.finalizer().unwrap()),1,"only this nonclone capsule owns its finalizer Arc");
    // Keep ONLY a Weak finalizer witness; a strong clone here would mask
    // destruction of the original queued capsule.
    let finalizer=Arc::downgrade(capsule.finalizer().unwrap());
    assert!(gated_send(&sender,capsule).is_ok(),"put the exact original capsule back into its original queue");
    assert!(finalizer.upgrade().is_some());
    assert_eq!(private.terminal.holds[0].custody.dispatch,PrivateDispatchPhase::Enqueued);
    assert!(private.terminal.holds[0].custody.pending.is_none());

    // Real participant revocation makes endpoint acquisition refuse while the
    // original registration, receiver, sender and queued capsule remain held.
    // No registry/authority field, outcome or phase is forced by this control.
    private.participant.revoke_admission(client,admitted(client).client_id).unwrap();
    assert!(private.endpoint_for(&f.registration).is_err());
    let answered_before=original.answer();
    assert!(Arc::ptr_eq(&original,private.terminal.holds[0].custody.completion.as_ref().unwrap()));
    assert_eq!(private.terminal.holds[0].custody.dispatch,PrivateDispatchPhase::Enqueued);
    assert!(private.terminal.holds[0].native.is_some());
    let (socket,_peer)=UnixStream::pair().unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert!(finalizer.upgrade().is_some(),"revocation did not destroy the actual queued capsule immediately before construction");
    let transport = XAuthorityOrderedTransport::bind(&f.registration, f.channels.ordered, &output, &wire, &pending, None)
        .unwrap_or_else(|_| panic!("this connection's own receiver and registration bind"));
    let returned=X11OrderedServingOwner::for_registration(private,&f.registration,transport);
    assert!(returned.is_err(),"the established endpoint refusal is returned");
    let payload_still_owned=finalizer.upgrade().is_some();
    assert_eq!(original.answer(),answered_before,"constructor failure does not change the completion answer");
    assert!(Arc::ptr_eq(&original,private.terminal.holds[0].custody.completion.as_ref().unwrap()));
    assert_eq!(private.terminal.holds[0].custody.dispatch,PrivateDispatchPhase::Enqueued);
    assert!(private.terminal.holds[0].native.is_some());
    assert!(payload_still_owned,"a refused constructor must return or durably retain its accepted receiver/capsule resources, not drop them through ?");
    drop(sender);
}

/// Drive a close to quiescence in bounded visits, reporting what each did.
fn close_to_quiet(
    owner: &mut X11OrderedServingOwner,
    cause: X11OrderedCloseCause,
) -> Vec<X11OrderedCloseStep> {
    owner
        .begin_close(cause)
        .unwrap_or_else(|kind| panic!("a socket pair ends: {kind:?}"));
    let mut steps = Vec::new();
    for _ in 0..32 {
        let step = owner.advance_close(XByteOrder::LittleEndian, 7);
        steps.push(step);
        if matches!(
            step,
            X11OrderedCloseStep::Quiet | X11OrderedCloseStep::Drained
        ) {
            break;
        }
    }
    steps
}

/// A serving owner for this fixture's own connection, with its output.
fn serving_owner_for(
    f: &mut PreparedOrderedFixture,
    socket: UnixStream,
) -> (X11OrderedServingOwner, Arc<Mutex<UnixStream>>) {
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(&f.registration, ordered, &output, &wire, &pending, None)
        .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));
    (owner, output)
}

#[test]
fn a_close_adjudicates_the_queued_admission_before_letting_its_payload_go() {
    // (a) The disposition is an answer this close established through the
    // capsule's own finalizer, not a client-wide sweep and not a drop whose
    // consequences someone else is assumed to clean up.
    let client = XServerFrontendClientId(7731);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77310, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 77310);
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    assert!(cell.answer().is_none(), "nothing has answered it yet");

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert!(
        matches!(
            steps.first(),
            Some(X11OrderedCloseStep::Adjudicated(
                PrivateAdjudication::Answered
            ))
        ),
        "the queued admission was offered an outcome, not discarded: {steps:?}"
    );
    let closing = owner.closing().expect("a close in progress");
    assert_eq!(
        (closing.answered, closing.already, closing.deferred),
        (1, 0, 0)
    );
    assert!(owner.retained_unanswered().is_empty() && owner.retained_foreign().is_empty());
    assert_eq!(
        cell.answer().map(|answer| answer.outcome),
        Some(XAuthorityInputDeliveryOutcome::ClientDisconnected),
        "and the answer is on the admission's own completion"
    );
    // The socket really ended. Read with a deadline: a connection that was
    // never ended would leave this waiting for a peer that is still there,
    // and a control that hangs says nothing.
    peer.set_read_timeout(Some(Duration::from_secs(2)))
        .expect("a deadline on the peer");
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).ok(),
        Some(0),
        "the peer sees the connection ended"
    );
}

#[test]
fn a_close_ends_the_socket_without_the_output_lock_it_may_be_stalled_under() {
    // (e) Ending a connection must not need the mutex a stalled write holds --
    // that is exactly when ending it is what is needed. The lock is held here
    // for the whole close.
    let client = XServerFrontendClientId(7741);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77410, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 77410);
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, output) = serving_owner_for(&mut f, socket);
    let held = output.lock().expect("the connection's own output");
    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    let closing = owner.closing().expect("a close in progress");
    assert_eq!(
        (closing.answered, closing.already, closing.deferred),
        (1, 0, 0),
        "and what it held was still offered an outcome: {steps:?}"
    );
    assert!(owner.retained_unanswered().is_empty());
    assert!(cell.answer().is_some());
    peer.set_read_timeout(Some(Duration::from_secs(2)))
        .expect("a deadline on the peer");
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).ok(),
        Some(0),
        "the peer sees it ended while the output lock was never released"
    );
    drop(held);
}

#[test]
fn a_close_under_a_held_claim_transfers_a_deferral_rather_than_an_answer() {
    // (c) A deferral is the authority taking reporting responsibility under a
    // claim it holds. Counting it as an answer would tell a caller the
    // admission was settled when what actually happened is that someone else
    // now owes the report.
    let client = XServerFrontendClientId(7761);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77610, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 77610);
    let recovery = private.broker.registry.input_recovery.clone();
    for _ in 0..8 {
        let _ = private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    // A real execution claim on this exact delivery, taken the ordinary way.
    let delivery = XAuthorityInputDeliveryId::from_raw(77610);
    assert_eq!(
        recovery.claim_execution(Some(delivery)),
        ExecutionClaim::Claimed,
        "the claim this control needs is the ledger's own"
    );

    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    let closing = owner.closing().expect("a close in progress");
    assert!(
        owner.retained_unanswered().is_empty(),
        "the offer was taken, in one form or another: {steps:?}"
    );
    assert_eq!(
        (closing.answered, closing.already, closing.deferred),
        (0, 0, 1),
        "and it was taken as a deferral, counted as itself"
    );
    assert!(
        cell.answer().is_none(),
        "a deferral is not a published answer: the claim still owes the report"
    );
}

#[test]
fn a_close_does_not_answer_a_capsule_belonging_to_another_endpoint() {
    // (d) This socket ending says nothing about another endpoint's recipient,
    // so a refused capsule is carried out still held rather than answered.
    let client = XServerFrontendClientId(7751);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77510, 272, true);

    let other = XServerFrontendClientId(7752);
    let other_window = XResourceId::new(0x307752, 1);
    let (other_registration, _other_channels) = {
        let p = f.runner.frontend.as_mut().unwrap();
        let registry = &p.broker.registry;
        let context = namespaced(other, f.namespace);
        let (registration, channels) = registry
            .register_client_with_admission(other, Some(context))
            .unwrap();
        registry.attach_private_lifecycle(&registration, context).unwrap();
        let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry
            .attach_connection_state(
                &registration,
                f.namespace,
                selected.clone(),
                Arc::new(AtomicU64::new(0)),
            )
            .unwrap();
        {
            let mut state = selected.lock().unwrap();
            state.register(
                other_window,
                XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
                Rect { x: 0, y: 0, width: 200, height: 100 },
            );
            state.observe_mapped(other_window);
            state.update(other_window, Some((1 << 2) | (1 << 3)), None);
        }
        let mut grabs = registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace, f.client.raw());
        grabs
            .grab_pointer(
                f.namespace,
                crate::XActiveInputGrab {
                    owner: other.raw(),
                    window: other_window,
                    owner_events: false,
                    pointer_mode: 1,
                    keyboard_mode: 1,
                    event_mask: u16::MAX,
                    xi_event_mask: [0; 8],
                    xi_event_mask_words: 0,
                    route_lease: None,
                },
            )
            .unwrap();
        (registration, channels)
    };
    attempt_run(&mut f, 77512, 273, true);

    let private = f.runner.frontend.as_mut().unwrap();
    let recovery = private.broker.registry.input_recovery.clone();
    let foreign_cell = admitted_cell(private, 77512);
    let foreign = {
        let record = private
            .terminal
            .holds
            .iter_mut()
            .find(|record| record.reached.client() == other)
            .expect("the other connection's own press");
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, other);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("it built its own capsule")
        };
        capsule
    };
    let sender = private
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("this connection's row")
        .ordered
        .clone();

    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    // STILL QUEUED, NEVER SERVED. The close path has to ask the same admission
    // question the serving path does: a capsule nobody classified is not this
    // connection's to answer for just because it is on its queue.
    gated_send(&sender, foreign).expect("onto this owner's queue");

    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert!(
        steps.contains(&X11OrderedCloseStep::Foreign),
        "the close classified it rather than offering for it: {steps:?}"
    );
    let closing = owner.closing().expect("a close in progress");
    assert_eq!(
        (closing.answered, closing.already, closing.deferred),
        (0, 0, 0),
        "nothing of another endpoint's was answered by this close"
    );
    let [held] = owner.retained_foreign() else {
        panic!("the foreign capsule is retained by the close")
    };
    assert_eq!(
        held.delivery().delivery(),
        XAuthorityInputDeliveryId::from_raw(77512)
    );
    assert_eq!(
        held.cause(),
        Some(X11OrderedAdmissionRefusal::ForeignEndpoint),
        "and still says why it was never this connection's to write"
    );
    assert!(
        foreign_cell.answer().is_none(),
        "closing this socket is not evidence about another endpoint's recipient"
    );
    drop(other_registration);
}

#[test]
fn a_close_retains_the_exact_capsule_when_the_authority_cannot_answer() {
    // The ordinary Refused branch: the authority takes nothing, so the close
    // consumes nothing. The capsule stays whole -- same completion, same
    // finalizer, same encoded bytes -- and its cell stays unanswered.
    let client = XServerFrontendClientId(7781);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 77810, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 77810);
    let recovery = private.broker.registry.input_recovery.clone();
    let sender = private
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .unwrap()
        .ordered
        .clone();
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    assert!(cell.answer().is_none());

    let (socket, peer) = UnixStream::pair().unwrap();
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    let capsule = owner.queue.try_recv().expect("the actual queued source press");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(77810)
    );
    assert!(Arc::ptr_eq(&cell, &capsule.finalizer().unwrap().completion));
    assert_eq!(Arc::strong_count(capsule.finalizer().unwrap()), 1);
    let original_finalizer = Arc::downgrade(capsule.finalizer().unwrap());
    let original_frames: Vec<Vec<u8>> = (0..capsule.emission().frame_count())
        .map(|index| {
            capsule
                .emission()
                .encode_frame(index, XByteOrder::LittleEndian, 7)
                .unwrap()
                .as_bytes()
                .to_vec()
        })
        .collect();
    assert!(!original_frames.is_empty());
    gated_send(&sender, capsule).unwrap();

    // The real mutex, poisoned without touching any ledger entry or outcome.
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = recovery.state.lock().unwrap();
            panic!("intentional recovery-lock poison for returned-refusal fixture");
        }))
        .is_err()
    );
    assert!(recovery.state.is_poisoned());

    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert!(
        steps.contains(&X11OrderedCloseStep::Adjudicated(
            PrivateAdjudication::Refused
        )),
        "the authority took nothing: {steps:?}"
    );
    let closing = owner.closing().expect("a close in progress");
    assert_eq!(
        (closing.answered, closing.already, closing.deferred),
        (0, 0, 0)
    );
    assert!(owner.retained_foreign().is_empty());
    let [held] = owner.retained_unanswered() else {
        panic!("the exact capsule is retained")
    };
    // The whole send state is kept, not the capsule alone: how far its bytes
    // got is part of what is still unknown about it.
    assert_eq!(held.frame_index(), 0);
    assert_eq!(held.blocked(), Duration::ZERO);
    let retained = held.delivery();
    assert_eq!(
        retained.delivery(),
        XAuthorityInputDeliveryId::from_raw(77810)
    );
    assert!(Arc::ptr_eq(&cell, &retained.finalizer().unwrap().completion));
    assert!(Arc::ptr_eq(
        &original_finalizer.upgrade().unwrap(),
        retained.finalizer().unwrap()
    ));
    let retained_frames: Vec<Vec<u8>> = (0..retained.emission().frame_count())
        .map(|index| {
            retained
                .emission()
                .encode_frame(index, XByteOrder::LittleEndian, 7)
                .unwrap()
                .as_bytes()
                .to_vec()
        })
        .collect();
    assert_eq!(retained_frames, original_frames);
    assert!(cell.answer().is_none());
    let mut byte = [0u8; 1];
    assert_eq!((&peer).read(&mut byte).unwrap(), 0);
}

#[test]
fn a_close_offers_the_end_of_a_connection_whatever_caused_it() {
    // A caller used to name the terminal outcome, so a close could record a
    // flush for bytes that were never written through a real finalizer. It
    // passes a cause now, and the cause is diagnostic: whichever one it is,
    // what the recipient is told is that the connection ended.
    for cause in [
        X11OrderedCloseCause::ConnectionEnded,
        X11OrderedCloseCause::PreparationFailed,
        X11OrderedCloseCause::SupervisorStopped,
    ] {
        let client = XServerFrontendClientId(7791);
        let mut f = prepared_ordered_fixture(client);
        attempt_run(&mut f, 77910, 272, true);
        let private = f.runner.frontend.as_mut().unwrap();
        let cell = admitted_cell(private, 77910);
        for _ in 0..8 {
            private.deliver_one(&mut |_, _| Ok(())).unwrap();
        }
        let (socket, _peer) = UnixStream::pair().unwrap();
        let (mut owner, _output) = serving_owner_for(&mut f, socket);
        let _ = close_to_quiet(&mut owner, cause);
        assert_eq!(
            cell.answer().map(|answer| answer.outcome),
            Some(XAuthorityInputDeliveryOutcome::ClientDisconnected),
            "no cause names a flush, a timeout or a write failure: {cause:?}"
        );
        assert_eq!(
            owner.closing().expect("closing").cause,
            cause,
            "the cause is kept for whoever reads it, and kept out of the answer"
        );
    }
}

#[test]
fn a_quiet_close_keeps_its_receiver_until_the_producers_are_actually_gone() {
    // An empty queue is not a stopped producer. While a sender for it is held
    // anywhere, a later capsule can still arrive, so a close that treated
    // Empty as the end would drop the receiver and lose whatever came next.
    let client = XServerFrontendClientId(7801);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78010, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78010);
    let sender = private
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("this connection's row")
        .ordered
        .clone();
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert_eq!(
        steps.last(),
        Some(&X11OrderedCloseStep::Quiet),
        "a held sender means quiet, not finished: {steps:?}"
    );
    assert!(cell.answer().is_some(), "and what was queued was answered");

    // The receiver was kept, so something arriving afterwards is still this
    // close's to account for rather than something it threw away.
    let late = {
        let private = f.runner.frontend.as_mut().unwrap();
        let recovery = private.broker.registry.input_recovery.clone();
        attempt_run(&mut f, 78012, 273, true);
        let private = f.runner.frontend.as_mut().unwrap();
        let record = private
            .terminal
            .holds
            .iter_mut()
            .find(|record| {
                record
                    .custody
                    .completion
                    .as_ref()
                    .is_some_and(|held| held.answer().is_none())
            })
            .expect("the later press");
        let emission = record.native.as_mut().unwrap().take_press_emission().unwrap();
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, client);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("it built its own capsule")
        };
        capsule
    };
    let late_cell = late.finalizer().expect("carried").completion.clone();
    gated_send(&sender, late).expect("the retained receiver still has a queue");
    assert!(matches!(
        owner.advance_close(XByteOrder::LittleEndian, 7),
        X11OrderedCloseStep::Adjudicated(_)
    ));
    assert!(
        late_cell.answer().is_some(),
        "a capsule that arrived after the close began is still accounted for"
    );

    // Only the producers actually going reports the end.
    drop(sender);
    f.runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .remove(&client);
    assert_eq!(
        owner.advance_close(XByteOrder::LittleEndian, 7),
        X11OrderedCloseStep::Drained,
        "with every sender gone, nothing further can arrive"
    );
}

#[test]
fn an_unusable_output_is_not_reported_as_an_empty_queue() {
    // Idle says there was nothing to do. An output this connection cannot take
    // says the opposite: something is owed and cannot be done. A caller told
    // the first would stop asking.
    let client = XServerFrontendClientId(7811);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78110, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78110);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, output) = serving_owner_for(&mut f, socket);

    // The real output mutex, poisoned without touching the socket or anything
    // this connection owes.
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = output.lock().unwrap();
            panic!("intentional output-lock poison for transport fixture");
        }))
        .is_err()
    );
    assert!(output.is_poisoned());

    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::TransportUnavailable
        ),
        "an unusable transport is its own answer"
    );
    assert!(
        owner.in_flight().is_none() && owner.refused().is_none(),
        "and nothing was received, written or disposed of"
    );
    assert!(
        cell.answer().is_none(),
        "a transport that could not be taken answers for nobody"
    );
}

#[test]
fn a_started_close_cannot_be_served_normally_again() {
    // Serving after a close has begun consumed the queued event and wrote at a
    // socket the close had already shut down, publishing WriteFailed through
    // the real finalizer -- a failure manufactured by a forbidden write,
    // recorded ahead of the ending the close was establishing. Two owners of
    // one admission is the whole problem.
    let client = XServerFrontendClientId(7821);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78210, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78210);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    owner
        .begin_close(X11OrderedCloseCause::ConnectionEnded)
        .expect("a socket pair ends");

    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::Closing
        ),
        "ordinary serving is over from the moment a close begins"
    );
    assert!(
        owner.in_flight().is_none(),
        "and it took nothing off the queue"
    );
    assert!(
        cell.answer().is_none(),
        "nothing was published by a write that must not have happened"
    );

    // The close itself is what answers it, and with the outcome a close knows.
    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert_eq!(
        cell.answer().map(|answer| answer.outcome),
        Some(XAuthorityInputDeliveryOutcome::ClientDisconnected),
        "{steps:?}"
    );
}

#[test]
fn a_close_reports_backpressure_rather_than_retaining_past_its_bound() {
    // Retention has to come from what is being retained. Growing the store
    // while holding custody is not reservation: it is finding out at the worst
    // moment that there was no room.
    let client = XServerFrontendClientId(7831);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78310, 272, true);

    let other = XServerFrontendClientId(7832);
    let other_window = XResourceId::new(0x307832, 1);
    let (other_registration, _other_channels) = {
        let p = f.runner.frontend.as_mut().unwrap();
        let registry = &p.broker.registry;
        let context = namespaced(other, f.namespace);
        let (registration, channels) = registry
            .register_client_with_admission(other, Some(context))
            .unwrap();
        registry.attach_private_lifecycle(&registration, context).unwrap();
        let selected = Arc::new(Mutex::new(XCoreEventSelectionState::default()));
        registry
            .attach_connection_state(
                &registration,
                f.namespace,
                selected.clone(),
                Arc::new(AtomicU64::new(0)),
            )
            .unwrap();
        {
            let mut state = selected.lock().unwrap();
            state.register(
                other_window,
                XResourceId::new(u64::from(X_SETUP_DEFAULT_ROOT), 1),
                Rect { x: 0, y: 0, width: 200, height: 100 },
            );
            state.observe_mapped(other_window);
            state.update(other_window, Some((1 << 2) | (1 << 3)), None);
        }
        let mut grabs = registry.input_authority.lock().unwrap();
        grabs.ungrab_pointer(f.namespace, f.client.raw());
        grabs
            .grab_pointer(
                f.namespace,
                crate::XActiveInputGrab {
                    owner: other.raw(),
                    window: other_window,
                    owner_events: false,
                    pointer_mode: 1,
                    keyboard_mode: 1,
                    event_mask: u16::MAX,
                    xi_event_mask: [0; 8],
                    xi_event_mask_words: 0,
                    route_lease: None,
                },
            )
            .unwrap();
        (registration, channels)
    };

    // Real foreign capsules, built one at a time by the source, deliberately
    // put on this connection's queue. Same staged wrong-queue boundary as the
    // other foreign controls; not a claim that the producer misroutes.
    let sender = {
        let private = f.runner.frontend.as_ref().unwrap();
        private
            .broker
            .registry
            .clients
            .lock()
            .unwrap()
            .get(&client)
            .expect("this connection's row")
            .ordered
            .clone()
    };
    let mut built = Vec::new();
    for index in 0..9u64 {
        // A distinct button each time: the same one joins the hold that exists
        // rather than beginning another, and this needs separate admissions.
        let delivery = 78320 + index;
        let button = 273 + u32::try_from(index).expect("small");
        f.ingress
            .submit(&f.keeper.lease(), button_to(
                f.surface,
                XAuthorityInputDeliveryId::from_raw(delivery),
                button,
                true,
            ))
            .unwrap();
        {
            let PrivatePreparedRunner {
                frontend,
                keyboards,
                watch,
                ..
            } = &mut f.runner;
            let private = frontend.as_mut().unwrap();
            private
                .step_once(keyboards, &mut |_, _| Ok(()), watch.as_ref().unwrap())
                .unwrap();
            let Some(PrivateOrderedItem::Ran { custody, .. }) = private.terminal.turn.pop() else {
                // The source will not accept another press here. However many
                // were built is what this control has to work with.
                break;
            };
            assert!(custody.observe().unwrap().is_some());
        }
        let private = f.runner.frontend.as_mut().unwrap();
        let recovery = private.broker.registry.input_recovery.clone();
        let cell = admitted_cell(private, delivery);
        let record = private
            .terminal
            .holds
            .iter_mut()
            .find(|record| {
                record
                    .custody
                    .completion
                    .as_ref()
                    .is_some_and(|held| Arc::ptr_eq(held, &cell))
            })
            .expect("this admission's own hold");
        assert_eq!(record.reached.client(), other, "owed to the other endpoint");
        let emission = record
            .native
            .as_mut()
            .unwrap()
            .take_press_emission()
            .expect("its own press emission");
        PrivateXServerFrontend::stow_press_capsule(&mut record.custody, emission, &recovery, other);
        let Some(PrivatePendingDelivery::Capsule(capsule)) = record.custody.pending.take() else {
            panic!("it built its own capsule")
        };
        built.push(capsule);
    }
    let bound = {
        let private = f.runner.frontend.as_ref().unwrap();
        private.broker.registry.per_client_input_capacity.get()
    };
    assert_eq!(
        built.len(),
        bound,
        "enough real foreign capsules to reach the bound exactly"
    );

    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    assert_eq!(owner.retention, bound, "retention is the queue's own capacity");
    owner
        .begin_close(X11OrderedCloseCause::ConnectionEnded)
        .expect("a socket pair ends");

    // One at a time, each classified and retained, right up to the bound.
    let mut retained = 0usize;
    for capsule in built {
        gated_send(&sender, capsule).expect("onto this connection's queue");
        assert_eq!(
            owner.advance_close(XByteOrder::LittleEndian, 7),
            X11OrderedCloseStep::Foreign,
            "another endpoint's capsule is classified and retained, never offered"
        );
        retained += 1;
    }
    assert_eq!(retained, bound);
    assert_eq!(owner.retained_foreign().len(), bound);

    // AT THE BOUND, NOT PAST IT. The next visit reports backpressure without
    // receiving anything, and the store is still exactly what was reserved.
    assert_eq!(
        owner.advance_close(XByteOrder::LittleEndian, 7),
        X11OrderedCloseStep::Backpressure,
        "retention at its bound is backpressure, not a bigger store"
    );
    assert_eq!(owner.retained_foreign().len(), bound, "nothing more was taken");
    assert_eq!(
        owner.retention_capacity(),
        (bound, bound),
        "and neither store ever grew to make room"
    );
    drop(other_registration);
}

#[test]
fn an_unterminated_close_publishes_nothing_and_a_real_retry_publishes_once() {
    // A close that could not end its wire recorded the fact and then nothing
    // read it: the driver tested only that a close existed, so it published
    // ClientDisconnected for an admission whose connection was still carrying
    // bytes. And asking again returned success because a close existed,
    // acknowledging an ending nobody had attempted a second time.
    //
    // STAGED AT THE STATE, AND SAID SO. std on this host gives no way to make
    // shutdown fail other than NotConnected, which is an ending; I tried an
    // already-ended handle and it reports success, so a control built that way
    // would silently exercise the happy path while looking like it covered
    // both. The refused termination is written directly instead. The retry
    // below is real: it calls the actual shutdown on the actual socket.
    let client = XServerFrontendClientId(7841);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78410, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78410);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    owner
        .begin_close(X11OrderedCloseCause::ConnectionEnded)
        .expect("the first attempt ends this socket");
    // Exactly what a refused shutdown leaves: the close is recorded, serving is
    // excluded, and termination is not a fact.
    {
        let closing = owner.closing.as_mut().expect("closing");
        closing.termination =
            X11OrderedTermination::Refused(std::io::ErrorKind::PermissionDenied);
        closing.attempts = 1;
    }

    // NOTHING DERIVED FROM AN ENDING THAT DID NOT HAPPEN.
    assert!(
        matches!(
            owner.advance_close(XByteOrder::LittleEndian, 7),
            X11OrderedCloseStep::TerminationUnconfirmed(std::io::ErrorKind::PermissionDenied)
        ),
        "the driver refuses to offer anything"
    );
    assert!(
        matches!(
            owner.adjudicate_in_flight(),
            X11OrderedCloseStep::TerminationUnconfirmed(std::io::ErrorKind::PermissionDenied)
        ),
        "and so does the offer itself, so a later caller cannot go round the driver"
    );
    assert!(
        cell.answer().is_none(),
        "an ending that did not happen answers nobody"
    );
    assert!(
        owner.in_flight().is_none(),
        "and nothing was received under an unconfirmed close"
    );
    // Serving stays excluded throughout.
    assert!(matches!(
        owner.serve_one(XByteOrder::LittleEndian, 7),
        X11OrderedServeStep::Closing
    ));

    // A REPEATED REQUEST IS A REAL RETRY. It calls the actual shutdown again,
    // keeps the original cause, and succeeds here.
    owner
        .begin_close(X11OrderedCloseCause::SupervisorStopped)
        .expect("the retry ends the wire");
    let closing = owner.closing().expect("closing");
    assert_eq!(
        closing.termination,
        X11OrderedTermination::Established,
        "and only that authorises anything"
    );
    assert_eq!(
        closing.cause,
        X11OrderedCloseCause::ConnectionEnded,
        "the original close's identity is kept, not replaced by the retry's"
    );
    assert_eq!(closing.attempts, 2, "the retry was an attempt, not a lookup");

    let steps = close_to_quiet(&mut owner, X11OrderedCloseCause::ConnectionEnded);
    assert_eq!(
        cell.answer().map(|answer| answer.outcome),
        Some(XAuthorityInputDeliveryOutcome::ClientDisconnected),
        "{steps:?}"
    );
    let published = steps
        .iter()
        .filter(|step| {
            matches!(
                step,
                X11OrderedCloseStep::Adjudicated(PrivateAdjudication::Answered)
            )
        })
        .count();
    assert_eq!(published, 1, "exactly one terminal publication: {steps:?}");
}

#[test]
fn a_close_stops_retrying_a_termination_that_keeps_refusing() {
    // The retry is bounded. A close that kept asking forever is one that never
    // finishes, and whoever is waiting for this connection to end waits with
    // it. Staged at the state, as above.
    let client = XServerFrontendClientId(7851);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78510, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78510);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }
    let (socket, _peer) = UnixStream::pair().unwrap();
    let (mut owner, _output) = serving_owner_for(&mut f, socket);
    owner
        .begin_close(X11OrderedCloseCause::ConnectionEnded)
        .expect("the first attempt ends this socket");
    {
        let closing = owner.closing.as_mut().expect("closing");
        closing.termination =
            X11OrderedTermination::Refused(std::io::ErrorKind::PermissionDenied);
        closing.attempts = X11_ORDERED_CLOSE_ATTEMPTS;
    }
    assert_eq!(
        owner.begin_close(X11OrderedCloseCause::ConnectionEnded),
        Err(std::io::ErrorKind::PermissionDenied),
        "past its bound it reports the unresolved termination rather than trying again"
    );
    assert_eq!(
        owner.closing().expect("closing").attempts,
        X11_ORDERED_CLOSE_ATTEMPTS,
        "and does not attempt past the bound"
    );
    assert!(cell.answer().is_none(), "still nothing offered");
}

#[test]
fn a_barred_wire_stops_every_writer_of_that_socket_including_control() {
    // A latch private to one writer fences only that writer. The permission is
    // the connection's, read under the same serialization every post-exposure
    // writer takes, so barring it closes the wire to all of them -- control
    // included, because control is the writer with PRIORITY, not the writer
    // allowed to follow the beginning of an event nobody can finish.
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = AtomicUsize::new(0);
    let sequence = AtomicU16::new(1);

    // Open: every path takes the wire.
    assert!(
        lock_x11_non_control_output(&output, &wire, &pending, None)
            .expect("a readable output")
            .is_some(),
        "the non-control path writes while the wire is open"
    );
    write_x11_control_records(
        &output,
        &wire,
        XByteOrder::LittleEndian,
        &sequence,
        vec![vec![0u8; 32]],
    )
    .expect("control writes while the wire is open");

    wire.bar();

    // Barred: every path refuses, and refuses for what it is.
    let non_control = lock_x11_non_control_output(&output, &wire, &pending, None)
        .expect_err("the non-control path is barred");
    assert!(
        non_control.client_failure,
        "a wire holding an unfinished event is this client's failure, not the service's"
    );
    let control = write_x11_control_records(
        &output,
        &wire,
        XByteOrder::LittleEndian,
        &sequence,
        vec![vec![0u8; 32]],
    )
    .expect_err("control is barred too");
    assert!(control.client_failure);
    assert!(
        !control.service_shutdown,
        "one connection's unusable wire does not end the service"
    );

    // And control never waits on its own pending counter: with a control
    // registered as pending, the control path still reaches its refusal rather
    // than spinning.
    pending.store(1, Ordering::Release);
    assert!(
        write_x11_control_records(
            &output,
            &wire,
            XByteOrder::LittleEndian,
            &sequence,
            vec![vec![0u8; 32]],
        )
        .is_err(),
        "control does not yield to control"
    );
}

#[test]
fn a_serving_owner_holds_its_connections_permission_not_one_of_its_own() {
    // What makes barring effective is that the owner holds the CONNECTION'S
    // permission. The trigger -- a shutdown that refuses after a part-written
    // frame -- is the branch this host gives me no honest way to reach, so
    // what this pins is the wiring: bar through the owner's own handle and
    // every writer of that socket is stopped.
    let client = XServerFrontendClientId(7861);
    let f = prepared_ordered_fixture(client);
    let (socket, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let transport =
        XAuthorityOrderedTransport::bind(&f.registration, f.channels.ordered, &output, &wire, &pending, None)
            .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    assert!(
        Arc::ptr_eq(&owner.wire, &wire),
        "the owner holds the connection's own permission, not a private latch"
    );
    let pending = AtomicUsize::new(0);
    assert!(
        lock_x11_non_control_output(&output, &wire, &pending, None)
            .expect("a readable output")
            .is_some()
    );

    // Barred through the handle the owner holds.
    owner.wire.bar();
    assert!(
        lock_x11_non_control_output(&output, &wire, &pending, None).is_err(),
        "barring through the owner stops the other writers of that socket"
    );
    // AND STOPS THE ORDERED STEP ITSELF. Holding the permission and never
    // asking it fenced nothing: the owner went on taking capsules and writing
    // them through the raw lock while every other writer was refused.
    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::WireBarred
        ),
        "the ordered step reads the same permission as everyone else"
    );
    assert!(
        owner.in_flight().is_none(),
        "and took nothing while it was barred"
    );
    assert!(
        write_x11_control_records(
            &output,
            &wire,
            XByteOrder::LittleEndian,
            &AtomicU16::new(1),
            vec![vec![0u8; 32]],
        )
        .is_err(),
        "control included"
    );
}

#[test]
fn an_ordered_step_yields_to_control_and_acts_on_being_stopped() {
    // Taking the raw lock skipped two things every other non-control writer
    // observes: the control-priority yield, and this writer's own stop. A stop
    // nothing acts on makes a join unbounded however carefully it was set.
    let client = XServerFrontendClientId(7871);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78710, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78710);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    // TOLD TO STOP WHILE CONTROL IS PENDING. It yields, sees the stop, and
    // leaves -- taking nothing, writing nothing, answering nothing, and saying
    // so rather than reporting an empty queue.
    pending.store(1, Ordering::Release);
    stop.store(true, Ordering::Release);
    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::Stopped
        ),
        "a stopped writer says it is leaving, not that there was nothing to do"
    );
    assert!(owner.in_flight().is_none(), "it took nothing");
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "and wrote nothing"
    );
    assert!(cell.answer().is_none(), "and answered nobody");

    // WITH NO CONTROL PENDING AT ALL. The shared wait only observes stop while
    // control is pending, so this is the case that saw nothing and served on.
    pending.store(0, Ordering::Release);
    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::Stopped
        ),
        "stop is this writer's own question, not one control has to raise"
    );
    assert!(owner.in_flight().is_none());
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "and still nothing written"
    );
    assert!(cell.answer().is_none());

    // Cleared: ordinary resumption. This proves serving after control has
    // finished and the stop is lifted -- not live waiting, which this control
    // does not test.
    stop.store(false, Ordering::Release);
    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::Advanced | X11OrderedServeStep::Flushed
        ),
        "with no stop and no control pending, its own event is served"
    );
}

#[test]
fn a_stop_set_while_waiting_for_the_output_is_seen_before_taking_custody() {
    // An entry-only check leaves the window between passing it and acquiring
    // serialization. This closes it from the other side: the stop is set while
    // the owner is blocked on the mutex, so it can only be seen by asking
    // again under the guard.
    let client = XServerFrontendClientId(7881);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78810, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78810);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_nonblocking(true).expect("a readable peer");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    // The parent takes the output, so the owner's serving step blocks on it.
    //
    // A COARSE RENDEZVOUS, AND NAMED AS ONE. The thread signals before calling
    // serve_one and the sleep only makes it likely the step is already blocked
    // on the mutex; a descheduled thread could still be at the entry check
    // when the stop is set, in which case this exercises that check instead.
    // Either way the required answer is the same, which is why it is asserted
    // here -- but this does not establish WHICH check saw it.
    let held = output.lock().expect("the connection's own output");
    let serving_stop = stop.clone();
    let (started, wait) = std::sync::mpsc::channel();
    let server = std::thread::spawn(move || {
        started.send(()).expect("started");
        let step = owner.serve_one(XByteOrder::LittleEndian, 7);
        (step, owner)
    });
    wait.recv().expect("the serving thread started");
    // It is now either about to take the lock or blocked on it. Setting the
    // stop here can only be observed by a check under the acquired guard.
    std::thread::sleep(Duration::from_millis(50));
    serving_stop.store(true, Ordering::Release);
    drop(held);

    let (step, owner) = server.join().expect("the serving thread finished");
    assert!(
        matches!(step, X11OrderedServeStep::Stopped),
        "a stop set while waiting for output is seen before custody is taken, got {step:?}"
    );
    assert!(owner.in_flight().is_none(), "it took nothing");
    let mut byte = [0u8; 1];
    assert!(
        matches!(
            (&peer).read(&mut byte),
            Err(ref error) if error.kind() == std::io::ErrorKind::WouldBlock
        ),
        "and wrote nothing"
    );
    assert!(cell.answer().is_none(), "and answered nobody");
}

#[test]
fn a_stop_mid_frame_leaves_the_wire_unusable_rather_than_yielding() {
    // Keeping custody is not enough when bytes are already on the wire: the
    // next writer to take the serialization puts its own event directly after
    // a prefix. The stop exit that the shared wait answers was reached without
    // ever asking about a begun frame, so that is exactly what happened.
    //
    // The prefix is real -- the source built the frame and five of its bytes
    // actually went -- and the stored progress is explicitly staged, because
    // nothing here produces a naturally interrupted send.
    let client = XServerFrontendClientId(7891);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 78910, 272, true);
    // A second admission, so one can be served and another staged mid-frame.
    attempt_run(&mut f, 78912, 273, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 78912);
    for _ in 0..16 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    // THE FIRST CAPSULE IS FINISHED THROUGH THE OWNER, not written and then
    // overwritten. Accepting Advanced and moving on would leave that delivery
    // owned and awaiting its own publication, and reading its bytes is not
    // that publication -- the staging below would be discarding custody rather
    // than adding to it.
    let first_cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 78910);
    let mut flushed = false;
    for _ in 0..16 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => {
                flushed = true;
                break;
            }
            other => panic!("its own first event is served: {other:?}"),
        }
    }
    assert!(flushed, "the first delivery finished through this owner");
    assert_eq!(
        first_cell.answer().map(|answer| answer.outcome),
        Some(XAuthorityInputDeliveryOutcome::Flushed),
        "and was published for its own admission"
    );
    assert!(owner.in_flight().is_none(), "so its slot is free");
    let mut drained = [0u8; 4096];
    while (&peer).read(&mut drained).is_ok_and(|read| read > 0) {}
    let taken = owner.queue.try_recv().expect("its next event");
    let frame = taken
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 7)
        .expect("its own first frame");
    {
        let mut socket = output.lock().expect("the connection's output");
        (*socket)
            .write_all(&frame.as_bytes()[..5])
            .expect("five real bytes of it go");
    }
    let staged_len = frame.as_bytes().len();
    assert!(staged_len > 5, "the frame really is longer than its prefix");
    owner.in_flight = Some(X11OrderedInFlight {
        delivery: taken,
        frame: 0,
        send: X11OrderedSendState {
            frame: Some(X11OrderedFrame {
                bytes: frame,
                progress: X11OrderedSendProgress::Sent(5),
            }),
            blocked: Duration::ZERO,
        },
    });
    assert!(owner.mid_frame(), "a frame is begun and not finished");

    // A WRITER IS ALREADY INSIDE. It passed the permission and holds the
    // serialization; setting the flag stops later admissions and retracts
    // nothing from this one. If the stop exit only barred, this writer would
    // resume and put its event straight after the prefix.
    let holder_output = output.clone();
    let holder_left = Arc::new(AtomicBool::new(false));
    let holder_flag = holder_left.clone();
    let (inside, resumed) = std::sync::mpsc::channel();
    let (release, wait_release) = std::sync::mpsc::channel();
    let holder = std::thread::spawn(move || {
        let mut socket = holder_output.lock().expect("the connection's output");
        inside.send(()).expect("inside");
        wait_release.recv().expect("released");
        let wrote = (*socket).write_all(&[0xABu8; 32]).is_ok();
        // WHAT THIS FLAG WITNESSES, exactly: that this writer's write attempt
        // finished. It is stored before the guard goes, so it does not witness
        // the release -- and moving it after the drop would only trade one
        // scheduling assumption for another. What the assertion below rests on
        // is the narrower fact that the step cannot have decided before this
        // writer had done its work, which is what "a flag retracts nothing
        // from a writer already inside" means.
        holder_flag.store(true, Ordering::Release);
        drop(socket);
        wrote
    });
    resumed.recv().expect("the other writer holds the output");

    // Told to stop, with control pending so the shared wait is the exit taken.
    pending.store(1, Ordering::Release);
    stop.store(true, Ordering::Release);
    let observed = holder_left.clone();
    let stepper = std::thread::spawn(move || {
        let step = owner.serve_one(XByteOrder::LittleEndian, 7);
        // Read the instant the step decided, not after the join. The sleep
        // above does not prove the stepper had reached acquisition, so this
        // does not establish where it was waiting -- only that it did not
        // decide before the writer already inside had finished writing.
        let had_left = observed.load(Ordering::Acquire);
        (step, had_left, owner)
    });
    std::thread::sleep(Duration::from_millis(100));
    release.send(()).expect("let the inside writer go");
    let _inside_wrote = holder.join().expect("the inside writer finished");
    let (step, had_left, mut owner) = stepper.join().expect("the serving thread finished");
    assert!(
        matches!(step, X11OrderedServeStep::Stopped),
        "the writer is leaving: {step:?}"
    );
    assert!(
        had_left,
        "exclusion was claimed before the writer already inside had finished: \
         a flag stops later admissions and retracts nothing from one already in"
    );
    let _ = &mut owner;

    // AND THE WIRE IS NOT LEFT FOR ANYONE ELSE.
    assert!(
        wire.barred(),
        "a prefix with no writer to finish it makes the wire unusable"
    );
    assert!(
        write_x11_control_records(
            &output,
            &wire,
            XByteOrder::LittleEndian,
            &AtomicU16::new(1),
            vec![vec![0u8; 32]],
        )
        .is_err(),
        "so no control event lands directly after those five bytes"
    );
    // The obligation is not what ended. The connection is.
    assert!(owner.in_flight().is_some(), "the delivery stays owned");
    assert!(cell.answer().is_none(), "and nobody answered for it");
}

#[test]
fn a_stop_arriving_after_admission_also_ends_a_wire_mid_frame() {
    // The other stop exit: admitted because nothing was pending and no stop was
    // set, then told to stop before the recheck under serialization. With a
    // frame begun it must end the wire there too, not simply hand the guard
    // back. Same staging note as the sibling control -- the prefix is real,
    // the stored progress is staged.
    let client = XServerFrontendClientId(7901);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 79010, 272, true);
    attempt_run(&mut f, 79012, 273, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 79012);
    for _ in 0..16 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    // THE FIRST CAPSULE IS FINISHED THROUGH THE OWNER, not written and then
    // overwritten. Accepting Advanced and moving on would leave that delivery
    // owned and awaiting its own publication, and reading its bytes is not
    // that publication -- the staging below would be discarding custody rather
    // than adding to it.
    let first_cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 79010);
    let mut flushed = false;
    for _ in 0..16 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => {
                flushed = true;
                break;
            }
            other => panic!("its own first event is served: {other:?}"),
        }
    }
    assert!(flushed, "the first delivery finished through this owner");
    assert_eq!(
        first_cell.answer().map(|answer| answer.outcome),
        Some(XAuthorityInputDeliveryOutcome::Flushed),
        "and was published for its own admission"
    );
    assert!(owner.in_flight().is_none(), "so its slot is free");
    let mut drained = [0u8; 4096];
    while (&peer).read(&mut drained).is_ok_and(|read| read > 0) {}
    let taken = owner.queue.try_recv().expect("its next event");
    let frame = taken
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 7)
        .expect("its own first frame");
    {
        let mut socket = output.lock().expect("the connection's output");
        (*socket)
            .write_all(&frame.as_bytes()[..5])
            .expect("five real bytes of it go");
    }
    owner.in_flight = Some(X11OrderedInFlight {
        delivery: taken,
        frame: 0,
        send: X11OrderedSendState {
            frame: Some(X11OrderedFrame {
                bytes: frame,
                progress: X11OrderedSendProgress::Sent(5),
            }),
            blocked: Duration::ZERO,
        },
    });
    assert!(owner.mid_frame());

    // Nothing pending and no stop, so the helper admits; the parent holds the
    // output, so the step blocks after that admission. The stop is set while
    // it is blocked, which only the recheck can see.
    let held = output.lock().expect("the connection's own output");
    let serving_stop = stop.clone();
    let (started, wait) = std::sync::mpsc::channel();
    let server = std::thread::spawn(move || {
        started.send(()).expect("started");
        let step = owner.serve_one(XByteOrder::LittleEndian, 7);
        (step, owner)
    });
    wait.recv().expect("the serving thread started");
    std::thread::sleep(Duration::from_millis(50));
    serving_stop.store(true, Ordering::Release);
    drop(held);

    let (step, owner) = server.join().expect("the serving thread finished");
    assert!(
        matches!(step, X11OrderedServeStep::Stopped),
        "the writer is leaving: {step:?}"
    );
    assert!(
        wire.barred(),
        "and the wire it left a prefix on is unusable"
    );
    assert!(
        write_x11_control_records(
            &output,
            &wire,
            XByteOrder::LittleEndian,
            &AtomicU16::new(1),
            vec![vec![0u8; 32]],
        )
        .is_err(),
        "so nothing lands after those five bytes"
    );
    assert!(owner.in_flight().is_some(), "the delivery stays owned");
    assert!(cell.answer().is_none());
}

#[test]
fn a_stop_that_cannot_take_the_output_claims_nothing_and_says_why() {
    // Failing to acquire the output is not a shutdown error, and recording one
    // would describe a syscall never made. Exclusion is not established, so it
    // is not claimed, and the reason is kept as its own kind.
    let client = XServerFrontendClientId(7911);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 79110, 272, true);
    attempt_run(&mut f, 79112, 273, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 79112);
    for _ in 0..16 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    let first_cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 79110);
    let mut flushed = false;
    for _ in 0..16 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => {
                flushed = true;
                break;
            }
            other => panic!("its own first event is served: {other:?}"),
        }
    }
    assert!(flushed);
    assert!(first_cell.answer().is_some());
    let mut drained = [0u8; 4096];
    while (&peer).read(&mut drained).is_ok_and(|read| read > 0) {}

    let taken = owner.queue.try_recv().expect("its next event");
    let frame = taken
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 7)
        .expect("its own first frame");
    {
        let mut socket = output.lock().expect("the connection's output");
        (*socket)
            .write_all(&frame.as_bytes()[..5])
            .expect("five real bytes of it go");
    }
    owner.in_flight = Some(X11OrderedInFlight {
        delivery: taken,
        frame: 0,
        send: X11OrderedSendState {
            frame: Some(X11OrderedFrame {
                bytes: frame,
                progress: X11OrderedSendProgress::Sent(5),
            }),
            blocked: Duration::ZERO,
        },
    });

    // The real output mutex, poisoned without touching the socket.
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = output.lock().unwrap();
            panic!("intentional output-lock poison for acquisition fixture");
        }))
        .is_err()
    );
    assert!(output.is_poisoned());

    pending.store(1, Ordering::Release);
    stop.store(true, Ordering::Release);
    assert!(
        matches!(
            owner.serve_one(XByteOrder::LittleEndian, 7),
            X11OrderedServeStep::Unterminated
        ),
        "exclusion could not be established, so nothing is claimed"
    );
    assert_eq!(
        owner.unterminated_cause(),
        Some(X11OrderedUnterminatedCause::OutputUnavailable),
        "and the reason is its own kind, not an invented shutdown error"
    );
    assert!(
        !wire.barred(),
        "no exclusion was claimed over a wire this could not take"
    );
    assert!(owner.in_flight().is_some(), "the delivery stays owned");
    assert!(cell.answer().is_none());
}

#[test]
fn a_continuation_place_is_taken_before_exposure_and_kept_while_work_remains() {
    // The bound covers live connections and retained leftovers together. A
    // connection that returned its place while still owing work would let a
    // churn of connections grow retention without limit, which is the whole
    // reason the two share one number.
    let client = XServerFrontendClientId(7921);
    let f = prepared_ordered_fixture(client);
    // UNCONFIGURED ADMITS NOTHING. A connection bound is not the
    // abandoned-work capacity; an owner that inherited one for the other would
    // allow as many connections as it happens to allow obligations, which is a
    // number nobody chose.
    let unconfigured = PrivateSettlementOwner::with_capacity(4);
    assert!(
        matches!(
            unconfigured.reserve_ordered_continuation(),
            Err(AdmissionRefusal::Saturated)
        ),
        "no connection is exposed against a bound nobody set"
    );

    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    assert_eq!(durable.continuations_reserved(), Some(0));

    let first = durable
        .reserve_ordered_continuation()
        .expect("a place for the first connection");
    let second = durable
        .reserve_ordered_continuation()
        .expect("a place for the second");
    assert_eq!(durable.continuations_reserved(), Some(2));

    // EXHAUSTED BEFORE PUBLICATION. A third connection cannot be exposed,
    // because there would be nowhere for what it accepted to go.
    assert!(
        matches!(
            durable.reserve_ordered_continuation(),
            Err(AdmissionRefusal::Saturated)
        ),
        "a connection that cannot be handed over is not built"
    );

    // A connection that finished owing nothing gives its place back.
    first.finish();
    assert_eq!(durable.continuations_reserved(), Some(1));
    let third = durable
        .reserve_ordered_continuation()
        .expect("the returned place is reusable");
    assert_eq!(durable.continuations_reserved(), Some(2));

    // AND ONE THAT STILL OWES WORK KEEPS ITS PLACE. Installing is not
    // returning: the leftovers occupy the place they were promised.
    // A real admission accepted into this connection's queue before anything
    // could be built for it -- the window the Setup case exists for.
    let sender = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("this connection's row")
        .ordered
        .clone();
    let (emission, _endpoint) =
        private_native_tests::emission_and_endpoint_for_writer_fixture(79210);
    let stranded = XAuthorityOrderedDelivery::from_emission(emission).unwrap();
    gated_send(&sender, stranded).expect("accepted into its queue");

    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(second, &mut source), PrivateContinuationCommit::Retained);
    assert!(source.is_none(), "it left the caller's slot");
    // AND IT IS STILL THERE. The queue came with the place, so an admission
    // accepted before a serving owner existed is not lost with the setup that
    // failed.
    let survived = durable
        .with_ordered_continuation(1, |continuation| {
            continuation
                .queue()
                .try_recv()
                .map(|capsule| capsule.delivery())
        })
        .expect("the place holds it");
    assert_eq!(
        survived.expect("the stranded admission"),
        XAuthorityInputDeliveryId::from_raw(79210),
        "accepted before the owner existed, and retained with its queue"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(2),
        "retained work still occupies its place"
    );
    assert_eq!(durable.continuations_retained(), Some(1));
    assert!(
        matches!(
            durable.reserve_ordered_continuation(),
            Err(AdmissionRefusal::Saturated)
        ),
        "so a reconnect cannot take a place the leftovers still hold"
    );
    assert_eq!(durable.continuations_abandoned(), Some(0));
    drop(third);
    assert_eq!(
        durable.continuations_abandoned(),
        Some(1),
        "a place whose holder disposed of neither is marked, not handed out again"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(2),
        "and stays taken"
    );
}

#[test]
fn a_whole_serving_owner_moves_into_its_place_with_everything_it_held() {
    // One ownership move. Nothing is unpacked, rebuilt, reselected or looked
    // up again: what arrives is what left, including how far a frame got and
    // why an ending refused.
    let client = XServerFrontendClientId(7931);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 79310, 272, true);
    attempt_run(&mut f, 79312, 273, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let staged_cell = admitted_cell(private, 79312);
    for _ in 0..16 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(f.client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(f.client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    let private = f.runner.frontend.as_ref().unwrap();
    let mut owner = X11OrderedServingOwner::for_registration(private, &f.registration, transport)
        .unwrap_or_else(|(refusal, _)| panic!("an owner for this registration: {refusal:?}"));

    // Its first event finishes properly, so what is staged below adds to this
    // owner's custody rather than replacing it.
    let first_cell = admitted_cell(f.runner.frontend.as_ref().unwrap(), 79310);
    let mut flushed = false;
    for _ in 0..16 {
        match owner.serve_one(XByteOrder::LittleEndian, 7) {
            X11OrderedServeStep::Advanced => {}
            X11OrderedServeStep::Flushed => {
                flushed = true;
                break;
            }
            other => panic!("its own first event is served: {other:?}"),
        }
    }
    assert!(flushed && first_cell.answer().is_some());
    let mut drained = [0u8; 4096];
    while (&peer).read(&mut drained).is_ok_and(|read| read > 0) {}

    // A real capsule with a real prefix written and its progress staged.
    let taken = owner.queue.try_recv().expect("its next event");
    let staged_finalizer = Arc::downgrade(taken.finalizer().expect("carried"));
    let frame = taken
        .emission()
        .encode_frame(0, XByteOrder::LittleEndian, 7)
        .expect("its own first frame");
    let staged_bytes = frame.as_bytes().to_vec();
    {
        let mut socket = output.lock().expect("the connection's output");
        (*socket)
            .write_all(&staged_bytes[..5])
            .expect("five real bytes of it go");
    }
    owner.in_flight = Some(X11OrderedInFlight {
        delivery: taken,
        frame: 0,
        send: X11OrderedSendState {
            frame: Some(X11OrderedFrame {
                bytes: frame,
                progress: X11OrderedSendProgress::Sent(5),
            }),
            blocked: Duration::ZERO,
        },
    });
    // And a failed ending, so a typed cause travels with it.
    owner.unterminated = true;
    owner.unterminated_cause =
        Some(X11OrderedUnterminatedCause::Shutdown(std::io::ErrorKind::PermissionDenied));

    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before this connection was exposed");
    let mut source = Some(PrivateOrderedContinuation::Serving {
        owner: home_holding(owner),
        // STAGED, NOT OBSERVED. No teardown ran in this control; this is the
        // value a record installed by one would carry, set directly because
        // the subject here is what arrives in the place, not what writes this
        // field.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
    assert!(source.is_none(), "it left the caller's slot");
    assert_eq!(durable.continuations_retained(), Some(1));

    // EVERYTHING ARRIVED. Read through a borrow of the stored record.
    let checked = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Serving { owner, .. } = continuation else {
                panic!("a serving owner was installed")
            };
            let held = owner.in_flight().expect("its in-flight record");
            let frame = held
                .send
                .frame
                .as_ref()
                .expect("the frame it was part way through");
            (
                held.delivery().delivery(),
                frame.progress,
                frame.bytes.as_bytes().to_vec(),
                owner.unterminated_cause(),
                Arc::ptr_eq(
                    held.delivery().finalizer().expect("carried"),
                    &staged_finalizer.upgrade().expect("still alive"),
                ),
            )
        })
        .expect("the place holds it");
    assert_eq!(checked.0, XAuthorityInputDeliveryId::from_raw(79312));
    assert_eq!(
        checked.1,
        X11OrderedSendProgress::Sent(5),
        "how far its bytes got came with it"
    );
    assert_eq!(checked.2, staged_bytes, "and the exact bytes, not re-encoded");
    assert_eq!(
        checked.3,
        Some(X11OrderedUnterminatedCause::Shutdown(
            std::io::ErrorKind::PermissionDenied
        )),
        "and why its ending refused"
    );
    assert!(checked.4, "carrying its own original finalizer");
    assert!(
        staged_cell.answer().is_none(),
        "a transfer answers nobody"
    );
}

#[test]
fn an_unreadable_owner_does_not_make_an_accepted_transfer_optional() {
    // The work has been accepted and the place is this connection's. Skipping
    // the move because the aggregate lock is unreadable would drop it, which
    // is the one thing a reserved destination exists to prevent.
    let client = XServerFrontendClientId(7941);
    let f = prepared_ordered_fixture(client);
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");

    // The real settlement mutex, poisoned without touching any record.
    let poisoner = durable.clone();
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = poisoner.inner.lock().unwrap();
            panic!("intentional settlement-lock poison for transfer fixture");
        }))
        .is_err()
    );
    assert!(durable.inner.is_poisoned());
    assert_eq!(
        durable.continuations_retained(),
        None,
        "and an ordinary read of it now refuses"
    );

    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    // It went in anyway, and can be read back through the same fail-closed
    // discipline every other already-accepted move here uses.
    let held = durable
        .with_ordered_continuation(0, |continuation| {
            matches!(
                continuation,
                PrivateOrderedContinuation::Setup {
                    refusal: X11OrderedServingRefusal::TransportUnavailable,
                    ..
                }
            )
        })
        .expect("the place holds it");
    assert!(held, "the accepted transfer happened despite the poison");
}

#[test]
fn driving_a_continuation_does_not_hold_the_store_behind_it() {
    // The helper's comment promised the aggregate lock was released and the
    // code held it across the callback, so every other retained connection sat
    // behind whichever one was being driven -- and a close that waits on its
    // output would have taken that wait under the settlement lock.
    let client = XServerFrontendClientId(7951);
    let f = prepared_ordered_fixture(client);
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    // Asked from inside the callback, about the real store.
    let store_free = durable
        .with_ordered_continuation(0, |_| durable.inner.try_lock().is_ok())
        .expect("the place holds it");
    assert!(
        store_free,
        "the settlement lock is released before a record is driven"
    );

    // And another place can still be reserved while one is being driven.
    let reserved_during = durable
        .with_ordered_continuation(0, |_| durable.reserve_ordered_continuation().is_ok())
        .expect("the place holds it");
    assert!(
        reserved_during,
        "one retained connection does not block the store for the rest"
    );
}

#[test]
fn a_bound_transport_that_could_not_be_served_keeps_its_ending_handle() {
    // How far setup got decides what there is to keep. A receiver that was
    // published but never bound has its queue; one that was bound has the
    // connection's output, its permission and -- the part that matters -- the
    // independent handle that can still end a wire nobody will serve. Keeping
    // only the queue there would discard the one thing able to terminate it.
    let client = XServerFrontendClientId(7971);
    let mut f = prepared_ordered_fixture(client);
    attempt_run(&mut f, 79710, 272, true);
    let private = f.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 79710);
    for _ in 0..8 {
        private.deliver_one(&mut |_, _| Ok(())).unwrap();
    }

    let PreparedOrderedFixture {
        mut runner,
        durable: _fixture_durable,
        registration,
        channels,
        ..
    } = f;
    let private = runner.frontend.as_mut().unwrap();
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let transport = XAuthorityOrderedTransport::bind(
        &registration,
        channels.ordered,
        &output,
        &wire,
        &pending,
        None,
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));

    // The registration stops being the current row, so serving cannot be
    // prepared -- with the transport already bound and holding real work.
    //
    // NO REPLACEMENT IS MADE, AND NONE IS NEEDED. What this control is about
    // is a registration that is no longer current, which removing the row
    // establishes on its own. A successor at the same number could not exist
    // here anyway: this registration still holds that number.
    private
        .participant
        .revoke_admission(client, admitted(client).client_id)
        .expect("the admission this fixture made is the one it revokes");
    private
        .broker
        .registry
        .clients
        .lock()
        .expect("a readable registry")
        .remove(&client);
    let (refusal, returned) =
        X11OrderedServingOwner::for_registration(private, &registration, transport)
            .err()
            .expect("a stale registration prepares no writer");

    // RETAINED WHOLE, ending handle included.
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Transport(Box::new(returned)),
        refusal,
        // Torn down, with its endpoint closed: the only way a record reaches
        // a place.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
    assert!(source.is_none());

    let ended = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup {
                accepted: PrivateOrderedSetupCustody::Transport(transport),
                ..
            } = continuation
            else {
                panic!("a bound transport was retained")
            };
            // Its queue came with it, and so did the handle that can end the
            // wire without the output lock.
            let queued = transport.ordered.try_recv().map(|capsule| capsule.delivery());
            let ended = transport.shutdown.shutdown(Shutdown::Both).is_ok();
            (queued, ended)
        })
        .expect("the place holds it");
    assert_eq!(
        ended.0.expect("the accepted admission came with it"),
        XAuthorityInputDeliveryId::from_raw(79710)
    );
    assert!(
        ended.1,
        "and the retained transport can still end the connection"
    );
    let mut byte = [0u8; 1];
    assert_eq!(
        (&peer).read(&mut byte).ok(),
        Some(0),
        "which the peer sees"
    );
    assert!(cell.answer().is_none(), "retention answers nobody");
    drop(registration);
    drop(runner);
}

#[test]
fn a_handover_waits_for_the_destination_reserved_for_it() {
    // The record was made while installing, so the one interval that must
    // contain nothing fallible contained an allocation: between taking a
    // connection's work out of its source and putting it somewhere. The
    // aggregate's reserved place and the record are different storage, and
    // reserving has to make both.
    let client = XServerFrontendClientId(7981);
    let f = prepared_ordered_fixture(client);
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");

    // WHAT THIS ESTABLISHES: that a home exists and is empty from the moment
    // its place is reserved, that a binding does not COMPLETE while something
    // holds that home, and that it completes once released. One owner, and a
    // handle is a way to ask rather than a way in.
    //
    // It does NOT establish where the other thread has got to -- a signal
    // before the attempt plus a sleep proves neither entry nor ordering -- and
    // there is no longer any take to order against an acquisition: the payload
    // goes into its home when the connection binds and is never anywhere
    // else.
    let record = {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(record) = &held.continuations[0] else {
            panic!("reserving made the record")
        };
        record.clone()
    };
    assert!(
        !record.occupied(),
        "made empty, at reservation"
    );

    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });

    // Held directly, because what is being established is that nothing else
    // gets at this home while a holder has it.
    let blocker = record.state.lock().expect("hold the destination");
    let (started, wait) = std::sync::mpsc::channel();
    let (checked, report) = std::sync::mpsc::channel();
    let installer = std::thread::spawn(move || {
        started.send(()).expect("started");
        assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
        checked.send(source.is_none()).expect("reported");
    });
    wait.recv().expect("the binding thread started");
    std::thread::sleep(Duration::from_millis(100));
    assert!(
        report.try_recv().is_err(),
        "a binding does not complete while something holds the home"
    );
    drop(blocker);
    let took = report.recv().expect("the binding finished");
    installer.join().expect("the binding thread finished");
    assert!(took, "and then it went in");

    assert_eq!(durable.continuations_retained(), Some(1));
    assert_eq!(durable.continuations_abandoned(), Some(0));
}

#[test]
fn a_handover_with_nothing_to_hand_over_is_recorded_rather_than_counted_done() {
    // Installing an empty source left the place looking taken by someone who
    // would come back for it, while no holder or driver remained. It is not
    // installed and not released; it is reported.
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let mut empty = None;
    assert_eq!(retain_into(slot, &mut empty), PrivateContinuationCommit::NothingBound);
    assert_eq!(durable.continuations_retained(), Some(0), "nothing installed");
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "and the place is not handed out again"
    );
    assert_eq!(
        durable.continuations_abandoned(),
        Some(1),
        "it is recorded as having no holder, not counted as done"
    );
}

#[test]
fn reading_the_store_does_not_take_a_record_beneath_it() {
    // Driving holds a record and may enter settlement. A reader that took a
    // record while holding the store would close that cycle from the other
    // side, so the store must be released before any record is read.
    let client = XServerFrontendClientId(7991);
    let f = prepared_ordered_fixture(client);
    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    let record = {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(record) = &held.continuations[0] else {
            panic!("its place holds the record")
        };
        record.clone()
    };

    // The record is held, as a driver would hold it. The store must stay
    // available to everyone else.
    let blocker = record.state.lock().expect("hold the record");
    assert!(
        durable.inner.try_lock().is_ok(),
        "the store is not behind a record"
    );
    let reporting = durable.clone();
    let reader = std::thread::spawn(move || reporting.continuations_retained());
    // The sleep does NOT establish that the reader reached the record lock --
    // a descheduled thread may not have started. What this half asserts is the
    // weaker fact that the store stays available while a reader is outstanding
    // and the record is held; the stronger claim about that exact interval is
    // not established here.
    std::thread::sleep(Duration::from_millis(100));
    assert!(
        durable.inner.try_lock().is_ok(),
        "the store stays available while a reader is outstanding"
    );
    drop(blocker);
    assert_eq!(
        reader.join().expect("the reader finished"),
        Some(1),
        "and it reports once the record is free"
    );
}

#[test]
fn an_unreadable_retained_record_is_not_reported_as_absent() {
    // Counting a poisoned record as empty publishes a zero for an obligation
    // that is still owned and still unanswered, which is the one answer a
    // caller must not be given.
    let client = XServerFrontendClientId(8001);
    let f = prepared_ordered_fixture(client);
    let sender = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("this connection's row")
        .ordered
        .clone();
    let (emission, _endpoint) =
        private_native_tests::emission_and_endpoint_for_writer_fixture(80010);
    gated_send(
        &sender,
        XAuthorityOrderedDelivery::from_emission(emission).unwrap(),
    )
    .expect("accepted into its queue");

    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let PreparedOrderedFixture { channels, .. } = f;
    let mut source = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
    assert_eq!(durable.continuations_retained(), Some(1));

    // A real panic while a record is borrowed poisons only that record.
    let record = {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(record) = &held.continuations[0] else {
            panic!("its place holds the record")
        };
        record.clone()
    };
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = record.state.lock().unwrap();
            panic!("intentional record poison for reporting fixture");
        }))
        .is_err()
    );
    assert!(record.unreadable());
    assert!(
        durable.inner.try_lock().is_ok(),
        "the store itself is still readable"
    );

    assert_eq!(
        durable.continuations_retained(),
        None,
        "an unreadable record is not an absent one"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "and its place is still taken"
    );
}

#[test]
fn a_quiet_continuation_keeps_its_place_and_does_not_starve_the_others() {
    // A place comes back when its work is gone, not when its queue falls
    // quiet: producers may still hold senders for it. And one record that
    // cannot progress must not take every visit, or the rest are never driven.
    let first = XServerFrontendClientId(8011);
    let second = XServerFrontendClientId(8012);
    let one = prepared_ordered_fixture(first);
    let two = prepared_ordered_fixture(second);
    // A sender for the first is kept alive, so its queue is quiet rather than
    // finished. The second's producers go.
    let live_sender = one
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&first)
        .expect("its row")
        .ordered
        .clone();

    let durable = PrivateSettlementOwner::with_capacities(4, 4);
    let mut places = Vec::new();
    for fixture in [one, two] {
        let slot = durable
            .reserve_ordered_continuation()
            .expect("a place, reserved before exposure");
        let PreparedOrderedFixture {
            channels,
            registration,
            ..
        } = fixture;
        // Bound, so a visit can actually end this wire. A receiver alone has
        // nothing to end with and could never reach a settled record, which
        // would make this control about the wrong thing.
        let mut source = Some(transport_continuation(&registration, channels.ordered));
        // And then gone, along with the row it published: a registration that
        // stayed would be a producer still holding a sender, which is the one
        // thing that keeps a queue from finishing.
        drop(registration);
        assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);
        places.push(());
    }
    assert_eq!(durable.continuations_reserved(), Some(2));
    assert_eq!(durable.continuations_retained(), Some(2));

    // EVERY RECORD GETS A VISIT. The first cannot finish -- a sender for it is
    // still held -- and that must not stop the second being reached.
    let driven = durable.drive_ordered_continuations(4);
    assert_eq!(driven, 4, "each visit reached a record");
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the one whose producers are gone gave its place back"
    );
    assert_eq!(durable.continuations_retained(), Some(1));

    // The quiet one keeps its place for as long as anything can still send.
    for _ in 0..4 {
        durable.drive_ordered_continuations(2);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "a quiet queue is not a finished one while a sender is held"
    );
    drop(live_sender);
    durable.drive_ordered_continuations(2);
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "and it comes back once nothing can send to it"
    );
    assert_eq!(durable.continuations_retained(), Some(0));
    let _ = places;
}

#[test]
fn asking_whether_a_continuation_is_settled_destroys_nothing() {
    // Receiving is the only way to question a channel, so a predicate that
    // questioned one consumed whatever was waiting and reported on work it had
    // just destroyed. The admission is real and its finalizer is watched by a
    // Weak, so a capsule thrown away by the question would be visible as gone.
    let client = XServerFrontendClientId(8021);
    let f = prepared_ordered_fixture(client);
    let sender = f
        .runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .clients
        .lock()
        .unwrap()
        .get(&client)
        .expect("this connection's row")
        .ordered
        .clone();
    let delivery = XAuthorityInputDeliveryId::from_raw(80210);
    // The ledger that actually admitted this delivery is the one that can
    // answer for it.
    let (recovery, _receipts) = claim_fixture(delivery);
    let (emission, _endpoint) =
        private_native_tests::emission_and_endpoint_for_writer_fixture(80210);
    let mut capsule = XAuthorityOrderedDelivery::from_emission(emission).unwrap();
    let completion = recovery
        .completion_for(delivery)
        .expect("a readable ledger")
        .expect("its admission minted a cell");
    capsule.carry_finalizer(Arc::new(finalizer_from_held(
        &recovery,
        &completion,
        delivery,
        client,
    )));
    let finalizer = Arc::downgrade(capsule.finalizer().expect("carried"));
    gated_send(&sender, capsule).expect("accepted into its queue");

    let durable = PrivateSettlementOwner::with_capacities(2, 2);
    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let PreparedOrderedFixture {
        channels,
        registration,
        ..
    } = f;
    let mut source = Some(transport_continuation(&registration, channels.ordered));
    drop(registration);
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    // ASKED REPEATEDLY, WITHOUT DRIVING. Nothing may be consumed by the
    // question, and the place may not come back while that admission exists.
    for _ in 0..8 {
        let settled = durable
            .with_ordered_continuation(0, |continuation| continuation.settled())
            .expect("the place holds it");
        assert!(!settled, "an accepted admission is not a settled connection");
    }
    assert!(
        finalizer.upgrade().is_some(),
        "the question did not destroy the capsule it was asked about"
    );
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert!(completion.answer().is_none(), "and answered nobody");

    // A visit takes it into custody, where it is still owed an answer, so the
    // place still does not come back.
    durable.drive_ordered_continuations(4);
    assert!(
        finalizer.upgrade().is_some(),
        "a visit receives into custody rather than discarding"
    );
    let retained = durable
        .with_ordered_continuation(0, |continuation| {
            let PrivateOrderedContinuation::Setup { retained, .. } = continuation else {
                panic!("a setup case was installed")
            };
            retained
                .first()
                .map(XAuthorityOrderedDelivery::delivery)
        })
        .expect("the place holds it");
    assert_eq!(
        retained,
        Some(delivery),
        "the exact admission is held, not thrown away"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "and its place stays taken while it is owed an answer"
    );
    assert!(completion.answer().is_none());
}

#[test]
fn a_stale_return_cannot_take_the_place_its_successor_holds() {
    // A place returned and reserved again between a visit finding a record and
    // that visit finishing with it. The stale return must not free the place
    // its successor now holds.
    //
    // STAGED AT THE API, not observed as a concurrent race: the interleave is
    // constructed by holding the old record's handle across the return and the
    // new reservation.
    let first = XServerFrontendClientId(8031);
    let second = XServerFrontendClientId(8032);
    let one = prepared_ordered_fixture(first);
    let two = prepared_ordered_fixture(second);
    let durable = PrivateSettlementOwner::with_capacities(2, 2);

    let slot = durable
        .reserve_ordered_continuation()
        .expect("a place, reserved before exposure");
    let PreparedOrderedFixture {
        channels,
        runner: one_runner,
        registration: one_registration,
        durable: _one_durable,
        ..
    } = one;
    // Bound, so a visit can establish an ending and this place can come back
    // at all. A receiver alone has nothing to end with.
    let mut source = Some(transport_continuation(&one_registration, channels.ordered));
    assert_eq!(retain_into(slot, &mut source), PrivateContinuationCommit::Retained);

    // A visit's view of that record, captured before the place moves on.
    let stale = {
        let held = durable.records_even_if_poisoned();
        let PrivateOrderedContinuationPlace::Taken(record) = &held.continuations[0] else {
            panic!("its place holds the record")
        };
        record.clone()
    };

    // Its producers go, so a drive returns the place.
    drop(one_registration);
    drop(one_runner);
    let PreparedOrderedFixture {
        channels: second_channels,
        runner: two_runner,
        registration: two_registration,
        durable: _two_durable,
        ..
    } = two;
    durable.drive_ordered_continuations(8);
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "the first connection's place came back"
    );

    // Another connection takes that same place.
    let replacement = durable
        .reserve_ordered_continuation()
        .expect("the returned place is reusable");
    let mut successor = Some(PrivateOrderedContinuation::Setup {
        accepted: PrivateOrderedSetupCustody::Receiver(Box::new(second_channels.ordered)),
        refusal: X11OrderedServingRefusal::TransportUnavailable,
        // A staged precondition: the value a torn-down record carries, set
        // directly rather than observed, because this control is about what
        // happens to a record that has one.
        evidence: PrivateOrderedEvidence {
            fence: Some(PrivateHandoverFence::Established),
            ..PrivateOrderedEvidence::unstarted()
        },
        retained: Vec::new(),
        drained: false,
        ended: false,
        ending_refused: None,
    });
    assert_eq!(retain_into(replacement, &mut successor), PrivateContinuationCommit::Retained);
    assert_eq!(durable.continuations_reserved(), Some(1));

    // THE STALE RETURN ARRIVES. It names a record that is no longer there.
    durable.return_ordered_continuation(0, &stale);
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "a return for a record that moved on does not free its successor's place"
    );
    let still_there = durable
        .with_ordered_continuation(0, |continuation| {
            matches!(continuation, PrivateOrderedContinuation::Setup { .. })
        })
        .expect("the successor is still installed");
    assert!(still_there);
    drop(two_registration);
    drop(two_runner);
}

/// A private instance over a store the caller keeps, with a declared limit.
///
/// Built through the real constructor. Nothing here installs a continuation
/// owner or declares a bound: a fixture that did either would be certifying
/// its own wiring rather than production's.
fn private_over(
    keeper: &crate::PrivateServiceOwner,
    clients: usize,
) -> crate::PrivateXServerFrontend {
    let (sender, _receiver) = sync_channel(4);
    let (delivery_sender, _delivery_receiver) = channel();
    let (authority, issuer, submit) = private_authority();
    crate::PrivateXServerFrontend::new(
        crate::PrivateFrontendParts {
            max_concurrent_clients: NonZeroUsize::new(clients).unwrap(),
            input_capacity: NonZeroUsize::new(4).unwrap(),
            control_acknowledgements: sender,
            input_deliveries: delivery_sender,
            authority,
            issuer,
            submit,
        },
        keeper,
    )
    .unwrap_or_else(|(refusal, _parts)| panic!("a fresh owner to have a slot: {refusal:?}"))
}

#[test]
fn a_private_instance_takes_its_connection_bound_from_its_declared_client_limit() {
    // THROUGH REAL CONSTRUCTION. The store arrives with no bound declared, and
    // an instance that left it that way would admit connections reserving
    // nothing -- the public frontend's behaviour, silently applied to a
    // private one whose accepted work must have somewhere to go.
    let durable = PrivateSettlementOwner::default();
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "nothing is reserved before an instance exists"
    );
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);

    let first = XServerFrontendClientId(8051);
    let one = private
        .broker
        .registry
        .register_client_with_admission(first, Some(admitted(first)))
        .expect("the first connection has a place");
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "production installed the owner, so registration reserves"
    );
    let second = XServerFrontendClientId(8052);
    let two = private
        .broker
        .registry
        .register_client_with_admission(second, Some(admitted(second)))
        .expect("the declared limit is two");
    assert_eq!(durable.continuations_reserved(), Some(2));

    // The bound is the declared limit, not the abandoned-work capacity the
    // store was built with, and not unbounded.
    let third = XServerFrontendClientId(8053);
    let refused = private
        .broker
        .registry
        .register_client_with_admission(third, Some(admitted(third)))
        .err()
        .expect("the declared limit is two");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ContinuationUnavailable { client } if client == third
        ),
        "refused for the place, got {refused:?}"
    );
    assert!(
        private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable registry")
            .get(&third)
            .is_none(),
        "the refused connection has no row, so nothing can be accepted for it"
    );
    drop(one);
    drop(two);
}

#[test]
fn a_registry_does_not_keep_the_store_it_takes_places_from_alive() {
    // THE RING IS BUILT, not assumed: an instance that ends owing a hold hands
    // its terminal inventory to the store, and that inventory keeps the
    // registry it must act through. A registry that owned the store back would
    // close it -- store, retained inventory, registry, store -- and nothing in
    // it would ever drop. What that looks like from outside is an instance
    // whose obligations stay readable forever, so it reads as still settling
    // rather than as a leak.
    let durable = PrivateSettlementOwner::default();
    let watch = Arc::downgrade(&durable.inner);
    let owner_of_durable = service_owner(&durable, 16);
    let client = XServerFrontendClientId(8061);
    let common = instance_handing_over_a_retained_hold(
        &owner_of_durable,
        client,
        SurfaceId::new(0x8061, 1),
        NamespaceId::from_raw(client.raw()),
        80610,
        272,
    );
    assert_eq!(
        durable.terminal_inventories().expect("readable"),
        1,
        "the store retains an inventory, and that inventory holds a registry"
    );
    assert!(watch.upgrade().is_some(), "the store is alive and in use");
    let answered_to = Arc::downgrade(&common);

    // Everything that legitimately owns the store goes here -- the service
    // owner included, which keeps the store and the evidence it is about. The
    // registry inside the retained inventory does not own it, so it holds
    // nothing back.
    drop(common);
    drop(durable);
    drop(owner_of_durable);
    assert!(
        watch.upgrade().is_none(),
        "a registry that owned its store back would keep the store, the \
         inventory and every obligation in it reachable forever"
    );
    assert!(
        answered_to.upgrade().is_none(),
        "and the authority the retained hold answered to goes with it"
    );
}

#[test]
fn a_registry_whose_store_is_gone_refuses_rather_than_exposing_a_connection() {
    // A STORE THAT HAS GONE IS NOT AN EMPTY STORE. The registry holds it
    // weakly, so it can outlive it; carrying on without one would expose a
    // connection whose accepted work has nowhere to go, which is the thing
    // reserving was for.
    let registry = {
        let durable = PrivateSettlementOwner::default();
        let service_keeper = service_owner(&durable, 4);
        let private = private_over(&service_keeper, 4);
        private.broker.registry.clone()
    };
    let client = XServerFrontendClientId(8101);
    let refused = registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("there is no store to take a place from");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ContinuationUnavailable { client: gone } if gone == client
        ),
        "refused for the place, got {refused:?}"
    );
    assert!(
        registry
            .clients
            .lock()
            .expect("a readable registry")
            .get(&client)
            .is_none(),
        "and published nothing"
    );
}

#[test]
fn a_later_instance_does_not_move_the_bound_its_places_were_taken_against() {
    // The store outlives the instance that declared its bound. A second
    // instance arriving with a different client limit finds places already
    // held against the first, and moving the number under them would hand out
    // places a departed instance already accounted for.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 1);
    let first_instance = private_over(&service_keeper, 1);
    let client = XServerFrontendClientId(8071);
    let registration = first_instance
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("the one place");
    // Retained: the connection's place stays held after its instance goes.
    drop(registration);
    drop(first_instance);
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the place is retained across the instance that took it"
    );

    let service_keeper = service_owner(&durable, 8);
    let second_instance = private_over(&service_keeper, 8);
    let later = XServerFrontendClientId(8072);
    let refused = second_instance
        .broker
        .registry
        .register_client_with_admission(later, Some(admitted(later)))
        .err()
        .expect("the bound in force is the one the retained place was taken against");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ContinuationUnavailable { client } if client == later
        ),
        "refused for the place, got {refused:?}"
    );
}

#[test]
fn a_refusal_before_publication_gives_its_place_back() {
    // A RESERVATION THAT PUBLISHED NOTHING IS NOT RETAINED WORK. No row and no
    // reachable queue means no capsule could have been accepted for it, so
    // holding the place would spend the bound on a connection that never
    // existed -- and the store cannot tell later, because there is nothing to
    // ask.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8081);
    let registration = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place");
    assert_eq!(durable.continuations_reserved(), Some(1));

    // Refused after the place was taken and before anything was published.
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("the client is already registered");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::DuplicateClient { client: duplicate } if duplicate == client
        ),
        "refused for the duplicate, got {refused:?}"
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the refusal gave its place back rather than retaining one for a \
         connection that was never exposed"
    );
    assert_eq!(
        durable.continuations_abandoned(),
        Some(0),
        "and did not abandon one either: there is nothing to account for"
    );

    // Proved against the bound, not just the counter: the second place is
    // still there to be taken.
    let other = XServerFrontendClientId(8082);
    let second = private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("the place the refused duplicate gave back");
    drop(registration);
    drop(second);
}

#[test]
fn a_registration_never_takes_the_settlement_store_beneath_the_client_table() {
    // THE DRIVE ALREADY HOLDS SETTLEMENT AND THEN TAKES CLIENTS, to release a
    // route lease. A registration that reserved under the client table would
    // be the other order, and two orders is a deadlock.
    //
    // WHAT THIS ESTABLISHES, exactly: the store is held for a window in which
    // the registration provably cannot finish -- it reserves nothing and
    // returns nothing until the store is released -- and throughout that
    // window the client table is free. It does NOT establish that the worker
    // reached its reservation: sleeping for a while is not a rendezvous, and
    // an observation that found the table free because the thread had not yet
    // started would look the same from here. The inversion mutant is what
    // gives the assertion its teeth, and a labelled hook at the reservation
    // boundary is what would establish arrival.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 4);
    let private = private_over(&service_keeper, 4);
    let clients = private.broker.registry.clients.clone();
    let registry = private.broker.registry.clone();
    let client = XServerFrontendClientId(8091);
    let held = durable.records_even_if_poisoned();
    let joiner = std::thread::spawn(move || {
        registry
            .register_client_with_admission(client, Some(admitted(client)))
            .map(|(registration, _channels)| registration)
    });
    // The store is held for the whole window, so the registration cannot get
    // past its reservation during it -- whether or not it has reached it.
    let mut free = 0;
    for _ in 0..40 {
        assert!(
            clients.try_lock().is_ok(),
            "a registration that has not completed must not be holding the \
             client table while the store is held: that is the order the \
             retained drive takes them in, reversed"
        );
        free += 1;
        std::thread::sleep(std::time::Duration::from_millis(5));
    }
    assert_eq!(
        free, 40,
        "the client table was free at every observation taken during the \
         window in which the registration could not complete"
    );
    assert_eq!(
        durable_reserved(&held), 0,
        "and the registration had not completed: no place was taken while the \
         store was held"
    );
    drop(held);
    let registration = joiner
        .join()
        .expect("the registration thread")
        .expect("a place, once the store is free");
    assert_eq!(durable.continuations_reserved(), Some(1));
    drop(registration);
}

/// Reserved places, read from a guard the caller already holds.
fn durable_reserved(held: &AbandonedSettlements) -> usize {
    held.continuation_slots
}

/// Stops this connection's worker however the control leaves.
///
/// A body waiting on its notice outlives an assertion that failed above it,
/// and a scope joins what it spawned -- so without this a control that failed
/// would hang instead of reporting. It stops on the way out, whichever way
/// out that is.
struct PrivateWorkerStopper<'a>(&'a Arc<AtomicBool>, &'a Arc<PrivateOrderedWake>);

impl Drop for PrivateWorkerStopper<'_> {
    fn drop(&mut self) {
        // THROUGH THE PRODUCTION CANCELLATION. A bare store and a signal
        // beside the predicate mutex can land after a waiter has checked stop
        // and before it waits, and then the signal reaches nobody: the cleanup
        // hangs on a body that will never look again. The existing helper
        // publishes the recheck under that mutex, which is what makes the
        // stop visible to a waiter either side of its check.
        cancel_connection_worker(self.0, self.1);
    }
}

/// Wait until this connection's body has been through its idle wait.
///
/// A HANDSHAKE, NOT A SLEEP, and it establishes exactly one thing: that the
/// body reached the wait and consumed the level, because only a waiter
/// consumes it and only under that wait's own mutex. A body that had not got
/// there would leave it set.
///
/// WHAT IT DOES NOT ESTABLISH is where the body is when this returns.
/// Consuming the level is how the wait ENDS: the body goes on to another
/// ordinary visit and, if that is idle again, to another wait. So this says a
/// wait happened, never that one is happening now -- and a control that acts
/// on the second reading is racing a legal schedule.
///
/// Bounded, because a control that never finishes reports nothing.
fn waited_and_consumed(wake: &Arc<PrivateOrderedWake>) -> bool {
    wake.publish_recheck();
    waited_for(|| {
        !wake
            .state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .pending
    })
}

/// Hand a capsule over the way a production producer does: the recheck level
/// is armed first and published as the notice drops, whatever the send did.
///
/// `admit` alone publishes nothing -- it is the gate, not the notice -- so a
/// control that only sent would leave a waiting body with nothing to wake it.
fn produced_send(sender: &PrivateGatedOrderedSender, capsule: XAuthorityOrderedDelivery) {
    let notify = sender.arm_wake();
    gated_send(sender, capsule).expect("an open endpoint");
    drop(notify);
}

/// A connection served by a real owner, with an actual stop it can be told to
/// use.
///
/// THE PRODUCTION BINDING PASSES NO STOP. A worker over an owner that has none
/// cannot be told to stop, so these controls bind with one -- through the same
/// `bind` production uses -- and the body refuses an owner without one rather
/// than running a thread nothing can end. Wiring that binding is the
/// attachment's work and is not done here.
struct PrivateWorkerFixture {
    fixture: PreparedOrderedFixture,
    home: Arc<PrivateOrderedHome>,
    wake: Arc<PrivateOrderedWake>,
    stop: Arc<AtomicBool>,
    sequence: Arc<AtomicU16>,
    sender: PrivateGatedOrderedSender,
    peer: UnixStream,
    _output: Arc<Mutex<UnixStream>>,
}

fn worker_fixture(client: XServerFrontendClientId) -> PrivateWorkerFixture {
    worker_fixture_bound(client, true)
}

/// The same, with the choice production makes today available: a transport
/// bound with no stop at all.
fn worker_fixture_bound(
    client: XServerFrontendClientId,
    stoppable: bool,
) -> PrivateWorkerFixture {
    // THE PREPARED CONNECTION, whole: admitted through its lifecycle, its
    // applied state attached, its durable store held by the fixture. Promotion
    // asks the boundary for this registration's endpoint, so a connection
    // assembled by hand would be refused as unadmitted -- and rightly.
    let mut f = prepared_ordered_fixture(client);
    let ordered = std::mem::replace(
        &mut f.channels.ordered,
        f.runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .register_client_with_admission(
                XServerFrontendClientId(client.raw() + 500_000),
                Some(admitted(XServerFrontendClientId(client.raw() + 500_000))),
            )
            .expect("a spare registration to borrow a receiver from")
            .1
            .ordered,
    );
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(3)))
        .expect("a bounded read");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let wake = Arc::clone(&ordered.wake);
    let transport = XAuthorityOrderedTransport::bind(
        &f.registration,
        ordered,
        &output,
        &wire,
        &pending,
        stoppable.then_some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    assert!(matches!(
        f.registration
            .retain_ordered_setup(PrivateOrderedContinuation::Setup {
                accepted: PrivateOrderedSetupCustody::Transport(Box::new(transport)),
                refusal: X11OrderedServingRefusal::Unserved,
                evidence: PrivateOrderedEvidence::unstarted(),
                retained: Vec::new(),
                drained: false,
                ended: false,
                ending_refused: None,
            }),
        Ok(())
    ));
    assert_eq!(
        f.registration
            .promote_ordered_serving(f.runner.frontend.as_ref().unwrap()),
        PrivateOrderedPromotion::Ready
    );
    let sender = capture_gated_sender(f.runner.frontend.as_ref().unwrap(), client);
    let home = Arc::clone(&f.registration.ordered_home);
    PrivateWorkerFixture {
        fixture: f,
        home,
        wake,
        stop,
        sequence: Arc::new(AtomicU16::new(7)),
        sender,
        peer,
        _output: output,
    }
}

impl PrivateWorkerFixture {
    /// This connection's startup permit, published the way startup publishes
    /// it: under the notice, and woken.
    fn permit(&self) {
        self.wake
            .state
            .lock()
            .expect("a readable notice")
            .started = true;
        self.wake.ready.notify_all();
    }

    /// This connection's handles, cloned so a body can be built inside a
    /// thread without borrowing the fixture the test still needs.
    fn handles(
        &self,
    ) -> (
        Arc<PrivateOrderedHome>,
        Arc<PrivateOrderedWake>,
        Arc<AtomicBool>,
        Arc<AtomicU16>,
    ) {
        (
            Arc::clone(&self.home),
            Arc::clone(&self.wake),
            Arc::clone(&self.stop),
            Arc::clone(&self.sequence),
        )
    }

    fn body<'a>(&'a self, exit: &'a PrivateWorkerExit, steps: usize) -> PrivateWorkerBody<'a> {
        PrivateWorkerBody {
            home: &self.home,
            wake: &self.wake,
            stop: &self.stop,
            byte_order: XByteOrder::LittleEndian,
            sequence: &self.sequence,
            exit,
            steps,
        }
    }
}

#[test]
fn a_body_serves_an_admitted_delivery_to_real_bytes_and_answers_for_it() {
    // THE WHOLE POINT OF A WORKER, end to end through the real owner: an
    // admitted delivery -- reserved, executed, observed and dispatched by the
    // production path -- becomes bytes this connection's peer can read, and
    // its completion says so. The body encodes nothing, writes nothing and
    // answers nothing itself; it asks the owner for one step at a time.
    let mut f = worker_fixture(XServerFrontendClientId(8391));
    attempt_run(&mut f.fixture, 83910, 272, true);
    let private = f.fixture.runner.frontend.as_mut().unwrap();
    let cell = admitted_cell(private, 83910);
    assert_eq!(
        private.dispatch_one_press(),
        Some(true),
        "the real producer handed it to this connection's queue"
    );
    assert!(cell.answer().is_none(), "and nothing has served it yet");

    f.permit();
    let exit = PrivateWorkerExit::unstarted();
    let (home, wake, stop, sequence) = f.handles();
    let outcome = std::thread::scope(|scope| {
        let exit = &exit;
        let worker = scope.spawn(move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit,
                steps: 16,
            }
            .run()
        });
        let _stopper = PrivateWorkerStopper(&f.stop, &f.wake);
        // ITS BYTES ARE ON THE WIRE. A whole X event, read by the peer this
        // connection was bound to.
        let mut seen = [0u8; 32];
        std::io::Read::read_exact(&mut (&f.peer), &mut seen)
            .expect("its peer reads what was sent");
        assert_eq!(seen[0], 4, "a button press, which is what was run");
        // THE EXECUTION CONTEXT IS THIS CONNECTION'S, and the bytes say so.
        // The sequence field carries the counter this body was given, in the
        // byte order it was given -- not a constant, and not the other order,
        // either of which would put different bytes here.
        assert_eq!(
            &seen[2..4],
            &[7, 0],
            "its own sequence, little-endian as supplied"
        );

        // AND ITS RECEIPT IS PUBLISHED, observed before anything is cancelled.
        // The step that finishes the write can return Advanced; finalising it
        // is the step after, and a body stopped in between would leave a
        // control asking for a receipt nobody had written.
        assert!(published(&cell), "the delivery is answered for");

        // AND THEN IT IS STOPPED AND JOINED, before anything is dropped: a
        // registration going while a borrower is still in its home is the
        // integration boundary, not this body's to cross.
        cancel_connection_worker(&f.stop, &f.wake);
        worker.join().expect("the body finished")
    });
    let answer = cell.answer().expect("and the delivery is answered for");
    assert_eq!(answer.delivery, XAuthorityInputDeliveryId::from_raw(83910));
    assert_eq!(answer.outcome, XAuthorityInputDeliveryOutcome::Flushed);
    assert!(
        stopped_by_cancellation(&outcome),
        "the owner's own word, whichever of the two saw the stop: {outcome:?}"
    );
    assert_eq!(exit.outcome(), Some(outcome));
    assert!(exit.left(), "and its frame is gone");
    drop(f.fixture);
}

#[test]
fn a_body_will_not_serve_work_queued_before_its_permit() {
    // WORK IS NOT PERMISSION. A queue with something on it says a producer got
    // there first, not that the transaction which owns this worker's handle
    // has finished; serving on the strength of it would be a worker running
    // before anything permitted it.
    //
    // AND IT IS NOT A REASON TO GIVE UP EITHER. The pending level is left
    // exactly as it was found, so whatever put it there still gets its wake.
    let f = worker_fixture(XServerFrontendClientId(8392));
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(83920);
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    produced_send(&f.sender, capsule);
    assert!(
        f.wake.state.lock().expect("a readable notice").pending,
        "the producer published a level"
    );

    // Stopped rather than permitted, so the body leaves startup without ever
    // serving. The trigger is not a race here and is asserted strictly: the
    // stop is set before the body runs at all, and the permit wait asks about
    // it first.
    //
    // SET DIRECTLY, NOT THROUGH THE CANCELLATION, and for this control only.
    // Nothing is running that could miss a signal, and the cancellation
    // publishes a recheck of its own -- which is the very level this control
    // goes on to assert the body left alone.
    f.stop.store(true, Ordering::SeqCst);
    let exit = PrivateWorkerExit::unstarted();
    let outcome = f.body(&exit, 8).run();

    assert_eq!(outcome.trigger, PrivateWorkerTrigger::Stopped);
    assert!(cell.answer().is_none(), "nothing was served");
    assert!(
        f.wake.state.lock().expect("a readable notice").pending,
        "and the level it never waited on is still there"
    );
    // THE CAPSULE IS STILL ON ITS OWN QUEUE, held by nobody else.
    assert!(
        f.home
            .borrow_live(|payload| {
                let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                    panic!("promoted")
                };
                owner.queue.try_recv().is_ok()
            })
            .acted()
            .expect("its own home"),
        "the work it refused to serve is where the producer put it"
    );
    drop(f.fixture);
}

#[test]
fn an_unpermitted_body_serves_nothing_until_it_is_permitted() {
    // THE PERMIT IS ASKED FOR, and waited on. A body that went straight to
    // serving would be writing this connection's events before the
    // transaction that owns its handle had finished -- and there is work
    // waiting here, so nothing but the permit is holding it back.
    let mut f = worker_fixture(XServerFrontendClientId(8402));
    attempt_run(&mut f.fixture, 84020, 272, true);
    let cell = admitted_cell(f.fixture.runner.frontend.as_ref().unwrap(), 84020);
    assert_eq!(
        f.fixture
            .runner
            .frontend
            .as_mut()
            .unwrap()
            .dispatch_one_press(),
        Some(true)
    );
    assert!(
        f.wake.state.lock().expect("a readable notice").pending,
        "work is queued and announced"
    );
    assert!(
        !f.wake.state.lock().expect("a readable notice").started,
        "and nothing has permitted this worker"
    );

    let exit = PrivateWorkerExit::unstarted();
    let (home, wake, stop, sequence) = f.handles();
    std::thread::scope(|scope| {
        let exit = &exit;
        let worker = scope.spawn(move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit,
                steps: 16,
            }
            .run()
        });
        let _stopper = PrivateWorkerStopper(&f.stop, &f.wake);
        // A WINDOW, AND ONLY A WINDOW. There is work in front of this body and
        // a budget to serve it with, so one that never asked for a permit had
        // every opportunity here and took none. It does NOT establish that the
        // body has reached its startup wait -- that wait consumes no level a
        // handshake could use, and a sleep cannot say where a thread is.
        std::thread::sleep(Duration::from_millis(100));
        assert!(cell.answer().is_none(), "it served nothing");
        assert!(!exit.left(), "and is still waiting to be allowed to");

        // AND NOW IT MAY.
        f.permit();
        let mut seen = [0u8; 32];
        std::io::Read::read_exact(&mut (&f.peer), &mut seen)
            .expect("its peer reads what the permitted body sent");
        assert_eq!(seen[0], 4);
        assert!(
            published(&cell),
            "and answered for it, which is a step after the write"
        );
        cancel_connection_worker(&f.stop, &f.wake);
        let outcome = worker.join().expect("the body finished");
        assert!(
            stopped_by_cancellation(&outcome),
            "the owner's own word, whichever of the two saw the stop: {outcome:?}"
        );
    });
    assert!(cell.answer().is_some());
    drop(f.fixture);
}

#[test]
fn waiting_for_a_permit_leaves_the_producers_level_where_it_was() {
    // A PERMIT IS NOT AN IDLE WAIT, and must not consume what an idle wait
    // consumes. The level belongs to whoever published it: a startup that
    // swallowed it would leave a producer having announced work to a worker
    // that then went to sleep without looking.
    //
    // NO STEPS ARE TAKEN HERE, so what is observed is the startup wait alone.
    let f = worker_fixture(XServerFrontendClientId(8403));
    f.permit();
    // Published the way a producer publishes it, with nothing sent: the level
    // is the subject, not the capsule.
    drop(f.sender.arm_wake());
    assert!(f.wake.state.lock().expect("a readable notice").pending);

    let exit = PrivateWorkerExit::unstarted();
    let outcome = f.body(&exit, 0).run();
    assert_eq!(outcome.trigger, PrivateWorkerTrigger::Exhausted);
    assert!(
        f.wake.state.lock().expect("a readable notice").pending,
        "the level a producer published is still there for whoever waits next"
    );
    drop(f.fixture);
}

#[test]
fn a_body_that_finds_nothing_waits_and_is_woken_by_an_actual_producer() {
    // THE REAL WAKE PATH, AND THE ANTI-SPIN CONTROL IN ONE. An idle body waits
    // on this connection's notice; what ends the wait is the production
    // producer publishing to that same notice, not a timeout and not a poll.
    //
    // AND IT WAITS RATHER THAN RETURNING AT ONCE. A body that woke on the
    // sticky permit, or on a level nothing cleared, would not have needed this
    // control's level to get through its wait. WHAT IS OBSERVED is that the
    // level was consumed and the body had not left. That it still has steps in
    // hand is NOT observed -- a paused body looks the same -- and nothing here
    // rests on it.
    let mut f = worker_fixture(XServerFrontendClientId(8393));
    f.permit();
    attempt_run(&mut f.fixture, 83930, 272, true);
    let cell = admitted_cell(f.fixture.runner.frontend.as_ref().unwrap(), 83930);
    let exit = PrivateWorkerExit::unstarted();
    let (home, wake, stop, sequence) = f.handles();

    std::thread::scope(|scope| {
        let exit = &exit;
        let worker = scope.spawn(move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit,
                steps: 8,
            }
            .run()
        });
        let _stopper = PrivateWorkerStopper(&f.stop, &f.wake);
        // IT WENT THROUGH A WAIT, established rather than timed: a level
        // published under that wait's own mutex, consumed only by a waiter.
        assert!(
            waited_and_consumed(&f.wake),
            "the body reached its idle wait"
        );
        assert!(
            !exit.left(),
            "and has not left, so it did not run its budget out on nothing"
        );
        assert!(cell.answer().is_none(), "having served nothing");

        // The production producer, which arms this connection's notice itself.
        assert_eq!(
            f.fixture
                .runner
                .frontend
                .as_mut()
                .unwrap()
                .dispatch_one_press(),
            Some(true)
        );
        // Its bytes reach the peer, which is what says the wake produced a
        // serve rather than merely a return.
        let mut seen = [0u8; 32];
        std::io::Read::read_exact(&mut (&f.peer), &mut seen)
            .expect("its peer reads what the woken body sent");
        assert_eq!(seen[0], 4);
        // ITS RECEIPT, BEFORE THE CANCELLATION. Finalising is the step after
        // the one that finishes the write, so a body stopped between them
        // would be asked for something nobody had written.
        assert!(
            published(&cell),
            "the woken body answered for what it served"
        );
        cancel_connection_worker(&f.stop, &f.wake);
        let outcome = worker.join().expect("the body finished");
        assert!(
            stopped_by_cancellation(&outcome),
            "the owner's own word, whichever of the two saw the stop: {outcome:?}"
        );
    });
    assert!(
        f.wake.state.lock().expect("a readable notice").started,
        "while the permit stayed set, having never been a reason to wake"
    );
    drop(f.fixture);
}

#[test]
fn a_body_told_to_stop_while_idle_asks_its_owner_what_that_means() {
    // A STOP IS A TRIGGER, NOT A RESULT. Reading the flag back as `Stopped`
    // would report a wire outcome nobody established; the owner is asked once,
    // and what it says is kept beside the trigger rather than instead of it.
    let f = worker_fixture(XServerFrontendClientId(8396));
    f.permit();
    let exit = PrivateWorkerExit::unstarted();
    std::thread::scope(|scope| {
        let (home, wake, stop, sequence) = f.handles();
        let exit = &exit;
        let worker = scope.spawn(move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit,
                steps: 16,
            }
            .run()
        });
        let _stopper = PrivateWorkerStopper(&f.stop, &f.wake);
        // A WAIT HAPPENED FIRST, so this is a stop told to a body that got
        // past startup -- not one that happened to land before it. Where the
        // body is when the stop arrives is not established and nothing here
        // rests on it: a stop is asked before every visit and inside every
        // wait, so either finds it.
        assert!(
            waited_and_consumed(&f.wake),
            "the body has been through its idle wait"
        );
        // THROUGH THE PRODUCTION CANCELLATION, which is how a running worker
        // is told: a bare write beside the predicate mutex can be lost by a
        // waiter between its check and its wait.
        cancel_connection_worker(&f.stop, &f.wake);
        let outcome = worker.join().expect("the body finished");
        // EITHER OF TWO LEGAL ANSWERS. A body told to stop before its own
        // check departs itself; one told between that check and its visit has
        // the owner observe the stop instead. Requiring one of them asserts a
        // schedule. What both carry is the owner's own word, which is what
        // this control is about.
        assert!(
            stopped_by_cancellation(&outcome),
            "the owner is what said so: {outcome:?}"
        );
    });
    drop(f.fixture);
}

#[test]
fn a_body_that_cannot_read_its_notice_stops_the_connection_and_asks_once() {
    // A NOTICE NOBODY STANDS BEHIND IS NOT A WAIT. Recovering the guard and
    // sleeping on it would put this worker to sleep on a level a panic left,
    // with nothing able to wake it. So the same authoritative stop is set and
    // the notice woken -- the connection's own stop, not a fresh flag -- and
    // the owner is asked once for its departure.
    for while_running in [false, true] {
        let f = worker_fixture(XServerFrontendClientId(8397));
        f.permit();
        let exit = PrivateWorkerExit::unstarted();
        if while_running {
            // POISONED WHILE THE BODY IS RUNNING, after it has been through a
            // wait. WHICH ACQUISITION FINDS IT IS NOT ESTABLISHED: consuming
            // the handshake level ends a wait, so the body may take another
            // ordinary visit and meet the poison on the next wait's initial
            // lock rather than on a Condvar reacquisition. Both are the same
            // classification and this control does not separate them. That the
            // reacquisition branch itself is taken is established elsewhere,
            // not here.
            std::thread::scope(|scope| {
                let body = f.body(&exit, 16);
                let worker = scope.spawn(move || body.run());
                assert!(
                    waited_and_consumed(&f.wake),
                    "the body has been through its idle wait"
                );
                assert!(
                    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        let _held = f.wake.state.lock().expect("a readable notice");
                        f.wake.ready.notify_all();
                        panic!("a holder unwound inside this connection's notice");
                    }))
                    .is_err(),
                    "the holder unwound"
                );
                let outcome = worker.join().expect("the body finished");
                assert_eq!(outcome.trigger, PrivateWorkerTrigger::NoticeUnreadable);
            });
        } else {
            assert!(
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    let _held = f.wake.state.lock().expect("a readable notice");
                    panic!("a holder unwound inside this connection's notice");
                }))
                .is_err(),
                "the holder unwound"
            );
            let outcome = f.body(&exit, 16).run();
            assert_eq!(outcome.trigger, PrivateWorkerTrigger::NoticeUnreadable);
            assert_eq!(
                outcome.last,
                Some(PrivateWorkerAsk::Said(X11OrderedServeStep::Stopped)),
                "the owner's own word about a connection now stopped"
            );
        }
        assert!(
            f.stop.load(Ordering::SeqCst),
            "the connection's own stop is what was set"
        );
        drop(f.fixture);
    }
}

#[test]
fn a_body_ends_on_the_owners_word_when_the_last_sender_disappears() {
    // GONE IS A HINT, AND THE OWNER'S RECEIVE IS THE FINDING. That every
    // sender has disappeared is a reason to look again; what says the queue is
    // finished is the owner receiving from it, and the outcome it gives is the
    // owner's rather than a flag this body read back.
    //
    // THE LAST SENDER GOES WITHOUT THE REGISTRATION GOING. The registry's own
    // routing removes a client's row when its protocol receiver has gone, so
    // dropping that receiver and driving the real routing seam takes the last
    // counted wrapper with it. No table surgery, no invented level, and no
    // registration torn down under a body still borrowing its home -- which is
    // the integration boundary, not this body's to cross.
    let f = worker_fixture(XServerFrontendClientId(8404));
    f.permit();
    let exit = PrivateWorkerExit::unstarted();
    let sender = f.sender;
    let protocol = f.fixture.channels.protocol;
    let (home, wake, stop, sequence) = (
        Arc::clone(&f.home),
        Arc::clone(&f.wake),
        Arc::clone(&f.stop),
        Arc::clone(&f.sequence),
    );
    let outcome = std::thread::scope(|scope| {
        let exit = &exit;
        let worker = scope.spawn(move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit,
                steps: 16,
            }
            .run()
        });
        let _stopper = PrivateWorkerStopper(&f.stop, &f.wake);
        assert!(
            waited_and_consumed(&f.wake),
            "the body is in its idle wait before anything disappears"
        );

        // The connection's protocol receiver goes, and the ordered sender this
        // control was holding with it.
        drop((protocol, sender));
        // THE REAL ROUTING SEAM: it finds the protocol queue disconnected and
        // removes the row, which is what releases the last ordered wrapper.
        f.fixture
            .runner
            .frontend
            .as_ref()
            .unwrap()
            .broker
            .registry
            .route_protocol(
                f.fixture.client,
                XClientEvent::UnmapNotify {
                    sequence: 1,
                    event: f.fixture.window,
                    window: f.fixture.window,
                    from_configure: false,
                },
            )
            .expect("a disconnected protocol queue is not this caller's error");
        let outcome = worker.join().expect("the body finished");
        // Read HERE, before the control's own cleanup stops anything: what is
        // being asked is whether the body ended on the owner's word without
        // the connection having been told to stop.
        (outcome, f.stop.load(Ordering::SeqCst), f.home.standing())
    });
    let (outcome, stopped, standing) = outcome;
    assert_eq!(outcome.trigger, PrivateWorkerTrigger::OwnerStep);
    assert_eq!(
        outcome.last,
        Some(PrivateWorkerAsk::Said(X11OrderedServeStep::Ended {
            outcome: XAuthorityInputDeliveryOutcome::ClientDisconnected,
            shutdown: true,
        })),
        "the owner's own ending, with its exact outcome and what it shut down"
    );
    // The connection is still live and was never told to stop: what ended was
    // its queue, established by the owner receiving from it.
    assert_eq!(standing, PrivateHomeStanding::Live);
    assert!(!stopped, "and nothing had told the connection to stop");
    drop(f.fixture.registration);
}

#[test]
fn a_departure_that_cannot_ask_its_owner_says_so_rather_than_nothing() {
    // A REFUSAL IS NOT AN ABSENCE. When a departure's ask cannot be made --
    // the home unreadable by the time the body is told to stop -- reporting
    // "nothing said" loses the one fact a caller has to act on, and leaves the
    // departure looking ordinary.
    //
    // THE SEAM IS CALLED DIRECTLY, and the control says so rather than
    // pretending to reach it through a running body. Poisoning a home under a
    // running worker does not decide which of two legal things happens: a body
    // that meets the poison on its next ordinary visit refuses eligibly and
    // never departs at all, which is correct and is not what this is about.
    // Waiting for a schedule to produce the one is a race, not a witness.
    //
    // WHAT IS REAL HERE: the connection, its owner, its home, the poison and
    // the cancellation. What is staged is only which of the body's own
    // entry points is entered.
    let f = worker_fixture(XServerFrontendClientId(8405));
    f.permit();
    let exit = PrivateWorkerExit::unstarted();
    let body = f.body(&exit, 16);
    assert!(
        body.credentials().is_ok(),
        "this body may serve this connection, a moment before it cannot"
    );

    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _held = f.home.state.lock().expect("a readable home");
            panic!("a holder unwound inside this connection's home");
        }))
        .is_err(),
        "the holder unwound"
    );
    assert!(f.home.unreadable());
    cancel_connection_worker(&f.stop, &f.wake);

    let outcome = body.depart(PrivateWorkerTrigger::Stopped);
    assert_eq!(outcome.trigger, PrivateWorkerTrigger::Stopped);
    assert_eq!(
        outcome.last,
        Some(PrivateWorkerAsk::Refused(
            PrivateWorkerRefusal::HomeUnreadable
        )),
        "what could not be asked, not silence standing in for it"
    );
    drop(f.fixture);
}

#[test]
fn a_body_that_spends_its_budget_still_says_what_it_was_doing() {
    // EXHAUSTION IS NOT INNOCENCE. A body that used every step it was given
    // has been serving, and reporting that nothing was ever asked would read
    // as one that never did -- which is exactly what a caller deciding
    // whether work is owed must not be told.
    let mut f = worker_fixture(XServerFrontendClientId(8406));
    attempt_run(&mut f.fixture, 84060, 272, true);
    let cell = admitted_cell(f.fixture.runner.frontend.as_ref().unwrap(), 84060);
    assert_eq!(
        f.fixture
            .runner
            .frontend
            .as_mut()
            .unwrap()
            .dispatch_one_press(),
        Some(true)
    );
    f.permit();

    // Two steps: enough to take the delivery and finish it, and no more, so
    // the budget is what ends this rather than the connection.
    let exit = PrivateWorkerExit::unstarted();
    let outcome = f.body(&exit, 2).run();
    let mut seen = [0u8; 32];
    std::io::Read::read_exact(&mut (&f.peer), &mut seen).expect("its peer reads what was sent");
    assert_eq!(seen[0], 4);
    assert_eq!(
        cell.answer().expect("answered for").outcome,
        XAuthorityInputDeliveryOutcome::Flushed
    );
    assert_eq!(outcome.trigger, PrivateWorkerTrigger::Exhausted);
    assert!(
        matches!(outcome.last, Some(PrivateWorkerAsk::Said(_))),
        "its last step, not a claim that it never took one: {outcome:?}"
    );
    drop(f.fixture);
}

#[test]
fn a_body_refuses_a_home_or_an_owner_it_may_not_serve() {
    // EACH REFUSAL IS A DIFFERENT FACT, and none of them is idleness. A body
    // that reported no work for any of these would say this connection had
    // nothing owed when what happened was that it could not serve it.
    //
    // NOTHING IS CONSUMED BY A REFUSAL: no receive, no write, no answer.
    // No stop: the production binding's own shape, refused rather than run.
    let unstoppable = worker_fixture_bound(XServerFrontendClientId(8398), false);
    let no_stop = PrivateWorkerExit::unstarted();
    let refused = unstoppable.body(&no_stop, 8).run();
    assert_eq!(
        refused.trigger,
        PrivateWorkerTrigger::Ineligible(PrivateWorkerRefusal::NoStop),
        "an owner with no stop is a worker nothing could end"
    );
    assert_eq!(
        refused.last,
        Some(PrivateWorkerAsk::Refused(PrivateWorkerRefusal::NoStop)),
        "and the refusal is kept rather than reported as nothing said"
    );
    drop(unstoppable.fixture);

    // A notice that is not this owner's.
    let f = worker_fixture(XServerFrontendClientId(8399));
    let foreign = Arc::new(PrivateOrderedWake::for_first_sender());
    let exit = PrivateWorkerExit::unstarted();
    assert_eq!(
        PrivateWorkerBody {
            home: &f.home,
            wake: &foreign,
            stop: &f.stop,
            byte_order: XByteOrder::LittleEndian,
            sequence: &f.sequence,
            exit: &exit,
            steps: 8,
        }
        .run()
        .trigger,
        PrivateWorkerTrigger::Ineligible(PrivateWorkerRefusal::ForeignNotice)
    );
    // A stop that is not this owner's.
    let other_stop = Arc::new(AtomicBool::new(false));
    assert_eq!(
        PrivateWorkerBody {
            home: &f.home,
            wake: &f.wake,
            stop: &other_stop,
            byte_order: XByteOrder::LittleEndian,
            sequence: &f.sequence,
            exit: &exit,
            steps: 8,
        }
        .run()
        .trigger,
        PrivateWorkerTrigger::Ineligible(PrivateWorkerRefusal::ForeignStop)
    );

    // A home whose connection has ended: whoever finishes it owns it now.
    let ended = {
        let g = worker_fixture(XServerFrontendClientId(8400));
        let home = Arc::clone(&g.home);
        let wake = Arc::clone(&g.wake);
        let stop = Arc::clone(&g.stop);
        let sequence = Arc::clone(&g.sequence);
        drop((g.fixture, g.sender));
        let exit = PrivateWorkerExit::unstarted();
        PrivateWorkerBody {
            home: &home,
            wake: &wake,
            stop: &stop,
            byte_order: XByteOrder::LittleEndian,
            sequence: &sequence,
            exit: &exit,
            steps: 8,
        }
        .run()
        .trigger
    };
    assert_eq!(
        ended,
        PrivateWorkerTrigger::Ineligible(PrivateWorkerRefusal::HomeRetained)
    );
    drop(f.fixture);
}


/// Take custody of this connection's evidence, before anything produces any.
///
/// THE ORDER IS THE SUBJECT. Every reaping below is handed a home this already
/// owns, in a scope that outlives the operation -- which is what makes losing
/// that operation cost the operation and not the result.
/// The custody this connection's REGISTRATION reserved, pinned.
///
/// NOT A FRESH ONE BESIDE IT. The home a control publishes into has to be the
/// one the service owner set aside before this connection's row went in --
/// otherwise every control would be exercising a custody no registration ever
/// knew about, and the reservation this component exists for would be
/// untested.
fn custody_for<'o>(
    f: &PrivateWorkerFixture,
    keeper: &'o crate::PrivateServiceOwner,
) -> PrivateCustodyPin<'o> {
    // THE KEEPER IS BORROWED, NOT THE FIXTURE. A pin tied to the whole fixture
    // would stop a control touching anything else in it, which is a borrow
    // about this helper's shape rather than about the owner this pin depends
    // on.
    let PrivateCustodyReach::Reached(pin) = f
        .fixture
        .registration
        .registered_custody(&keeper.lease())
        .expect("a private registration reserves a custody")
    else {
        panic!("its own service owner still keeps it")
    };
    pin
}

/// A started worker, through the real startup transaction, whose handle a
/// reaping can take.
///
/// THE ACTUAL PAIR: the body runs in the thread the startup transaction
/// spawned, writing its departure into the exit record the reaping reads.
/// Nothing asserts that pairing from the types -- they cannot establish it --
/// which is why it is built from one startup rather than assembled from parts.
/// Start one worker into THIS CONNECTION'S OWN registered slot.
///
/// The destination is the custody's, not a local of this helper: that is the
/// component's whole subject, and a control that started into a slot beside it
/// would be exercising the old shape.
fn started_worker<F>(custody: &PrivateEvidenceCustody, f: &PrivateWorkerFixture, body: F)
where
    F: FnOnce() + Send + 'static,
{
    assert_eq!(
        start_connection_worker(custody.worker_slot(), &f.stop, &f.wake, || {
            std::thread::Builder::new().spawn(body)
        }),
        PrivateStartupOutcome::Started
    );
}

/// The payload a publication home holds, as a string, if it holds one.
fn panic_payload_of(evidence: &PrivateJoinEvidence) -> Option<String> {
    let PrivateJoinResult::Panicked(payload) = evidence.result()? else {
        return None;
    };
    let held = payload.lock().expect("a readable payload");
    held.downcast_ref::<&str>()
        .map(|carried| (*carried).to_owned())
}

/// The payload a reaping kept, as a string, if it kept one.
fn panic_payload(record: &PrivateReapingRecord<'_>) -> Option<String> {
    panic_payload_of(&record.join_evidence())
}

#[test]
fn a_reaping_keeps_what_a_worker_that_returned_actually_returned() {
    // THE ORDINARY CASE, end to end: a real startup, a real body over this
    // connection's own home, a real stop, and a join whose result is in the
    // caller's record before the attempt reports anything.
    let f = worker_fixture(XServerFrontendClientId(8411));
    f.permit();
    let custody = custody_for(&f, &f.fixture.keeper);
    let (home, wake, stop, sequence) = f.handles();
    let running = Arc::clone(custody.exit_sink());
    started_worker(&custody, &f, move || {
        PrivateWorkerBody {
            home: &home,
            wake: &wake,
            stop: &stop,
            byte_order: XByteOrder::LittleEndian,
            sequence: &sequence,
            exit: &running,
            steps: 16,
        }
        .run();
    });
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.phase(), PrivateReapingPhase::NotBegun);

    cancel_connection_worker(&f.stop, &f.wake);
    let reaping = record.reap();

    assert_eq!(reaping.reaped, PrivateReaped::Joined);
    assert!(!reaping.slot_poisoned);
    assert_eq!(record.phase(), PrivateReapingPhase::Joined);
    assert!(
        matches!(record.result(), Some(PrivateJoinResult::Returned)),
        "the frame returned, and the record says which"
    );
    // THE BODY'S OWN EVIDENCE IS BESIDE IT, not derived from the join.
    let Some(PrivateExitReading::Classified(outcome)) = reaping.exit else {
        panic!("the body left a classification: {:?}", reaping.exit)
    };
    assert!(
        stopped_by_cancellation(&outcome),
        "the owner's own word: {outcome:?}"
    );
    drop(f.fixture);
}

#[test]
fn a_reaping_keeps_the_payload_a_worker_panicked_with() {
    // A JOIN THAT REPORTS A PANIC IS A COMPLETED JOIN, and what the frame was
    // carrying is kept rather than reduced to the fact that it panicked.
    let f = worker_fixture(XServerFrontendClientId(8412));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || {
        panic!("a worker frame carried this out with it");
    });
    let record = PrivateReapingRecord::bound_to(&custody);
    let reaping = record.reap();

    assert_eq!(reaping.reaped, PrivateReaped::Joined);
    assert_eq!(record.phase(), PrivateReapingPhase::Joined);
    assert_eq!(
        panic_payload(&record).as_deref(),
        Some("a worker frame carried this out with it"),
        "the exact payload, still there to be read"
    );
    // AND NOTHING WAS INVENTED FOR THE BODY. This thread never ran one, so
    // there is no classification and the join does not supply one.
    assert_eq!(reaping.exit, Some(PrivateExitReading::NotLeft));
    drop(f.fixture);
}

#[test]
fn a_departure_noticed_is_not_a_thread_collected() {
    // LEFT IS A HINT, NOT A JOIN. A departure is published as a frame goes,
    // which is before the thread has finished going; only the join says the
    // thread is quiescent.
    //
    // WHAT THIS ESTABLISHES is that the two facts are separate and that a
    // reaping does not take the first for the second. It does NOT establish
    // that an active reaper waits on a still-running worker: this control
    // releases the thread before asking. The control beside it, where two
    // threads ask at once, is where a reaping runs against a live worker.
    //
    // THE GUARD IS INSTALLED BY HAND, so the departure can be published while
    // the thread is deliberately held open. No body runs here.
    let f = worker_fixture(XServerFrontendClientId(8413));
    let custody = custody_for(&f, &f.fixture.keeper);
    let (release, held) = std::sync::mpsc::channel::<()>();
    let departing = Arc::clone(custody.exit_sink());
    started_worker(&custody, &f, move || {
        {
            let _leaving = PrivateWorkerLeaving(&departing);
        }
        let _ = held.recv();
    });
    let record = PrivateReapingRecord::bound_to(&custody);
    assert!(
        waited_for(|| custody.exit_sink().left()),
        "the frame published that it had gone"
    );
    assert_eq!(
        custody.exit_sink().reading(),
        PrivateExitReading::Unclassified,
        "departure noticed, classification absent -- and that is not a panic"
    );
    assert_eq!(
        record.phase(),
        PrivateReapingPhase::NotBegun,
        "and nothing has been joined"
    );

    drop(release);
    let reaping = record.reap();
    assert_eq!(reaping.reaped, PrivateReaped::Joined);
    assert!(
        matches!(record.result(), Some(PrivateJoinResult::Returned)),
        "the join is what establishes the thread finished, and how"
    );
    assert_eq!(
        reaping.exit,
        Some(PrivateExitReading::Unclassified),
        "and the join did not manufacture a classification"
    );
    drop(f.fixture);
}

#[test]
fn two_asks_at_once_join_a_worker_once() {
    // ONE ATTEMPT OWNS THE HANDLE, and this is the case the claim exists for:
    // two threads asking the same record while the worker is still running.
    //
    // THE OVERLAP IS WITNESSED, NOT HOPED FOR. The worker is held until the
    // slot itself says its handle has gone to a joiner AND the losing ask has
    // come back; releasing it and trusting the scheduler would let both asks
    // run serially after the thread had already finished, which would prove
    // nothing about either.
    let f = worker_fixture(XServerFrontendClientId(8418));
    let custody = custody_for(&f, &f.fixture.keeper);
    let (release, held) = std::sync::mpsc::channel::<()>();
    started_worker(&custody, &f, move || {
        let _ = held.recv();
        panic!("what exactly one of them keeps");
    });
    let record = PrivateReapingRecord::bound_to(&custody);

    std::thread::scope(|scope| {
        let (report, asked) = std::sync::mpsc::channel();
        for _ in 0..2 {
            let record = &record;
            let report = report.clone();
            scope.spawn(move || report.send(record.reap()));
        }
        drop(report);

        // ONE OF THEM HAS THE HANDLE, said by the slot rather than assumed.
        assert!(
            waited_for(|| {
                custody.worker_slot().lock().expect("a readable slot").life == PrivateWorkerLife::HandedToJoiner
            }),
            "an ask took the handle while its worker is still running"
        );
        // AND THE OTHER HAS ALREADY COME BACK, while that worker is still
        // held: the only ask that can return now is the one that found the
        // record taken, because the one that joined is waiting on the thread.
        let losing = asked
            .recv_timeout(Duration::from_secs(3))
            .expect("the losing ask returned");
        assert_eq!(losing.reaped, PrivateReaped::AlreadyAsked);
        assert_eq!(losing.exit, None, "it read nothing, having done nothing");
        assert_eq!(
            record.phase(),
            PrivateReapingPhase::InProgress,
            "a handle is consumed and no result is confirmed"
        );
        assert!(record.result().is_none());

        // Only now may the worker finish.
        drop(release);
        let winning = asked
            .recv_timeout(Duration::from_secs(3))
            .expect("the joining ask returned");
        assert_eq!(winning.reaped, PrivateReaped::Joined);
    });

    assert_eq!(record.phase(), PrivateReapingPhase::Joined);
    assert_eq!(
        panic_payload(&record).as_deref(),
        Some("what exactly one of them keeps"),
        "one join, one result"
    );
    let held = custody.worker_slot().lock().expect("a readable slot");
    assert!(held.handle.is_none());
    assert_eq!(held.life, PrivateWorkerLife::HandedToJoiner);
    drop(held);
    drop(f.fixture);
}

#[test]
fn a_second_ask_joins_nothing_and_changes_nothing() {
    // A second ask must not join twice, detach another handle, overwrite what
    // the first established, or leave the slot looking startable over a thread
    // that has already run.
    let f = worker_fixture(XServerFrontendClientId(8414));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || {
        panic!("what the first ask keeps");
    });
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);

    let again = record.reap();
    assert_eq!(again.reaped, PrivateReaped::AlreadyAsked);
    assert_eq!(again.exit, None, "it read nothing, having done nothing");
    assert_eq!(record.phase(), PrivateReapingPhase::Joined);
    assert_eq!(
        panic_payload(&record).as_deref(),
        Some("what the first ask keeps")
    );
    let held = custody.worker_slot().lock().expect("a readable slot");
    assert!(held.handle.is_none());
    assert_eq!(held.life, PrivateWorkerLife::HandedToJoiner);
    drop(held);
    drop(f.fixture);
}

#[test]
fn an_ask_that_consumes_nothing_says_which_nothing_it_found() {
    // THREE DIFFERENT NOTHINGS, and a caller deciding whether to expect a join
    // needs them apart. None of them consumes anything, so each leaves this
    // connection's one publication right where it found it.
    //
    // ALL THREE ARE ASKED OF ONE REGISTERED SOURCE, in the order a single slot
    // can actually reach them: a reaping view has no slot of its own to be
    // given any more, so the states are produced in this connection's own slot
    // rather than staged in three slots beside it.
    let f = worker_fixture(XServerFrontendClientId(8415));
    let custody = custody_for(&f, &f.fixture.keeper);

    // NEVER STARTED, which is true of this source until something starts it.
    let first = PrivateReapingRecord::bound_to(&custody);
    let reaping = first.reap();
    assert_eq!(reaping.reaped, PrivateReaped::NothingStarted);
    assert_eq!(reaping.exit, None);
    assert_eq!(
        first.phase(),
        PrivateReapingPhase::NotBegun,
        "the intent is withdrawn: this attempt consumed nothing"
    );

    // HANDED ELSEWHERE. A real worker is started into this connection's own
    // slot and its handle is taken by this control, which is what any other
    // joiner would have done.
    started_worker(&custody, &f, || {});
    let handle = hand_worker_to_joiner(custody.worker_slot())
        .handle
        .expect("the started worker's handle");
    let second = PrivateReapingRecord::bound_to(&custody);
    let elsewhere = second.reap();
    assert_eq!(elsewhere.reaped, PrivateReaped::HandedElsewhere);
    assert_eq!(second.phase(), PrivateReapingPhase::NotBegun);
    assert!(second.result().is_none());
    handle.join().expect("this control joins what it took");

    // A HANDLE GONE WITH NOTHING SAYING IT WAS HANDED ON. STAGED, and only
    // this: the connection's own slot is written into the state something
    // would leave if it took a handle without recording that it had. No path
    // here produces it, which is why it is written rather than reached.
    *custody
        .worker_slot()
        .lock()
        .expect("a readable slot") = PrivateWorkerSlot {
        handle: None,
        departing: false,
        life: PrivateWorkerLife::Running,
    };
    let third = PrivateReapingRecord::bound_to(&custody);
    let missing = third.reap();
    assert_eq!(
        missing.reaped,
        PrivateReaped::HandleMissing,
        "neither never-started nor handed on, and a caller told either \
         would be wrong"
    );
    assert_eq!(third.phase(), PrivateReapingPhase::NotBegun);
    assert!(
        third.result().is_none(),
        "three looks, and nothing published by any of them"
    );
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_poisoned_slot_still_gives_up_its_handle_and_says_it_was_poisoned() {
    // A THREAD LEFT UNJOINABLE BECAUSE SOMEBODY PANICKED NEAR ITS SLOT IS THE
    // WORSE OUTCOME. The slot is recovered far enough to get the handle out,
    // and the poison is reported beside the answer rather than absorbed.
    let f = worker_fixture(XServerFrontendClientId(8416));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || {});
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _held = custody.worker_slot().lock().expect("a readable slot");
            panic!("a holder unwound inside this connection's worker slot");
        }))
        .is_err(),
        "the holder unwound"
    );
    assert!(custody.worker_slot().is_poisoned());

    let record = PrivateReapingRecord::bound_to(&custody);
    let reaping = record.reap();
    assert_eq!(reaping.reaped, PrivateReaped::Joined);
    assert!(reaping.slot_poisoned, "and the poison is reported");
    assert!(matches!(record.result(), Some(PrivateJoinResult::Returned)));
    drop(f.fixture);
}

#[test]
fn a_joined_result_publishes_while_its_exit_record_is_held() {
    // THE RESULT IS NOT HOSTAGE TO A DIAGNOSTIC. The exit record is read after
    // the join result has been retained and published, and never as a
    // condition of it -- so a record another thread is holding costs a caller
    // the diagnostic and not the join.
    //
    // HELD ACROSS THE REAPING, not merely poisoned: a reaping that took this
    // lock on its way to publishing would wait here, and the phase would not
    // move until it was released.
    let f = worker_fixture(XServerFrontendClientId(8417));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || {});
    let record = PrivateReapingRecord::bound_to(&custody);

    let reaping = std::thread::scope(|scope| {
        let (taken, wait) = std::sync::mpsc::channel();
        let (release, held) = std::sync::mpsc::channel::<()>();
        let holder = Arc::clone(custody.exit_sink());
        let keeper = scope.spawn(move || {
            let _guard = holder.outcome.lock().expect("a readable exit record");
            taken.send(()).expect("the exit record is held");
            let _ = held.recv();
        });
        wait.recv().expect("the exit record is held");
        let record = &record;
        let reaper = scope.spawn(move || record.reap());
        // The join and its publication happen while the diagnostic is held.
        assert!(
            waited_for(|| record.phase() == PrivateReapingPhase::Joined),
            "the result is published without waiting for the exit record"
        );
        drop(release);
        keeper.join().expect("the holder finished");
        reaper.join().expect("the reaping finished")
    });

    assert_eq!(reaping.reaped, PrivateReaped::Joined);
    assert!(matches!(record.result(), Some(PrivateJoinResult::Returned)));
    drop(f.fixture);
}

/// A connection whose worker has been started, run and joined, with its gate
/// captured while the registration still had one to give.
///
/// THE PAIRING IS THE CALLER'S: the gate is this registration's own and the
/// join is over the thread that was serving through it. Nothing in the types
/// establishes that, which is why it is built from one connection here.
struct PrivateFenceFixture {
    f: PrivateWorkerFixture,
    gate: Arc<PrivateHandoverGate>,
}

fn fence_fixture(client: XServerFrontendClientId) -> PrivateFenceFixture {
    let f = worker_fixture(client);
    f.permit();
        let custody = custody_for(&f, &f.fixture.keeper);
    let gate = f.fixture.registration.handover_gate();
    let (home, wake, stop, sequence) = f.handles();
    {
        // THE WORKER GOES INTO THE CONNECTION'S OWN SLOT, and is handed only
        // the sink it writes its classification into -- not the custody, not
        // the registration and not the owner.
        let running = Arc::clone(custody.exit_sink());
        started_worker(&custody, &f, move || {
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit: &running,
                steps: 16,
            }
            .run();
        });
    }
    PrivateFenceFixture { f, gate }
}

#[test]
fn a_fence_waits_for_the_join_that_makes_it_eligible() {
    // A JOINED THREAD IS ONE WHOSE OWN SERVING HAS FINISHED, which is the
    // sequencing this component waits for. It is not a claim that nothing can
    // hand anything over afterwards -- producers are what the gate holds back,
    // and they outlive a consumer. Every weaker sign leaves this connection
    // still being served: a departure published, an empty slot, an attempt
    // that may have taken a handle.
    let g = fence_fixture(XServerFrontendClientId(8421));
    let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);

    // ASKED TOO EARLY: nothing is entered and nothing is spent.
    assert_eq!(fence.record_fence(), PrivateFenced::JoinIncomplete);
    assert_eq!(fence.phase(), PrivateFencePhase::NotAttempted);
    assert_eq!(fence.fence(), None);
    assert_eq!(
        g.f.fixture.registration.ordered_handovers_fenced(),
        Some(false),
        "the gate is untouched and this connection still admits handovers"
    );

    // THE SAME RECORD IS STILL ELIGIBLE once that same join completes.
    cancel_connection_worker(&g.f.stop, &g.f.wake);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert_eq!(fence.phase(), PrivateFencePhase::FenceRecorded);
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));
    assert_eq!(
        g.f.fixture.registration.ordered_handovers_fenced(),
        Some(true),
        "and now it does not"
    );
    drop(g.f.fixture);
}

#[test]
fn an_unconfirmed_join_is_not_a_joined_one() {
    // AN ATTEMPT THAT MAY HAVE TAKEN A HANDLE IS NOT A FINISHED THREAD. The
    // worker is held here, so the reaping is genuinely in flight: its record
    // says InProgress, its slot says the handle has gone, and neither is a
    // reason to close anything.
    let g = fence_fixture(XServerFrontendClientId(8422));
    let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);

    std::thread::scope(|scope| {
        let record = &record;
        let reaper = scope.spawn(move || record.reap());
        // ARMED BEFORE ANY ASSERTION THAT CAN FAIL. A failing assertion below
        // would otherwise skip the cancellation, and the scope would join a
        // reaper that is waiting on a worker nothing had told to stop.
        let _stopper = PrivateWorkerStopper(&g.f.stop, &g.f.wake);
        // THE SLOT IS WHAT SAYS THE HANDLE HAS GONE, not the record's phase.
        // The intent is written BEFORE the handoff -- that is what write-ahead
        // means -- so a reaping paused between them has an InProgress record
        // over a slot that is still Running with its handle in it. Waiting on
        // the phase and then asserting the slot would be asserting a schedule.
        assert!(
            waited_for(|| {
                custody.worker_slot().lock().expect("a readable slot").life
                    == PrivateWorkerLife::HandedToJoiner
            }),
            "the reaping took the handle"
        );
        assert_eq!(
            record.phase(),
            PrivateReapingPhase::InProgress,
            "a handle is consumed and no result is confirmed"
        );

        assert_eq!(
            fence.record_fence(),
            PrivateFenced::JoinIncomplete,
            "an unconfirmed attempt is not a completed join"
        );
        assert_eq!(fence.phase(), PrivateFencePhase::NotAttempted);
        assert_eq!(
            g.f.fixture.registration.ordered_handovers_fenced(),
            Some(false),
            "and the gate is untouched"
        );

        cancel_connection_worker(&g.f.stop, &g.f.wake);
        assert_eq!(
            reaper.join().expect("the reaping finished").reaped,
            PrivateReaped::Joined
        );
    });

    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));
    drop(g.f.fixture);
}

#[test]
fn a_join_that_reported_a_panic_is_a_completed_join() {
    // BOTH RESULTS ARE COMPLETED JOINS. A thread that panicked is as finished
    // as one that returned, and the payload is neither inspected nor locked to
    // decide it -- a fence that had to read one would be hostage to whoever
    // was reading the payload at the time.
    let f = worker_fixture(XServerFrontendClientId(8423));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || panic!("what the join kept"));
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    let fence = PrivateFenceRecord::bound_to(&custody);

    // The payload is held by this control for the whole of the fencing, which
    // a fence that needed it could not have got past.
    let PrivateJoinResult::Panicked(payload) = record.result().expect("a completed join") else {
        panic!("this worker panicked")
    };
    let held = payload.lock().expect("a readable payload");
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));
    assert_eq!(
        held.downcast_ref::<&str>().copied(),
        Some("what the join kept"),
        "and the payload is exactly as it was"
    );
    drop(held);
    drop(f.fixture);
}

#[test]
fn a_fence_keeps_the_three_things_a_gate_can_say() {
    // ESTABLISHED, ALREADY ESTABLISHED AND UNREADABLE ARE THREE FACTS. A
    // closure somebody else made is not one this made, and a gate whose lock
    // carried a panic out of somebody's handover is not a fence at all.
    let established = {
        let g = fence_fixture(XServerFrontendClientId(8424));
        cancel_connection_worker(&g.f.stop, &g.f.wake);
        let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let seen = fence.fence();
        drop(g.f.fixture);
        seen
    };
    assert_eq!(established, Some(PrivateHandoverFence::Established));

    // ALREADY ESTABLISHED, reached by a real close this component did not
    // make: the registration's own fencing runs first.
    let already = {
        let g = fence_fixture(XServerFrontendClientId(8425));
        cancel_connection_worker(&g.f.stop, &g.f.wake);
        let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        assert_eq!(
            g.f.fixture.registration.fence_ordered_handovers(),
            PrivateHandoverFence::Established,
            "somebody else closed it first, through the real API"
        );
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let seen = fence.fence();
        drop(g.f.fixture);
        seen
    };
    assert_eq!(already, Some(PrivateHandoverFence::AlreadyEstablished));

    // UNREADABLE: a holder panicked inside the gate. The lock is acquired --
    // that is what poisoning means -- and what could not be established is
    // closure over custody nobody stands behind.
    let unreadable = {
        let g = fence_fixture(XServerFrontendClientId(8426));
        cancel_connection_worker(&g.f.stop, &g.f.wake);
        let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        assert!(
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let _inside = g.gate.fenced.lock().expect("a readable gate");
                panic!("a holder unwound inside this connection's gate");
            }))
            .is_err(),
            "the holder unwound"
        );
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let seen = fence.fence();
        // NOT CLEARED AND NOT REOPENED: the gate is left exactly as it was
        // found.
        assert!(g.gate.fenced.is_poisoned());
        drop(g.f.fixture);
        seen
    };
    assert_eq!(unreadable, Some(PrivateHandoverFence::Unreadable));
}

#[test]
fn a_second_fencing_asks_nothing_and_replaces_nothing() {
    // A REPEATED ASK MUST NOT ASK THE GATE AGAIN. The second call would get
    // AlreadyEstablished from a gate this record itself had closed, and
    // writing that over the first Established would turn a closure this made
    // into one it merely found.
    let g = fence_fixture(XServerFrontendClientId(8427));
    cancel_connection_worker(&g.f.stop, &g.f.wake);
    let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);

    assert_eq!(fence.record_fence(), PrivateFenced::AlreadyAttempted);
    assert_eq!(
        fence.fence(),
        Some(PrivateHandoverFence::Established),
        "the first attempt's answer, not a second one over the top of it"
    );
    assert_eq!(fence.phase(), PrivateFencePhase::FenceRecorded);
    drop(g.f.fixture);
}

#[test]
fn a_fencing_that_waits_on_a_handover_leaves_its_evidence_readable() {
    // THE GATE MAY BLOCK, and the point is what stays readable while it does.
    // A handover admitted before this asks holds the gate until it is done;
    // nothing of this connection's is held behind that wait, so a caller can
    // still read the join result and this attempt's standing.
    let g = fence_fixture(XServerFrontendClientId(8428));
    cancel_connection_worker(&g.f.stop, &g.f.wake);
    let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    let fence = PrivateFenceRecord::bound_to(&custody);

    std::thread::scope(|scope| {
        let (admitted, wait) = std::sync::mpsc::channel();
        let (release, held) = std::sync::mpsc::channel::<()>();
        let sender = g.f.sender.clone();
        let producer = scope.spawn(move || {
            let _inside = sender.admit().expect("an open endpoint");
            admitted.send(()).expect("inside the gate");
            let _ = held.recv();
        });
        wait.recv().expect("a handover is inside the gate");

        let fence = &fence;
        let fencing = scope.spawn(move || fence.record_fence());
        // WHAT IS OBSERVED, exactly: while that handover holds the gate, no
        // fence is published, and the join result and this attempt's standing
        // are both readable. It does NOT establish that the fencing thread has
        // reached the gate's lock -- nothing here can say that.
        assert!(
            waited_for(|| fence.phase() == PrivateFencePhase::InProgress),
            "the attempt claimed this record"
        );
        assert_eq!(fence.fence(), None, "and has published nothing");
        assert!(
            matches!(record.result(), Some(PrivateJoinResult::Returned)),
            "the join result is readable throughout"
        );
        assert_eq!(record.phase(), PrivateReapingPhase::Joined);

        drop(release);
        producer.join().expect("the handover finished");
        assert_eq!(
            fencing.join().expect("the fencing finished"),
            PrivateFenced::Recorded
        );
    });
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));
    drop(g.f.fixture);
}

#[test]
fn fencing_one_connection_leaves_another_connections_gate_open() {
    // A GATE IS ONE CONNECTION'S. This record holds the one it was bound to
    // and reaches nothing by lookup, so closing it says nothing about anybody
    // else's endpoint -- and nothing about anybody's queue, custody or wire,
    // its own included.
    //
    // THE WORK IS QUEUED BEFORE THE FENCE, on both connections, so what is
    // compared afterwards is the same capsule that was there: a capsule
    // inserted after a closure and then found could have been anything.
    // Fixture capsules, carrying their own completions; no claim is made that
    // either recipient would have admitted them.
    let g = fence_fixture(XServerFrontendClientId(8429));
    let other = worker_fixture(XServerFrontendClientId(8430));
    // The target's own worker is stopped and joined first, so what is queued
    // for it below stays queued: a running body would serve it, which is that
    // component's business and not this one's.
    cancel_connection_worker(&g.f.stop, &g.f.wake);
    let custody = custody_for(&g.f, &g.f.fixture.keeper);
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);

    let queued = [(&g.f, 84290u64), (&other, 84300u64)].map(|(f, delivery)| {
        let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(delivery);
        let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
        let frames = order_pass_frames(&capsule);
        produced_send(&f.sender, capsule);
        (cell, frames)
    });
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));

    assert_eq!(
        g.f.fixture.registration.ordered_handovers_fenced(),
        Some(true)
    );
    assert_eq!(
        other.fixture.registration.ordered_handovers_fenced(),
        Some(false),
        "the other connection still admits handovers"
    );

    // AND NEITHER QUEUE WAS TOUCHED. The exact capsules, their frames and
    // their completion cells, on the fenced connection and on its neighbour
    // alike: closing a gate receives nothing and answers nothing.
    for (f, (cell, frames), delivery) in [
        (&g.f, &queued[0], 84290u64),
        (&other, &queued[1], 84300u64),
    ] {
        let survived = f
            .home
            .borrow_live(|payload| {
                let PrivateOrderedContinuation::Serving { owner, .. } = payload else {
                    panic!("promoted")
                };
                owner.queue.try_recv().ok()
            })
            .acted()
            .expect("its own home")
            .expect("what was accepted for it before the fencing");
        assert_eq!(
            survived.delivery(),
            XAuthorityInputDeliveryId::from_raw(delivery)
        );
        assert_eq!(order_pass_frames(&survived), *frames);
        assert!(Arc::ptr_eq(
            cell,
            &survived.finalizer().expect("carried").completion
        ));
        assert!(cell.answer().is_none(), "and nothing answered for it");
        // AND NOTHING REACHED EITHER PEER. A fence writes no bytes.
        let mut byte = [0u8; 1];
        assert_eq!(
            std::io::Read::read(&mut (&f.peer), &mut byte)
                .expect_err("nothing was written")
                .kind(),
            std::io::ErrorKind::WouldBlock
        );
        assert_eq!(
            f.home.standing(),
            PrivateHomeStanding::Live,
            "and no standing was changed"
        );
    }
    drop((g.f.fixture, other.fixture));
}

#[test]
fn a_fence_is_not_delayed_by_a_diagnostic_somebody_is_holding() {
    // A PUBLISHED JOIN IS ENOUGH, AND NEITHER OPTIONAL LOCK IS ON THE WAY TO
    // THE GATE. WHAT THIS ESTABLISHES, exactly: a fencing completes while both
    // the panic payload and the exit diagnostic are held by somebody else. It
    // does NOT establish that a fencing can run before the reaping call has
    // returned from its own diagnostic read -- the reap here finishes first --
    // and that is a separate claim needing a separate control.
    let f = worker_fixture(XServerFrontendClientId(8431));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || panic!("held while the gate is closed"));
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    let fence = PrivateFenceRecord::bound_to(&custody);

    let PrivateJoinResult::Panicked(payload) = record.result().expect("a completed join") else {
        panic!("this worker panicked")
    };
    let payload_held = payload.lock().expect("a readable payload");
    let diagnostic_held = custody.exit_sink().outcome.lock().expect("a readable exit record");
    assert_eq!(
        fence.record_fence(),
        PrivateFenced::Recorded,
        "neither lock is on the way to the gate"
    );
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));
    drop((payload_held, diagnostic_held));
    drop(f.fixture);
}

/// Which holder entry, if any, this store has set aside for a place.
fn maintenance_destination(
    durable: &PrivateSettlementOwner,
    place: usize,
) -> Option<&'static str> {
    let held = durable.records_even_if_poisoned();
    held.holders.iter().find_map(|entry| match entry {
        PrivateHolderPlace::Reserved(reserved) if *reserved == place => Some("reserved"),
        PrivateHolderPlace::Promised(promised) if *promised == place => Some("promised"),
        PrivateHolderPlace::Taken(holder) if holder.credit.index == place => Some("taken"),
        _ => None,
    })
}

#[test]
fn a_connections_obligation_is_named_and_housed_before_it_is_published() {
    // BEFORE THE ROW, WHICH IS THE WHOLE POINT. What will eventually fill this
    // destination -- a joined worker, a closed gate, an obligation somebody
    // commits -- all happens long after this connection is reachable. Finding
    // storage for it then would mean a connection whose sender producers can
    // already reach could be left unable to be finished for want of room.
    //
    // SOURCE ORDERING IS WHAT ESTABLISHES "BEFORE" HERE. The reservation runs
    // inside register_client_with_admission ahead of publish_registered_client
    // and ahead of the client table, and the destination is set aside in the
    // same acquisition as the place. What this control observes is the state
    // that ordering leaves: a registration that exists at all already has
    // both, on one credit.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8441);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");

    let identity = registration
        .maintenance_identity()
        .expect("this connection has a place, so it has a name");
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert_eq!(
        maintenance_destination(&durable, identity.place()),
        Some("reserved"),
        "its destination was set aside with its place"
    );
    assert_eq!(
        durable.holders_taken(),
        Some(0),
        "and nothing holds one: a reserved destination is inert"
    );

    // THE SAME NAME EVERY TIME, and it names this connection's own home.
    let again = registration
        .maintenance_identity()
        .expect("the same connection");
    assert!(identity.same_as(&again), "one connection, one name");
    assert!(
        identity
            .with_home(|home| Arc::ptr_eq(home, &registration.ordered_home))
            .reached()
            .expect("its place is its own"),
        "and the home it names is the one this registration binds into"
    );
    drop((registration, private));
}

#[test]
fn every_connection_at_the_bound_already_has_its_destination() {
    // NO SECOND POOL AND NO SECOND CHARGE. One connection place carries one
    // maintenance destination, so a store at its bound has a destination for
    // every connection it admitted and the conversion needs no extra credit.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let held: Vec<_> = [8442u64, 8443]
        .iter()
        .map(|raw| {
            let client = XServerFrontendClientId(*raw);
            private
                .broker
                .registry
                .register_client_with_admission(client, Some(admitted(client)))
                .expect("a place and a row")
                .0
        })
        .collect();
    assert_eq!(durable.continuations_reserved(), Some(2), "at the bound");
    for registration in &held {
        let place = registration
            .maintenance_identity()
            .expect("a place, so a name")
            .place();
        assert_eq!(maintenance_destination(&durable, place), Some("reserved"));
    }

    // AND THE APPROVED CONVERSION FINDS ITS DESTINATION ALREADY THERE, taking
    // no further credit for it.
    let lease = lease_of(&held[0]);
    let before = durable.continuations_reserved();
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("the destination reserved with this place");
    assert_eq!(durable.continuations_reserved(), before);
    assert_eq!(
        maintenance_destination(&durable, lease.index),
        Some("promised")
    );
    let outer = durable.clone();
    assert!(matches!(
        lease.convert_to_internal(&outer, destination),
        PrivateInternalConversion::Held
    ));
    assert_eq!(durable.continuations_reserved(), before, "and still none");
    assert_eq!(durable.continuations_abandoned(), Some(0));
    drop((held, private, outer));
}

#[test]
fn a_preparation_that_is_never_committed_leaves_the_destination_reserved() {
    // BACK TO RESERVED, NOT FREE. Nothing was put in it and the place it was
    // set aside for is still this connection's; handing it to somebody else
    // would leave a published connection with nowhere for its obligation.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8444);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let lease = lease_of(&registration);
    {
        let destination = durable
            .prepare_internal_holder(&lease)
            .expect("its own destination");
        assert_eq!(
            maintenance_destination(&durable, destination.for_place),
            Some("promised")
        );
    }
    assert_eq!(
        maintenance_destination(&durable, lease.index),
        Some("reserved"),
        "the preparation went and the reservation stayed"
    );
    // And it can be prepared again, because it is still this connection's.
    assert!(durable.prepare_internal_holder(&lease).is_ok());
    drop((registration, private, lease));
}

#[test]
fn an_unexposed_refusal_leaves_no_destination_behind() {
    // A RESERVATION THAT PUBLISHED NOTHING GIVES BACK BOTH. The existing
    // unexposed release returns the place; the destination set aside with it
    // goes the same way, or the next connection to reserve would find one of
    // its entries already spoken for by a connection that never existed.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let lease = durable
        .reserve_ordered_continuation()
        .expect("a declared bound leaves a place");
    let place = lease.index;
    assert_eq!(maintenance_destination(&durable, place), Some("reserved"));

    lease.relinquish_unexposed();
    assert_eq!(durable.continuations_reserved(), Some(0));
    assert_eq!(
        maintenance_destination(&durable, place),
        None,
        "and its destination went with it"
    );
    drop(private);
}

#[test]
fn a_name_outlives_its_connection_and_its_conversion() {
    // THE NAME IS WHAT THE OBLIGATION IS CALLED, so it has to survive the
    // things that end a connection without ending what it owed: its
    // registration being destroyed, and its place becoming the store's own
    // responsibility.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8445);
    let (private, registration, cell, frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 84450);
    let identity = registration
        .maintenance_identity()
        .expect("a place, so a name");

    let outer = hand_place_to_store(&durable, &registration);
    // A CONVERSION DOES NOT RENAME IT: same store, same place, same home.
    let named = durable.take_internal_holder(0).expect("a holder");
    assert!(
        identity.same_as(&named.credit.maintenance_identity()),
        "the store's own holder names the same obligation"
    );

    drop(registration);
    // AND THE CONNECTION ENDING DOES NOT EITHER. The name still resolves, and
    // the home it reaches still holds what was accepted for it.
    let survived = identity
        .with_home(|home| home.borrow(|continuation| continuation.queue().try_recv().ok()))
        .reached()
        .expect("its place is still its own")
        .expect("its home")
        .expect("the capsule accepted before it ended");
    assert_eq!(
        survived.delivery(),
        XAuthorityInputDeliveryId::from_raw(84450)
    );
    assert_eq!(order_pass_frames(&survived), frames);
    assert!(Arc::ptr_eq(
        &cell,
        &survived.finalizer().expect("carried").completion
    ));
    drop((private, survived, cell, named, outer));
}

#[test]
fn a_name_stops_resolving_when_its_place_goes_back() {
    // A RETURNED PLACE IS NOBODY'S, INCLUDING ITS OWN. The name must stop
    // resolving the moment the place goes back -- not when a successor
    // arrives -- because between those two a caller acting on "still current"
    // would be acting on a place that is free.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8446);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 84460);
    let identity = registration
        .maintenance_identity()
        .expect("a place, so a name");
    let place = identity.place();
    let outer = hand_place_to_store(&durable, &registration);
    drop(registration);
    let mut named = durable.take_internal_holder(0).expect("a holder");
    assert!(matches!(
        credit_receives(&named.credit),
        PrivateCreditReach::Reached(Some(_))
    ));
    drop(private);

    // The place is returned through the credit's own release.
    let mut settled = false;
    for _ in 0..8 {
        let Some(finished) = named
            .credit
            .with_place(|continuation| {
                continuation.visit();
                continuation.settled()
            })
            .reached()
        else {
            panic!("the place is this credit's until it releases it")
        };
        settled = finished;
        if settled {
            break;
        }
    }
    assert!(settled);
    assert!(matches!(
        named.credit.release(),
        PrivateCreditRelease::Released
    ));
    assert_eq!(durable.continuations_reserved(), Some(0));

    // NOTHING HAS TAKEN THE NUMBER YET, and the name is already stale.
    assert!(matches!(
        identity.with_home(|_| ()),
        PrivateMaintenanceReach::Stale
    ));
    assert_eq!(
        maintenance_destination(&durable, place),
        None,
        "and its destination is free for whoever comes next"
    );

    // A SUCCESSOR TAKES THE SAME NUMBER AND GETS A DIFFERENT NAME.
    let second = XServerFrontendClientId(8447);
    let (successor, successor_registration, successor_cell, successor_frames, _successor_wire, _successor_keeper) =
        converted_fixture(&durable, second, 84470);
    let successor_identity = successor_registration
        .maintenance_identity()
        .expect("a place, so a name");
    assert_eq!(successor_identity.place(), place, "the same number");
    assert!(
        !identity.same_as(&successor_identity),
        "and a different obligation"
    );
    assert!(matches!(
        identity.with_home(|_| ()),
        PrivateMaintenanceReach::Stale
    ));
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("reserved"),
        "the successor's own destination, set aside with its own place"
    );

    // AND THE OLD NAME REACHED NOTHING OF THE SUCCESSOR'S.
    let capsule = successor_registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the successor's own capsule");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(84470)
    );
    assert_eq!(order_pass_frames(&capsule), successor_frames);
    assert!(Arc::ptr_eq(
        &successor_cell,
        &capsule.finalizer().expect("carried").completion
    ));
    assert!(successor_cell.answer().is_none());
    drop((successor_registration, successor, capsule, named, outer));
}

#[test]
fn a_name_from_another_store_resolves_to_nothing_here() {
    // A NAME CARRIES ITS STORE. Two connections can hold the same number in
    // different stores, and neither is the other's.
    let one = PrivateSettlementOwner::default();
    let two = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&one, 2);
    let first = private_over(&service_keeper, 2);
    let service_keeper = service_owner(&two, 2);
    let second = private_over(&service_keeper, 2);
    let a = XServerFrontendClientId(8448);
    let b = XServerFrontendClientId(8449);
    let (one_registration, _one_channels) = first
        .broker
        .registry
        .register_client_with_admission(a, Some(admitted(a)))
        .expect("a place and a row");
    let (two_registration, _two_channels) = second
        .broker
        .registry
        .register_client_with_admission(b, Some(admitted(b)))
        .expect("a place and a row");
    let here = one_registration.maintenance_identity().expect("a name");
    let there = two_registration.maintenance_identity().expect("a name");

    // WHAT THIS ESTABLISHES is structural: each name carries its own store
    // weakly and resolves in that one, so two connections holding the same
    // number in different stores are different obligations and neither
    // resolves into the other. There is no receiving store to refuse a
    // foreign name -- with_home has nowhere to be asked from -- and this does
    // not claim such a refusal exists.
    assert_eq!(here.place(), there.place(), "the same number");
    assert!(!here.same_as(&there), "and different obligations");
    assert!(
        here.with_home(|home| Arc::ptr_eq(home, &one_registration.ordered_home))
            .reached()
            .expect("its own store"),
        "each resolves in its own store"
    );
    assert!(
        there
            .with_home(|home| Arc::ptr_eq(home, &two_registration.ordered_home))
            .reached()
            .expect("its own store")
    );
    drop((one_registration, two_registration, first, second));
}

#[test]
fn a_lookup_keeps_the_store_it_found_until_its_act_is_over() {
    // A NAME HOLDS ITS STORE WEAKLY, so every lookup begins by upgrading. An
    // operation that let that upgrade go before acting would be acting on a
    // home whose store could disappear underneath it -- and the home survives
    // in the handle the lookup pinned, so the act would finish and look like
    // success.
    //
    // THE LAST HOLDER IS DROPPED FROM INSIDE THE ACT, which is precisely the
    // interval. Nothing is injected and no thread is raced.
    let durable = PrivateSettlementOwner::default();
    let capability = durable.settlement_ref();
    let client = XServerFrontendClientId(8451);
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let identity = registration.maintenance_identity().expect("a name");
    let home = Arc::clone(&registration.ordered_home);
    // Every holder of the store that is not the lookup's own goes in here --
    // the service owner with them, because keeping the store is exactly what
    // an owner is for.
    drop(registration);
    let last = std::cell::Cell::new(Some((private, durable, service_keeper)));
    let watch = capability.clone();

    let reached = identity
        .with_home(|found| {
            assert!(Arc::ptr_eq(found, &home));
            drop(last.take());
            // THE ASSERTION THAT SEPARATES THEM. A lookup that let its upgrade
            // go would leave the store gone from here on, and the rest of this
            // act would run against a home nobody could reach -- which reads
            // exactly like success, because the home itself survives in the
            // handle the lookup pinned.
            watch.owner().is_some()
        })
        .reached()
        .expect("its place is its own");
    assert!(
        reached,
        "the lookup holds the store it found for as long as its act runs"
    );

    // AND ONLY UNTIL IT IS OVER.
    assert!(capability.owner().is_none());
    assert!(matches!(
        identity.with_home(|_| ()),
        PrivateMaintenanceReach::StoreGone
    ));
    drop(home);
}

#[test]
fn a_name_whose_store_has_gone_says_so_and_holds_nothing_up() {
    // A NAME IS A NAME, NOT CUSTODY. It holds its store weakly, so a store
    // whose legitimate holders have all gone drops with everything in it --
    // and the name says the store has gone rather than that the place moved.
    let capability;
    let identity;
    {
        let durable = PrivateSettlementOwner::default();
        capability = durable.settlement_ref();
        let client = XServerFrontendClientId(8450);
        let service_keeper = service_owner(&durable, 2);
        let private = private_over(&service_keeper, 2);
        let (registration, _channels) = private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client)))
            .expect("a place and a row");
        identity = registration.maintenance_identity().expect("a name");
        assert!(identity.with_home(|_| ()).reached().is_some());
        drop((registration, private, durable));
    }
    assert!(
        capability.owner().is_none(),
        "a name does not keep a store alive"
    );
    assert!(matches!(
        identity.with_home(|_| ()),
        PrivateMaintenanceReach::StoreGone
    ));
}

/// Settle a connection's retained place through the real drive, so it goes
/// back and its number becomes available to a successor.
///
/// Every step is production's: the connection ends, its own teardown retains
/// what it owed, and the store's drive finishes and returns it.
fn settle_and_return(durable: &PrivateSettlementOwner, place: usize) {
    for _ in 0..16 {
        durable.drive_ordered_continuations(4);
        if matches!(
            durable.records_even_if_poisoned().continuations.get(place),
            Some(PrivateOrderedContinuationPlace::Free)
        ) {
            return;
        }
    }
    panic!("the drive did not return this place");
}

#[test]
fn a_stale_preparations_drop_leaves_its_successors_promise_alone() {
    // A DESTINATION ENTRY IS REUSABLE NOW, which is what makes this possible:
    // returning a place frees its destination at once, so a successor can be
    // reserved and prepared while an old preparation is still in somebody's
    // hand. A drop that recognised only "promised" would put that successor's
    // promise back to reserved and give its count away, and the successor
    // could then be prepared twice over.
    //
    // Both generations use the same number deliberately; what separates them
    // is which home occupies the place.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let lease = durable
        .reserve_ordered_continuation()
        .expect("a declared bound leaves a place");
    let place = lease.index;
    let stale = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    lease.relinquish_unexposed();
    assert_eq!(durable.continuations_reserved(), Some(0));

    // A REAL SUCCESSOR AT THE SAME NUMBER, with a preparation of its own.
    let client = XServerFrontendClientId(8452);
    let (successor, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let successor_lease = lease_of(&successor);
    assert_eq!(successor_lease.index, place, "the number was handed on");
    let kept = durable
        .prepare_internal_holder(&successor_lease)
        .expect("the successor's own destination");
    assert_eq!(durable.holders_taken(), Some(1));

    // THE OLD PREPARATION GOES, and takes nothing of the successor's with it.
    drop(stale);
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("promised"),
        "the successor's promise is still its own"
    );
    assert_eq!(durable.holders_taken(), Some(1), "and still counted once");
    assert!(
        matches!(
            durable.prepare_internal_holder(&successor_lease),
            Err(PrivateHolderRefusal::AlreadyHeld)
        ),
        "so it cannot be prepared a second time"
    );
    drop((kept, successor, channels, successor_lease, private));
}

#[test]
fn a_stale_lease_cannot_prepare_its_successors_destination() {
    // A LEASE CAN OUTLIVE ITS PLACE. The drive returns a place whose work is
    // settled and does not consult the lease that reserved it, so a caller
    // holding one after that is holding a number somebody else now has.
    // Preparing on the strength of it takes the successor's destination and
    // leaves the successor unable to prepare its own.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8453);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 84530);
    let stale_lease = lease_of(&registration);
    let place = stale_lease.index;
    // Its capsule is taken out, so the drive can finish the record.
    assert!(registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().is_ok())
        .expect("its own home"));
    drop(registration);
    settle_and_return(&durable, place);
    assert_eq!(durable.continuations_reserved(), Some(0));

    // A REAL SUCCESSOR TAKES THE NUMBER.
    let second = XServerFrontendClientId(8454);
    let (successor, successor_registration, successor_cell, successor_frames, _wire, _successor_keeper) =
        converted_fixture(&durable, second, 84540);
    let successor_lease = lease_of(&successor_registration);
    assert_eq!(successor_lease.index, place);

    // THE STALE LEASE IS REFUSED, and the successor is untouched.
    assert!(
        matches!(
            durable.prepare_internal_holder(&stale_lease),
            Err(PrivateHolderRefusal::Stale)
        ),
        "a lease whose place has gone back prepares nothing"
    );
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("reserved"),
        "the successor's destination is still reserved for it"
    );
    assert!(
        durable.prepare_internal_holder(&successor_lease).is_ok(),
        "and the successor can still prepare its own"
    );
    let capsule = successor_registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the successor's own capsule");
    assert_eq!(
        capsule.delivery(),
        XAuthorityInputDeliveryId::from_raw(84540)
    );
    assert_eq!(order_pass_frames(&capsule), successor_frames);
    assert!(Arc::ptr_eq(
        &successor_cell,
        &capsule.finalizer().expect("carried").completion
    ));
    assert!(successor_cell.answer().is_none());
    drop((
        private,
        successor,
        successor_registration,
        successor_lease,
        stale_lease,
        capsule,
    ));
}

#[test]
fn a_conversion_whose_place_moved_on_disturbs_nothing() {
    // THE CHECK AND THE PUBLICATION ARE TWO ACQUISITIONS, with the store
    // released in between. A place whose work settles in that gap goes back,
    // and the next connection takes the number and prepares a destination of
    // its own -- so publishing on the strength of the earlier check would
    // replace that connection's promise with a holder naming a home it never
    // had.
    //
    // WHAT THIS CONTROL ACTUALLY REACHES, said plainly: the place goes back
    // before the conversion is asked at all, so the FIRST of the two checks
    // catches it and the answer is NoPlace. The revalidation in the second
    // acquisition -- the one that matters when the place moves in the gap --
    // is not reached from here, and cannot be: the gap is inside one call and
    // closing it needs a schedule this control cannot impose. That the
    // successor is left untouched is established either way, and it is the
    // part a caller depends on.
    let durable = PrivateSettlementOwner::default();
    let client = XServerFrontendClientId(8455);
    let (private, registration, _cell, _frames, _wire, _private_keeper) =
        converted_fixture(&durable, client, 84550);
    let lease = lease_of(&registration);
    let place = lease.index;
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    assert!(registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().is_ok())
        .expect("its own home"));
    drop(registration);
    settle_and_return(&durable, place);

    // A REAL SUCCESSOR AT THE SAME NUMBER, with its own destination reserved.
    let second = XServerFrontendClientId(8456);
    let (successor, successor_registration, successor_cell, successor_frames, _wire, _successor_keeper) =
        converted_fixture(&durable, second, 84560);
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("reserved"),
        "the successor's own"
    );

    // THE OLD CONVERSION IS ASKED AND REFUSES.
    let outer = durable.clone();
    let PrivateInternalConversion::NoPlace(lease) = lease.convert_to_internal(&outer, destination)
    else {
        panic!("a place that moved on is not this lease's to commit")
    };
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("reserved"),
        "the successor's destination is untouched"
    );
    assert!(durable.take_internal_holder(0).is_none(), "no holder was made");
    assert_eq!(
        durable.continuations_abandoned(),
        Some(0),
        "and nothing was marked against the successor"
    );
    let capsule = successor_registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the successor's own capsule");
    assert_eq!(order_pass_frames(&capsule), successor_frames);
    assert!(Arc::ptr_eq(
        &successor_cell,
        &capsule.finalizer().expect("carried").completion
    ));
    assert!(successor_cell.answer().is_none());
    drop((private, successor, successor_registration, lease, outer, capsule));
}

#[test]
fn a_publication_that_is_refused_leaves_exactly_the_first_connections_reservation() {
    // THE REFUSAL PRODUCTION ACTUALLY HAS. A second registration for a client
    // that already has one is refused at publication, after its own place and
    // destination were reserved -- and the existing unexposed release is what
    // gives both back. The first connection keeps exactly what it had.
    let durable = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&durable, 2);
    let private = private_over(&service_keeper, 2);
    let client = XServerFrontendClientId(8457);
    let (first, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row");
    let identity = first.maintenance_identity().expect("a name");
    assert_eq!(durable.continuations_reserved(), Some(1));

    assert!(
        matches!(
            private
                .broker
                .registry
                .register_client_with_admission(client, Some(admitted(client))),
            Err(XServerFrontendRouteError::DuplicateClient { .. })
        ),
        "a client that already has a row is refused"
    );

    assert_eq!(
        durable.continuations_reserved(),
        Some(1),
        "the refused registration gave its place back"
    );
    assert_eq!(
        maintenance_destination(&durable, identity.place()),
        Some("reserved"),
        "and exactly the first connection's destination is left"
    );
    assert_eq!(
        durable
            .records_even_if_poisoned()
            .holders
            .iter()
            .filter(|place| !matches!(place, PrivateHolderPlace::Free))
            .count(),
        1,
        "one destination, not two"
    );
    assert!(
        identity
            .with_home(|home| Arc::ptr_eq(home, &first.ordered_home))
            .reached()
            .expect("still its own"),
        "and the first connection's name still resolves to its own home"
    );
    drop((first, private));
}

/// A registration of its own, to stand in a fixture's field while the real one
/// is dropped.
///
/// The fixture owns its registration and other records borrow its slot and
/// gate, so a control that needs the connection to END cannot simply move the
/// registration out. This puts an unrelated one in its place; nothing in the
/// control touches it.
fn spare_registration(
    f: &PreparedOrderedFixture,
) -> XServerFrontendClientRouteRegistration {
    let client = XServerFrontendClientId(f.client.raw() + 900_000);
    f.runner
        .frontend
        .as_ref()
        .unwrap()
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place and a row")
        .0
}

/// A connection carried all the way to committable evidence: real startup,
/// real body, real join, real fencing.
///
/// THE ASSOCIATION IS THIS FIXTURE'S, built from one registration and that
/// connection's own startup, join and gate. Nothing in the types establishes
/// which connection a worker served, and this does not claim otherwise.
struct PrivateCommitFixture {
    g: PrivateFenceFixture,
    place: usize,
}

fn commit_fixture(client: XServerFrontendClientId, panicking: bool) -> PrivateCommitFixture {
    let f = worker_fixture(client);
    f.permit();
    let gate = f.fixture.registration.handover_gate();
    let place = f
        .fixture
        .registration
        .maintenance_identity()
        .expect("a place, so a name")
        .place();
    let (home, wake, stop, sequence) = f.handles();
    {
        let custody = custody_for(&f, &f.fixture.keeper);
        let running = Arc::clone(custody.exit_sink());
        started_worker(&custody, &f, move || {
            if panicking {
                panic!("what this connection's worker carried out with it");
            }
            PrivateWorkerBody {
                home: &home,
                wake: &wake,
                stop: &stop,
                byte_order: XByteOrder::LittleEndian,
                sequence: &sequence,
                exit: &running,
                steps: 16,
            }
            .run();
        });
    }
    if !panicking {
        cancel_connection_worker(&f.stop, &f.wake);
    }
    PrivateCommitFixture {
        g: PrivateFenceFixture { f, gate },
        place,
    }
}

#[test]
fn a_commitment_waits_for_the_evidence_it_rests_on() {
    // COMPLETED, PUBLISHED EVIDENCE AND NOTHING WEAKER. A fencing that has not
    // recorded what the gate said, and a join that has published no result,
    // are both reasons this connection's obligation cannot yet be stated --
    // and neither is a reason to go and produce one.
    let c = commit_fixture(XServerFrontendClientId(8461), false);
    let durable = c.g.f.fixture.durable.clone();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("the destination reserved with this place");
    let outer = durable.clone();
    // The fixture's own spare registration has already ended, so this store's
    // abandonment account is not zero. What matters is that nothing below
    // moves it.
    let abandoned_before = durable.continuations_abandoned();

    // NEITHER JOINED NOR FENCED.
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::NotYetEvidenced));
    // NOTHING WAS CONSUMED AND NOTHING WAS CHANGED. The lease and the prepared
    // destination both stay in this context -- the destination still promised
    // to this place -- so the same context simply asks again.
    assert_eq!(
        maintenance_destination(&durable, c.place),
        Some("promised"),
        "the prepared destination stayed in this context, not spent and not \
         handed back"
    );
    assert_eq!(durable.continuations_abandoned(), abandoned_before);

    // JOINED BUT NOT FENCED: still not enough, and still the same context.
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert!(matches!(context.commit(), PrivateCommitted::NotYetEvidenced));
    assert_eq!(
        maintenance_destination(&durable, c.place),
        Some("promised"),
        "the prepared destination stayed in this context across both refusals"
    );

    // AND WHEN THE FENCE HAS RECORDED, THE SAME CONTEXT COMMITS.
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert!(matches!(context.commit(), PrivateCommitted::Committed));
    // A SECOND VISIT REPLACES NOTHING.
    assert!(matches!(context.commit(), PrivateCommitted::AlreadyCommitted));
    assert!(
        durable
            .committed_obligation(c.place)
            .is_some(),
        "the obligation is in this connection's own destination"
    );
    drop((c.g.f.fixture, outer));
}

#[test]
fn a_commitment_keeps_the_exact_evidence_after_the_frames_that_made_it_go() {
    // WHAT KEEPS THE EVIDENCE IS THE CUSTODY, TAKEN BEFORE ANY OF THIS BEGAN.
    // A worker that panicked was carrying something; an obligation that
    // recorded only "it panicked" while the payload went with the caller's
    // record would have kept the wrong thing, and a commitment that HANDED the
    // only handle back would have offered a keeper rather than made one.
    //
    // NOTHING IS RETURNED HERE. Every frame that produced this evidence --
    // the reaping record, the fencing record, the commitment context, the
    // borrowed view -- goes away below, and the payload is read afterwards out
    // of the home the custody has owned throughout.
    let c = commit_fixture(XServerFrontendClientId(8462), true);
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let durable = c.g.f.fixture.durable.clone();
    let place = c.place;
    {
        let view = custody.view();
        // A view reaches everything the custody has, and owns none of it.
        assert!(view.identity().same_as(custody.identity()));
        assert!(Arc::ptr_eq(view.join(), custody.join()));
        let lease = lease_of(&c.g.f.fixture.registration);
        let record = PrivateReapingRecord::bound_to(&custody);
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let destination = view
            .store()
            .prepare_internal_holder(&lease)
            .expect("its own destination");
        let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
        assert!(matches!(context.commit(), PrivateCommitted::Committed));
        // And the borrowed view ends here, which is the end of a borrow.
    }

    let obligation = durable
        .committed_obligation(place)
        .expect("the store names this connection's obligation");
    assert_eq!(obligation.closed(), PrivateHandoverFence::Established);
    assert_eq!(obligation.identity().place(), place);
    let evidence = obligation
        .join()
        .expect("its custodian still owns the evidence");
    assert!(
        Arc::ptr_eq(&evidence, custody.join()),
        "the very home the custody has owned since before the join"
    );
    let PrivateJoinResult::Panicked(payload) = evidence.result().expect("a completed join") else {
        panic!("this worker panicked")
    };
    assert_eq!(
        payload
            .lock()
            .expect("a readable payload")
            .downcast_ref::<&str>()
            .copied(),
        Some("what this connection's worker carried out with it"),
        "the exact payload, after every frame that made it has gone"
    );
    drop(evidence);

    // A READER LETTING GO IS NOT THE END OF IT. This pin was one handle among
    // others; what keeps this home is the service owner's inventory, and it is
    // still there.
    drop(custody);
    assert!(
        durable
            .committed_obligation(place)
            .expect("the obligation is still here")
            .join()
            .is_some(),
        "an operation's handle going is not the keeper letting go"
    );

    // AND ONLY THE ULTIMATE OWNER LETTING GO ENDS IT. The fixture holds the
    // service owner and drops it last, after the instance it kept for. The
    // obligation then says the evidence has gone -- which is not a
    // disposition and not a fresh fact about the join.
    drop(c.g.f.fixture);
    assert!(
        durable
            .committed_obligation(place)
            .expect("the obligation is still here")
            .join()
            .is_none(),
        "the store named it and did not own it"
    );
}

#[test]
fn a_commitment_records_what_the_gate_said_whichever_it_was() {
    // ALL THREE STAY DISTINCT. An unreadable gate is not a closed one, and
    // recording it as established would claim something nobody established --
    // but it is also not a reason to refuse the responsibility, because
    // something is still owed and that case is what this retention is for.
    for (client, arrange, expected) in [
        (
            8463u64,
            None::<fn(&PrivateCommitFixture)>,
            PrivateHandoverFence::Established,
        ),
        (
            8464,
            Some((|c: &PrivateCommitFixture| {
                assert_eq!(
                    c.g.f.fixture.registration.fence_ordered_handovers(),
                    PrivateHandoverFence::Established,
                    "somebody else closed it first, through the real API"
                );
            }) as fn(&PrivateCommitFixture)),
            PrivateHandoverFence::AlreadyEstablished,
        ),
        (
            8465,
            Some((|c: &PrivateCommitFixture| {
                assert!(
                    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                        let _inside = c.g.gate.fenced.lock().expect("a readable gate");
                        panic!("a holder unwound inside this connection's gate");
                    }))
                    .is_err(),
                    "the holder unwound"
                );
            }) as fn(&PrivateCommitFixture)),
            PrivateHandoverFence::Unreadable,
        ),
    ] {
        let c = commit_fixture(XServerFrontendClientId(client), false);
        let durable = c.g.f.fixture.durable.clone();
        let outer = durable.clone();
        let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
        let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        if let Some(arrange) = arrange {
            arrange(&c);
        }
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let destination = durable
            .prepare_internal_holder(&lease)
            .expect("its own destination");
        let context =
            PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
        assert!(matches!(context.commit(), PrivateCommitted::Committed));
        assert_eq!(
            durable
                .committed_obligation(c.place)
                .expect("an obligation")
                .closed(),
            expected,
            "exactly what the gate said"
        );
        drop((c.g.f.fixture, outer));
    }
}

#[test]
fn a_commitment_is_not_gated_by_a_diagnostic_somebody_is_holding() {
    // THE PUBLISHED EVIDENCE IS READ DIRECTLY. Whether anybody is holding the
    // exit diagnostic or the panic payload has nothing to do with whether this
    // connection's worker finished or its gate was asked.
    let c = commit_fixture(XServerFrontendClientId(8466), true);
    let durable = c.g.f.fixture.durable.clone();
    let outer = durable.clone();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");

    let PrivateJoinResult::Panicked(payload) = record.result().expect("a completed join") else {
        panic!("this worker panicked")
    };
    let payload_held = payload.lock().expect("a readable payload");
    let diagnostic_held = custody
        .exit_sink()
        .outcome
        .lock()
        .expect("a readable exit record");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(
        matches!(context.commit(), PrivateCommitted::Committed),
        "neither lock is on the way to the obligation"
    );
    // The pin goes before the keeper it borrows, which is the order the
    // borrow checker now insists on and the order the thing itself has.
    drop((payload_held, diagnostic_held, outer));
    drop(custody);
    drop(c.g.f.fixture);
}

#[test]
fn a_commitment_takes_no_further_credit_and_moves_the_duty_once() {
    // THE SAME PLACE, THE SAME NAME, THE SAME COUNT. Committing states what a
    // connection is owed; it does not charge for a second place, and it leaves
    // exactly one holder owing this place's disposal.
    let c = commit_fixture(XServerFrontendClientId(8467), false);
    let durable = c.g.f.fixture.durable.clone();
    let outer = durable.clone();
    let identity = c
        .g
        .f
        .fixture
        .registration
        .maintenance_identity()
        .expect("a name");
    let reserved_before = durable.continuations_reserved();
    let abandoned_before = durable.continuations_abandoned();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::Committed));

    assert_eq!(durable.continuations_reserved(), reserved_before);
    assert_eq!(durable.continuations_abandoned(), abandoned_before);
    assert!(
        identity.same_as(
            durable
                .committed_obligation(c.place)
                .expect("an obligation")
                .identity()
        ),
        "the same name it was reserved under"
    );
    // ONE HOLDER OWES THIS PLACE. Taking it out and dropping it marks the
    // place once, which it could not do if the lease still owed it too.
    let named = durable
        .take_internal_holder(c.place)
        .expect("the store's holder");
    drop(named);
    assert_eq!(
        durable.continuations_abandoned(),
        abandoned_before.map(|before| before + 1),
        "once, which it could not be if the lease still owed it too"
    );
    drop((c.g.f.fixture, outer));
}

#[test]
fn a_second_commitment_replaces_nothing() {
    // A REPEATED REQUEST MUST NOT RESTATE THE OBLIGATION. The first evidence
    // stands, and a second attempt finds its destination already holding one.
    let c = commit_fixture(XServerFrontendClientId(8468), false);
    let durable = c.g.f.fixture.durable.clone();
    let outer = durable.clone();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::Committed));

    // THERE IS NO SECOND LEASE TO ASK WITH: the first commitment consumed it,
    // and the registration has none to give.
    assert!(
        c.g.f
            .fixture
            .registration
            .maintenance_identity()
            .is_none(),
        "this registration is not holding a lease any more"
    );
    assert_eq!(
        maintenance_destination(&durable, c.place),
        Some("taken"),
        "and its destination holds the first obligation"
    );
    // THE OBLIGATION IS THE FIRST ONE, with its own evidence.
    assert_eq!(
        durable
            .committed_obligation(c.place)
            .expect("an obligation")
            .closed(),
        PrivateHandoverFence::Established
    );
    drop((c.g.f.fixture, outer));
}

#[test]
fn a_commitment_leaves_no_store_self_cycle() {
    // AN OBLIGATION IS KEPT BY THE STORE, so nothing it names may keep the
    // store. WHAT ACTUALLY MAKES THAT TRUE is the weak edge: the obligation
    // names its evidence rather than owning it, and its identity names the
    // store weakly too.
    //
    // AND THIS CONTROL COVERS THE RETURNED CASE ONLY. A join that panicked
    // carries whatever the frame was carrying, which may be anything at all
    // including a handle to this store; that the graph still releases then
    // rests on the custodian being outside it. The control that shows THAT is
    // a_payload_holding_the_store_is_a_chain_from_its_custodian, where the
    // payload really is a store handle -- not the neighbouring panic controls,
    // whose payloads are strings and establish nothing about this graph.
    let capability;
    let outer;
    {
        let c = commit_fixture(XServerFrontendClientId(8469), false);
        let durable = c.g.f.fixture.durable.clone();
        capability = durable.settlement_ref();
        outer = durable.clone();
        let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
        let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let destination = durable
            .prepare_internal_holder(&lease)
            .expect("its own destination");
        let context =
            PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
        assert!(matches!(context.commit(), PrivateCommitted::Committed));
        drop((c.g.f.fixture, durable));
    }
    assert!(
        capability.owner().is_some(),
        "the caller's own holder keeps it"
    );
    drop(outer);
    assert!(
        capability.owner().is_none(),
        "and a committed obligation is on no ring"
    );
}

#[test]
fn a_commitment_whose_place_moved_on_leaves_the_successor_alone() {
    // THE OCCUPANT IS CHECKED IN THE ACQUISITION THAT INSTALLS. A place whose
    // work settles goes back and the next connection takes the number, so a
    // commitment resting on a lease that has outlived its place would state an
    // obligation into the successor's destination on the strength of evidence
    // about somebody else's connection.
    //
    // NO HOOK: the place goes back before the commitment is asked. The
    // preparation happens first, because a stale lease can no longer prepare.
    let mut c = commit_fixture(XServerFrontendClientId(8470), false);
    let durable = c.g.f.fixture.durable.clone();
    let outer = durable.clone();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination, while it is still its own");

    // The connection ends and the real drive returns its place. The reaping
    // and fencing records borrow the slot and gate, which the fixture still
    // owns, so only the registration goes here.
    let place = c.place;
    // Its row and this control's own captured sender both go: the drive can
    // only finish a queue whose producers have all disappeared, and a sender
    // this fixture is still holding is a producer.
    let stand_in = spare_registration(&c.g.f.fixture);
    let stand_in_client = stand_in.client;
    let registration = std::mem::replace(&mut c.g.f.fixture.registration, stand_in);
    let spare_sender = capture_gated_sender(
        c.g.f.fixture.runner.frontend.as_ref().unwrap(),
        stand_in_client,
    );
    let sender = std::mem::replace(&mut c.g.f.sender, spare_sender);
    drop((registration, sender));
    // This connection's place is back; the stand-in above holds one of its
    // own, so the store's total is not zero and nothing here claims it is.
    settle_and_return(&durable, place);

    // A REAL SUCCESSOR TAKES THE NUMBER.
    let second = XServerFrontendClientId(8471);
    let (successor, successor_registration, successor_cell, successor_frames, _wire, _successor_keeper) =
        converted_fixture(&durable, second, 84710);
    let abandoned_before = durable.continuations_abandoned();
    // THE SUCCESSOR PREPARES ITS OWN DESTINATION FIRST, which is what
    // separates the two halves of the check: the entry is Promised for this
    // number again, so a commitment that asked only about the promise would
    // find it satisfied. What differs is the home.
    let successor_lease = lease_of(&successor_registration);
    let successors_own = durable
        .prepare_internal_holder(&successor_lease)
        .expect("the successor's own destination");
    assert_eq!(maintenance_destination(&durable, place), Some("promised"));

    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::Stale));
    assert_eq!(
        maintenance_destination(&durable, place),
        Some("promised"),
        "the successor's own promise is untouched"
    );
    assert!(
        durable.committed_obligation(place).is_none(),
        "and nothing was committed into it"
    );
    assert_eq!(
        durable.continuations_abandoned(),
        abandoned_before,
        "nothing was marked on the successor's account"
    );
    let capsule = successor_registration
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("its own home")
        .expect("the successor's own capsule");
    assert_eq!(order_pass_frames(&capsule), successor_frames);
    assert!(Arc::ptr_eq(
        &successor_cell,
        &capsule.finalizer().expect("carried").completion
    ));
    assert!(successor_cell.answer().is_none());
    drop((
        successor,
        successor_registration,
        successor_lease,
        successors_own,
        capsule,
        outer,
    ));
}

#[test]
fn a_commitment_with_a_destination_from_elsewhere_is_refused() {
    // A DESTINATION BELONGS TO ONE PLACE IN ONE STORE. Committing through one
    // from another store, or one prepared for another place, would state this
    // connection's obligation into storage that was never its own.
    let c = commit_fixture(XServerFrontendClientId(8472), false);
    let durable = c.g.f.fixture.durable.clone();
    let outer = durable.clone();
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);

    // Another store, with a connection and a destination of its own.
    let elsewhere = PrivateSettlementOwner::default();
    let service_keeper = service_owner(&elsewhere, 2);
    let other_private = private_over(&service_keeper, 2);
    let other = XServerFrontendClientId(8473);
    let (other_registration, _other_channels) = other_private
        .broker
        .registry
        .register_client_with_admission(other, Some(admitted(other)))
        .expect("a place and a row");
    let other_lease = lease_of(&other_registration);
    let foreign = elsewhere
        .prepare_internal_holder(&other_lease)
        .expect("the other store's own destination");

    let foreign_context =
        PrivateCommitmentContext::bound_to(&custody, &fence, lease, foreign);
    assert!(matches!(foreign_context.commit(), PrivateCommitted::Foreign));
    assert!(durable.committed_obligation(c.place).is_none());
    assert_eq!(
        maintenance_destination(&durable, c.place),
        Some("reserved"),
        "this connection's own destination was never touched"
    );

    // And a context over its own destination still commits.
    let lease = foreign_context
        .into_parts()
        .expect("nothing was consumed")
        .0;
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::Committed));
    drop((
        c.g.f.fixture,
        other_registration,
        other_private,
        other_lease,
        outer,
    ));
}

#[test]
fn an_operation_that_unwinds_loses_the_operation_and_not_the_result() {
    // THE WHOLE POINT OF TAKING CUSTODY FIRST. A reaping publishes into a home
    // its custodian already owned, so a frame that returns -- or one that
    // unwinds -- takes itself away and leaves the result where it was.
    //
    // THE UNWIND IS THE CALLER'S, AFTER THE REAL OPERATION RETURNED. It
    // establishes that boundary and no other: nothing here witnesses an
    // arbitrary instruction inside a reaping.
    let f = worker_fixture(XServerFrontendClientId(8481));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || panic!("what the custodian keeps"));

    let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let record = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        panic!("the frame that did the reaping goes here");
    }));
    assert!(unwound.is_err(), "the operation's frame unwound");

    // AND THE RESULT IS EXACTLY WHERE IT WAS PUBLISHED.
    let PrivateJoinResult::Panicked(payload) =
        custody.join().result().expect("a completed join")
    else {
        panic!("this worker panicked")
    };
    assert_eq!(
        payload
            .lock()
            .expect("a readable payload")
            .downcast_ref::<&str>()
            .copied(),
        Some("what the custodian keeps"),
        "the exact payload, after the frame that joined it unwound"
    );
    drop(f.fixture);
}

#[test]
fn losing_an_operation_before_a_result_exists_invents_none() {
    // AN UNWIND BEFORE PUBLICATION MUST NOT LEAVE A RESULT. What the home says
    // then is what it said before: not begun, or an attempt that may have
    // consumed a handle -- readable states of this same home, and neither a
    // join outcome.
    let f = worker_fixture(XServerFrontendClientId(8482));
    let custody = custody_for(&f, &f.fixture.keeper);
    let (release, held) = std::sync::mpsc::channel::<()>();
    started_worker(&custody, &f, move || {
        let _ = held.recv();
    });

    assert_eq!(custody.join().phase(), PrivateReapingPhase::NotBegun);
    let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _record = PrivateReapingRecord::bound_to(&custody);
        panic!("the frame goes before it ever asks");
    }));
    assert!(unwound.is_err());
    assert_eq!(
        custody.join().phase(),
        PrivateReapingPhase::NotBegun,
        "nothing was begun, so nothing says it was"
    );
    assert!(custody.join().result().is_none(), "and no result was invented");

    // The worker is released and joined before the registration goes, because
    // teardown is not worker-aware.
    drop(release);
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    drop(f.fixture);
}

#[test]
fn a_commitment_needs_no_returned_handle_to_keep_its_evidence() {
    // COMMITTING RETURNS NOTHING TO KEEP. The custody owned this home before
    // the reaping began and still does; there is nothing a caller could drop
    // or unwind holding that would cost the result.
    let c = commit_fixture(XServerFrontendClientId(8483), true);
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let durable = c.g.f.fixture.durable.clone();
    let place = c.place;
    let lease = lease_of(&c.g.f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    // The outcome is a word, not a handle: there is nothing here to discard.
    assert!(matches!(context.commit(), PrivateCommitted::Committed));

    // AND THE COMMITTED NAME RESOLVES THE EXACT ORIGINAL HOME.
    let named = durable
        .committed_obligation(place)
        .expect("an obligation")
        .join()
        .expect("its custodian owns it");
    assert!(Arc::ptr_eq(&named, custody.join()));
    drop(custody);
    drop(c.g.f.fixture);
}

#[test]
fn a_commitment_refuses_another_connections_evidence() {
    // A COMMITMENT CANNOT BE GIVEN ANY LIVE KEEPER. Its custody must be about
    // the connection whose place it is committing, by name AND by home.
    //
    // TWO SEPARATE MISTAKES, and each is made here with everything else right,
    // so neither is caught by a check that was already there. Both custodies
    // belong to the same store, so the store comparison cannot refuse either.
    let c = commit_fixture(XServerFrontendClientId(8484), false);
    let durable = c.g.f.fixture.durable.clone();
    // A SIBLING OF THE SAME STORE, AND ITS OWN REGISTERED CUSTODY -- the one
    // its registration reserved, not one made beside it. Its place, its home,
    // its slot and its exit record are all that connection's.
    let sibling = spare_registration(&c.g.f.fixture);
    let PrivateCustodyReach::Reached(sibling_custody) = sibling
        .registered_custody(&c.g.f.fixture.keeper.lease())
        .expect("a sibling registration reserves a custody of its own")
    else {
        panic!("the same owner keeps it")
    };
    // BOTH CUSTODIES BEFORE THE LEASE IS TAKEN: a name is handed out from the
    // registration's lease, so a custody asked for after the lease has gone
    // has nothing to be about.
    let twin = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let lease = lease_of(&c.g.f.fixture.registration);

    // (1) THE WRONG NAME. The whole operation runs against the sibling's
    // custody -- ITS slot, ITS exit record and ITS home, because a reaping
    // view can no longer be handed parts from two connections. So the
    // fencing's evidence IS the home this context names, and the sibling's
    // store is this store. Only the name says this reservation is not the one
    // that custody is about.
    //
    // The sibling's own worker, in the sibling's own slot, so there is a real
    // join for that custody to have.
    started_worker(&sibling_custody, &c.g.f, || {});
    let misnamed = PrivateReapingRecord::bound_to(&sibling_custody);
    let misfence = PrivateFenceRecord::bound_to(&sibling_custody);
    assert_eq!(misnamed.reap().reaped, PrivateReaped::Joined);
    assert_eq!(misfence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let wrong_name =
        PrivateCommitmentContext::bound_to(&sibling_custody, &misfence, lease, destination);
    assert!(
        matches!(wrong_name.commit(), PrivateCommitted::Foreign),
        "the store and the home matched, and the name did not"
    );
    assert!(
        durable.committed_obligation(c.place).is_none(),
        "nothing was stated about this connection"
    );

    // (2) THE WRONG HOME. This custody has the RIGHT name -- it is about this
    // very connection -- but it is not the keeper the fencing published into,
    // so an obligation naming its home would name a home holding nothing.
    let (lease, destination) = wrong_name.into_parts().expect("nothing was consumed");
    assert!(twin.identity().same_as(&lease.maintenance_identity()));
    let wrong_home = PrivateCommitmentContext::bound_to(&twin, &misfence, lease, destination);
    assert!(
        matches!(wrong_home.commit(), PrivateCommitted::Foreign),
        "the store and the name matched, and the home did not"
    );
    assert!(durable.committed_obligation(c.place).is_none());

    // AND THE REFUSED CONTEXT KEPT WHAT IT WAS GIVEN, so the correct
    // commitment still happens -- which is what makes the two refusals above
    // refusals rather than breakage.
    let (lease, destination) = wrong_home.into_parts().expect("nothing was consumed");

    // THIS CONNECTION'S OWN WORKER, joined through its own custody. That is
    // also this control's obligation to the thread it started.
    let own = PrivateReapingRecord::bound_to(&twin);
    assert_eq!(
        own.reap().reaped,
        PrivateReaped::Joined,
        "its own handle was never the sibling's to take"
    );
    let own_fence = PrivateFenceRecord::bound_to(&twin);
    assert_eq!(own_fence.record_fence(), PrivateFenced::Recorded);
    let context = PrivateCommitmentContext::bound_to(&twin, &own_fence, lease, destination);
    assert!(
        matches!(context.commit(), PrivateCommitted::Committed),
        "its own name over its own home commits"
    );
    let stated = durable
        .committed_obligation(c.place)
        .expect("the obligation is stated now");
    assert!(
        Arc::ptr_eq(
            &stated.join().expect("its custodian owns it"),
            twin.join()
        ),
        "over the home its own custody has owned throughout"
    );
    drop(stated);
    drop(context);
    drop(own);
    drop((sibling_custody, twin));
    drop((c.g.f.fixture, sibling));
}

#[test]
fn a_completed_join_cannot_be_withdrawn_by_a_later_view() {
    // WHAT SHARING THE HOME COST, AND WHAT PAYS FOR IT. When each record kept
    // its own claim, a second view over the same source and the same custody
    // arrived with a claim of its own, made an empty attempt and withdrew the
    // phase of a join that had already completed: the result sat in storage
    // and stopped being readable, and the obligation naming it read None.
    //
    // NO HOOK, NO SECOND WORKER, NO SCHEDULE. The first view is simply gone by
    // the time the second one is made.
    let c = commit_fixture(XServerFrontendClientId(8487), true);
    let custody = custody_for(&c.g.f, &c.g.f.fixture.keeper);
    let durable = c.g.f.fixture.durable.clone();
    let lease = lease_of(&c.g.f.fixture.registration);
    {
        let first = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(first.reap().reaped, PrivateReaped::Joined);
        let fence = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
        let destination = durable
            .prepare_internal_holder(&lease)
            .expect("its own destination");
        let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
        assert!(matches!(context.commit(), PrivateCommitted::Committed));
    }
    let stated = durable
        .committed_obligation(c.place)
        .expect("the obligation is stated");
    assert!(
        stated
            .join()
            .expect("its evidence is still kept")
            .result()
            .is_some(),
        "the join it rests on is readable before the second view exists"
    );

    // A SECOND VIEW OF THE SAME SOURCE AND THE SAME CUSTODY. It is refused,
    // because the one right to publish into that home went with the attempt
    // that consumed the handle and is not something a new view can mint.
    let second = PrivateReapingRecord::bound_to(&custody);
    let repeated = second.reap();
    assert_eq!(repeated.reaped, PrivateReaped::NotThePublisher);
    assert_eq!(repeated.exit, None, "it read nothing, having done nothing");
    assert_eq!(
        custody.join().phase(),
        PrivateReapingPhase::Joined,
        "a view that is not the producer cannot withdraw a completed phase"
    );
    assert!(
        stated
            .join()
            .expect("its evidence is still kept")
            .result()
            .is_some(),
        "and the obligation still reads the join it rests on"
    );
    assert_eq!(
        panic_payload_of(custody.join()).as_deref(),
        Some("what this connection's worker carried out with it"),
        "the original result, and not a fresh one"
    );
    drop(custody);
    drop(c.g.f.fixture);
}

#[test]
fn two_views_of_one_home_do_not_both_publish() {
    // TWO SEPARATE RECORDS OVER ONE HOME, ASKING TOGETHER. This is the case a
    // record-local claim never covered: neither view has been asked before, so
    // each would have claimed itself and gone on to write the other's phase.
    //
    // THE OVERLAP IS WITNESSED, NOT HOPED FOR. The worker is held until the
    // slot itself says its handle has gone to a joiner and the refused view
    // has come back.
    let f = worker_fixture(XServerFrontendClientId(8488));
    let custody = custody_for(&f, &f.fixture.keeper);
    let (release, held) = std::sync::mpsc::channel::<()>();
    started_worker(&custody, &f, move || {
        let _ = held.recv();
        panic!("what exactly one view keeps");
    });

    // BOTH VIEWS REACH FOR THE RIGHT AT THE SAME MOMENT. Each is built before
    // the rendezvous, so what the two threads do after it is the acquisition
    // itself: a right that was looked at and then taken, rather than taken in
    // one exchange, has its window here.
    let together = std::sync::Barrier::new(2);
    std::thread::scope(|scope| {
        let (report, asked) = std::sync::mpsc::channel();
        for _ in 0..2 {
            let custody = &custody;
            let together = &together;
            let report = report.clone();
            scope.spawn(move || {
                let view = PrivateReapingRecord::bound_to(custody);
                together.wait();
                report.send(view.reap().reaped)
            });
        }
        drop(report);

        assert!(
            waited_for(|| {
                custody.worker_slot().lock().expect("a readable slot").life == PrivateWorkerLife::HandedToJoiner
            }),
            "one view took the handle while its worker is still running"
        );
        // AND THE OTHER IS ALREADY BACK, while that worker is still held: the
        // only view that can return now is the one refused the right, because
        // the one that took it is waiting on the thread.
        assert_eq!(
            asked
                .recv_timeout(Duration::from_secs(3))
                .expect("the refused view returned"),
            PrivateReaped::NotThePublisher
        );
        assert_eq!(
            custody.join().phase(),
            PrivateReapingPhase::InProgress,
            "a handle is consumed and no result is confirmed"
        );
        assert!(custody.join().result().is_none());

        drop(release);
        assert_eq!(
            asked
                .recv_timeout(Duration::from_secs(3))
                .expect("the publishing view returned"),
            PrivateReaped::Joined
        );
    });

    assert_eq!(custody.join().phase(), PrivateReapingPhase::Joined);
    assert_eq!(
        panic_payload_of(custody.join()).as_deref(),
        Some("what exactly one view keeps"),
        "one join, one result"
    );
    let state = custody.worker_slot().lock().expect("a readable slot");
    assert!(state.handle.is_none());
    assert_eq!(state.life, PrivateWorkerLife::HandedToJoiner);
    drop(state);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_view_that_consumed_nothing_leaves_the_right_for_the_next() {
    // THE RIGHT IS NOT SPENT BY LOOKING. An attempt that found no handle
    // consumed nothing, so it gives the right back and a later view of the
    // same home still does the real join. Keeping it would have made one early
    // look enough to leave a connection's evidence unpublishable for good.
    let f = worker_fixture(XServerFrontendClientId(8489));
    let custody = custody_for(&f, &f.fixture.keeper);

    // A VIEW THAT ARRIVES BEFORE THE WORKER DOES, and is then gone.
    {
        let early = PrivateReapingRecord::bound_to(&custody);
        assert_eq!(early.reap().reaped, PrivateReaped::NothingStarted);
        assert_eq!(custody.join().phase(), PrivateReapingPhase::NotBegun);
    }
    assert_eq!(
        start_connection_worker(custody.worker_slot(), &f.stop, &f.wake, || {
            std::thread::Builder::new().spawn(|| {})
        }),
        PrivateStartupOutcome::Started
    );

    // A LATER VIEW, WHICH IS A DIFFERENT RECORD, still publishes.
    let later = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(later.reap().reaped, PrivateReaped::Joined);
    assert!(matches!(
        custody.join().result(),
        Some(PrivateJoinResult::Returned)
    ));
    assert_eq!(custody.join().phase(), PrivateReapingPhase::Joined);

    // AND NOW IT IS SPENT, because that one consumed a handle.
    let third = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(third.reap().reaped, PrivateReaped::NotThePublisher);
    assert_eq!(custody.join().phase(), PrivateReapingPhase::Joined);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_payload_holding_the_store_is_a_chain_from_its_custodian() {
    // THE CASE THE EXTERNAL KEEPER EXISTS FOR. A panic payload is whatever the
    // frame was carrying, and it may be a handle to this very store. If the
    // store owned the evidence, that would be a ring with itself: store,
    // holder, obligation, evidence, payload, store.
    //
    // It does not own it. The custodian does, so the chain runs custodian ->
    // evidence -> payload -> store, and letting the custodian go releases all
    // of it -- with nothing broken by hand in cleanup.
    // EXACTLY ONE WORKER IS STARTED HERE, and this control joins it. A fixture
    // that starts a worker of its own and then starts a second would be
    // dropping its connection with a thread it never collected -- cancelling
    // one is not joining it -- so this assembles the pieces from a worker
    // fixture rather than taking a fixture that has already started one.
    let f = worker_fixture(XServerFrontendClientId(8486));
    f.permit();
    let durable = f.fixture.durable.clone();
    let capability = durable.settlement_ref();
    let custody = custody_for(&f, &f.fixture.keeper);
    let place = f
        .fixture
        .registration
        .maintenance_identity()
        .expect("a place, so a name")
        .place();
    let gate = f.fixture.registration.handover_gate();

    // A real worker panicking with a real handle to this store.
    let carried = durable.clone();
    started_worker(&custody, &f, move || {
        std::panic::panic_any(carried);
    });
    let lease = lease_of(&f.fixture.registration);
    let record = PrivateReapingRecord::bound_to(&custody);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    let destination = durable
        .prepare_internal_holder(&lease)
        .expect("its own destination");
    let context = PrivateCommitmentContext::bound_to(&custody, &fence, lease, destination);
    assert!(matches!(context.commit(), PrivateCommitted::Committed));

    // The payload really is a store handle.
    let evidence = Arc::clone(custody.join());
    let PrivateJoinResult::Panicked(payload) = evidence.result().expect("a completed join") else {
        panic!("this worker panicked")
    };
    assert!(
        payload
            .lock()
            .expect("a readable payload")
            .downcast_ref::<PrivateSettlementOwner>()
            .is_some(),
        "it is carrying a handle to this very store"
    );

    // THE OPERATIONS AND THIS CONTROL'S OWN HANDLES GO HERE: the commitment,
    // the fencing, the reaping, the pin, this control's store handle, the
    // worker's slot and exit and the connection's gate.
    //
    // THE FIXTURE IS STILL HOLDING ITS INSTANCE AND ITS OWN STORE HANDLE at
    // this point, and the custodian with them. What the assertion below says
    // is only that the chain is not yet broken -- the release comes after the
    // fixture goes, which is the last drop in this control.
    drop(context);
    drop(record);
    drop(custody);
    drop((durable, gate));
    assert!(
        capability.owner().is_some(),
        "the custodian's chain keeps the store"
    );
    let still_here = f
        .fixture
        .keeper
        .store()
        .committed_obligation(place)
        .expect("the obligation is still here");
    assert!(
        still_here.join().is_some(),
        "and the obligation still reaches its evidence"
    );
    drop(still_here);

    // AND THE CUSTODIAN LETTING GO RELEASES ALL OF IT -- once this reader's
    // own owning handle on the evidence goes too, which is allowed to outlive
    // it and is not what keeps the graph.
    drop(evidence);
    drop(f.fixture);
    assert!(
        capability.owner().is_none(),
        "a payload holding the store is a chain from outside, not a ring"
    );
}

/// An owner established over this store for this many connections.
///
/// THE OWNER IS THE CONTROL'S OWN LOCAL, declared before whatever it is about
/// to build and dropped after it. That is the shape the construction path
/// requires, and a control that let it go first would be testing a service
/// whose keeper had already gone.
fn service_owner(
    store: &crate::PrivateSettlementOwner,
    connections: usize,
) -> crate::PrivateServiceOwner {
    crate::PrivateServiceOwner::established_over(
        store,
        NonZeroUsize::new(connections).expect("a control declares a real bound"),
    )
    .expect("a readable store declares its bound")
}

#[test]
fn a_connections_evidence_keeper_is_reserved_before_its_row_is_published() {
    // THE INTERVAL, OBSERVED FROM INSIDE IT. Seeing a custody and a row both
    // present afterwards says nothing about which came first, and counting one
    // before and one after says only that the total did not change. This holds
    // the client table itself -- the lock publication must take -- so a second
    // registration is stopped exactly between preparing and publishing, and
    // its OWN entry is counted while it waits there.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8501);
    let (first, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    assert_eq!(keeper.custodies_kept(), 1);
    assert_eq!(keeper.custody_capacity_remaining(), 3);
    let home = {
        let PrivateCustodyReach::Reached(kept) = first
            .registered_custody(&keeper.lease())
            .expect("its own custody")
        else {
            panic!("its owner keeps it")
        };
        Arc::clone(kept.join())
    };

    let registry = private.broker.registry.clone();
    let refused = std::thread::scope(|scope| {
        // THE REAL CLIENT TABLE, held by this control. Nothing is hooked: the
        // registration below runs its ordinary path and stops where it would
        // stop against any other publisher.
        let table = registry.clients.lock().expect("a readable client table");
        let attempt = scope.spawn(|| {
            registry.register_client_with_admission(client, Some(admitted(client)))
        });
        // ITS OWN ENTRY IS HERE WHILE PUBLICATION CANNOT HAVE HAPPENED.
        assert!(
            waited_for(|| keeper.custodies_kept() == 2),
            "the attempt reserved its evidence before reaching publication"
        );
        assert_eq!(keeper.custody_capacity_remaining(), 2);
        assert_eq!(
            durable.continuations_reserved(),
            Some(2),
            "and its place, on the same reservation"
        );
        drop(table);
        attempt.join().expect("the attempt returned")
    });

    // AND PUBLICATION REFUSED IT, so both of that attempt's reservations went
    // back and the live sibling it collided with kept everything of its own.
    assert!(matches!(
        refused,
        Err(XServerFrontendRouteError::DuplicateClient { client: same }) if same == client
    ));
    assert_eq!(
        keeper.custodies_kept(),
        1,
        "the refused attempt gave back exactly its own"
    );
    assert_eq!(keeper.custody_capacity_remaining(), 3);
    assert_eq!(durable.continuations_reserved(), Some(1));
    let PrivateCustodyReach::Reached(again) = first
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner still keeps it")
    };
    assert!(
        Arc::ptr_eq(again.join(), &home),
        "the live connection's home is the one it always had"
    );
    drop(again);
    drop((first, private, registry, keeper));
}

#[test]
fn asking_a_registration_for_its_custody_twice_names_one_home() {
    // A CAPABILITY, NOT A FACTORY. A registration that could make a
    // publication home on demand would be deciding its connection's keeper
    // after that connection was already exposed, and two operations could be
    // publishing into two different homes for one join.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 2);
    let private = private_over(&keeper, 2);
    let client = XServerFrontendClientId(8502);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    let mut homes = Vec::new();
    for _ in 0..3 {
        let PrivateCustodyReach::Reached(pin) =
            registration.registered_custody(&keeper.lease()).expect("its own custody")
        else {
            panic!("its owner keeps it")
        };
        homes.push(Arc::clone(pin.join()));
    }
    assert!(Arc::ptr_eq(&homes[0], &homes[1]) && Arc::ptr_eq(&homes[1], &homes[2]));
    assert_eq!(
        keeper.custodies_kept(),
        1,
        "asking is not reserving: three asks made no second entry"
    );
    // AND IT IS ABOUT THIS CONNECTION'S PLACE.
    let PrivateCustodyReach::Reached(pin) =
        registration.registered_custody(&keeper.lease()).expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(
        pin.identity()
            .same_as(&registration.maintenance_identity().expect("a name")),
        "the custody names the place this registration holds"
    );
    drop(pin);
    drop((registration, private, keeper));
}

#[test]
fn one_connections_keeper_is_not_another_connections() {
    // BY NAME AND BY HOME, not by number. Two live connections of one service
    // have two entries, and neither name reaches the other's evidence.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let mut kept = Vec::new();
    for raw in [8503, 8504] {
        let client = XServerFrontendClientId(raw);
        let (registration, _channels) = private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client)))
            .expect("a place, a keeper and a row");
        kept.push(registration);
    }
    assert_eq!(keeper.custodies_kept(), 2);
    let pins: Vec<_> = kept
        .iter()
        .map(|registration| {
            let PrivateCustodyReach::Reached(pin) =
                registration.registered_custody(&keeper.lease()).expect("its own custody")
            else {
                panic!("its owner keeps it")
            };
            pin
        })
        .collect();
    assert!(
        !Arc::ptr_eq(pins[0].join(), pins[1].join()),
        "two connections, two homes"
    );
    assert!(!pins[0].identity().same_as(pins[1].identity()));
    assert_ne!(pins[0].identity().place(), pins[1].identity().place());

    // AND THE OWNER RESOLVES EACH NAME TO ITS OWN HOME, never to the other's.
    for (registration, pin) in kept.iter().zip(pins.iter()) {
        let named = registration.maintenance_identity().expect("a name");
        let found = keeper.custody_named(&named).expect("its own entry");
        assert!(Arc::ptr_eq(found.join(), pin.join()));
    }
    // A NAME FROM ANOTHER STORE ENTIRELY RESOLVES TO NOTHING HERE.
    let elsewhere = PrivateSettlementOwner::default();
    let stranger_keeper = service_owner(&elsewhere, 2);
    let stranger = private_over(&stranger_keeper, 2);
    let outsider = XServerFrontendClientId(8599);
    let (foreign, _foreign_channels) = stranger
        .broker
        .registry
        .register_client_with_admission(outsider, Some(admitted(outsider)))
        .expect("a place, a keeper and a row");
    assert!(
        keeper
            .custody_named(&foreign.maintenance_identity().expect("a name"))
            .is_none(),
        "one owner's inventory does not answer for another store's connection"
    );
    drop(pins);
    drop((kept, private, keeper));
    drop((foreign, stranger, stranger_keeper, elsewhere));
}

#[test]
fn a_connection_whose_evidence_cannot_be_kept_is_not_exposed() {
    // THE BOUND IS THE STORE'S, AND OUTSTANDING ENTRIES CONSUME IT. A place
    // that goes back can be taken again; the evidence of what happened in it
    // cannot be written over, so a service whose inventory is full refuses the
    // next connection BEFORE its row goes in rather than admitting it and
    // discarding somebody's result.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 2);
    let private = private_over(&keeper, 2);
    let mut live = Vec::new();
    for raw in [8505, 8506] {
        live.push(bound_on(&private, XServerFrontendClientId(raw)));
    }
    assert_eq!(keeper.custodies_kept(), 2);
    assert_eq!(keeper.custody_capacity_remaining(), 0);

    // BOTH PLACES GO BACK. The store has room again; the keeper does not.
    let places: Vec<usize> = live
        .iter()
        .map(|registration| {
            registration
                .maintenance_identity()
                .expect("a name")
                .place()
        })
        .collect();
    drop(live);
    for place in places {
        settle_and_return(&durable, place);
    }
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "the store has its places back"
    );
    assert_eq!(
        keeper.custodies_kept(),
        2,
        "and the evidence of those connections is still kept"
    );

    // SO THE NEXT CONNECTION IS REFUSED, AND NOTHING IS EXPOSED.
    let later = XServerFrontendClientId(8507);
    let refused = private
        .broker
        .registry
        .register_client_with_admission(later, Some(admitted(later)));
    assert!(
        matches!(
            refused,
            Err(XServerFrontendRouteError::EvidenceCustodyUnavailable { client })
                if client == later
        ),
        "refused for the keeper, and told so: {refused:?}",
        refused = refused.as_ref().err()
    );
    assert_eq!(
        durable.continuations_reserved(),
        Some(0),
        "the place the refused attempt took went back with it"
    );
    assert_eq!(keeper.custodies_kept(), 2, "and nothing was retired to fit");
    assert_eq!(keeper.custody_capacity_remaining(), 0);
    drop((private, keeper));
}

#[test]
fn a_successor_at_one_number_does_not_take_its_predecessors_evidence() {
    // A PLACE IS A NUMBER AND EVIDENCE IS NOT. The first connection's place
    // goes back and the next connection takes the same index; its custody is
    // its own, and the entry the first one left is untouched.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    let first = bound_on(&private, XServerFrontendClientId(8508));
    let PrivateCustodyReach::Reached(first_pin) =
        first.registered_custody(&keeper.lease()).expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    let first_home = Arc::clone(first_pin.join());
    let first_sink = Arc::clone(first_pin.exit_sink());
    let first_slot = std::ptr::from_ref(first_pin.worker_slot()) as usize;
    let place = first.maintenance_identity().expect("a name").place();
    drop((first_pin, first));
    settle_and_return(&durable, place);

    let next_client = XServerFrontendClientId(8509);
    let (next, _next_channels) = private
        .broker
        .registry
        .register_client_with_admission(next_client, Some(admitted(next_client)))
        .expect("a place, a keeper and a row");
    assert_eq!(
        next.maintenance_identity().expect("a name").place(),
        place,
        "the successor really did take that number"
    );
    let PrivateCustodyReach::Reached(next_pin) =
        next.registered_custody(&keeper.lease()).expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(
        !Arc::ptr_eq(next_pin.join(), &first_home),
        "a reused number is not a reused home"
    );
    assert!(
        !Arc::ptr_eq(next_pin.exit_sink(), &first_sink),
        "nor a reused exit record"
    );
    assert_ne!(
        std::ptr::from_ref(next_pin.worker_slot()) as usize,
        first_slot,
        "nor a reused worker slot: the successor's handle has nowhere to go \
         that its predecessor's evidence is in"
    );
    assert_eq!(
        keeper.custodies_kept(),
        2,
        "the predecessor's evidence is still kept beside the successor's"
    );
    assert_eq!(keeper.custody_capacity_remaining(), 1);
    assert!(
        Arc::strong_count(&first_home) >= 1 && first_home.result().is_none(),
        "its home is still here, and still says nothing happened in it"
    );
    assert!(
        !first_sink.left(),
        "and its exit record still says nothing left"
    );
    drop(next_pin);
    drop((next, private, keeper));
}

#[test]
fn a_service_that_ends_leaves_its_connections_evidence_with_its_owner() {
    // SERVICE EXIT IS NOT SETTLEMENT. The frontend, the registration and every
    // frame that used this connection go here; the custody, its published
    // result and the payload it carries stay with the owner, which is the only
    // thing whose destruction ends them.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 2);
    let carried;
    let home;
    {
        let private = private_over(&keeper, 2);
        let client = XServerFrontendClientId(8510);
        let (registration, _channels) = private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client)))
            .expect("a place, a keeper and a row");
        let PrivateCustodyReach::Reached(pin) =
            registration.registered_custody(&keeper.lease()).expect("its own custody")
        else {
            panic!("its owner keeps it")
        };
        home = Arc::downgrade(pin.join());

        // ONE REAL WORKER FOR THIS ONE SOURCE, started into the slot that
        // source owns and joined here -- before the registration it belongs
        // to goes anywhere.
        let stop = Arc::new(AtomicBool::new(false));
        let wake = Arc::new(PrivateOrderedWake::for_first_sender());
        assert_eq!(
            start_connection_worker(pin.worker_slot(), &stop, &wake, || {
                std::thread::Builder::new().spawn(|| panic!("what this one carried"))
            }),
            PrivateStartupOutcome::Started
        );
        let record = PrivateReapingRecord::bound_to(&pin);
        assert_eq!(record.reap().reaped, PrivateReaped::Joined);
        carried = panic_payload_of(pin.join()).expect("its payload");
        assert_eq!(carried, "what this one carried");

        // And the whole service scope ends: the record first, because it
        // borrows the pin it publishes through and the compiler will not let
        // it outlive one, then the pin, the registration and the frontend.
        drop(record);
        drop((pin, registration, private));
    }

    // THE KEEPER STILL HAS IT, and it still says what happened.
    assert_eq!(keeper.custodies_kept(), 1);
    let kept = home.upgrade().expect("its owner keeps this home");
    assert_eq!(kept.phase(), PrivateReapingPhase::Joined);
    assert_eq!(
        panic_payload_of(&kept).as_deref(),
        Some("what this one carried"),
        "the exact result, after the service that produced it has gone"
    );

    // AND ONLY DESTROYING THE OWNER ENDS IT, which is a separate event.
    drop(kept);
    drop(keeper);
    assert!(
        home.upgrade().is_none(),
        "the ultimate owner letting go is what releases the graph"
    );
    drop(durable);
}

#[test]
fn a_service_cannot_be_prepared_over_a_keeper_that_is_not_its_own() {
    // TWO OWNERS OVER ONE STORE ARE TWO INVENTORIES. A service built with one
    // and prepared with the other would reserve evidence in one place and look
    // for it in another, so the association is refused rather than carried.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 2);
    let stranger = service_owner(&durable, 2);
    let private = private_over(&keeper, 2);
    let (cause, returned) = match private.prepare_runner(NamespaceId::from_raw(8511), &stranger) {
        Ok(_) => panic!("a foreign owner prepared an execution scope"),
        Err(refused) => refused,
    };
    assert_eq!(cause, PrivateRunnerRefusal::ForeignServiceOwner);

    // REFUSED WITH NOTHING INSTALLED AND NOTHING CONSUMED: the caller still
    // has its frontend, and its own owner still prepares.
    let prepared = returned
        .prepare_runner(NamespaceId::from_raw(8511), &keeper)
        .map_err(|(cause, _)| cause);
    assert!(prepared.is_ok(), "its own owner prepares it");

    // AND A LEASE ON THE WRONG OWNER UNLOCKS NOTHING. A lease proves that SOME
    // keeper is alive; every act asks whether it is THIS service's, because a
    // stranger's liveness is not this service's liveness. The stranger here is
    // an owner over the very same store, which is the closest a wrong one can
    // be.
    let mut runner = prepared.expect("its own owner prepared it");
    let client = XServerFrontendClientId(8514);
    let (registration, _channels) = runner
        .frontend
        .as_ref()
        .expect("a live runner")
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    assert_eq!(
        runner
            .ingress_for(&stranger.lease(), client, DeviceId::from_raw(1))
            .err(),
        Some(PrivateServiceRefusal::ForeignServiceOwner),
        "a producer is not handed out on somebody else's keeper"
    );
    assert!(
        matches!(
            runner.service_turn(&stranger.lease()),
            Err(XServerFrontendRouteError::ForeignServiceOwner)
        ),
        "and no turn is served on one"
    );
    // AND A MISMATCH IS NOT A DESTRUCTION. Both owners are alive; what is
    // wrong is the association, and a caller told the keeper had gone would go
    // looking for something that never happened.
    assert!(
        matches!(
            registration.registered_custody(&stranger.lease()),
            Some(PrivateCustodyReach::ForeignKeeper)
        ),
        "and no custody is reached through one"
    );
    assert!(
        matches!(
            registration.registered_custody(&keeper.lease()),
            Some(PrivateCustodyReach::Reached(_))
        ),
        "its own lease reaches it immediately, so nothing was destroyed"
    );
    // ITS OWN OWNER GETS PAST ALL THREE. What the participant then says about
    // this connection is its own business -- this control registered a route
    // and did not admit one -- and an admission refusal is not a refusal about
    // the service.
    assert!(
        !matches!(
            runner.ingress_for(&keeper.lease(), client, DeviceId::from_raw(1)),
            Err(PrivateServiceRefusal::ForeignServiceOwner)
        ),
        "its own owner is this service's keeper"
    );
    assert!(runner.service_turn(&keeper.lease()).is_ok());
    assert!(matches!(
        registration.registered_custody(&keeper.lease()),
        Some(PrivateCustodyReach::Reached(_))
    ));
    drop((registration, runner));

    // AND AN OWNER CANNOT BE ESTABLISHED OVER A STORE NOBODY CAN READ. The
    // bound it must size itself to is the store's, so a store that cannot say
    // what its bound is cannot have an owner made over it. (Establishing also
    // refuses when the storage for that many places cannot be allocated, which
    // this control does not arrange.)
    let unreadable = PrivateSettlementOwner::default();
    let broken = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = unreadable.records_even_if_poisoned();
        panic!("poisoning this store's aggregate, and nothing else");
    }));
    assert!(broken.is_err(), "the store's lock is poisoned");
    assert!(
        crate::PrivateServiceOwner::established_over(
            &unreadable,
            NonZeroUsize::new(2).expect("a real bound"),
        )
        .is_none(),
        "an owner is not established over a bound nobody could read"
    );
    drop((keeper, stranger, durable, unreadable));
}

/// A connection registered AND BOUND on this instance, the way a real one is,
/// so that its place can afterwards be finished and returned.
fn bound_on(
    private: &crate::PrivateXServerFrontend,
    client: XServerFrontendClientId,
) -> XServerFrontendClientRouteRegistration {
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    let (stream, _peer) = UnixStream::pair().expect("a socket pair");
    let output = Arc::new(Mutex::new(stream));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    assert_eq!(
        registration
            .bind_ordered_output(channels.ordered, &output, &wire, &pending)
            .unwrap_or_else(|_| panic!("a fresh registration holds no custody")),
        None
    );
    registration
}


#[test]
fn an_inventory_refuses_a_second_home_and_a_foreign_name() {
    // ASKED OF THE KEEPER DIRECTLY, which is the same capability the registry
    // holds and reserves through. Registration reserves once per connection,
    // so neither of these answers is reachable by registering: they are what
    // the inventory says to a caller that asks twice, or asks about somebody
    // else's store.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    let client = XServerFrontendClientId(8511);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    let named = registration.maintenance_identity().expect("a name");
    let PrivateCustodyReach::Reached(pin) =
        registration.registered_custody(&keeper.lease()).expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    let home = Arc::clone(pin.join());
    assert_eq!(keeper.custodies_kept(), 1);

    // A SECOND PREPARATION FOR ONE LIVE RESERVATION. The first home is
    // preserved and the state it is in -- here, a join that has not happened
    // -- is left exactly as it was.
    let capability = keeper.keeper();
    assert!(matches!(
        capability.reserve_for(
            &named,
            registration.handover_gate(),
            Arc::clone(&registration.cleanup),
        ),
        PrivateCustodyReserved::AlreadyKept
    ));
    assert_eq!(
        keeper.custodies_kept(),
        1,
        "nothing was added and nothing was replaced"
    );
    let PrivateCustodyReach::Reached(again) =
        registration.registered_custody(&keeper.lease()).expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(
        Arc::ptr_eq(again.join(), &home),
        "the home this connection had is the home it has"
    );
    assert_eq!(again.join().phase(), PrivateReapingPhase::NotBegun);

    // A NAME FROM ANOTHER STORE IS NOT THIS OWNER'S TO KEEP, however well
    // formed it is.
    let elsewhere = PrivateSettlementOwner::default();
    let stranger_keeper = service_owner(&elsewhere, 2);
    let stranger = private_over(&stranger_keeper, 2);
    let outsider = XServerFrontendClientId(8512);
    let (foreign, _foreign_channels) = stranger
        .broker
        .registry
        .register_client_with_admission(outsider, Some(admitted(outsider)))
        .expect("a place, a keeper and a row");
    assert!(matches!(
        capability.reserve_for(
            &foreign.maintenance_identity().expect("a name"),
            foreign.handover_gate(),
            Arc::clone(&foreign.cleanup),
        ),
        PrivateCustodyReserved::Foreign
    ));
    assert_eq!(
        keeper.custodies_kept(),
        1,
        "a refused name took no place in this inventory"
    );
    assert_eq!(stranger_keeper.custodies_kept(), 1, "and none in that one");
    drop((pin, again));
    drop((registration, private, keeper));
    drop((foreign, stranger, stranger_keeper, elsewhere, durable));
}

#[test]
fn a_registry_cannot_be_given_a_second_keeper() {
    // ONE SERVICE, ONE INVENTORY. A registry that accepted a second keeper
    // could put this connection's evidence in one owner's inventory and the
    // next connection's in another, and afterwards nothing could say which
    // owner was answerable for what.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let substitute = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    assert!(
        !private
            .broker
            .registry
            .install_custody_keeper(substitute.keeper()),
        "construction installed this registry's keeper already"
    );

    // AND CONNECTIONS STILL GO TO THE OWNER IT WAS BUILT WITH.
    let client = XServerFrontendClientId(8513);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper and a row");
    assert_eq!(keeper.custodies_kept(), 1);
    assert_eq!(
        substitute.custodies_kept(),
        0,
        "the substitute keeps nothing, which is what being refused means"
    );
    let named = registration.maintenance_identity().expect("a name");
    assert!(keeper.custody_named(&named).is_some());
    assert!(
        substitute.custody_named(&named).is_none(),
        "and it answers for nothing either"
    );
    drop((registration, private, keeper, substitute, durable));
}

#[test]
fn a_producer_asks_again_at_every_acceptance() {
    // ISSUANCE IS NOT A STANDING PERMISSION. A producer handed out while the
    // keeper was alive goes on existing; what it must not do is go on
    // ACCEPTING work once the lease it is offered is not this service's. Both
    // producer classes are asked, because both take work into the service.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 2);
    let stranger = service_owner(&durable, 2);
    let mut private = private_over(&keeper, 2);
    let client = XServerFrontendClientId(8515);
    let surface = SurfaceId::new(8515, 1);
    let namespace = NamespaceId::from_raw(8515);
    let admission = namespaced(client, namespace);
    private.participant.admit(client, admission).expect("admitted");
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admission))
        .expect("a place, a keeper and a row");
    private
        .broker
        .registry
        .register_surface(client, namespace, surface, XResourceId::new(0x8515, 1))
        .expect("the surface to register");
    // The plain stamped ingress, not a reserving producer: taking one of
    // those engages the ordered consumer, and this control drives the
    // unprepared instance's own routing path below.
    let ingress = private.ingress();
    let control = private.control_producer();

    // ITS OWN OWNER, AND THE WORK IS ACCEPTED.
    assert!(
        ingress
            .submit(
                &keeper.lease(),
                button_to(surface, XAuthorityInputDeliveryId::from_raw(85150), 272, true),
            )
            .is_ok(),
        "a live keeper accepts"
    );

    // A STRANGER'S LEASE, AND NOTHING IS ACCEPTED -- by either class. The work
    // comes back in hand, unaccepted, which is what a refusal owes a producer.
    let refused = ingress.submit(
        &stranger.lease(),
        button_to(surface, XAuthorityInputDeliveryId::from_raw(85151), 272, false),
    );
    assert!(
        matches!(refused, Err(PrivateSendError::ForeignServiceOwner(_))),
        "the input producer asks at acceptance: {refused:?}"
    );
    let control_refused = control.submit(
        &stranger.lease(),
        XAuthorityClientControlCommand {
            client,
            command: XAuthorityControlCommand::FocusSurface {
                transaction: TransactionId::from_raw(8515),
                surface,
            },
        },
    );
    assert!(
        matches!(
            control_refused,
            Err((AdmissionRefusal::ForeignServiceOwner, _))
        ),
        "and so does the control producer"
    );

    // AND THE UNPREPARED INSTANCE'S OWN EXECUTION PATH ASKS TOO. This frontend
    // was never prepared into a runner, so it carries no borrow of its owner;
    // without this it would go on applying accepted work with no keeper.
    assert!(
        matches!(
            private.route_pending(&stranger.lease()),
            Err(XServerFrontendRouteError::ForeignServiceOwner)
        ),
        "an unprepared instance is not an unguarded one"
    );
    let ran = private
        .route_pending(&keeper.lease())
        .expect("its own owner runs it");
    assert_eq!(ran.len(), 1, "the one accepted entry, and only it");
    drop((ingress, control, registration, private, keeper, stranger));
}

#[test]
fn a_connections_worker_source_is_inert_and_names_one_slot_sink_and_home() {
    // WHAT THIS ESTABLISHES, AND WHAT IT DOES NOT. It looks at the source the
    // moment a registration returns: the slot is empty, the exit record says
    // nothing, the home says nothing, and asking again names the same three.
    //
    // IT IS NOT AN OBSERVATION OF THE INTERVAL. That the source was allocated
    // BEFORE the row went in is established by the order of the source --
    // reserve_for runs before publish_registered_client, and a refused
    // publication has an entry of its own to give back, which
    // a_connections_evidence_keeper_is_reserved_before_its_row_is_published
    // observes from inside the client table. Nothing here watches that
    // interval, and a control that inspected afterwards and called it proof
    // would be reading a state and claiming a schedule.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    let client = XServerFrontendClientId(8601);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a source and a row");

    // EMPTY AND UNSTARTED, which is what reserving storage means.
    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    {
        let slot = pin.worker_slot().lock().expect("a readable slot");
        assert!(slot.handle.is_none(), "no thread was started by registering");
        assert_eq!(slot.life, PrivateWorkerLife::NeverStarted);
        assert!(!slot.departing);
    }
    assert_eq!(
        pin.exit_sink().reading(),
        PrivateExitReading::NotLeft,
        "the exit record is this connection's own, and says nothing yet"
    );
    assert!(!pin.exit_sink().left(), "nothing has left, because nothing ran");
    assert_eq!(pin.join().phase(), PrivateReapingPhase::NotBegun);

    // AND ASKING AGAIN NAMES THE SAME THREE THINGS. A registration that could
    // make a second source would be deciding where its worker lives after the
    // connection was already exposed.
    let slot_address = std::ptr::from_ref(pin.worker_slot()) as usize;
    let home = Arc::clone(pin.join());
    let sink = Arc::clone(pin.exit_sink());
    drop(pin);
    for _ in 0..3 {
        let PrivateCustodyReach::Reached(again) = registration
            .registered_custody(&keeper.lease())
            .expect("its own custody")
        else {
            panic!("its owner keeps it")
        };
        assert_eq!(std::ptr::from_ref(again.worker_slot()) as usize, slot_address);
        assert!(Arc::ptr_eq(again.exit_sink(), &sink));
        assert!(Arc::ptr_eq(again.join(), &home));
    }
    assert_eq!(keeper.custodies_kept(), 1, "asking is not reserving");
    drop((sink, home));
    drop((registration, private, keeper, durable));
}

#[test]
fn a_started_worker_stays_with_its_source_after_the_view_that_started_it_ends() {
    // THE POINT OF THE WHOLE COMPONENT. A handle installed in the registered
    // slot belongs to the connection's external owner, so the frame that
    // started it can end -- ordinarily -- and a completely fresh view finds
    // that exact thread and joins it, publishing the original result into the
    // original home.
    //
    // OBSERVED FIRST, COLLECTED, AND ONLY THEN COMPARED. The worker is held on
    // a channel, so the final comparisons are arranged to follow its release
    // and its join on this path.
    //
    // THAT IS ALL THIS ORDER ESTABLISHES. The helper calls and lock reads
    // above it can still fail first, and no cleanup guard is armed, so this is
    // not a claim that every failure path collects the worker.
    let f = worker_fixture(XServerFrontendClientId(8602));
    f.permit();
    let (release, held) = std::sync::mpsc::channel::<()>();
    let home;
    let started_into_the_slot;
    {
        // ONE STARTUP VIEW, which ends here and takes nothing with it.
        let starting = custody_for(&f, &f.fixture.keeper);
        home = Arc::clone(starting.join());
        started_worker(&starting, &f, move || {
            let _ = held.recv();
            panic!("what this connection's worker carried out with it");
        });
        started_into_the_slot = starting
            .worker_slot()
            .lock()
            .expect("a readable slot")
            .handle
            .is_some();
    }

    // WHAT A FRESH VIEW FINDS, taken while the worker is still blocked.
    let later = custody_for(&f, &f.fixture.keeper);
    let found = {
        let slot = later.worker_slot().lock().expect("a readable slot");
        (slot.handle.is_some(), slot.life)
    };
    let same_home = Arc::ptr_eq(later.join(), &home);

    // RELEASED AND COLLECTED THROUGH THAT VIEW, before the comparisons.
    drop(release);
    let record = PrivateReapingRecord::bound_to(&later);
    let reaped = record.reap().reaped;
    let payload = panic_payload_of(&home);

    assert!(
        started_into_the_slot,
        "the handle went into the registered slot, not into the starting frame"
    );
    assert_eq!(
        found,
        (true, PrivateWorkerLife::Running),
        "its owner still held the thread after the starting view ended"
    );
    assert!(same_home, "and the same home for it");
    assert_eq!(reaped, PrivateReaped::Joined);
    assert_eq!(
        payload.as_deref(),
        Some("what this connection's worker carried out with it"),
        "the original result, in the home the source has owned throughout"
    );
    drop(record);
    drop(later);
    drop(f.fixture);
}

#[test]
fn a_caller_that_unwinds_after_startup_leaves_the_handle_with_its_owner() {
    // THE BOUNDARY IS AFTER STARTUP RETURNED, and this control says so rather
    // than claiming anything about an interruption inside a spawn. What it
    // establishes is that losing the frame that started a worker does not lose
    // the worker.
    //
    // THE COMPARISONS FOLLOW RELEASE AND COLLECTION ON THIS PATH. Every
    // observation below is taken into a local first; the thread is released
    // and joined; and only then does anything compare.
    //
    // NOT A GENERAL CLAIM ABOUT FAILURE PATHS. The helper calls and lock reads
    // before that point can fail on their own, and nothing here arms a
    // release-and-join guard that would run if they did.
    let f = worker_fixture(XServerFrontendClientId(8603));
    f.permit();
    let (release, held) = std::sync::mpsc::channel::<()>();
    let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let starting = custody_for(&f, &f.fixture.keeper);
        started_worker(&starting, &f, move || {
            let _ = held.recv();
        });
        panic!("the frame that started it goes here");
    }));

    let after = custody_for(&f, &f.fixture.keeper);
    let observed = {
        let slot = after.worker_slot().lock().expect("a readable slot");
        (slot.handle.is_some(), slot.life)
    };

    // RELEASED AND COLLECTED, before the comparisons.
    drop(release);
    let record = PrivateReapingRecord::bound_to(&after);
    let reaped = record.reap().reaped;
    let published = matches!(after.join().result(), Some(PrivateJoinResult::Returned));

    assert!(unwound.is_err(), "the caller really did unwind");
    assert_eq!(
        observed,
        (true, PrivateWorkerLife::Running),
        "an unwound starter does not take the handle with it"
    );
    assert_eq!(reaped, PrivateReaped::Joined);
    assert!(published, "and its result went into its own home");
    drop(record);
    drop(after);
    drop(f.fixture);
}

#[test]
fn a_control_context_takes_its_credentials_from_its_own_serving_owner() {
    // NOT FROM WHOEVER PREPARED IT. The stop and the notice are the ones this
    // connection's own serving owner published, resolved under the one
    // acquisition of the home that establishes that owner is there and live.
    let f = worker_fixture(XServerFrontendClientId(8701));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody
        .prepare_control()
        .expect("a live serving owner with a stop of its own");

    // THE EXACT ORIGINAL HANDLES, not copies of what they held. The fixture's
    // own clones came from the same binding, so pointer identity is the whole
    // assertion.
    assert!(
        Arc::ptr_eq(context.stop(), &f.stop),
        "this connection's authoritative stop"
    );
    assert!(
        Arc::ptr_eq(context.notice(), &f.wake),
        "and its own notice"
    );
    assert!(
        Arc::ptr_eq(context.home(), &f.fixture.registration.ordered_home),
        "resolved to the home its own reservation made"
    );
    assert!(Arc::ptr_eq(context.exit_sink(), custody.exit_sink()));

    // AND A FRESH VIEW RECOVERS THE PUBLISHED ASSOCIATION rather than binding
    // a second one.
    //
    // ASKED WHERE A SECOND BINDING WOULD ANSWER DIFFERENTLY. Preparing again
    // over a live owner would derive the same handles either way, which proves
    // nothing; this connection's home is RETAINED first, so a preparation that
    // rebound would refuse -- and the association that is already published is
    // what a later view must still find.
    // The first context ends here; it is a borrow, so there is nothing to
    // release.
    assert!(f.fixture.registration.ordered_home.retain());
    let again = custody_for(&f, &f.fixture.keeper);
    let recovered = again
        .prepare_control()
        .expect("what was published is still this connection's");
    assert!(Arc::ptr_eq(recovered.stop(), &f.stop));
    assert!(Arc::ptr_eq(recovered.notice(), &f.wake));
    assert!(Arc::ptr_eq(
        recovered.home(),
        &f.fixture.registration.ordered_home
    ));
    drop(again);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn one_connections_context_cannot_stop_its_sibling() {
    // TWO REAL CONNECTIONS OF ONE INSTANCE, over ONE store and ONE service
    // owner -- which this control asserts rather than assumes, because two
    // fixtures would be two stores and separation between those is not the
    // question. Each derives its own credentials from its own serving owner.
    let f = worker_fixture(XServerFrontendClientId(8702));
    let (sibling, sibling_stop, sibling_notice, _sibling_peer) =
        serving_sibling(&f, XServerFrontendClientId(8703), true);
    let keeper = &f.fixture.keeper;
    assert!(
        keeper
            .custody_named(&f.fixture.registration.maintenance_identity().expect("a name"))
            .is_some()
            && keeper
                .custody_named(&sibling.maintenance_identity().expect("a name"))
                .is_some(),
        "one owner's inventory answers for both, so this is one store"
    );

    let first_custody = custody_for(&f, keeper);
    let PrivateCustodyReach::Reached(second_custody) = sibling
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("the same owner keeps it")
    };
    let first_context = first_custody.prepare_control().expect("its own owner");
    let second_context = second_custody.prepare_control().expect("its own owner");

    assert!(
        !Arc::ptr_eq(first_context.stop(), second_context.stop()),
        "two connections, two stops"
    );
    assert!(!Arc::ptr_eq(first_context.notice(), second_context.notice()));
    assert!(!Arc::ptr_eq(first_context.home(), second_context.home()));
    assert!(Arc::ptr_eq(second_context.stop(), &sibling_stop));
    assert!(Arc::ptr_eq(second_context.notice(), &sibling_notice));

    // ONE EXACT CAPSULE ON THE SIBLING'S QUEUE, so a cancellation that reached
    // across would have something of its neighbour's to disturb.
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(87030);
    let delivery = capsule.delivery();
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    let sibling_sender = capture_gated_sender(
        f.fixture.runner.frontend.as_ref().expect("a live runner"),
        XServerFrontendClientId(8703),
    );
    produced_send(&sibling_sender, capsule);

    // ONE IS CANCELLED, AND ONLY ONE IS TOLD TO STOP.
    first_context.cancel();
    assert!(
        f.stop.load(std::sync::atomic::Ordering::Acquire),
        "the one this context is about"
    );
    assert!(
        !sibling_stop.load(std::sync::atomic::Ordering::Acquire),
        "and its sibling was not told anything"
    );

    // AND THE SIBLING'S EXACT QUEUED WORK IS WHERE IT WAS.
    let queued = second_context
        .home()
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("a readable live home")
        .expect("the capsule this control accepted for it");
    assert_eq!(queued.delivery(), delivery);
    assert!(Arc::ptr_eq(
        &cell,
        &queued.finalizer().expect("carried").completion
    ));
    assert_eq!(order_pass_frames(&queued), frames);
    assert!(cell.answer().is_none());
    drop(queued);
    drop(sibling_sender);
    drop((first_custody, second_custody));
    drop(sibling);
    drop(f.fixture);
}

#[test]
fn cancelling_through_a_context_does_not_wait_on_the_home_it_came_from() {
    // THE CASE THE BINDING EXISTS FOR. A worker blocked while borrowing its
    // own home is exactly when cancellation must work, so a cancellation that
    // went back to the home to find its own stop would queue behind the thing
    // it is trying to stop.
    //
    // THE HOME IS HELD BY THIS CONTROL for the whole cancellation, which is
    // the same lock a borrowing worker would hold. This says nothing about how
    // long anything takes.
    let f = worker_fixture(XServerFrontendClientId(8704));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");

    let blocked = context.home().borrow(|_| {
        // Inside the home's own lock, and this is where cancellation runs.
        context.cancel();
        (
            f.stop.load(std::sync::atomic::Ordering::Acquire),
            f.wake.state.lock().expect("a readable notice").pending,
        )
    });
    assert_eq!(
        blocked,
        Some((true, true)),
        "the stop was set and the recheck published while its home was held"
    );

    // AND THE STORE'S AGGREGATE WAS NOT NEEDED EITHER: this one runs with the
    // settlement store's own guard held by this control. That is the store,
    // not the owner's custody inventory -- naming the wrong lock would be
    // claiming a separation this does not test.
    let other = worker_fixture(XServerFrontendClientId(8705));
    let other_custody = custody_for(&other, &other.fixture.keeper);
    let other_context = other_custody.prepare_control().expect("its own owner");
    let held = other.fixture.durable.records_even_if_poisoned();
    other_context.cancel();
    drop(held);
    assert!(other.stop.load(std::sync::atomic::Ordering::Acquire));
    drop((custody, other_custody));
    drop((f.fixture, other.fixture));
}

#[test]
fn a_departure_that_wins_leaves_the_spawner_uncalled() {
    // NO MORE STARTS MEANS NO MORE STARTS. Departure and startup use the same
    // registered slot, so a start that arrives afterwards never reaches its
    // spawner -- which is the only way to be sure no thread was made.
    let f = worker_fixture(XServerFrontendClientId(8706));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");

    assert_eq!(
        context.depart(),
        PrivateDeparted::Decided(PrivateDeparture::NothingStarted)
    );
    assert!(
        f.stop.load(std::sync::atomic::Ordering::Acquire),
        "departure set this connection's own stop first"
    );
    let called = std::sync::atomic::AtomicBool::new(false);
    let outcome = context.start(|| {
        called.store(true, std::sync::atomic::Ordering::Release);
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(outcome, PrivateStartupOutcome::NoLongerStartable);
    assert!(
        !called.load(std::sync::atomic::Ordering::Acquire),
        "the spawner was never called, so no thread exists to be lost"
    );
    assert_eq!(
        context.depart(),
        PrivateDeparted::AlreadyDecided(PrivateDeparture::NothingStarted),
        "and saying it again reports the decision rather than making another"
    );
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_stop_reaches_a_worker_whose_destination_is_still_held() {
    // THE OTHER HALF OF THE SAME PROPERTY. A spawn holds this connection's
    // slot for the whole transaction; a cancellation arriving in that window
    // must still be able to set the stop and publish the recheck, because it
    // needs neither the slot nor the home to find them.
    let f = worker_fixture(XServerFrontendClientId(8707));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");
    let (enter, entered) = std::sync::mpsc::channel::<()>();
    let (release, released) = std::sync::mpsc::channel::<()>();

    let witnessed = std::thread::scope(|scope| {
        let context = &context;
        let started = scope.spawn(move || {
            context.start(move || {
                // The destination is held for as long as this spawner runs.
                enter.send(()).expect("its caller is waiting");
                let _ = released.recv();
                std::thread::Builder::new().spawn(|| {})
            })
        });
        entered
            .recv_timeout(Duration::from_secs(3))
            .expect("the spawn began and is holding the slot");
        // WITNESSED WHILE THE SLOT IS HELD: this is the interval, not a guess
        // about one.
        context.cancel();
        let witnessed = (
            f.stop.load(std::sync::atomic::Ordering::Acquire),
            f.wake.state.lock().expect("a readable notice").pending,
        );
        drop(release);
        assert_eq!(started.join().expect("the startup returned"), PrivateStartupOutcome::Started);
        witnessed
    });
    assert_eq!(
        witnessed,
        (true, true),
        "the stop was set while this connection's own destination was held"
    );

    // AND THE WORKER IT DID MAKE IS THIS CONNECTION'S, AND IS COLLECTED HERE.
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_body_driven_by_its_own_context_stops_when_that_context_says_so() {
    // END TO END THROUGH THE REGISTERED SEAM. The approved body runs on the
    // handles this context derived and the exit sink this source owns; the
    // same context cancels it; and its custody joins it.
    let f = worker_fixture(XServerFrontendClientId(8708));
    f.permit();
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");
    let home = Arc::clone(context.home());
    let notice = Arc::clone(context.notice());
    let stop = Arc::clone(context.stop());
    let sink = Arc::clone(context.exit_sink());
    let sequence = Arc::clone(&f.sequence);
    assert_eq!(
        context.start(|| {
            std::thread::Builder::new().spawn(move || {
                PrivateWorkerBody {
                    home: &home,
                    wake: &notice,
                    stop: &stop,
                    byte_order: XByteOrder::LittleEndian,
                    sequence: &sequence,
                    exit: &sink,
                    steps: 16,
                }
                .run();
            })
        }),
        PrivateStartupOutcome::Started
    );

    // TOLD TO STOP THROUGH THE CONTEXT, and collected through the custody.
    context.cancel();
    let record = PrivateReapingRecord::bound_to(&custody);
    let reaping = record.reap();
    let reaped = reaping.reaped;
    let exit = reaping.exit;

    assert_eq!(reaped, PrivateReaped::Joined);
    let Some(PrivateExitReading::Classified(outcome)) = exit else {
        panic!("the body left a classification: {exit:?}")
    };
    assert!(
        stopped_by_cancellation(&outcome),
        "the owner's own terminal answer, which is not the same fact as the \
         cancellation that triggered it: {outcome:?}"
    );
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn preparing_a_control_context_refuses_each_shape_as_itself() {
    // SEVEN DIFFERENT ANSWERS, and a caller told the wrong one looks in the
    // wrong place. None of them starts anything, permits anything, sets a
    // stop, takes queued work or changes what a home holds.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 6);
    let private = private_over(&keeper, 6);

    // NOTHING BOUND: a registered connection whose setup never arrived. Its
    // home is live and empty, so there is no owner to take credentials from.
    let bare = XServerFrontendClientId(8711);
    let (bare_registration, _bare_channels) = private
        .broker
        .registry
        .register_client_with_admission(bare, Some(admitted(bare)))
        .expect("a place, a keeper, a source and a row");
    let PrivateCustodyReach::Reached(bare_custody) = bare_registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert_eq!(
        bare_custody.prepare_control().err(),
        Some(PrivateControlRefusal::NothingBound)
    );
    assert!(
        bare_custody.prepare_control().is_err(),
        "a refusal leaves it unprepared, so asking again asks again"
    );
    assert_eq!(
        bare_custody
            .worker_slot()
            .lock()
            .expect("a readable slot")
            .life,
        PrivateWorkerLife::NeverStarted,
        "and starts nothing"
    );

    // UNSTOPPABLE: a real serving owner bound without a stop of its own. Its
    // binding said so, and nothing here mints a replacement.
    let unstoppable = worker_fixture_bound(XServerFrontendClientId(8712), false);
    let unstoppable_custody = custody_for(&unstoppable, &unstoppable.fixture.keeper);
    assert_eq!(
        unstoppable_custody.prepare_control().err(),
        Some(PrivateControlRefusal::Unstoppable),
        "a stop this context invented would be one its worker never reads"
    );

    // RETAINED: its connection has ended. Driving is not how retained work is
    // finished, and this is not that borrower's home.
    let ended = worker_fixture(XServerFrontendClientId(8713));
    let ended_custody = custody_for(&ended, &ended.fixture.keeper);
    assert!(ended_custody.prepare_control().is_ok(), "live to begin with");
    let later = worker_fixture(XServerFrontendClientId(8714));
    let later_custody = custody_for(&later, &later.fixture.keeper);

    // ONE EXACT CAPSULE, ACCEPTED BEFORE ANY OF THIS, so the refusal below has
    // something it could have taken.
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(87140);
    let delivery = capsule.delivery();
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    produced_send(&later.sender, capsule);
    assert!(later.fixture.registration.ordered_home.retain());
    assert_eq!(
        later_custody.prepare_control().err(),
        Some(PrivateControlRefusal::Retained)
    );

    // AND THE EXACT QUEUED WORK IS STILL THERE, unanswered and unchanged: the
    // refusal did not take it, answer it or rebind it.
    let queued = later
        .fixture
        .registration
        .ordered_home
        .peek_retained(|continuation| continuation.queue().try_recv().ok())
        .expect("a readable retained home")
        .flatten()
        .expect("the capsule this control accepted is still queued");
    assert_eq!(queued.delivery(), delivery);
    assert!(Arc::ptr_eq(
        &cell,
        &queued.finalizer().expect("carried").completion
    ));
    assert_eq!(order_pass_frames(&queued), frames);
    assert!(cell.answer().is_none(), "and nothing answered it");
    drop(queued);

    // NOT SERVING: a real connection bound but never promoted. Its home holds
    // its setup, which is a payload and is not an owner to take credentials
    // from. Nothing is staged -- this is the shape a connection has between
    // binding and promotion.
    let host = worker_fixture(XServerFrontendClientId(8718));
    let (unpromoted, _unpromoted_stop, _unpromoted_notice, _unpromoted_peer) =
        serving_sibling(&host, XServerFrontendClientId(8719), false);
    let PrivateCustodyReach::Reached(setup_custody) = unpromoted
        .registered_custody(&host.fixture.keeper.lease())
        .expect("its own custody")
    else {
        panic!("the same owner keeps it")
    };
    assert_eq!(
        setup_custody.prepare_control().err(),
        Some(PrivateControlRefusal::NotServing)
    );

    // UNREADABLE: a holder panicked inside the home. Not recovered into
    // eligibility -- the lock WAS acquired, and what is unknown is what is in
    // there, which is the thing preparation would be asserting.
    let broken = worker_fixture(XServerFrontendClientId(8720));
    let broken_custody = custody_for(&broken, &broken.fixture.keeper);
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = broken
            .fixture
            .registration
            .ordered_home
            .state
            .lock()
            .expect("a readable home");
        panic!("poisoning this connection's home, and nothing else");
    }));
    assert!(poisoning.is_err());
    assert_eq!(
        broken_custody.prepare_control().err(),
        Some(PrivateControlRefusal::Unreadable)
    );

    // STORE GONE IS DEFENSIVE HERE, and this control says so rather than
    // staging a path to it. A registered custody owns the store its name is
    // in, so while that custody exists the store does; the answer is kept
    // apart because it is a different fact, not because this reaches it.

    drop((
        bare_custody,
        unstoppable_custody,
        ended_custody,
        later_custody,
        setup_custody,
        broken_custody,
    ));
    drop(unpromoted);
    drop((host.fixture, broken.fixture));
    drop(bare_registration);
    drop((unstoppable.fixture, ended.fixture, later.fixture));
    drop((private, keeper, durable));
}

#[test]
fn a_stale_name_prepares_nothing_for_the_connection_that_took_its_place() {
    // A NAME OUTLIVES ITS CONNECTION, and a place is taken again. A context
    // prepared from the old name would be driving the successor's worker with
    // the predecessor's credentials.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    let first = bound_on(&private, XServerFrontendClientId(8715));
    let PrivateCustodyReach::Reached(first_custody) = first
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    let place = first.maintenance_identity().expect("a name").place();
    drop(first);
    settle_and_return(&durable, place);

    // A REAL SUCCESSOR TAKES THAT NUMBER.
    let successor = bound_on(&private, XServerFrontendClientId(8716));
    assert_eq!(
        successor.maintenance_identity().expect("a name").place(),
        place
    );
    assert_eq!(
        first_custody.prepare_control().err(),
        Some(PrivateControlRefusal::StaleName),
        "the old name reaches nothing at a number its connection gave back"
    );
    drop(first_custody);
    drop((successor, private, keeper, durable));
}

#[test]
fn a_permit_that_cannot_be_published_stops_this_connection_and_keeps_its_worker() {
    // THE PATH THE STOP IN A STARTUP IS FOR. A permit that cannot be published
    // leaves a thread already running, so the transaction tells THIS
    // connection to stop, wakes it, and keeps the handle where it is to be
    // joined. A startup holding somebody else's stop would set a flag its own
    // worker never looks at.
    let f = worker_fixture(XServerFrontendClientId(8717));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");

    // The notice is poisoned by an ordinary panic under its own lock. Nothing
    // is rewritten: this is what a holder that unwound would leave.
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = context.notice().state.lock().expect("a readable notice");
        panic!("poisoning this connection's notice, and nothing else");
    }));
    assert!(poisoning.is_err());
    assert!(context.notice().state.is_poisoned());

    let outcome = context.start(|| std::thread::Builder::new().spawn(|| {}));
    let stopped = f.stop.load(std::sync::atomic::Ordering::Acquire);
    let kept = context
        .custody
        .worker_slot()
        .lock()
        .expect("a readable slot")
        .handle
        .is_some();

    // COLLECTED BEFORE ANYTHING COMPARES, so a failure cannot leave a thread
    // this control started with nobody to join it.
    let record = PrivateReapingRecord::bound_to(&custody);
    let reaped = record.reap().reaped;

    assert_eq!(outcome, PrivateStartupOutcome::PermitRefused);
    assert!(
        stopped,
        "the transaction set THIS connection's own stop, which is the one its \
         worker reads"
    );
    assert!(kept, "and kept the handle where its owner can join it");
    assert_eq!(reaped, PrivateReaped::Joined);
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_preparation_that_loses_a_race_recovers_what_the_winner_published() {
    // OVERLAPPING, NOT SEQUENTIAL. The sequential case -- ask, then ask again
    // -- is covered where a retained home makes a rebinding preparation
    // answer differently. THIS one is about a preparation that began when
    // nothing was published and finishes after another has committed: its own
    // resolution fails, and the connection nevertheless has an association.
    //
    // A caller refused here would have to ask again for what this call should
    // have recovered, and nothing about that refusal is still true.
    //
    // STAGED WITHOUT A THREAD. The order is produced by doing the two halves
    // of the losing preparation around the winner: this control observes that
    // nothing is published, lets the winner publish, poisons the home by an
    // ordinary caught panic under its own mutex, and only then runs the
    // preparation whose resolution must fail.
    let f = worker_fixture(XServerFrontendClientId(8721));
    let losing = custody_for(&f, &f.fixture.keeper);
    let winning = custody_for(&f, &f.fixture.keeper);

    // THE LOSER'S STARTING CONDITION, observed rather than assumed.
    assert!(
        losing.bound().is_none(),
        "nothing is published when the losing preparation begins"
    );

    // THE WINNER COMMITS.
    let published = winning.prepare_control().expect("a live serving owner");
    let stop = Arc::clone(published.stop());
    let notice = Arc::clone(published.notice());
    let home = Arc::clone(published.home());

    // AND THE HOME BECOMES UNREADABLE, which is what the loser's own
    // resolution will find.
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = f
            .fixture
            .registration
            .ordered_home
            .state
            .lock()
            .expect("a readable home");
        panic!("poisoning this connection's home, and nothing else");
    }));
    assert!(poisoning.is_err());

    // THE LOSING PREPARATION FINISHES. Its entry check already found nothing
    // -- that is what was observed above -- so what runs now is the half that
    // resolves, which is where the interval is. Its resolution cannot read the
    // home; the connection's association exists; the association is the
    // answer.
    let recovered = losing
        .resolve_control()
        .expect("the binding another preparation committed");
    assert!(Arc::ptr_eq(recovered.stop(), &stop));
    assert!(Arc::ptr_eq(recovered.notice(), &notice));
    assert!(Arc::ptr_eq(recovered.home(), &home));

    // AND A SOURCE NOBODY PREPARED STILL GETS THE REFUSAL. Recovering a
    // published binding is not recovering a poisoned home into eligibility.
    let unprepared = worker_fixture(XServerFrontendClientId(8722));
    let never = custody_for(&unprepared, &unprepared.fixture.keeper);
    let breaking = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = unprepared
            .fixture
            .registration
            .ordered_home
            .state
            .lock()
            .expect("a readable home");
        panic!("poisoning a home nobody has prepared over");
    }));
    assert!(breaking.is_err());
    assert_eq!(
        never.resolve_control().err(),
        Some(PrivateControlRefusal::Unreadable),
        "an unprepared source has no association to recover"
    );
    assert_eq!(
        never.prepare_control().err(),
        Some(PrivateControlRefusal::Unreadable),
        "by either entry point"
    );
    drop((losing, winning, never));
    drop((f.fixture, unprepared.fixture));
}

/// A SECOND connection of THIS instance, served by a real owner of its own.
///
/// The same registry, the same store and the same service owner as the fixture
/// it is given: a sibling built on its own frontend would be a different
/// store, and separation between two stores is not the question.
fn serving_sibling(
    f: &PrivateWorkerFixture,
    client: XServerFrontendClientId,
    promote: bool,
) -> (
    XServerFrontendClientRouteRegistration,
    Arc<AtomicBool>,
    Arc<PrivateOrderedWake>,
    UnixStream,
) {
    let private = f
        .fixture
        .runner
        .frontend
        .as_ref()
        .expect("a live runner");
    // IN THIS INSTANCE'S OWN NAMESPACE, which is what makes it this
    // instance's sibling rather than a stranger it would refuse.
    let admission = namespaced(client, f.fixture.namespace);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admission))
        .expect("a place, a keeper, a source and a row");
    // Admitted at the boundary, because promotion asks it for this
    // registration's endpoint and a connection assembled beside it is refused
    // as unadmitted -- rightly.
    private
        .participant
        .admit(client, admission)
        .expect("the boundary admits this sibling");
    // And its applied state, because the endpoint promotion asks for is the
    // one attached to this registration's own row.
    private
        .broker
        .registry
        .attach_connection_state(
            &registration,
            f.fixture.namespace,
            Arc::new(Mutex::new(XCoreEventSelectionState::default())),
            Arc::new(AtomicU64::new(0)),
        )
        .expect("its own applied state attaches");
    let (socket, peer) = UnixStream::pair().expect("a socket pair");
    peer.set_read_timeout(Some(Duration::from_secs(3)))
        .expect("a bounded read");
    let output = Arc::new(Mutex::new(socket));
    let wire = Arc::new(X11WirePermission::open());
    let pending = Arc::new(AtomicUsize::new(0));
    let stop = Arc::new(AtomicBool::new(false));
    let wake = Arc::clone(&channels.ordered.wake);
    let transport = XAuthorityOrderedTransport::bind(
        &registration,
        channels.ordered,
        &output,
        &wire,
        &pending,
        Some(&stop),
    )
    .unwrap_or_else(|(refusal, _)| panic!("its own receiver and output bind: {refusal:?}"));
    assert!(matches!(
        registration.retain_ordered_setup(PrivateOrderedContinuation::Setup {
            accepted: PrivateOrderedSetupCustody::Transport(Box::new(transport)),
            refusal: X11OrderedServingRefusal::Unserved,
            evidence: PrivateOrderedEvidence::unstarted(),
            retained: Vec::new(),
            drained: false,
            ended: false,
            ending_refused: None,
        }),
        Ok(())
    ));
    if promote {
        assert_eq!(
            registration.promote_ordered_serving(private),
            PrivateOrderedPromotion::Ready
        );
    }
    (registration, stop, wake, peer)
}

#[test]
fn a_connections_fence_source_names_the_gate_its_queue_was_minted_with() {
    // THE EXACT GATE, not one that matches. The sender, the row, the
    // registration and this source were all given the same Arc, which is what
    // makes a fencing through this custody a fencing of this connection.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8801);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a source and a row");
    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(
        Arc::ptr_eq(pin.gate(), &registration.handover_gate()),
        "the registration's own gate"
    );

    // AND ITS FENCE STORAGE IS RESERVED, INERT AND EMPTY.
    assert_eq!(
        pin.fence_evidence().phase(),
        PrivateFencePhase::NotAttempted
    );
    assert!(pin.fence_evidence().fence().is_none());
    assert!(
        !registration
            .ordered_handovers_fenced()
            .expect("a readable gate"),
        "and reserving it closed nothing"
    );

    // ASKING AGAIN NAMES THE SAME GATE AND THE SAME STORAGE. This is an
    // observation after registration returned; that the gate was bound BEFORE
    // publication is established by source order -- reserve_for runs before
    // publish_registered_client -- and by the client-table control named
    // below, not by anything this control watches.
    let address = std::ptr::from_ref(pin.fence_evidence()) as usize;
    drop(pin);
    let PrivateCustodyReach::Reached(again) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(Arc::ptr_eq(again.gate(), &registration.handover_gate()));
    assert_eq!(
        std::ptr::from_ref(again.fence_evidence()) as usize,
        address
    );

    // A REFUSED DUPLICATE PUBLICATION RETURNS ONLY ITS OWN, AND THAT IS ALL
    // THIS SHOWS. A count that is one before and one after does not witness
    // the interval: what establishes that the gate and this storage are bound
    // BEFORE the row goes in is source order -- reserve_for runs before
    // publish_registered_client -- and the client-table rendezvous in
    // a_connections_evidence_keeper_is_reserved_before_its_row_is_published,
    // which observes a waiting attempt's own entry while publication is
    // excluded.
    assert_eq!(keeper.custodies_kept(), 1);
    assert!(matches!(
        private
            .broker
            .registry
            .register_client_with_admission(client, Some(admitted(client))),
        Err(XServerFrontendRouteError::DuplicateClient { .. })
    ));
    assert_eq!(keeper.custodies_kept(), 1);
    assert!(Arc::ptr_eq(again.gate(), &registration.handover_gate()));
    assert!(
        !registration
            .ordered_handovers_fenced()
            .expect("a readable gate"),
        "and the live connection's gate is untouched"
    );
    drop(again);
    drop((registration, private, keeper, durable));
}

#[test]
fn fencing_one_connection_through_its_custody_leaves_its_sibling_alone() {
    // TWO REAL CONNECTIONS OF ONE INSTANCE. A fencing takes its join, its gate
    // and its result home from one custody, so there is nothing to give it
    // that belongs to the other.
    let f = worker_fixture(XServerFrontendClientId(8802));
    let (sibling, _sibling_stop, _sibling_notice, _sibling_peer) =
        serving_sibling(&f, XServerFrontendClientId(8803), true);
    let keeper = &f.fixture.keeper;
    let custody = custody_for(&f, keeper);
    let PrivateCustodyReach::Reached(sibling_custody) = sibling
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("the same owner keeps it")
    };

    // ONE EXACT CAPSULE ON THE SIBLING'S QUEUE.
    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(88030);
    let delivery = capsule.delivery();
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    let sibling_sender = capture_gated_sender(
        f.fixture.runner.frontend.as_ref().expect("a live runner"),
        XServerFrontendClientId(8803),
    );
    produced_send(&sibling_sender, capsule);

    // ITS OWN WORKER, JOINED, AND ITS OWN GATE CLOSED.
    started_worker(&custody, &f, || {});
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    let fence = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(fence.record_fence(), PrivateFenced::Recorded);
    assert_eq!(fence.fence(), Some(PrivateHandoverFence::Established));

    // AND THE SIBLING IS EXACTLY AS IT WAS.
    assert!(
        !sibling
            .ordered_handovers_fenced()
            .expect("a readable gate"),
        "its gate is open"
    );
    assert_eq!(
        sibling_custody.fence_evidence().phase(),
        PrivateFencePhase::NotAttempted,
        "nothing was attempted for it"
    );
    assert_eq!(
        sibling.ordered_home.standing(),
        PrivateHomeStanding::Live,
        "and its home is live"
    );
    let queued = sibling
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("a readable live home")
        .expect("the capsule this control accepted for it");
    assert_eq!(queued.delivery(), delivery);
    assert!(Arc::ptr_eq(
        &cell,
        &queued.finalizer().expect("carried").completion
    ));
    assert_eq!(order_pass_frames(&queued), frames);
    assert!(cell.answer().is_none());
    drop(queued);
    drop(record);
    drop(sibling_sender);
    drop((custody, sibling_custody));
    drop(sibling);
    drop(f.fixture);
}

#[test]
fn a_fencing_survives_the_view_that_recorded_it() {
    // THE RESULT BELONGS TO THE KEEPER, NOT THE VIEW. An early view refuses
    // and costs nothing; a later one records; and what it recorded is still
    // there after that view ends ordinarily AND after another unwinds holding
    // one.
    let f = worker_fixture(XServerFrontendClientId(8804));
    let custody = custody_for(&f, &f.fixture.keeper);

    // TOO EARLY: no join has published, so no gate is touched and no attempt
    // is spent.
    {
        let early = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(early.record_fence(), PrivateFenced::JoinIncomplete);
        assert_eq!(
            custody.fence_evidence().phase(),
            PrivateFencePhase::NotAttempted
        );
        assert!(
            !f.fixture
                .registration
                .ordered_handovers_fenced()
                .expect("a readable gate"),
            "an ask made too early asks no gate"
        );
    }

    started_worker(&custody, &f, || {});
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);

    // A LATER VIEW RECORDS, AND THEN ENDS.
    {
        let recording = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(recording.record_fence(), PrivateFenced::Recorded);
    }
    assert_eq!(
        custody.fence_evidence().fence(),
        Some(PrivateHandoverFence::Established),
        "the answer is the keeper's, and the view that got it has gone"
    );

    // AND AN UNWIND AFTER RECORDING TAKES NOTHING WITH IT.
    let unwound = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let holding = PrivateFenceRecord::bound_to(&custody);
        assert_eq!(holding.record_fence(), PrivateFenced::AlreadyAttempted);
        panic!("the frame holding a view goes here");
    }));
    assert!(unwound.is_err());
    assert_eq!(
        custody.fence_evidence().fence(),
        Some(PrivateHandoverFence::Established),
        "still the original answer"
    );

    // A FRESH VIEW OBSERVES THAT ORIGINAL RESULT rather than asking the gate
    // again: a second close call would answer AlreadyEstablished, and this
    // connection's record of its own closure would become the wrong one.
    let fresh = PrivateFenceRecord::bound_to(&custody);
    assert_eq!(fresh.record_fence(), PrivateFenced::AlreadyAttempted);
    assert_eq!(fresh.fence(), Some(PrivateHandoverFence::Established));
    drop((fresh, record));
    drop(custody);
    drop(f.fixture);
}

#[test]
fn two_eligible_views_make_one_attempt() {
    // TWO FRESHLY BUILT VIEWS, NEITHER PREVIOUSLY ASKED. A claim kept on the
    // view would let each mint its own right and both reach the gate; the
    // second close call would answer AlreadyEstablished and overwrite nothing
    // -- but this connection would have two records of one closure and the
    // published one would be whichever won a race.
    //
    // THE OVERLAP IS WITNESSED BY HOLDING THE GATE'S OWN ADMISSION, not by
    // sleeping. What that establishes is exactly this: one view has CLAIMED
    // the attempt and has not finished it, and the loser's answer is read
    // while that is true. Where the winner has got to is not established --
    // it may not have reached the gate's mutex at all -- and this control
    // does not say it has.
    let f = worker_fixture(XServerFrontendClientId(8805));
    let custody = custody_for(&f, &f.fixture.keeper);
    started_worker(&custody, &f, || {});
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);

    let own_gate = f.fixture.registration.handover_gate();
    let admitted_handover = own_gate
        .entered()
        .expect("an open gate admits this control");
    let (report, answered) = std::sync::mpsc::channel();
    let observed = std::thread::scope(|scope| {
        let custody = &custody;
        let report = report.clone();
        let winner = scope.spawn(move || {
            let view = PrivateFenceRecord::bound_to(custody);
            report.send(view.record_fence()).expect("its caller waits");
        });
        // THE CLAIM IS TAKEN WHILE THIS CONTROL HOLDS THE GATE.
        assert!(
            waited_for(|| custody.fence_evidence().phase() == PrivateFencePhase::InProgress),
            "one view claimed the attempt and has not finished it"
        );
        let losing = PrivateFenceRecord::bound_to(custody);
        let loser = losing.record_fence();
        let phase_while_held = custody.fence_evidence().phase();
        let result_while_held = custody.fence_evidence().fence();
        drop(admitted_handover);
        winner.join().expect("the fencing view returned");
        (loser, phase_while_held, result_while_held)
    });
    let winner = answered
        .recv_timeout(Duration::from_secs(3))
        .expect("the winning view reported");

    assert_eq!(observed.0, PrivateFenced::AlreadyAttempted, "one attempt");
    assert_eq!(
        observed.1,
        PrivateFencePhase::InProgress,
        "the losing ask did not withdraw the winner's intent"
    );
    assert_eq!(
        observed.2, None,
        "and an unfinished attempt publishes no result"
    );
    assert_eq!(winner, PrivateFenced::Recorded);
    assert_eq!(
        custody.fence_evidence().fence(),
        Some(PrivateHandoverFence::Established),
        "the one attempt's own answer"
    );
    drop(record);
    drop(custody);
    drop(f.fixture);
}

/// The cleanup record this connection's registration and keeper share.
fn cleanup_of(registration: &XServerFrontendClientRouteRegistration) -> Arc<PrivateCleanupRecord> {
    Arc::clone(&registration.cleanup)
}

#[test]
fn a_registration_and_its_keeper_reach_one_cleanup_record() {
    // ONE RESPONSIBILITY, ONE HOME. The handle a caller drops and the keeper
    // that outlives it must reach the same state, or deferring that
    // destruction later would be deferring a copy of it.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8901);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    let shared = cleanup_of(&registration);
    assert!(
        Arc::ptr_eq(pin.cleanup_record(), &shared),
        "the keeper reaches the registration's own record"
    );

    // THE SAME MUTABLE STATE, not a snapshot of it. A late lifecycle
    // attachment is written through the registration and read through the
    // keeper's handle.
    assert!(
        shared.lifecycle.lock().expect("readable").is_none(),
        "nothing is attached yet"
    );
    private
        .broker
        .registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the boundary admits and the lifecycle attaches");
    assert!(
        shared.lifecycle.lock().expect("readable").is_some(),
        "and the keeper's record sees what was attached afterwards"
    );

    // AND THE PLACE IS IN THAT ONE RECORD TOO.
    assert!(
        shared.maintenance_identity().is_some(),
        "its reservation lives here, not beside it"
    );
    assert!(Arc::ptr_eq(&shared.ordered_gate, &registration.handover_gate()));

    // A FRESH PIN AFTER THE FIRST VIEW ENDS FINDS THE SAME RECORD.
    drop(pin);
    let PrivateCustodyReach::Reached(again) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert!(Arc::ptr_eq(again.cleanup_record(), &shared));
    drop(again);
    drop((registration, private, keeper, durable, shared));
}

#[test]
fn a_refused_duplicate_leaves_no_cleanup_record_behind() {
    // THIS ATTEMPT'S OWN RESERVATIONS, AND ONLY THOSE. A duplicate is refused
    // while publication is excluded, so the attempt has a record of its own to
    // give back -- and the live connection it collided with keeps everything.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8902);
    let (first, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let live = cleanup_of(&first);
    let place = first.maintenance_identity().expect("a name").place();
    assert_eq!(keeper.custodies_kept(), 1);
    assert_eq!(durable.continuations_reserved(), Some(1));

    let registry = private.broker.registry.clone();
    let refused = std::thread::scope(|scope| {
        // THE REAL CLIENT TABLE, held by this control: the attempt below stops
        // exactly between preparing its record and publishing it.
        let table = registry.clients.lock().expect("a readable client table");
        let attempt = scope.spawn(|| {
            registry.register_client_with_admission(client, Some(admitted(client)))
        });
        assert!(
            waited_for(|| keeper.custodies_kept() == 2),
            "the attempt prepared its own custody and record before publication"
        );
        assert_eq!(
            durable.continuations_reserved(),
            Some(2),
            "and its own place, on the same reservation"
        );
        drop(table);
        attempt.join().expect("the attempt returned")
    });
    assert!(matches!(
        refused,
        Err(XServerFrontendRouteError::DuplicateClient { .. })
    ));

    // BOTH OF THAT ATTEMPT'S RESERVATIONS WENT BACK, AND THE LIVE SIBLING IS
    // UNTOUCHED -- including the record it is still holding.
    assert_eq!(keeper.custodies_kept(), 1);
    assert_eq!(durable.continuations_reserved(), Some(1));
    assert!(Arc::ptr_eq(&cleanup_of(&first), &live));
    assert_eq!(
        live.maintenance_identity().expect("a name").place(),
        place,
        "the live connection's own place"
    );
    assert!(
        !first
            .ordered_handovers_fenced()
            .expect("a readable gate"),
        "and nothing ran its cleanup"
    );
    drop((first, live, private, registry, keeper, durable));
}

#[test]
fn keeping_a_cleanup_record_neither_runs_it_nor_repeats_it() {
    // KEEPING IS NOT RUNNING. The registration's own Drop performs this
    // connection's cleanup at exactly the point it always did; the keeper goes
    // on holding the record afterwards, and holding it does nothing.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8903);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let shared = cleanup_of(&registration);
    assert!(
        private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable client table")
            .contains_key(&client),
        "its row is in"
    );
    assert!(!shared.ordered_gate.fenced().expect("a readable gate"));

    // THE HANDLE GOES, AND THE CLEANUP RAN.
    drop(registration);
    assert!(
        shared
            .ordered_gate
            .fenced()
            .expect("a readable gate"),
        "its gate was closed by the cleanup its Drop performed"
    );
    assert!(
        !private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable client table")
            .contains_key(&client),
        "and its row is out"
    );
    assert_eq!(
        shared.ordered_home.standing(),
        PrivateHomeStanding::Retained,
        "its queue went to the place reserved for it"
    );

    // AND THE KEEPER STILL HAS THE RECORD, which changes nothing.
    assert_eq!(keeper.custodies_kept(), 1);
    let fenced_before = shared.ordered_gate.fenced();
    drop(shared);
    assert_eq!(
        keeper.custodies_kept(),
        1,
        "a record going out of one holder's hands is not a disposition"
    );
    assert_eq!(fenced_before, Some(true));
    drop((private, keeper, durable));
}

#[test]
fn a_connection_with_a_lifecycle_lease_closes_it_when_its_registration_goes() {
    // THE LEASE IS PRESENT THROUGH TEARDOWN, which is the case that moving its
    // home could have changed. It used to be a field of the handle, so its own
    // destructor ran at exactly that point; it now lives in a record that
    // outlives the handle, and the cleanup takes it rather than leaving it.
    //
    // WHAT THIS CONTROL SEPARATES. It shows the gate is closed when the
    // registration goes AND that the lease was taken rather than closed in
    // place: a cleanup that closed through a borrow would leave the lease in a
    // record its keeper still holds, and the assertion below is what refuses
    // that.
    //
    // WHAT IT DOES NOT SEPARATE is the explicit close from the disposal. This
    // lease's own `Drop` closes the same gate and closing is idempotent, so
    // dropping it without closing it first leaves the same observable state.
    // The explicit close is written for the reason the original had it, not
    // because this control can tell.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8904);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    private
        .broker
        .registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the boundary admits and the lifecycle attaches");
    let shared = cleanup_of(&registration);
    let gate = shared
        .lifecycle
        .lock()
        .expect("a readable lifecycle")
        .as_ref()
        .expect("a lease is attached")
        .gate();
    assert!(gate.is_open(), "its lifecycle is open");

    drop(registration);
    assert!(
        !gate.is_open(),
        "the cleanup closed this connection's lifecycle"
    );
    assert!(
        shared
            .lifecycle
            .lock()
            .expect("a readable lifecycle")
            .is_none(),
        "and took the lease rather than leaving it for whenever the record goes"
    );
    drop((shared, private, keeper, durable));
}

#[test]
fn a_poisoned_lifecycle_cell_still_closes_this_connections_gate() {
    // WHAT THE HANDLE USED TO GET FOR FREE. The lease was a field of the
    // registration, so its destructor ran when the handle was destroyed and
    // closed the gate even on the path where the explicit close was skipped.
    // Once its home outlived the handle, leaving it in place on that path
    // meant the gate stayed open for as long as the keeper held the record.
    //
    // NO WORKER IS INVOLVED. The cell is poisoned by an ordinary caught panic
    // under its own lock, and nothing in it is rewritten.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(8905);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    private
        .broker
        .registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the boundary admits and the lifecycle attaches");
    let shared = cleanup_of(&registration);
    let gate = shared
        .lifecycle
        .lock()
        .expect("a readable lifecycle")
        .as_ref()
        .expect("a lease is attached")
        .gate();
    assert!(gate.is_open());

    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = shared.lifecycle.lock().expect("a readable lifecycle");
        panic!("poisoning this connection's lifecycle cell, and nothing else");
    }));
    assert!(poisoning.is_err());
    assert!(shared.lifecycle.is_poisoned());

    // ONLY THE REGISTRATION GOES. The keeper still holds the record, which is
    // exactly the condition that used to hide the missing disposal.
    drop(registration);
    assert!(
        !gate.is_open(),
        "its lifecycle was closed, which is what dropping the lease always did"
    );
    let still_held = match shared.lifecycle.lock() {
        Ok(held) => held.is_some(),
        Err(poisoned) => poisoned.into_inner().is_some(),
    };
    assert!(
        !still_held,
        "and the lease was taken, not left for whenever the record goes"
    );
    drop((shared, private, keeper, durable));
}

#[test]
fn a_connection_can_depart_before_anything_prepares_it() {
    // NO PREPARED ASSOCIATION IS REQUIRED. Forbidding a future start must not
    // mean entering this connection's home, inventing a stop, or making it
    // serve first -- a connection that never became serving is exactly one
    // that may need forbidding.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9001);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a source and a row");
    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    assert_eq!(pin.startup_admitted(), Some(true));
    assert!(
        pin.prepare_control().is_err(),
        "nothing is bound: this connection never became serving"
    );

    assert_eq!(
        pin.depart_registered(),
        PrivateDeparted::Decided(PrivateDeparture::NothingStarted)
    );
    assert_eq!(pin.startup_admitted(), Some(false));
    assert_eq!(
        pin.departure_observation(),
        Some(PrivateDeparture::NothingStarted),
        "and the connection keeps what was found, not the frame that asked"
    );

    // AND NOTHING WAS ENTERED TO DO IT. Its home is live and empty, its gate
    // is open, and its place is exactly where it was.
    assert_eq!(registration.ordered_home.standing(), PrivateHomeStanding::Live);
    assert!(!registration.ordered_handovers_fenced().expect("a readable gate"));
    assert_eq!(durable.continuations_reserved(), Some(1));
    drop(pin);
    drop((registration, private, keeper, durable));
}

#[test]
fn a_context_obtained_before_departure_cannot_start_afterwards() {
    // A CONTEXT IS STILL A CONTEXT; what it must not be is a way in. This one
    // is prepared first, departs through the source, and then tries to start.
    let f = worker_fixture(XServerFrontendClientId(9002));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");

    assert_eq!(
        custody.depart_registered(),
        PrivateDeparted::Decided(PrivateDeparture::NothingStarted)
    );

    let called = std::sync::atomic::AtomicBool::new(false);
    let outcome = context.start(|| {
        called.store(true, std::sync::atomic::Ordering::Release);
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(outcome, PrivateStartupOutcome::NoLongerStartable);
    assert!(
        !called.load(std::sync::atomic::Ordering::Acquire),
        "a refused start calls no spawner, so no thread exists to be lost"
    );
    assert_eq!(
        custody.worker_slot().lock().expect("a readable slot").life,
        PrivateWorkerLife::NeverStarted
    );

    // AND ASKING FOR A CONTEXT AFTERWARDS DOES NOT REOPEN ANYTHING.
    //
    // WHAT THIS IS NOT. The association was already published by the context
    // above, so this ask returns at the entry check -- it is a second view,
    // not a resolution that began before the departure and finished after it.
    //
    // AND NO CONTROL HERE ARRANGES THAT SCHEDULE.
    // a_preparation_that_loses_a_race_recovers_what_the_winner_published
    // separates the two halves of a preparation, but it stages one preparation
    // against another and then poisons the home; it never departs and never
    // closes admission. A preparation resolving across a departure is not
    // covered by anything landed here.
    let later = custody.prepare_control().expect("its association stands");
    assert!(Arc::ptr_eq(later.stop(), context.stop()));
    assert_eq!(custody.startup_admitted(), Some(false));
    let outcome = later.start(|| std::thread::Builder::new().spawn(|| {}));
    assert_eq!(outcome, PrivateStartupOutcome::NoLongerStartable);
    drop(f.fixture);
}

#[test]
fn a_departure_reaching_an_admitted_start_stops_it_before_waiting() {
    // THE RACE THIS COMPONENT EXISTS FOR. A start is admitted and is inside
    // its transaction holding the destination; a departure arrives, finds the
    // pair that start published, stops the worker through it, and only then
    // waits for the slot.
    //
    // THE OVERLAP IS WITNESSED BY HOLDING THE SPAWNER, not by sleeping: the
    // start cannot leave its transaction while this control holds it, and the
    // stop is observed while that is true.
    let f = worker_fixture(XServerFrontendClientId(9003));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");
    let (enter, entered) = std::sync::mpsc::channel::<()>();
    let (release, released) = std::sync::mpsc::channel::<()>();

    let (started, departed, witnessed) = std::thread::scope(|scope| {
        let context = &context;
        let custody = &custody;
        let starting = scope.spawn(move || {
            context.start(move || {
                enter.send(()).expect("its caller is waiting");
                let _ = released.recv();
                std::thread::Builder::new().spawn(|| {})
            })
        });
        entered
            .recv_timeout(Duration::from_secs(3))
            .expect("the spawn began and holds the destination");

        // THE PAIR IS ALREADY PUBLISHED, which is what makes the stop below
        // reachable without the home.
        let published = custody.published_stop().is_some();

        let departing = scope.spawn(move || custody.depart_registered());
        // OBSERVED INTO A LOCAL, NOT COMPARED HERE. This control has started a
        // worker whose handle is in the custody; a comparison that failed at
        // this point would leave that worker uncollected, and joining these
        // two helper threads is not collecting it.
        let stopped_while_held = waited_for(|| f.stop.load(std::sync::atomic::Ordering::Acquire));
        let witnessed = (
            published,
            stopped_while_held,
            custody.startup_admitted(),
        );
        drop(release);
        let started = starting.join().expect("the startup returned");
        let departed = departing.join().expect("the departure returned");
        (started, departed, witnessed)
    });

    // COLLECTED BEFORE THE COMPARISONS THIS CONTROL IS ABOUT. The worker it
    // started is joined here, through its own custody, and the stop and
    // outcome observations are compared after that.
    //
    // NOT A GENERAL FAILURE-PATH CLAIM. The setup, the channel receives and
    // the helper joins above can still fail on their own, and no cleanup guard
    // is armed for those.
    let record = PrivateReapingRecord::bound_to(&custody);
    let reaped = record.reap().reaped;

    assert_eq!(started, PrivateStartupOutcome::Started);
    assert_eq!(
        witnessed,
        (true, true, Some(false)),
        "the pair was published, the stop was set while the destination was \
         held, and admission was closed"
    );
    // EXACTLY WHAT THIS ARRANGEMENT ESTABLISHES. Nothing here hands the handle
    // on before the departure returns, and this control's own reaping is the
    // first joiner -- so WorkerHandedOn and HandedElsewhere are not outcomes
    // this fixture can reach, and accepting them would accept a schedule in
    // which it never collected its worker.
    assert_eq!(
        departed,
        PrivateDeparted::Decided(PrivateDeparture::WorkerRunning),
        "its handle was in the slot when the departure reached it"
    );
    assert_eq!(reaped, PrivateReaped::Joined);
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn one_departure_decision_is_recorded_however_many_ask() {
    // ONE DEPARTURE, ONE HISTORY. A second ask reports what the first
    // established rather than deciding again, and a view ending takes nothing
    // with it.
    let f = worker_fixture(XServerFrontendClientId(9004));
    f.permit();
    let custody = custody_for(&f, &f.fixture.keeper);
    // STARTED THROUGH THE REGISTERED SEAM, so this connection's pair is
    // published where a departure reaches it. The low-level transaction would
    // have made a worker without going through admission at all, which is not
    // what this protocol control is about.
    let starting = custody.prepare_control().expect("its own owner");
    assert_eq!(
        starting.start(|| std::thread::Builder::new().spawn(|| {})),
        PrivateStartupOutcome::Started
    );

    let first = custody.depart_registered();
    assert_eq!(
        first,
        PrivateDeparted::Decided(PrivateDeparture::WorkerRunning),
        "its handle was still in the slot when this looked"
    );
    for _ in 0..3 {
        assert_eq!(
            custody.depart_registered(),
            PrivateDeparted::AlreadyDecided(PrivateDeparture::WorkerRunning),
            "reported, not decided again"
        );
    }

    // AND THROUGH A CONTEXT PREPARED AFTERWARDS, which is another view of the
    // same connection and not another departure.
    let context = custody.prepare_control().expect("its own owner");
    assert_eq!(
        context.depart(),
        PrivateDeparted::AlreadyDecided(PrivateDeparture::WorkerRunning)
    );
    assert_eq!(
        custody.departure_observation(),
        Some(PrivateDeparture::WorkerRunning),
        "the first fact, which is the connection's"
    );

    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_departure_leaves_a_same_store_sibling_exactly_as_it_was() {
    // ONE CONNECTION'S DECISION IS ONE CONNECTION'S. A sibling of the same
    // instance keeps its admission, its stop, its gate, its standing and the
    // exact work already accepted for it.
    let f = worker_fixture(XServerFrontendClientId(9005));
    let (sibling, sibling_stop, _sibling_notice, _peer) =
        serving_sibling(&f, XServerFrontendClientId(9006), true);
    let keeper = &f.fixture.keeper;
    let custody = custody_for(&f, keeper);
    let PrivateCustodyReach::Reached(sibling_custody) = sibling
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("the same owner keeps it")
    };

    let (capsule, _endpoint, _recovery, _receipts) = answerable_capsule(90060);
    let delivery = capsule.delivery();
    let cell = Arc::clone(&capsule.finalizer().expect("carried").completion);
    let frames = order_pass_frames(&capsule);
    let sender = capture_gated_sender(
        f.fixture.runner.frontend.as_ref().expect("a live runner"),
        XServerFrontendClientId(9006),
    );
    produced_send(&sender, capsule);

    // COUNTED BEFORE, because this fixture holds more than this connection --
    // it keeps a spare registration of its own -- and what this control means
    // is that departing changes nothing, not that the total is any number.
    let reserved_before = f.fixture.durable.continuations_reserved();
    assert_eq!(
        custody.depart_registered(),
        PrivateDeparted::Decided(PrivateDeparture::NothingStarted)
    );

    assert_eq!(
        sibling_custody.startup_admitted(),
        Some(true),
        "its sibling still admits a start"
    );
    assert_eq!(sibling_custody.departure_observation(), None);
    assert!(!sibling_stop.load(std::sync::atomic::Ordering::Acquire));
    assert!(!sibling.ordered_handovers_fenced().expect("a readable gate"));
    assert_eq!(sibling.ordered_home.standing(), PrivateHomeStanding::Live);
    let queued = sibling
        .ordered_home
        .borrow(|continuation| continuation.queue().try_recv().ok())
        .expect("a readable live home")
        .expect("the capsule this control accepted for it");
    assert_eq!(queued.delivery(), delivery);
    assert!(Arc::ptr_eq(
        &cell,
        &queued.finalizer().expect("carried").completion
    ));
    assert_eq!(order_pass_frames(&queued), frames);
    assert!(cell.answer().is_none());

    // AND THE DECISION CHANGED NO STANDING AND NO ACCOUNTING for either.
    assert_eq!(
        f.fixture.registration.ordered_home.standing(),
        PrivateHomeStanding::Live
    );
    assert_eq!(
        f.fixture.durable.continuations_reserved(),
        reserved_before,
        "no place was returned or taken by deciding"
    );
    drop(queued);
    drop(sender);
    drop((custody, sibling_custody));
    drop(sibling);
    drop(f.fixture);
}

#[test]
fn an_unreadable_admission_boundary_admits_nothing() {
    // FAIL CLOSED. A boundary nobody can read is exactly when letting a start
    // through would be worst: it would be restoring an eligibility nobody
    // established, on the one path where nothing can be established at all.
    //
    // The boundary is poisoned by an ordinary caught panic under its own lock,
    // and nothing in it is rewritten.
    let f = worker_fixture(XServerFrontendClientId(9007));
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");
    assert_eq!(custody.startup_admitted(), Some(true));

    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = custody
            .source
            .departure
            .lock()
            .expect("a readable boundary");
        panic!("poisoning this connection's admission boundary, and nothing else");
    }));
    assert!(poisoning.is_err());
    assert!(custody.source.departure.is_poisoned());

    let called = std::sync::atomic::AtomicBool::new(false);
    let outcome = context.start(|| {
        called.store(true, std::sync::atomic::Ordering::Release);
        std::thread::Builder::new().spawn(|| {})
    });
    assert_eq!(outcome, PrivateStartupOutcome::NoLongerStartable);
    assert!(
        !called.load(std::sync::atomic::Ordering::Acquire),
        "no spawner ran, so no thread exists that nothing admitted"
    );
    assert_eq!(
        custody.worker_slot().lock().expect("a readable slot").life,
        PrivateWorkerLife::NeverStarted
    );

    // AND A DEPARTURE SAYS IT ESTABLISHED NOTHING, rather than reporting an
    // absence it could not read.
    assert_eq!(custody.depart_registered(), PrivateDeparted::Unreadable);
    assert_eq!(custody.startup_admitted(), None);
    assert_eq!(custody.departure_observation(), None);
    drop(f.fixture);
}

#[test]
fn an_unreadable_boundary_still_stops_the_worker_it_admitted() {
    // FAILING CLOSED TO A NEW START IS NOT A REASON TO LEAVE A RUNNING ONE
    // ALONE. The worker below was admitted through this boundary before it
    // became unreadable, so its stop is known: the association that published
    // it is immutable and does not live behind that lock.
    //
    // BOTH ENTRY POINTS ARE EXERCISED, because the bug was reachable through
    // each: the custody's own departure and a context's.
    for through_context in [false, true] {
        let client = XServerFrontendClientId(if through_context { 9010 } else { 9009 });
        let f = worker_fixture(client);
        f.permit();
        let custody = custody_for(&f, &f.fixture.keeper);
        let context = custody.prepare_control().expect("its own owner");
        let (release, held) = std::sync::mpsc::channel::<()>();
        assert_eq!(
            context.start(move || {
                std::thread::Builder::new().spawn(move || {
                    let _ = held.recv();
                })
            }),
            PrivateStartupOutcome::Started
        );
        assert!(custody.published_stop().is_some());

        let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _guard = custody
                .source
                .departure
                .lock()
                .expect("a readable boundary");
            panic!("poisoning this connection's admission boundary, and nothing else");
        }));
        assert!(poisoning.is_err());

        let answer = if through_context {
            context.depart()
        } else {
            custody.depart_registered()
        };
        let stopped = f.stop.load(std::sync::atomic::Ordering::Acquire);

        // RELEASED AND COLLECTED BEFORE THE COMPARISONS THIS CONTROL IS
        // ABOUT. The startup, publication and poisoning above assert on their
        // own and would end this iteration before here; what follows the
        // collection is the departure's answer and the stop it sent.
        drop(release);
        let record = PrivateReapingRecord::bound_to(&custody);
        let reaped = record.reap().reaped;

        assert_eq!(
            answer,
            PrivateDeparted::Unreadable,
            "it established nothing about the slot, and says so"
        );
        assert!(
            stopped,
            "and the worker it had already admitted was told to stop \
             (through {})",
            if through_context { "its context" } else { "its custody" }
        );
        assert_eq!(reaped, PrivateReaped::Joined);
        drop(record);
        drop(custody);
        drop(f.fixture);
    }
}

#[test]
fn a_repeated_departure_ask_does_not_go_back_to_the_worker_slot() {
    // A RECORDED FACT IS REPORTED, NOT RE-ESTABLISHED. An ask that went to the
    // slot again would spend a second decision on a connection that has one --
    // and would wait for a slot somebody else may be holding, which is what
    // this control makes true while it asks.
    let f = worker_fixture(XServerFrontendClientId(9008));
    f.permit();
    let custody = custody_for(&f, &f.fixture.keeper);
    let starting = custody.prepare_control().expect("its own owner");
    assert_eq!(
        starting.start(|| std::thread::Builder::new().spawn(|| {})),
        PrivateStartupOutcome::Started
    );
    assert_eq!(
        custody.depart_registered(),
        PrivateDeparted::Decided(PrivateDeparture::WorkerRunning)
    );

    let (report, answered) = std::sync::mpsc::channel();
    let repeated = std::thread::scope(|scope| {
        // THE SLOT IS HELD BY THIS CONTROL for the whole of the second ask.
        let held = custody.worker_slot().lock().expect("a readable slot");
        let custody = &custody;
        let asking = scope.spawn(move || {
            report
                .send(custody.depart_registered())
                .expect("its caller waits");
        });
        let answer = answered.recv_timeout(Duration::from_secs(3));
        // RELEASED BEFORE ANYTHING COMPARES, so a second ask that did go to
        // the slot is collected rather than left waiting on this control.
        drop(held);
        asking.join().expect("the repeated ask returned");
        answer
    });

    assert_eq!(
        repeated.ok(),
        Some(PrivateDeparted::AlreadyDecided(PrivateDeparture::WorkerRunning)),
        "it reported the recorded fact without waiting for the slot"
    );
    let record = PrivateReapingRecord::bound_to(&custody);
    assert_eq!(record.reap().reaped, PrivateReaped::Joined);
    drop(record);
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_start_admitted_before_departure_still_cannot_spawn_after_it() {
    // THE OTHER ORDER. A start passes admission and is then delayed before it
    // reaches its transaction; a departure records that nothing was started;
    // and the delayed start must still not make a thread.
    //
    // A DIRECT SEAM CONTROL, AND LABELLED AS ONE. It does not pause a real
    // context.start between its two halves -- that needs a scheduling hook
    // this control does not have. What it does is drive the same two seams in
    // that order, through the connection's own admission boundary and the
    // approved startup transaction, so the worker-slot decision is what has to
    // refuse.
    let f = worker_fixture(XServerFrontendClientId(9011));
    f.permit();
    let custody = custody_for(&f, &f.fixture.keeper);
    let context = custody.prepare_control().expect("its own owner");

    // Admitted: this is what context.start does before it holds anything.
    assert_eq!(
        custody.admit_start(context.stop(), context.notice()),
        PrivateStartAdmission::Admitted
    );
    assert!(custody.published_stop().is_some());

    // The departure runs while that start has gone no further.
    assert_eq!(
        custody.depart_registered(),
        PrivateDeparted::Decided(PrivateDeparture::NothingStarted)
    );

    // AND THE DELAYED START REACHES ITS TRANSACTION TOO LATE.
    let called = std::sync::atomic::AtomicBool::new(false);
    let outcome = start_connection_worker(
        custody.worker_slot(),
        context.stop(),
        context.notice(),
        || {
            called.store(true, std::sync::atomic::Ordering::Release);
            std::thread::Builder::new().spawn(|| {})
        },
    );
    assert_eq!(outcome, PrivateStartupOutcome::NoLongerStartable);
    assert!(
        !called.load(std::sync::atomic::Ordering::Acquire),
        "the slot decision refused it, so no thread exists after a departure \
         that recorded none"
    );
    assert_eq!(
        custody.departure_observation(),
        Some(PrivateDeparture::NothingStarted),
        "and the recorded fact is still the one that was established"
    );
    drop(custody);
    drop(f.fixture);
}

#[test]
fn a_number_is_not_free_because_its_row_went() {
    // ABSENCE FROM THE CLIENT TABLE IS NOT AN ANSWER. A row is removed when a
    // send finds its endpoint disconnected and when a client stops draining,
    // so "no row" says nothing about whether the connection that had the
    // number has finished with it.
    //
    // THE ROW HERE GOES THROUGH A REAL ROUTING FAILURE -- its receiver is
    // dropped and an ordinary send finds the endpoint gone -- not by reaching
    // into the table.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9101);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    assert_eq!(private.broker.registry.occupancy.state_of(client), Some(PrivateNumberStanding::Held));

    // Its endpoint goes; the next send finds it disconnected and removes the
    // row, which is one of the paths this rule exists for.
    drop(channels);
    let sent = private.broker.registry.route_control(XAuthorityClientControlCommand {
        client,
        command: XAuthorityControlCommand::FocusSurface {
            transaction: TransactionId::from_raw(91010),
            surface: SurfaceId::new(9101, 1),
        },
    });
    assert!(sent.is_err(), "the send found its endpoint gone: {sent:?}");
    assert!(
        !private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable registry")
            .contains_key(&client),
        "and its row went with it"
    );

    // THE NUMBER IS STILL THIS REGISTRATION'S. Its ending has not run, so
    // everything that ending does by number is still to come.
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("its number is not free");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "{refused:?}"
    );

    // AND A DIFFERENT NUMBER IS UNAFFECTED.
    let neighbour = XServerFrontendClientId(9102);
    let (other, _other_channels) = private
        .broker
        .registry
        .register_client_with_admission(neighbour, Some(admitted(neighbour)))
        .expect("another number is another connection's");
    drop(other);

    // ONLY ITS ENDING FREES IT, and then a real successor takes it.
    drop(registration);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        None,
        "its ending established that the number may be reused"
    );
    let (successor, _successor_channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("the number is free now");

    // THE SUCCESSOR'S OWN STATE IS ITS OWN. Nothing the predecessor's ending
    // did by number reached it: it has a row, a recovery registration of its
    // own and an expected writer of its own.
    assert!(
        private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable registry")
            .contains_key(&client)
    );
    // AND ITS OWN ENDPOINT WORKS. The predecessor's ending cancelled an
    // expected writer and disconnected a recovery ledger entry under this
    // number; a successor that had been reached by either would not accept
    // this.
    let accepted = private
        .broker
        .registry
        .route_control(XAuthorityClientControlCommand {
            client,
            command: XAuthorityControlCommand::FocusSurface {
                transaction: TransactionId::from_raw(91011),
                surface: SurfaceId::new(9101, 2),
            },
        });
    assert!(
        accepted.is_ok(),
        "the successor's own endpoint accepts its own control: {accepted:?}"
    );
    drop(successor);
    drop((private, keeper, durable));
}

#[test]
fn a_number_stays_held_while_its_endings_effects_run() {
    // THE PROTECTED INTERVAL, OBSERVED FROM INSIDE IT. This control holds a
    // lock the ending needs, so the ending is demonstrably part-way through
    // its number-keyed effects while the question is asked. It establishes no
    // timing bound: the ending simply cannot get past this control.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9103);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let registry = private.broker.registry.clone();

    let (entered, row_gone, excluded, outcome, neighbour_ok) = std::thread::scope(|scope| {
        // A TABLE THE ENDING TAKES LATE, AND PUBLICATION NEVER TAKES. The
        // ending reaches this one after its writer cancellation, its recovery
        // disconnect and its row removal, so holding it stops the ending
        // inside the interval its number authorises -- and a registration
        // asked meanwhile needs none of the locks the ending is still to take.
        //
        // Holding an EARLIER one instead would deadlock this control against
        // the ending rather than test it: publication needs the recovery
        // ledger, and an ending stopped before releasing it would be waiting
        // for this table while this control waited for that ledger.
        let parents = registry
            .window_parents
            .lock()
            .expect("a readable parent table");
        let ending = scope.spawn(move || drop(registration));
        // OBSERVED INTO LOCALS, COMPARED AFTER THE LOCK GOES. A comparison
        // made here would, when it fails, unwind while this table is held and
        // leave the ending waiting on a poisoned lock forever -- so a control
        // that had something to report would hang instead of reporting it.
        let entered = waited_for(|| {
            matches!(
                registry.occupancy.state_of(client),
                Some(PrivateNumberStanding::Visiting)
            )
        });
        // AND ITS ROW IS GONE. Visiting is set before the row removal, so a
        // publication asked between the two would rightly be refused as a
        // duplicate -- the table's refusal, not the number's. The number's is
        // what this control is about, so the row's absence is established
        // first, while this table still holds the interval open.
        let row_gone = waited_for(|| {
            matches!(
                registry.client_senders(client),
                Err(XServerFrontendRouteError::UnknownClient { .. })
            )
        });
        let attempted = registry.register_client_with_admission(client, Some(admitted(client)));
        let excluded = matches!(
            attempted.as_ref().err(),
            Some(XServerFrontendRouteError::ClientNumberExcluded { client: same })
                if *same == client
        );
        let outcome = format!("{:?}", attempted.as_ref().err());

        // AND AN UNRELATED NUMBER IS NOT QUEUED BEHIND IT.
        //
        // KEPT, NOT DROPPED HERE. Its own ending would need the table this
        // control is holding, so dropping it inline would be this thread
        // waiting for a lock it holds itself -- which would look exactly like
        // the queueing this asserts does not happen.
        let neighbour = XServerFrontendClientId(9104);
        let admitted_neighbour =
            registry.register_client_with_admission(neighbour, Some(admitted(neighbour)));
        let neighbour_ok = admitted_neighbour.is_ok();
        drop(parents);
        // WHATEVER THAT ATTEMPT WAS, DISPOSED OF AFTER THE TABLE GOES. An
        // attempt that succeeded is a second live registration whose own
        // ending needs this table, so dropping it any earlier would be this
        // thread waiting for a lock it holds itself.
        drop(attempted);
        drop(admitted_neighbour);
        ending.join().expect("the ending finished");
        (entered, row_gone, excluded, outcome, neighbour_ok)
    });

    assert!(
        entered,
        "its ending is inside the interval its number authorises"
    );
    assert!(
        row_gone,
        "and past its row removal, so the table cannot answer the attempt"
    );
    assert!(
        excluded,
        "its number is not available while that interval is open: {outcome}"
    );
    assert!(
        neighbour_ok,
        "one connection's ending does not hold up another connection's number"
    );
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        None,
        "and the interval closed when the ending finished"
    );
    drop((private, keeper, durable));
}

#[test]
fn a_number_whose_ending_could_not_finish_stays_held() {
    // RETURNING FROM A BEST-EFFORT BODY IS NOT PROOF. An ending that could not
    // read a table it had to clear leaves work nobody did, so handing the
    // number on would hand it on over an effect that never happened.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9105);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");

    // A table this connection's ending must clear is poisoned by an ordinary
    // caught panic under its own lock. Nothing in it is rewritten.
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = private
            .broker
            .registry
            .surfaces
            .lock()
            .expect("a readable surface table");
        panic!("poisoning this registry's surface table, and nothing else");
    }));
    assert!(poisoning.is_err());

    drop(registration);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Unestablished),
        "its ending could not establish that the number may be reused"
    );
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("an unfinished ending keeps its number");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "{refused:?}"
    );
    drop((private, keeper, durable));
}

#[test]
fn an_old_senders_failure_does_not_remove_the_connection_that_took_its_number() {
    // THE SCHEDULE THE NUMBER RESERVATION ALONE DOES NOT COVER. An operation
    // captured a sender while its connection was live; that connection ends,
    // its number is released, a successor takes it -- and only THEN does the
    // old send fail. The removal that follows is keyed by the number, so
    // without an identity check it revokes a connection nothing was wrong
    // with.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9106);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");

    // The old operation's sender AND the identity it came with, from the one
    // lookup an operation makes while its connection is live. The pair below
    // is that captured pair, not a sender beside an invented cell.
    let senders = private
        .broker
        .registry
        .client_senders(client)
        .expect("its own senders");
    let stale_incarnation = Arc::clone(&senders.connection_state);
    let stale = senders.control;

    // Its connection ends, which releases the number, and a real successor
    // takes it with channels of its own.
    drop(channels);
    drop(registration);
    assert_eq!(private.broker.registry.occupancy.state_of(client), None);
    let (successor, successor_channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("the number is free");

    // NOW THE OLD SEND FAILS. Its endpoint is gone, which is exactly the path
    // that removes a row.
    let failed = private.broker.registry.route_to_client(
        client,
        &stale_incarnation,
        stale,
        X11RoutedControl::FocusOut {
            window: XResourceId::new(0x9106, 1),
            time_msec: 0,
            claim: None,
            origin: None,
        },
    );
    assert!(
        matches!(
            failed,
            Err(XServerFrontendRouteError::ClientQueueDisconnected { .. })
        ),
        "the old send really did find its endpoint gone: {failed:?}"
    );

    // AND THE SUCCESSOR IS STILL THERE. Its row was not removed by somebody
    // else's failure at the same number.
    assert!(
        private
            .broker
            .registry
            .clients
            .lock()
            .expect("a readable registry")
            .contains_key(&client),
        "a stale sender's failure removed the connection that took its number"
    );
    let accepted = private
        .broker
        .registry
        .route_control(XAuthorityClientControlCommand {
            client,
            command: XAuthorityControlCommand::FocusSurface {
                transaction: TransactionId::from_raw(91060),
                surface: SurfaceId::new(9106, 1),
            },
        });
    assert!(accepted.is_ok(), "and it still routes: {accepted:?}");
    drop(successor_channels);
    drop(successor);
    drop((private, keeper, durable));
}

#[test]
fn a_stale_cleanup_request_does_not_run_against_the_successor() {
    // THE RECORD OUTLIVES ITS REGISTRATION -- its keeper holds it -- so asking
    // it to clean up again is reachable. A request that reacquired a
    // relinquished right would run every number-keyed effect against whoever
    // holds the number now.
    //
    // A DIRECT SEAM CONTROL. It calls the cleanup the registration's own Drop
    // calls, on the record that Drop already used, rather than arranging a
    // second Drop.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9107);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    let stale_record = Arc::clone(pin.cleanup_record());
    drop(pin);

    // Its ending runs, its number is released, and a real successor takes it.
    drop(registration);
    assert_eq!(private.broker.registry.occupancy.state_of(client), None);
    let (successor, successor_channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("the number is free");
    let successor_state = private
        .broker
        .registry
        .client_senders(client)
        .expect("its own senders")
        .connection_state;

    // THE STALE RECORD IS ASKED AGAIN.
    stale_record.run_synchronous_cleanup();

    // AND THE SUCCESSOR IS UNTOUCHED: its row is there, it is the same
    // registration it was, and it still routes.
    let current = private
        .broker
        .registry
        .client_senders(client)
        .expect("the successor still has a row");
    assert!(
        Arc::ptr_eq(&current.connection_state, &successor_state),
        "the row under this number is still the successor's own"
    );
    let accepted = private
        .broker
        .registry
        .route_control(XAuthorityClientControlCommand {
            client,
            command: XAuthorityControlCommand::FocusSurface {
                transaction: TransactionId::from_raw(91070),
                surface: SurfaceId::new(9107, 1),
            },
        });
    assert!(accepted.is_ok(), "and it still routes: {accepted:?}");
    assert!(
        matches!(
            private.broker.registry.occupancy.state_of(client),
            Some(PrivateNumberStanding::Held)
        ),
        "the successor's own claim is intact and not marked clearing"
    );
    drop(successor_channels);
    drop(successor);
    drop((stale_record, private, keeper, durable));
}

#[test]
fn a_refused_publication_changes_nothing_under_the_number_it_could_not_take() {
    // THE REFUSAL COMES BEFORE THE STATE, AND THAT ORDER IS THE RULE. The
    // recovery ledger's registration REPLACES a connection's entry -- its
    // lifecycle gate, its socket and its revocation all go with it -- and the
    // expected-writer record is keyed by the number too. An attempt that
    // touched either before finding the number excluded would have disarmed
    // the connection that actually holds it, and the refusal it then returned
    // would be a lie about having changed nothing.
    //
    // THE ROW IS GONE FIRST, so the client table cannot answer and the
    // occupancy record is what refuses.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9109);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    private
        .broker
        .registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the incumbent is admitted to the boundary");
    let (peer, owned) = UnixStream::pair().expect("socket pair");
    // A COPY THE TEST KEEPS, so that losing the ledger's own copy does not
    // close the connection by itself. What the peer observes below is a
    // shutdown somebody performed, not a file descriptor going out of scope.
    let retained = owned.try_clone().expect("a second handle on the same connection");
    private
        .broker
        .registry
        .input_recovery
        .attach(client, owned)
        .expect("the incumbent's own socket");
    private
        .broker
        .registry
        .control_completion()
        .expect("a private frontend installs one")
        .writer_started(client);

    drop(channels);
    let sent = private.broker.registry.route_control(XAuthorityClientControlCommand {
        client,
        command: XAuthorityControlCommand::FocusSurface {
            transaction: TransactionId::from_raw(91090),
            surface: SurfaceId::new(9109, 1),
        },
    });
    assert!(sent.is_err(), "the send found its endpoint gone: {sent:?}");

    // THE ATTEMPT THAT CANNOT HAVE THE NUMBER.
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("its number is not free");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "{refused:?}"
    );
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Held),
        "and the incumbent's own claim is not marked by somebody else's attempt"
    );

    // THE WRITER RECORD IS STILL THE INCUMBENT'S OWN. Its writer has started
    // and nothing expects a second one, so when that writer stops there is
    // nothing left to say this client may still execute.
    private
        .broker
        .registry
        .control_completion()
        .expect("a private frontend installs one")
        .writer_stopped(client);
    assert!(
        private
            .broker
            .registry
            .control_completion()
        .expect("a private frontend installs one")
            .enter_routing(client)
            .is_none(),
        "a refused attempt must not leave an expectation nobody will meet"
    );

    // AND THE RECOVERY ENTRY IS STILL THE INCUMBENT'S OWN, so its ending
    // reaches the socket it attached.
    peer.set_read_timeout(Some(std::time::Duration::from_secs(5)))
        .expect("a bounded wait");
    drop(registration);
    let mut byte = [0u8; 1];
    let read = std::io::Read::read(&mut &peer, &mut byte);
    assert!(
        matches!(read, Ok(0)),
        "the incumbent's ending still reached its own socket: {read:?}"
    );
    drop((retained, peer, private, keeper, durable));
}

#[test]
fn a_successor_admitted_after_the_release_has_only_its_own_state() {
    // WHAT THE NUMBER AUTHORISED, AND WHAT IT DID NOT. A connection's ending
    // removes its recovery entry, its expected writer, its row, its surfaces,
    // its selection and presentation subscriptions and its pending presents --
    // all keyed by the number. The exclusion exists so that every one of those
    // reaches only the connection that held it.
    //
    // THIS IS THE AFTER PICTURE. The predecessor's ending established that the
    // number may be reused; the successor then builds each of those kinds for
    // itself, and each is observably its own rather than something inherited.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let registry = &private.broker.registry;
    let client = XServerFrontendClientId(9111);
    let namespace = admitted(client).namespace.id;
    let window = XResourceId::new(0x9111, 1);
    let selection = 0x9111;
    let event_id = XResourceId::new(0x9111, 7);

    let (registration, channels) = registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    registry
        .attach_private_lifecycle(&registration, admitted(client))
        .expect("the predecessor is admitted to the boundary");
    registry
        .register_surface(client, namespace, SurfaceId::new(9111, 1), window)
        .expect("its own surface");
    registry
        .select_xfixes_selection_input(client, namespace, window, selection, 0xf)
        .expect("its own selection interest");
    registry
        .select_present_input(client, event_id, window, 0xf)
        .expect("its own presentation interest");
    registry
        .queue_present(
            TransactionId::from_raw(91110),
            client,
            window,
            XResourceId::new(0x9111, 2),
            1,
            None,
            false,
        )
        .expect("its own pending present");

    // ITS ENDING TAKES ALL OF IT, and only then is the number free.
    drop(channels);
    drop(registration);
    assert_eq!(
        registry.occupancy.state_of(client),
        None,
        "its ending established that the number may be reused"
    );
    assert!(
        registry
            .xfixes_selection_subscribers(namespace, selection, 0)
            .expect("a readable table")
            .is_empty(),
        "the predecessor's selection interest went with it"
    );
    assert!(
        registry
            .present_configure_subscribers(window)
            .expect("a readable table")
            .is_empty(),
        "and its presentation interest"
    );
    assert!(
        !registry
            .route_present_idle(TransactionId::from_raw(91110))
            .expect("a readable table"),
        "and its pending present"
    );

    // THE BOUNDARY'S OWN RETIREMENT, WHICH IS NOT THIS COMPONENT'S TO
    // PERFORM. A closed gate is a request; the lifecycle drive is what
    // completes it. Until it runs the boundary still holds the predecessor's
    // admission, and a successor at this number is refused there rather than
    // here -- which is the boundary's own exclusion, not this one.
    let lifecycle = registry
        .input_recovery
        .lifecycle
        .get()
        .expect("a private frontend installs one");
    let retired = lifecycle
        .drive(NonZeroUsize::new(4).expect("a budget"))
        .expect("a reachable boundary");
    assert!(retired >= 1, "the predecessor's slot is retired: {retired}");

    // THE SUCCESSOR, WITH THE SAME NUMBER AND NOTHING ELSE OF ITS
    // PREDECESSOR'S.
    let (successor, successor_channels) = registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("the number is free");
    registry
        .attach_private_lifecycle(&successor, admitted(client))
        .expect("the successor is admitted on its own account");
    let (peer, owned) = UnixStream::pair().expect("socket pair");
    let retained = owned.try_clone().expect("a second handle on the same connection");
    registry
        .input_recovery
        .attach(client, owned)
        .expect("a recovery entry of its own");
    registry
        .control_completion()
        .expect("a private frontend installs one")
        .writer_started(client);
    registry
        .register_surface(client, namespace, SurfaceId::new(9111, 3), window)
        .expect("a surface of its own");
    registry
        .select_xfixes_selection_input(client, namespace, window, selection, 0xf)
        .expect("a selection interest of its own");
    registry
        .select_present_input(client, event_id, window, 0xf)
        .expect("a presentation interest of its own");
    registry
        .queue_present(
            TransactionId::from_raw(91111),
            client,
            window,
            XResourceId::new(0x9111, 4),
            2,
            None,
            false,
        )
        .expect("a pending present of its own");

    // AND A LIVE QUEUE OF ITS OWN, holding the exact delivery it was given:
    // the same identity, the same encoded frames, and a completion nobody has
    // answered. The predecessor's ending settles unanswered deliveries under
    // its number, and this one is untouched.
    let (capsule, _endpoint, capsule_recovery, _receipts) = answerable_capsule(91112);
    let delivery = capsule.delivery();
    let cell = Arc::clone(
        &capsule
            .finalizer()
            .expect("an answerable capsule")
            .completion,
    );
    let frames = order_pass_frames(&capsule);
    let sender = registry
        .clients
        .lock()
        .expect("a readable registry")
        .get(&client)
        .expect("the successor's own row")
        .ordered
        .clone();
    gated_send(&sender, capsule).expect("the successor's own endpoint");

    assert_eq!(
        registry
            .xfixes_selection_subscribers(namespace, selection, 0)
            .expect("a readable table"),
        vec![(client, window)],
        "the successor's own selection interest"
    );
    assert_eq!(
        registry
            .present_configure_subscribers(window)
            .expect("a readable table"),
        vec![(client, event_id)],
        "the successor's own presentation interest"
    );
    assert!(
        registry
            .route_present_idle(TransactionId::from_raw(91111))
            .expect("a readable table"),
        "the successor's own pending present"
    );
    let queued = successor_channels
        .ordered
        .try_recv()
        .expect("the successor's own queue holds it");
    assert_eq!(queued.delivery(), delivery);
    assert!(
        Arc::ptr_eq(
            &cell,
            &queued.finalizer().expect("an answerable capsule").completion
        ),
        "the exact delivery it was given, not a rebuilt one"
    );
    assert_eq!(order_pass_frames(&queued), frames);
    assert!(
        queued
            .finalizer()
            .expect("an answerable capsule")
            .completion
            .answer()
            .is_none(),
        "and nothing has answered it"
    );

    // ITS OWN RECOVERY ENTRY, reached by its own ending and nobody else's.
    peer.set_read_timeout(Some(std::time::Duration::from_secs(5)))
        .expect("a bounded wait");
    drop((queued, successor_channels));
    drop(successor);
    let mut byte = [0u8; 1];
    let read = std::io::Read::read(&mut &peer, &mut byte);
    assert!(
        matches!(read, Ok(0)),
        "the successor's own ending reached its own socket: {read:?}"
    );
    assert_eq!(registry.occupancy.state_of(client), None);
    drop((retained, peer, capsule_recovery, private, keeper, durable));
}

#[test]
fn two_attempts_at_one_number_cannot_both_have_it() {
    // TAKEN IN ONE ACQUISITION, so there is no interval in which two attempts
    // have both looked and neither has taken. Whichever refusal the loser gets
    // -- the table's or the number's -- exactly one attempt may proceed.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 8);
    let private = private_over(&keeper, 8);
    let registry = private.broker.registry.clone();
    let client = XServerFrontendClientId(9112);

    let (first, second) = std::thread::scope(|scope| {
        let contender = registry.clone();
        let racing = scope
            .spawn(move || contender.register_client_with_admission(client, Some(admitted(client))));
        let here = registry.register_client_with_admission(client, Some(admitted(client)));
        (here, racing.join().expect("the contender finished"))
    });

    let admitted_count = usize::from(first.is_ok()) + usize::from(second.is_ok());
    assert_eq!(
        admitted_count, 1,
        "exactly one attempt has the number: {:?} / {:?}",
        first.as_ref().err(),
        second.as_ref().err()
    );
    let refusal = first.as_ref().err().or_else(|| second.as_ref().err());
    assert!(
        matches!(
            refusal,
            Some(
                XServerFrontendRouteError::ClientNumberExcluded { client: same }
                    | XServerFrontendRouteError::DuplicateClient { client: same }
            ) if *same == client
        ),
        "the loser is refused for the number it could not have: {refusal:?}"
    );
    assert_eq!(
        registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Held),
        "and the winner's claim is the one that is held"
    );

    // AND THE WINNER IS A WHOLE CONNECTION, not one that the loser's refusal
    // took anything from.
    let accepted = registry.route_control(XAuthorityClientControlCommand {
        client,
        command: XAuthorityControlCommand::FocusSurface {
            transaction: TransactionId::from_raw(91120),
            surface: SurfaceId::new(9112, 1),
        },
    });
    assert!(accepted.is_ok(), "the winner routes: {accepted:?}");
    drop((first, second));
    assert_eq!(
        registry.occupancy.state_of(client),
        None,
        "and its own ending gives the number back"
    );
    drop((private, keeper, durable));
}

#[test]
fn an_operation_view_ending_does_not_give_the_number_back() {
    // THE RIGHT IS KEPT WITH THE RESPONSIBILITY. Views of a connection come
    // and go -- a custody pin, a maintenance name, a lease on the keeper --
    // and none of them is what ends the connection. A number given back when
    // one of those ended would be free while the effects keyed by it had not
    // run at all.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let client = XServerFrontendClientId(9113);
    let (registration, channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");

    let PrivateCustodyReach::Reached(pin) = registration
        .registered_custody(&keeper.lease())
        .expect("its own custody")
    else {
        panic!("its owner keeps it")
    };
    drop(pin);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Held),
        "a custody view ending is not this connection ending"
    );

    let name = registration.maintenance_identity().expect("a name");
    drop(name);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Held),
        "nor a maintenance name going out of scope"
    );

    drop(channels);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Held),
        "nor its endpoints going"
    );

    // ONLY THE RESPONSIBILITY ENDING DOES.
    drop(registration);
    assert_eq!(private.broker.registry.occupancy.state_of(client), None);
    drop((private, keeper, durable));
}

#[test]
fn a_refused_attempt_at_an_excluded_number_consumes_no_place() {
    // A REFUSAL IS NOT AN ADMISSION, AND IT IS NOT AN OCCUPANCY EITHER. The
    // attempt reserves a place before it can find out that the number is
    // excluded, so a place kept on that path would make each refusal shrink
    // the service by one connection.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 3);
    let private = private_over(&keeper, 3);
    let registry = &private.broker.registry;
    let first = XServerFrontendClientId(9114);
    let (held, channels) = registry
        .register_client_with_admission(first, Some(admitted(first)))
        .expect("the first of three");
    let second = XServerFrontendClientId(9115);
    let (_second, _second_channels) = registry
        .register_client_with_admission(second, Some(admitted(second)))
        .expect("the second of three");

    // Its row goes through a real routing failure, so the attempt below has to
    // reach the number itself.
    drop(channels);
    let sent = registry.route_control(XAuthorityClientControlCommand {
        client: first,
        command: XAuthorityControlCommand::FocusSurface {
            transaction: TransactionId::from_raw(91140),
            surface: SurfaceId::new(9114, 1),
        },
    });
    assert!(sent.is_err(), "the send found its endpoint gone: {sent:?}");

    // FOUR REFUSALS. A place lost on each would leave none for the third
    // connection below.
    for attempt in 0..4 {
        let refused = registry
            .register_client_with_admission(first, Some(admitted(first)))
            .err()
            .unwrap_or_else(|| panic!("attempt {attempt} cannot have an excluded number"));
        assert!(
            matches!(
                refused,
                XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == first
            ),
            "{refused:?}"
        );
    }

    // THE THIRD PLACE IS STILL THERE.
    let third = XServerFrontendClientId(9116);
    let (_third, _third_channels) = registry
        .register_client_with_admission(third, Some(admitted(third)))
        .expect("the third of three");

    // AND THE ACCOUNTING IS EXACT, not merely non-empty: a fourth is refused
    // for the capacity it does not have, and says so in those terms. Which
    // capacity runs out first is this service's own arrangement -- here the
    // publication home's -- and the point is that it runs out at the fourth
    // and not at the third.
    let fourth = XServerFrontendClientId(9117);
    let saturated = registry
        .register_client_with_admission(fourth, Some(admitted(fourth)))
        .err()
        .expect("three is three");
    assert!(
        matches!(
            saturated,
            XServerFrontendRouteError::ContinuationUnavailable { client: same }
                if same == fourth
        ),
        "{saturated:?}"
    );
    assert_eq!(
        registry.occupancy.state_of(fourth),
        None,
        "a saturated attempt leaves no claim behind either"
    );
    drop(held);
    drop((private, keeper, durable));
}

/// An ending that could not perform one of its number-keyed effects.
///
/// `poison` takes the one lock that effect needs, under an ordinary caught
/// panic, and rewrites nothing. The registration then ends while its keeper
/// still holds its record. What is asserted is the number's standing
/// afterwards and what a successor is told -- not that the effect ran.
fn an_ending_that_could_not(
    client: XServerFrontendClientId,
    poison: impl FnOnce(&XServerFrontendRouteRegistry),
) {
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let (registration, _channels) = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        poison(&private.broker.registry);
    }));
    assert!(poisoning.is_err(), "the poisoning panic is caught here");

    drop(registration);
    assert_eq!(
        private.broker.registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Unestablished),
        "its ending could not establish that the number may be reused"
    );
    let refused = private
        .broker
        .registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("an unestablished ending keeps its number");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "{refused:?}"
    );
    drop((private, keeper, durable));
}

#[test]
fn an_ending_over_an_unreadable_selection_table_keeps_its_number() {
    // THE EFFECT IS STILL THERE TO BE DONE, and the ending said so. The
    // poisoned guard is read here as diagnostics only -- nothing is recovered
    // into service -- to show the exact subscription is still present under a
    // number the ending must therefore not have handed on.
    let durable = PrivateSettlementOwner::default();
    let keeper = service_owner(&durable, 4);
    let private = private_over(&keeper, 4);
    let registry = &private.broker.registry;
    let client = XServerFrontendClientId(9120);
    let namespace = admitted(client).namespace.id;
    let window = XResourceId::new(0x9120, 1);
    let (registration, _channels) = registry
        .register_client_with_admission(client, Some(admitted(client)))
        .expect("a place, a keeper, a record and a row");
    registry
        .select_xfixes_selection_input(client, namespace, window, 0x9120, 0xf)
        .expect("its own selection interest");
    let poisoning = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let _held = registry
            .xfixes_selection_subscriptions
            .lock()
            .expect("a readable table");
        panic!("poisoning this registry's selection table, and nothing else");
    }));
    assert!(poisoning.is_err());

    drop(registration);
    let remaining = match registry.xfixes_selection_subscriptions.lock() {
        Ok(_) => panic!("the table is poisoned"),
        Err(poisoned) => poisoned
            .into_inner()
            .contains_key(&(client, window, 0x9120)),
    };
    assert!(remaining, "the subscription the ending could not retire is still there");
    assert_eq!(
        registry.occupancy.state_of(client),
        Some(PrivateNumberStanding::Unestablished)
    );
    let refused = registry
        .register_client_with_admission(client, Some(admitted(client)))
        .err()
        .expect("a number with work still under it is not free");
    assert!(
        matches!(
            refused,
            XServerFrontendRouteError::ClientNumberExcluded { client: same } if same == client
        ),
        "{refused:?}"
    );
    drop((private, keeper, durable));
}

#[test]
